using namespace std;

struct Edge {
	int from, to, cost;
	bool filled;

	Edge() {
		this->filled = false;
	}
	Edge(int from, int to, int cost) {
		this->from = from;
		this->to = to;
		this->cost = cost;
		this->filled = false;
	}
	bool operator<(Edge &r) {
		return cost < r.cost;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

struct UF {
	int par[100000];
	int sum[100000];

	void init(int n, int x[]) {
		int i;
		for (i = 0; i < n; i++) {
			par[i] = i;
			sum[i] = x[i];
		}
	}

	int root(int x) {
		if (par[x] == x) return x;
		return par[x] = root(par[x]);
	}

	int vsum(int x) {
		return sum[root(x)];
	}

	void unit(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			par[x] = y;
			sum[y] += sum[x];
		}
	}
};

int n, m;
int x[100000];
Graph g;
Edge edges[100000];
bool is_max[100000];
bool visit[100000];

void dfs(int v, int c) {
	if (visit[v]) return;
	visit[v] = true;

	int i;
	for (i = 0; i < g[v].size(); i++) {
		Edge& e = g[v][i];
		if (!e.filled && e.cost <= c) {
			//cout << "fill(" << e.from + 1 << ", " << e.to + 1 << ", " << e.cost << ")" << endl;
			e.filled = true;
			dfs(e.to, c);
		}
	}
}

signed main() {
	int i, j;

	cin >> n >> m;
	rep(i, n) cin >> x[i];

	g.resize(n);
	rep(i, m) {
		int a, b, y;
		cin >> a >> b >> y;
		a--; b--;
		edges[i] = Edge(a, b, y);
		g[a].push_back(Edge(a, b, y));
		g[b].push_back(Edge(b, a, y));
	}
	sort(edges, edges + m);

	static UF uf;

	uf.init(n, x);
	rep(i, m) {
		uf.unit(edges[i].from, edges[i].to);
		if (uf.vsum(edges[i].to) >= edges[i].cost) {
			is_max[i] = true;
		}
	}

	for (i = m - 1; i >= 0; i--) {
		if (is_max[i]) {
			//cout << edges[i].from + 1 << ", " << edges[i].to + 1 << ", " << edges[i].cost << endl;
			dfs(edges[i].from, edges[i].cost);
		}
	}

	int ans = 0;
	for (i = 0; i < n; i++) {
		for (j = 0; j < g[i].size(); j++) {
			if (!g[i][j].filled) {
				ans++;
			}
		}
	}
	cout << ans / 2 << endl;
	return 0;
}

