struct UF {
	vector<int> belong;
	vector<long long int> size;
	vector<long long int> mx;
	vector<set<int> > wait;
	vector<multiset<long long int> > que;
	int gross;
	void resize(int n) {
		belong.assign(n + 1, -1);
		mx.resize(n + 1, 0);
		que.assign(n, multiset<long long int>());
		wait.assign(n, set<int>());
		size = node;
		gross = 0;
	}
	inline int root(int b) {
		if (belong[b] == -1) {
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b,long long int cost) {
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
		mx[b] = max(mx[b], mx[a]);
		mx[b] = max(mx[b], cost);
		if (wait[b].size() < wait[a].size())swap(wait[a], wait[b]);
		for (auto el : wait[a]) {
			if (wait[b].count(el)) {
				que[b].insert(ed[el].cost);
				wait[b].erase(el);
			}
			else {
				wait[b].insert(el);
			}
		}
		wait[a].clear();
		if (que[b].size() < que[a].size())swap(que[a], que[b]);
		for (auto el : que[a]) {
			que[b].insert(el);
		}
		que[a].clear();
		while (que[b].size() && (*que[b].begin()) <= size[b]) {
			que[b].erase(que[b].begin());
			gross++;
		}
	}
	bool valid(int a) {
		a = root(a);
		return mx[a] > size[a];
	}
	void dum(int a, long long int z) {
		a = root(a);
		if (z <= size[a]) {
			gross++;
			return;
		}
		que[a].insert(z);
	}
};
