void MakeSet(int v)
{
    par[v] = v;
    sz[v] = 1;
    sum[v] = x[v];
    e[v] = 0;
}
int Root(int v)
{
    return (par[v] == v) ? v : (par[v] = Root(par[v]));
}
void Union(int u, int v)
{
    u = Root(u); v = Root(v);
    if (u == v) return;
    if (sz[u] > sz[v])
        swap(u, v);
    par[u] = v;
    sz[v] += sz[u];
    sum[v] += sum[u];
    e[v] += e[u];
    e[u] = 0;
}
int main()
{
