using namespace std;

int Xs[100008];
int As[100008];
int Bs[100008];
int Ys[100008];
int edge_ids[100008];
int cmp(const void *a,const void *b) {
	int va=*(int  *)a;
	int vb=*(int  *)b;
	if(Ys[va]!=Ys[vb]) return Ys[va]-Ys[vb];
	return va-vb;
}
int N,M;
int ufs[100008];
long long weights[100008];
void reset(void) {
	for(int i=1;i<=N;i++) {
		ufs[i]=i;
		weights[i]=Xs[i];
	}
}
int getpa(int id) {
	if(ufs[id]==id) return id;
	ufs[id]=getpa(ufs[id]);
	return ufs[id];
}
void comb(int a,int b) {
	weights[getpa(b)] += weights[getpa(a)];
	ufs[getpa(a)]=getpa(b);
}
int M_MST=0;
int mst_ids[100008];
int mst_uses[100008];
vector<int> mst_to[100008];
vector<int> mst_vec_edge_id[100008];
vector<int> mst_y[100008];
int mst_search_used[100008];
void search(int now,int from,int weight) {
	for(int i=0;i<mst_to[now].size();i++) {
		int to=mst_to[now][i];
		if(to==from) continue;
		if(mst_search_used[mst_vec_edge_id[now][i]]) continue;
		if(mst_y[now][i]>weight) continue;
		mst_search_used[mst_vec_edge_id[now][i]]=1;
		comb(now, to);
		search(to, now, weight);
	}
}
int main() {
	scanf("%d%d",&N,&M);
	for(int i=1;i<=N;i++) scanf("%d",&Xs[i]);
	for(int i=0;i<M;i++) {
		scanf("%d%d%d",&As[i],&Bs[i],&Ys[i]);
		edge_ids[i]=i;
	}
	qsort(edge_ids, M,sizeof(int),cmp);
	// get MST
	reset();
	for(int i=0;i<M;i++) {
		int eid=edge_ids[i];
		if(getpa(As[eid])!=getpa(Bs[eid])) {
			mst_ids[M_MST++]=eid;
			comb(As[eid], Bs[eid]);
		}
	}
	// setup graph
	for(int i=0;i<M_MST;i++) {
		int eid=mst_ids[i];
		mst_to[As[eid]].push_back(Bs[eid]);
		mst_y[As[eid]].push_back(Ys[eid]);
		mst_vec_edge_id[As[eid]].push_back(eid);
		mst_to[Bs[eid]].push_back(As[eid]);
		mst_y[Bs[eid]].push_back(Ys[eid]);
		mst_vec_edge_id[Bs[eid]].push_back(eid);
	}
	// check use
	reset();
	for(int i=0;i<M_MST;i++) {
		int eid=mst_ids[i];
		if(weights[getpa(As[eid])] + weights[getpa(Bs[eid])] >= Ys[eid]) {
			//use
			mst_uses[i]=1;
		}
		comb(As[eid], Bs[eid]);
	}
	reset();
	for(int i=M_MST-1;i>=0;i--) {
		if(mst_uses[i]) {
			int eid=mst_ids[i];
			search(As[eid], -1, Ys[eid]);
		}
	}
	int sol=0;
	for(int i=0;i<M;i++) {
		if(weights[getpa(As[i])] < Ys[i]) sol++;
	}
	printf("%d\n",sol);
	return 0;
}

