    info(int a, int b){
        u = a, v = b;
    }
};
int n,m;
iii e[100000];
int par[100001],num[100001];
ll w[100001];
stack<info> st;
Vi vv[100001];
int find(int u){
	if(u==par[u]) return u;
	return find(par[u]);
}
void merge(int u, int v){
	u=find(u),v=find(v);
	if(u==v)
	{
		st.push(info(-1,-1));
		return;
	}
	if (num[u] < num[v])
		swap(u, v);
	st.push(info(u,v));
	par[v] = u;
	num[u] += num[v];
	w[u]+=w[v];
	vv[u].pb(v);
}
void rollback(){
	info I=st.top();
	st.pop();
	if(I.u<0)return;
	par[I.u] = I.u;
	par[I.v] = I.v;
	num[I.u] -= num[I.v];
	w[I.u] -= w[I.v];
	vv[I.u].pop_back();
}
bool chk[100001];
void dfs(int x)
{
	chk[x]=1;
	for(int y:vv[x])dfs(y);
}
int main(){
	scanf("%d%d",&n,&m);
	fup(i,1,n,1)par[i]=i,num[i]=1;
	fup(i,1,n,1)scanf("%lld",w+i);
	fup(i,0,m-1,1)
	{
		int x,y,z;
		scanf("%d%d%d",&x,&y,&z);
		e[i]=iii(z,x,y);
	}
	sort(e,e+m);
	fup(i,0,m-1,1)
	{
		int x,y;
		tie(ignore,x,y)=e[i];
		merge(x,y);
	}
	int ans=0;
	fdn(i,m-1,0,1)
	{
		int z,x,y;
		tie(z,x,y)=e[i];
		if(!chk[x])
		{
			if(w[x]>=z)dfs(x);
			else ans++;
		}
		rollback();
	}
	printf("%d",ans);
}

