using namespace std;

typedef long long ll;
int const maxn = 1e5 + 5, K = 300;
ll x[maxn];
int used[maxn], cur, oks[maxn], tmp, timer, was[maxn], Q[maxn];
set < int > g[maxn];
multiset < int > G[maxn];
ll sum[maxn], f;

inline void bfs1(int v) {
    int head = 0, R = 0, u;
    Q[R++] = v, oks[v] = tmp;
    while (head < R) {
        u = Q[head++];
        f += sum[u];
        for (auto to : G[u]) {
            if (oks[to] != tmp) {
                oks[to] = tmp, Q[R++] = to;
            }
        }
    }
}

inline void bfs(int v) {
    int head = 0, R = 0, u;
    was[v] = timer;
    Q[R++] = v;
    while (head < R) {
        u = Q[head++];
        used[u] = cur;
        sum[cur] += x[u];
        for (auto to : g[u]) {
            if (was[to] != timer) {
                was[to] = timer, Q[R++] = to;
            }
        }
    }
}

