int sz[max_n];
int pr[max_n];
ll sumv[max_n];
ll cnte[max_n];
ll sete[max_n];
int n, m;


int get_set(int a) {
    if (pr[a] == a) {
        return a;
    } else {
        return pr[a] = get_set(pr[a]);
    }
}

int ans = 0;

void unite_set(int a, int b, int w) {
    int pra = get_set(a);
    int prb = get_set(b);
    if (pra == prb) {
        int pr = pra;
        if (w <= sumv[pr]) {
            ans++;
            cnte[pr]++;
            sete[pr]++;
            if (cnte[pr] != sete[pr]) {
                exit(228);
            }
        } else {
            cnte[pr]++;
        }
        return;
    }
    ll n_sumv = sumv[pra] + sumv[prb];
    ll n_cnte;
    ll n_sete;
    if (w <= n_sumv) {
        ans -= sete[pra];
        ans -= sete[prb];
        n_cnte = cnte[pra] + cnte[prb] + 1;
        n_sete = n_cnte;
        ans += n_cnte;
    } else {
        n_cnte = cnte[pra] + cnte[prb] + 1;
        n_sete = sete[pra] + sete[prb];
    }
    if (sz[pra] > sz[prb]) {
        sz[pra] += sz[prb];
        pr[prb] = pra;
        sumv[pra] = n_sumv;
        cnte[pra] = n_cnte;
        sete[pra] = n_sete;
    } else {
        sz[prb] += sz[pra];
        pr[pra] = prb;
        sumv[prb] = n_sumv;
        cnte[prb] = n_cnte;
        sete[prb] = n_sete;
    }
}

