void solve(int L, int R)
{
	ll sum = 0;
	for (int i = L; i <= R; ++ i)
	{
		sum += x[p[i]];
		u[p[i]] = 0;
	}
	for (int i = L; i <= R; ++ i)
	{
		limit[p[i]] = sum;
		tv[p[i]].clear();
		for (auto e : v[p[i]])
		{
			if (e.X <= sum && L <= r[e.Y] && r[e.Y] <= R)
				tv[p[i]].push_back(e);
		}
		v[p[i]] = tv[p[i]];
	}

	int pos = L;
	vector<int> to;
	for (int i = L; i <= R; ++ i)
	{
		if (!u[p[i]])
		{
			queue<int> Q;

			tp[pos] = p[i];
			tr[p[i]] = pos;
			pos ++;

			u[p[i]] = 1;
			Q.push(p[i]);
			while (!Q.empty())
			{
				int x = Q.front();
				Q.pop();
				for (auto y : v[x])
					if (!u[y.Y])
					{
						tp[pos] = y.Y;
						tr[y.Y] = pos;
						pos ++;

						u[y.Y] = 1;
						Q.push(y.Y);
					}
			}
			to.push_back(pos);
		}
	}
	if (to.size() == 1) return;
	for (int i = L; i <= R; ++ i)
	{
		p[i] = tp[i];
		r[i] = tr[i];
	}
	int l = L;
	for (auto r : to)
	{
		solve(l, r-1);
		l = r;
	}
}

