class union_find {
public:
    union_find(int n)
        : par_(n, -1)
    {}
    void init(int n) {
        par_.assign(n, -1);
    }

    int root(int x) {
        return par_[x] < 0 ? x : par_[x] = root(par_[x]);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if(x == y) {
            return false;
        } else {
            if(par_[x] < par_[y]) {
                par_[x] += par_[y];
                par_[y] = x;
            } else {
                par_[y] += par_[x];
                par_[x] = y;
            }
            return true;
        }
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return -par_[root(x)];
    }

private:
    std::vector<int> par_;
};

struct edge {
    int u, v, cost, id;
    bool operator<(const edge& that) const {
        return cost < that.cost;
    }
};

using edges = vector<edge>;
using graph = vector<edges>;

void add_edge(graph& g, int from, int to, int cost, int id) {
    g[from].push_back(edge{from, to, cost, id});
    g[to].push_back(edge{to, from, cost, id});
}

int main() {
    int n, m; cin >> n >> m;
    vector<ll> x(n), sum(n);
    for(int i = 0; i < n; ++i) {
        cin >> x[i];
        sum[i] = x[i];
    }
    edges es(m);
    graph g(n);
    for(int i = 0; i < m; ++i) {
        cin >> es[i].u >> es[i].v >> es[i].cost;
        es[i].id = i;
        es[i].u--, es[i].v--;
        add_edge(g, es[i].u, es[i].v, es[i].cost, i);
    }
    sort(begin(es), end(es));

    vector<bool> cand(m);
    union_find uf(n);
    for(int i = 0; i < m; ++i) {
        int u = uf.root(es[i].u), v = uf.root(es[i].v);
        if(uf.unite(es[i].u, es[i].v)) {
            const ll s = sum[u] + sum[v];
            sum[u] = sum[v] = s;
        }
        u = uf.root(es[i].u);
        if(es[i].cost <= sum[u]) {
            cand[es[i].id] = true;
        }
    }

    reverse(begin(es), end(es));
    vector<bool> used(m), visited(n);
    function<void(int, int)> dfs = [&] (int v, int ub) {
        visited[v] = true;
        for(auto const& e : g[v]) {
            const int to = e.v;
            if(e.cost <= ub) used[e.id] = true;
            if(visited[to] || e.cost > ub) continue;
            dfs(to, ub);
        }
    };
    for(int i = 0; i < m; ++i) {
        if(cand[es[i].id] && !visited[es[i].u]) {
            dfs(es[i].u, es[i].cost);
        }
    }

    cout << count(begin(used), end(used), false) << endl;
}

