struct edge{
  ll u,v,W;
  bool operator < (const edge &a) const {
    return W < a.W;
  }
};
vector<edge> e;
ll w[MAXn];
ll dsu[MAXn],szw[MAXn],sz[MAXn];
ii lr[MAXn];
ll V[MAXn];
ll fnd(ll x){
  if (x == dsu[x]) return x;
  return fnd(dsu[x]);
}
void mrg(ll x,ll y){
  dsu[y] = x;
  szw[x] += szw[y];
  sz[x] += sz[y];
}
int main(){
  IOS();
  ll n,m;
  cin >> n >> m;
  REP (i,n) {
    cin >> w[i];
    dsu[i] = i, szw[i] = w[i], sz[i] = 1;
  }
  REP (i,m) {
    ll u,v,W;
    cin >> u >> v >> W;
    u--,v--;
    e.eb((edge){u,v,W});
    lr[i] = {-1,-1};
  }

  sort(ALL(e));
  REP (i,SZ(e)) {
    ll u = fnd(e[i].u), v = fnd(e[i].v);
    if (u == v) continue;
    debug(e[i].W);
    if (sz[u] < sz[v]) {
      swap(u,v);
      swap(e[i].u,e[i].v);
    }
    V[e[i].v] = v;
    lr[i] = {szw[u],szw[v]};
    mrg(u,v);
  }

  ll ans = 0;
  for (ll i=SZ(e)-1;i>=0;i--) {
    // debug(szw[fnd(e[i].u)]);
    // debug(e[i].u,e[i].v,e[i].W);
    ll u = fnd(e[i].u);
    if (szw[u] >= e[i].W) continue;
    ans++;
    // debug(lr[i]);
    if (lr[i].X == -1) continue;
    // debug(V[e[i].v]);
    dsu[V[e[i].v]] = V[e[i].v];
    szw[V[e[i].v]] = lr[i].Y;
    assert(szw[u] - lr[i].Y == lr[i].X);
    szw[u] = lr[i].X;
    // debug(szw[V[e[i].v]],szw[u]);
  }
  cout << ans << endl;
}

