class UnionFind {
public:
	vector<ll> v;
	UnionFind(size_t size) : v(size, -1) {}

	ll root(ll x) {
		return (v[x] < 0 ? x : v[x] = root(v[x]));
	}

	bool is_root(ll x) {
		return x == root(x);
	}

	bool is_same(ll x, ll y) {
		return root(x) == root(y);
	}

	bool unite(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (v[x] > v[y]) swap(x, y);
		v[x] += v[y];
		v[y] = x;
		return true;
	}

	ll size(ll x) {
		return -v[root(x)];
	}
};
/*-----8<-----library-----8<-----*/

void solve() {
	ll N,M;
	cin>>N>>M;
	vector<ll> X(N,0);
	rep(i,N)cin>>X[i];
	vector<ll> A(M,0),B(M,0),Y(M,0);
	rep(i,M){
		cin>>A[i]>>B[i]>>Y[i];
		A[i]--;B[i]--;
	}

	vector<vector<pair<ll,ll>>> g(N);
	rep(i,M){
		g[A[i]].push_back({B[i],Y[i]});
		g[B[i]].push_back({A[i],Y[i]});
	}

	UnionFind u(N);
	vector<vector<ll>> candidate;
	vector<vector<ll>> v;
	rep(i,M){
		v.push_back({Y[i],A[i],B[i]});
	}
	sort(all(v));

	vector<ll> vpoints(N,0);
	rep(i,N)vpoints[i]=X[i];
	rep(i,M){
		ll av=v[i][1];
		ll bv=v[i][2];
		ll aroot=u.root(av);
		ll broot=u.root(bv);
		ll t;
		if(u.unite(av,bv)){
			ll aaroot=u.root(av);
			ll bbroot=u.root(bv);
			if(aroot==aaroot){
				vpoints[aroot]+=vpoints[broot];
				t=vpoints[aroot];
			}else{
				vpoints[broot]+=vpoints[aroot];
				t=vpoints[broot];
			}
		}else{
			t=vpoints[aroot];
		}

		if(t>=v[i][0])candidate.push_back(v[i]);
	}

	sort(rall(candidate));
	debug(vpoints);
	debug(candidate);

	set<pair<ll,ll>> s;
	auto dfs = [&](auto&& dfs, vector<vector<pair<ll,ll>>> &g, ll v, ll p, ll val) -> void{
		debug(v);
		for(pair<ll,ll> nextv : g[v]){
			ll a=v,b=nextv.first;
			if(a>b)swap(a,b);
			pair<ll,ll> p{a,b};
			if(s.count(p)>0) continue;
			if(nextv.second>val) continue;
			s.insert(p);
			dfs(dfs, g, nextv.first, v, val);
		}

	};

	rep(i,candidate.size()){
		ll a=candidate[i][1];
		ll b=candidate[i][2];
		if(a>b)swap(a,b);
		pair<ll,ll> p{a,b};
		if(s.count(p)==0){
			dfs(dfs, g, a, -1, candidate[i][0]);
		}
	}

	p(M-s.size());

}

signed main() {
	solve();
	return 0;
}

