void make_node(int i,int k){
    dsu[i].par=i;
    dsu[i].mx=0;
    dsu[i].sum=k;
}

int get(int p){
    if (dsu[p].par==p)return p;
    return dsu[p].par=get(dsu[p].par);
}

void unite(int a,int b,ll len){
    a=get(a);
    b=get(b);
    if (a!=b){
        if (dsu[a].sum<dsu[a].mx)qan--;
        if (dsu[b].sum<dsu[b].mx)qan--;
        dsu[a].sum+=dsu[b].sum;
        dsu[a].mx=max(len,max(dsu[a].mx,dsu[b].mx));
        dsu[b].par=a;
    }
    else{
        dsu[a].mx=max(dsu[a].mx,len);
    }
    if (dsu[a].sum<dsu[a].mx)qan++;
}
