class UnionFind{
private:
	::std::vector<int_fast32_t> par;
	::std::vector<int64> sz;
	::std::vector<int64> ok, alle;
	size_t n;

public:
	UnionFind(){}
	UnionFind(size_t n):n(n){
		par.resize(n, -1);
		sz.resize(n);
		ok.resize(n, 0);
		alle.resize(n, 0);
	}

	void set_sz(vector<int64>& a){
		REP(i, sz.size()) sz[i] = a[i];
	}

	uint_fast32_t find(uint_fast32_t x){
		return par[x] < 0 ? x : par[x] = find(par[x]);
	}

	size_t size(uint_fast32_t x){
		return -par[find(x)];
	}

	int64 get_sum(int32 x){
		return sz[find(x)];
	}

	void make_ok(int32 x){
		x = find(x);
		ok[x] = alle[x];
	}

	bool unite(uint_fast32_t x, uint_fast32_t y){
		x = find(x);
		y = find(y);
		if(x == y) { alle[x]++; return false; }
		if(size(x) < size(y)) std::swap(x, y);
		par[x] += par[y];
		sz[x] += sz[y];
		alle[x] += alle[y]+1;
		ok[x] += ok[y];
		par[y] = x;
		return true;
	}

	int64 get_ok(int32 x){
		return ok[find(x)];
	}

	bool same(uint_fast32_t x, uint_fast32_t y){
		return find(x) == find(y);
	}
};

