		if (ran[a] == ran[b])ran[b]++;
	}
	void activate(int a)
	{
		for (int i = 0; i < ko[a].size(); i++)
		{
			if (isact[ko[a][i]])continue;
			activate(ko[a][i]);
			isact[ko[a][i]] = true;
		}
	}
};
