class UnionFind {
public:
    int n;
    std::vector<int> par;
    vll vsum;
    UnionFind(int n) : n(n), par(n, -1), vsum(n) {}

    // 集合の代表を返す
    int find(int x) {
        if (par[x] < 0) return x;
        return par[x] = find(par[x]);
    }
    // x と y が同じ集合に属するかを判別
    bool same(int x, int y) {
        return find(x) == find(y);
    }
    // x が属する集合の大きさを返す
    int size(int x) {
        return -par[find(x)];
    }
    // x と y を結合 (merge した場合に true を返す)
    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (par[px] > par[py]) swap(px, py);
        vsum[px] += vsum[py];
        par[px] += par[py];
        par[py] = px;
        return true;
    }
};

