	ki[v].pb(id);
	for (auto x:com[u]){
		com[v].pb(x);
		par[x] = v;
	}
	for (auto x:ki[u]) ki[v].pb(x);
	ki[u].clear();
	ki[u].shrink_to_fit();
	com[u].clear();
	com[u].shrink_to_fit();
	return 1;
}

bool cmp(edge x, edge y){
	return x.w < y.w;
}

void modify(int id, int ind, int x){
	if (ind == 0) seg[ind][id] = max(seg[ind][id], x), lazy[ind][id] = max(lazy[ind][id], x);
	else seg[ind][id] = min(seg[ind][id], x), lazy[ind][id] = min(lazy[ind][id], x);
}

void shift(int id, int ind){
	modify(id << 1, ind, lazy[ind][id]);
	modify(id << 1 | 1, ind, lazy[ind][id]);
	if (ind == 0) lazy[ind][id] = 0;
	else lazy[ind][id] = 2000000000;
}

void add(int id, int ind, int lq, int rq, int x, int l, int r){
	if (rq <= l || r <= lq) return;
	if (lq <= l && r <= rq){
		//cout << id << endl;
		modify(id, ind, x);
		return;
	}
	int md = (l + r) >> 1;
	shift(id, ind);
	add(id << 1, ind, lq, rq, x, l, md);
	add(id << 1 | 1, ind, lq, rq, x, md, r);
	if (ind == 0) seg[ind][id] = max(seg[ind][id << 1], seg[ind][id << 1 | 1]);
	else seg[ind][id] = min(seg[ind][id << 1], seg[ind][id << 1 | 1]);
}

int get(int id, int ind, int lq, int rq, int l, int r){
	if (rq <= l || r <= lq){
		if (ind == 0) return 0;
		return 2000000000;
	}
	if (lq <= l && r <= rq){
       // cout << lq << ' ' << rq << ' ' << seg[ind][id] << endl;
		return seg[ind][id];
	}
	shift(id, ind);
	int md = (l + r) >> 1;
	if (ind == 0){
		return max(get(id << 1, ind, lq, rq, l, md), get(id << 1 | 1, ind, lq, rq, md, r));
	}
	return min(get(id << 1, ind, lq, rq, l, md), get(id << 1 | 1, ind, lq, rq, md, r));
}

