void double_bfs(int s1, int s2) {
	queue<int> q1;
	queue<int> q2;
	vector<int> seen1 = {s1};
	vector<int> seen2 = {s2};
	vector<int> seen_e1;
	vector<int> seen_e2;
	used[s1] = 1;
	used[s2] = 1;
	q1.push(s1);
	q2.push(s2);
	for (int c = 0; ; c++) {
		if (c & 1) {
			while (!q1.empty()) {
				int v = q1.front();
				int any = 0;
				for (; pnt[v] < (int)g[v].size(); pnt[v]++) {
					if (E[g[v][pnt[v]]].alive == 0) continue;
					int u = E[g[v][pnt[v]]].get(v);
					if (!used[u]) {
						used[u] = 1;
						q1.push(u);
						seen1.push_back(u);
						seen_e1.push_back(g[v][pnt[v]]);
						any = 1;
						break;
					}
				}
				if (!any) {
					q1.pop();
				} else {
					break;
				}
			}
			if (q1.empty()) {
				seen = seen1;
				seen_e = seen_e1;
				break;
			}
		} else {
			// cerr << "go 2 " << endl;
			while (!q2.empty()) {
				int v = q2.front();
				int any = 0;
				// cerr << "pop " << v << endl;
				for (; pnt[v] < (int)g[v].size(); pnt[v]++) {
					if (E[g[v][pnt[v]]].alive == 0) continue;
					int u = E[g[v][pnt[v]]].get(v);
					if (!used[u]) {
						// cerr << "push " << u << endl;
						used[u] = 1;
						q2.push(u);
						seen2.push_back(u);
						seen_e2.push_back(g[v][pnt[v]]);
						any = 1;
						break;
					}
				}
				// cerr << "any " << any << endl;
				if (!any) {
					q2.pop();
				} else {
					break;
				}
			}
			if (q2.empty()) {
				seen = seen2;
				seen_e = seen_e2;
				break;

			}
		}
	}
	for (auto x : seen1) {
		used[x] = 0;
		pnt[x] = 0;
	}
	for (auto x : seen2) {
		used[x] = 0;
		pnt[x] = 0;
	}
}

queue<int> bad_comps;

void split(int ind) {
	E[ind].alive = 0;
	Edge e = E[ind];
	assert(comp[e.u] == comp[e.v]);
	int W = comp[e.u];
	//
	// cerr << "bfs " << e.u << ' ' << e.v << endl;
	double_bfs(e.u, e.v);
	//
	for (auto t : seen) {
		size_comp[comp[t]]--;
		sum_a_comp[comp[t]] -= a[t];
		comp[t] = pnt_c;
		size_comp[comp[t]]++;
		sum_a_comp[comp[t]] += a[t];
	}
	for (auto t : seen_e) {
		edge_comp[W].erase({E[t], t});
		edge_comp[pnt_c].insert({E[t], t});
	}
	edge_comp[W].erase({E[ind], ind});
	if (!edge_comp[W].empty() && sum_a_comp[W] < edge_comp[W].rbegin()->first.w) {
		bad_comps.push(W);
	}
	if (!edge_comp[pnt_c].empty() && sum_a_comp[pnt_c] < edge_comp[pnt_c].rbegin()->first.w) {
		bad_comps.push(pnt_c);
	}
	pnt_c++;
}

