struct UF
{
	int par[SIZE],rank[SIZE];
	ll sz[SIZE];
	int cnt[SIZE];

	void init(int n)
	{
		for(int i=0;i<n;i++)
		{
			par[i]=i;
			rank[i]=1;
			sz[i]=0;
		}
	}
	void ins(int v,ll x)
	{
		sz[v]=x;
	}
	int find(int x)
	{
		if(x==par[x]) return x;
		return par[x]=find(par[x]);
	}
	void unite(int x,int y)
	{
		x=find(x);
		y=find(y);
		if(x==y) return;
		if(rank[x]<rank[y])
		{
