template <class T, class F> T getFirst(T lo, T hi, F f) {
    while (lo < hi) {
        T mid = lo + (hi - lo) / 2;
        if (f(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

template <const int MAXV> struct ConnectedComponentsUF {
    int UF[MAXV], id[MAXV]; vector<vector<int>> components;
    void init(int N) { fill(UF, UF + N, -1); }
    int find(int v) { return UF[v] < 0 ? v : UF[v] = find(UF[v]); }
    bool addEdge(int v, int w) {
        if ((v = find(v)) == (w = find(w))) return false;
        if (UF[v] > UF[w]) swap(v, w);
        UF[v] += UF[w]; UF[w] = v;
        return true;
    }
    bool connected(int v, int w) { return find(v) == find(w); }
    int getSize(int v) { return -UF[find(v)]; }
    void assign(int V) { // assigns ids to each component
        fill(id, id + V, -1); int cnt = 0;
        for (int v = 0; v < V; v++) if (find(v) == v) { id[v] = cnt++; components.emplace_back(1, v); }
        for (int v = 0; v < V; v++) if (id[v] == -1) components[id[v] = id[find(v)]].push_back(v);
    }
    void assign2(const vector<int> &verts) {
        int cnt = 0;
        for (int v : verts) id[v] = -1;
        for (int v : verts) if (find(v) == v) { id[v] = cnt++; components.emplace_back(1, v); }
        for (int v : verts) if (id[v] == -1) components[id[v] = id[find(v)]].push_back(v);
    }
    void clear() { components.clear(); }
};

const int MAXNM = 1e5 + 5;

int N, M;
ll W[MAXNM], sum[MAXNM];
pair<ll, pii> E[MAXNM];
ConnectedComponentsUF<MAXNM> CC1, CC2;
vector<pair<ll, pii>> compEdges[MAXNM];

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(N, M);
    read(W, W + N);
    CC1.init(N);
    FOR(i, M) {
        read(E[i].s, E[i].f);
        CC1.addEdge(--E[i].s.f, --E[i].s.s);
    }
    CC1.assign(N);
    FOR(i, M) compEdges[CC1.id[E[i].s.f]].pb(E[i]);
    int ans = 0;
    FOR(c, sz(CC1.components)) {
        sort(all(compEdges[c]), greater<pair<ll, pii>>());
        auto f = [&] (int ind) {
            FORE(v, CC1.components[c]) CC2.UF[v] = -1;
            For(i, ind, sz(compEdges[c])) CC2.addEdge(compEdges[c][i].s.f, compEdges[c][i].s.s);
            CC2.assign2(CC1.components[c]);
            fill(sum, sum + sz(CC2.components), 0);
            FORE(v, CC1.components[c]) sum[CC2.id[v]] += W[v];
            For(i, ind, sz(compEdges[c]))  if (sum[CC2.id[compEdges[c][i].s.f]] < compEdges[c][i].f) return false;
            return true;
        };
        ans += getFirst(0, sz(compEdges[c]) + 1, f);
    }
    writeln(ans);
    return 0;
}

