template <class T = int>
class UF {
    T *par;

    public:
    UF(T n) : par(new T[n]) {
        for (T i = 0; i < n; i++) par[i] = i;
    }
    ~UF() { delete[] par; }

    T root(T x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool same(T x, T y) {
        return root(x) == root(y);
    }

    void unite(T x, T y) {
        x = root(x);
        y = root(y);
        if (x != y) par[x] = y;
    }
};

