			int C = uf.id(a);
			sum[C] = SA + SB;
			del[C] = DA + DB;
			if(y > sum[C]) { del[C]++; } else { del[C] = 0; }
		} else {
			sum[A] = SA;
			del[A] = DA;
			if(y > sum[A]) { del[A]++; }
		}
	}

	int ans = 0;
	RF(e, del) { ans += e; }

	cout << ans << endl;

	return 0;
}

