		return x;
	return p[x] = find(p[x]);
}


void merge(int x, int y)
{
	x = find(x);
	y = find(y);
	p[x] = y;
	qan[y] += qan[x];
	qanprev[y] += qanprev[x];
	X[y] += X[x];
}

