#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define pb push_back
#define mp make_pair
#define ldb long double
#define mt make_tuple
const int N=1000050;
ll X[N];
ll p[N],sz[N];
vector<ll> E[N];
ll was[N];
ll Find(ll x){ return p[x]==x?x:Find(p[x]);}
void Union(ll x, ll y)
{
	x=Find(x);y=Find(y);
	if(sz[x]<sz[y]) swap(x,y);
	X[x]+=X[y];
	p[y]=x;
	sz[x]+=sz[y];
	E[x].pb(y);
}
void Mark(ll u)
{
	if(was[u]) return;
	was[u]=1;
	//printf("mark:%i\n",u);
	for(ll v:E[u]) if(!was[v]) Mark(v);
}
ll sol,bsol,n,m;
ll U[N],V[N],W[N];
ll XX[N];
void input()
{
	scanf("%lld %lld",&n,&m);
	for(int i=1;i<=n;i++) scanf("%lld",&XX[i]);
	for(int i=1;i<=m;i++) scanf("%lld %lld %lld",&U[i],&V[i],&W[i]);
}
void output()
{
	printf("%lld\n",sol);
}
void Solve()
{
	ll u,v,w;
	for(int i=1;i<=n;i++) sz[i]=1,p[i]=i,X[i]=XX[i],E[i].clear(),was[i]=0;
	vector<pair<ll,pair<ll,ll> > > edges;
	vector<pair<ll,ll> > ws;
	for(int i=1;i<=m;i++) u=U[i],v=V[i],w=W[i],edges.pb(mp(w,mp(u,v)));
	sort(edges.begin(),edges.end());
	for(int i=0;i<edges.size();i++)
	{
		u=edges[i].second.first;
		v=edges[i].second.second;
		//printf("%i %i\n",u,v);
		if(Find(u)!=Find(v)) Union(u,v);
		ws.pb(mp(X[Find(u)],Find(u)));
	}
	int ans=0;
	for(int i=m-1;i>=0;i--)
	{
		u=edges[i].second.first;
		v=edges[i].second.second;
		w=edges[i].first;
		if(w>ws[i].first && !was[u])
		{
			//printf("rem:%i %i\n",u,v);

			ans++;
		}
		else
		{
			Mark(ws[i].second);
		}
	}
	sol=ans;
}
void Run()
{
	input();
	Solve();
	output();
}
void BruteForce()
{
	bsol=m;
	for(int mask=0;mask<1<<m;mask++)
	{
		for(int i=1;i<=n;i++) p[i]=i,sz[i]=1,X[i]=XX[i];
		for(int i=1;i<=m;i++) if((mask>>(i-1))&1)
		{
			if(Find(U[i])!=Find(V[i])) Union(U[i],V[i]);
		}
		bool ok=1;
		int cnt=0;
		for(int i=1;i<=m;i++) if((mask>>(i-1))&1)
		{
			if(W[i]>X[Find(U[i])]) ok=0;
			cnt++;
		}
		if(ok) bsol=min(bsol,m-cnt);
	}
}
void MakeTestCase()
{
	n=rand()%10+1;
	m=rand()%10+n-1;
	for(int i=1;i<=n;i++) XX[i]=rand()%100+1;
	m=min(m,n*(n-1)/2);
	set<pair<int,int>> st;
	for(int i=1;i<=m;i++)
	{
		U[i]=rand()%n+1,V[i]=rand()%n+1;
		if(U[i]>V[i]) swap(U[i],V[i]);
		W[i]=rand()%100+1;
		while(U[i]==V[i] || st.count(mp(U[i],V[i])))
		{
			U[i]=rand()%n+1,V[i]=rand()%n+1;
			if(U[i]>V[i]) swap(U[i],V[i]);
		}
	}
}
bool Compare()
{
	return sol==bsol;
}
void Print()
{
	printf("%i %i\n",n,m);
	for(int i=1;i<=n;i++) printf("%i ",XX[i]);
	printf("\n");
	for(int i=1;i<=m;i++) printf("%i %i %i\n",U[i],V[i],W[i]);
	printf("Solve: %i\n",sol);
	printf("Brute: %i\n",bsol);
}
double GetTime(){ return (ldb)clock()/CLOCKS_PER_SEC;}
double s_time,e_time,d_time;
void Start(){ s_time=GetTime();}
void Stop(){ e_time=GetTime();d_time=e_time-s_time;}
void Test()
{
	srand(time(0));
	cout<<fixed<<setprecision(4);
	int work=100000;
	double max_time=0;
	bool speed_only=0;
	for(int i=1;i<=work;i++)
	{
		MakeTestCase();
		if(!speed_only) BruteForce();
		Start();
		Solve();
		Stop();
		if(!speed_only && !Compare())
