const ll INF = 1LL<<60;

struct UnionFind {
    vector<ll> par, s, w;
    UnionFind(int n, vector<ll> a) : w(a) { 
        s.assign(n, 1); par.resize(n); 
        iota(par.begin(), par.end(), 0);

    }
    int find(int x) {
        if(par[x] == x) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(s[x] < s[y]) par[x] = y, s[y] += s[y], w[y] += w[x];
        else par[y] = x, s[x] += s[y], w[x] += w[y];
    }
    bool same(int x, int y) { return find(x) == find(y); }
    int size(int x) { return s[find(x)]; }
    int weight(int x) { return w[find(x)]; }
};

int main(void) {
    ll n, m;
    cin >> n >> m;
    vector<ll> x(n);
    REP(i, n) cin >> x[i];
    vector<ll> a(m), b(m), y(m);
    vector<vector<PII>> g(n);
    REP(i, m) {
        cin >> a[i] >> b[i] >> y[i];
        a[i]--, b[i]--;
        g[a[i]].push_back({b[i], y[i]});
        g[b[i]].push_back({a[i], y[i]});
    }

    vector<ll> ord(m);
    iota(ALL(ord), 0LL);
    sort(ALL(ord), [&](ll l, ll r){ return y[l] < y[r]; });

    // 重みがy[i]以下の辺が全て追加された状態 
    // 辺iが属する連結成分の頂点重みがy[i]以上 → iから重みy[i]以下の辺をたどって到達できる辺は残せる 
    vector<ll> ok;
    UnionFind uf(n, x);
    for(auto i: ord) {
        uf.unite(a[i], b[i]);
        if(uf.weight(a[i]) >= y[i]) ok.push_back(i);
    }

    // 残せる辺の和集合を取る
    ll ret = 0;
    vector<bool> used(n);
    function<void(ll,ll)> dfs = [&](ll v, ll ub) {
        used[v] = true;
        for(auto to: g[v]) {
            if(to.second <= ub) {
                ret++;
                if(!used[to.first]) dfs(to.first, ub);
            }
        }
    };
    reverse(ALL(ok));
    for(auto i: ok) {
        if(!used[a[i]]) dfs(a[i],y[i]);
        if(!used[b[i]]) dfs(b[i],y[i]);
    }

    cout << m-ret/2 << endl;    

    return 0;
}

#include<bits/stdc++.h>
#define maxl 100010

using namespace std;

int n,m,ans;
int a[maxl];
struct ed
{
	int u,v,val;
}e[maxl];
int f[maxl],cnt[maxl];
long long sum[maxl];

inline bool cmp(const ed &x,const ed &y)
{
	return x.val<y.val;
}

inline void prework()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
		f[i]=i;cnt[i]=0;sum[i]=a[i];
	}
	for(int i=1;i<=m;i++)
		scanf("%d%d%d",&e[i].u,&e[i].v,&e[i].val);
	sort(e+1,e+1+m,cmp);
}

inline int find(int x)
{
	if(f[x]!=x)
	{
		f[x]=find(f[x]);
		cnt[f[x]]+=cnt[x];
		sum[f[x]]+=cnt[x];
		sum[x]=cnt[x]=0;
	}
	return f[x];
}

inline void mainwork()
{
	int x,y,xx,yy;
	for(int i=1;i<=m;i++)
	{
		x=e[i].u;y=e[i].v;
		xx=find(x);yy=find(y);
		if(xx!=yy)
		{
			cnt[xx]+=cnt[yy]+1;
			sum[xx]+=sum[yy];
			f[yy]=xx;
			sum[yy]=0;cnt[yy]=0;
			if(sum[xx]>=e[i].val)
			{
				ans+=cnt[xx];
				cnt[xx]=0;
			}
		}
		else
		{
			cnt[xx]++;
			if(sum[xx]>=e[i].val)
			{
				ans+=cnt[xx];
				cnt[xx]=0; 
			}
		}
	}
}

inline void print()
{
	printf("%d",m-ans);
}

int main()
{
	prework();
	mainwork();
	print();
	return 0;
}

