class UF {
private:
    int sz; vector<int> par,nrank;
public:
    vector<ll> weight;
    UF(){}
    UF(int node_size){ sz = node_size; par.resize(sz),nrank.resize(sz,0); weight.resize(sz, 0); rep(i,sz) par[i] = i; }
    int find(int x){ if(par[x] == x){ return x; }else{ return par[x] = find(par[x]); } }
    void unite(int x,int y){
        x = find(x),y = find(y); if(x == y) return;
    	if(nrank[x] < nrank[y]) swap(x,y); weight[x] += weight[y]; par[y] = x; if(nrank[x] == nrank[y]) nrank[x]++; }
    bool same(int x,int y){ return find(x) == find(y); }
};

struct edge
{
    int from, to;
    ll cost;
    bool operator< (const edge& another) const {
        return cost < another.cost;
    };
};

vector<int> G[MAX_N];
bool used[2*MAX_N];
int ver[2*MAX_N];
int ans = 0;

void dfs(int u)
{
    ans++;
    each(v, G[u]){
        if(!used[v]){
            dfs(v);
        }
    }
}

