void dfs2(int cur) {
	if(cur<N) return;
	ok[E[cur][0]]=1;
	dfs2(E[cur][1]);
	dfs2(E[cur][2]);
}

void dfs(int cur) {
	if(cur<N) return;

	if(Y[E[cur][0]]<=X[cur]) {
		dfs2(cur);
	}
	else {
		ok[E[cur][0]]=-1;
		dfs(E[cur][1]);
		dfs(E[cur][2]);
	}
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>M;
	FOR(i,N) {
		cin>>X[i];
		top[i]=i;
	}
	FOR(i,M) {
		cin>>A[i]>>B[i]>>Y[i];
		A[i]--;
		B[i]--;
		P[i]={Y[i],i};
	}

	sort(P,P+M);
	int cur=N;
	FOR(i,M) {
		x=P[i].second;
		int a=top[uf[A[x]]];
		int b=top[uf[B[x]]];
		if(a!=b) {
			E[cur]={x,a,b};
			X[cur]=X[a]+X[b];
			uf(A[x],B[x]);
			top[uf[A[x]]]=cur;
			cur++;
		}
	}

	dfs(cur-1);
	uf.reinit();

	int ret=0;
	FOR(i,M) {
		x=P[i].second;
		int a=uf[A[x]];
		int b=uf[B[x]];
		if(ok[x]==1) {
			X[a]=X[b]=X[a]+X[b];
			uf(a,b);
		}
		else if(ok[x]==-1) {
			ret++;
		}
	}
	FOR(i,M) {
		x=P[i].second;
		int a=uf[A[x]];
		if(ok[x]==0 && Y[x]>X[a]) {
			ret++;
		}
	}
	cout<<ret<<endl;

}


