}
inline void merge(int x,int y)
{
	x=find(x);y=find(y);
	if(x==y)
		return;
	dis[x]=y;a[y]+=a[x];
	return;
}
void dfs(int x,int w)
{
	register int i;
	for(auto c:V[x])
		if(c.w<=w&&!bk[c.u]&&!book[c.v])
			bk[c.u]=1,book[c.v]=1,dfs(c.v,w);
