    sort(edges.begin(), edges.end());
    int ret = 0;
    for (int i = 0; i < m; ++i) {
        int cost = edges[i].first;
        pii edge = edges[i].second;
        uf.unite(edge.first, edge.second);
        uf.add(edge.first, 1);
        if (cost <= uf.getSize(edge.first)) {
            ret += uf.getCnt(edge.first);
            uf.clr(edge.first);
        }
    }
    cout << m - ret << "\n";
