    }

    int root(int x) {
        return roots[x];
    }

    void unite(int x, int y) {
        int rootX = roots[x];
        int rootY = roots[y];
        if (rootX == rootY) return;
        if (children[rootX].size() < children[rootY].size()) {
            for (int child : children[rootX]) {
                roots[child] = roots[rootY];
            }
            children[rootY].insert(children[rootY].end(), all(children[rootX]));
            children[rootX].clear();
            hangEdges[rootY].insert(all(hangEdges[rootX]));
            hangEdges[rootX].clear();
            sums[rootY] += sums[rootX];
        } else {
            for (int child : children[rootY]) {
                roots[child] = roots[rootX];
            }
            children[rootX].insert(children[rootX].end(), all(children[rootY]));
            children[rootY].clear();
            hangEdges[rootX].insert(all(hangEdges[rootY]));
            hangEdges[rootY].clear();
            sums[rootX] += sums[rootY];
        }
    }

    bool same(int x, int y) {
        return roots[x] == roots[y];
    }

    int count(int x) {
        return sums[roots[x]];
    }

    void hang(int x, int weight) {
        hangEdges[roots[x]].insert(weight);
    }

    int open(int x) {
        int rootX = roots[x];
        int cnt = count(rootX);

        int ret = 0;
        auto it = hangEdges[rootX].begin();
        while (it != hangEdges[rootX].end()) {
            int w = *it;
            if (w > cnt) break;
            ret++;
            it++;
        }
        hangEdges[rootX].erase(hangEdges[rootX].begin(), it);

        return ret;
    }
};

