		return w < other.w;
	}
};

struct Dsu {
	int n;
	vector<int> p;
	vector<int> rank;

	Dsu() {}

	Dsu(int n_) {
		n = n_;
		p.resize(n);
		iota(p.begin(), p.end(), 0);
		rank.resize(n);
	}

	int get(int v) {
		if (p[v] != v) {
			p[v] = get(p[v]);
		} 
		return p[v];
	}

	int merge(int a, int b) {
		a = get(a);
		b = get(b);
		if (a == b) {
			return 0;
		} else {
			if (rank[a] < rank[b]) {
				swap(a, b);
			}
			p[b] = a;
			if (rank[a] == rank[b]) {
				rank[a]++;
			}
			return 1;
		}
	}
};

const int N = 1e5 + 2;

