struct UnionFind {
    vector<int> par;
    vector<long long> w;

    UnionFind(int n, vector<long long> w) : par(n, -1), w(w) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        w[x] += w[y];
        return true;
    }

    long long get(int x) {
        x = root(x);
        return w[x];
    }

    int size(int x) {
        return -par[root(x)];
    }
};


