// UnionFind木
// unite()で2つの集合を1つに統合する
// find()で2つの集合が同じ集合かどうかわかる
// root()で集合の識別番号(その集合のルートの番号)を求められる
struct UnionFind{

	std::vector<int> data;
	// dataの各要素について
	// 負の値:その集合のルートであること示す。また、その絶対値は集合の要素数となっている。
	// 正の値:親ノードの番号(dataのインデックス)。root()を呼び出すたびに集合のルートを指すように書きなおされるので木はそんなに深くならない
	std::vector<ll> Value;

	//初期化 size:最大要素数
	UnionFind(int size, vector<ll> val): data(size, -1), Value(val) {}

	// 集合を併合する
	// すでに同じ集合だった場合は、falseが返る
	bool unite(int x, int y){
		x=root(x);
		y=root(y);
		if( x != y ){
			// 要素数の大きな方へ合併するためのswap
			if( data[y] < data[x] ) std::swap(x, y);
			// 要素数を加算する
			data[x] += data[y];
			// yの属する集合のルートをxに変更
			data[y] = x;
			//
			Value[x] += Value[y];
		}
		return x!=y;
	}

	// 同じ集合かどうか判定
	bool find(int x, int y){
		return root(x) == root(y);
	}

	// 集合の識別番号を返す
	int root(int x){
		// 負の値を持つものがその集合のルート
		// 正の値は同じ集合に属するものを指す(辿ればいずれルートへ着く)
		return (data[x] < 0)? x : data[x]=root(data[x]);
	}

	// 集合の要素数を返す
	int size(int x){
		return -data[ root(x) ];
	}

	ll value(int x){
		return Value[root(x)];
	}
};


int main(){
	ios_base::sync_with_stdio(false);
	ll N, M, ans=0;
	ll A[100005], B[100005], Y[100005];
	vector<pair<ll,pii>> v;

	cin >> N >> M;
	vector<ll> X(N);
	rep(i,N) cin >> X[i];
	rep(i,M){
		cin >> A[i] >> B[i] >> Y[i];
		A[i]--;
		B[i]--;
		v.emplace_back(Y[i], pii(A[i], B[i]));
	}

	sort(all(v));

	UnionFind uf(N, X);
	pll cut[100005] = {};
	vector<pair<int,UnionFind>> st;
	st.emplace_back(-1,uf);
	auto push_st = [&](int i, UnionFind &uf, int N){
		int pcount = __builtin_popcount(N-i);
		//int d = 1;
		//while( st.size() > 1 ){
		//	int l = st.size()-1;
		//	if( st[l].X - st[l].X == d ) st.pop_back();
		//	else break;
		//	d *= 2;
		//}
		while( st.size() && st.back().X >= i ) st.pop_back();
		if(pcount == 1) st.emplace_back(i, uf);
	};
	rep(i,M){
		pii p = v[i].Y;
		if( !uf.find(p.X, p.Y) ){
			cut[i] = pll(uf.value(p.X), uf.value(p.Y));
		}
		uf.unite(p.X, p.Y);
		push_st(i, uf, N);
	}

	bool safe[100005] = {};
	rrep(i,M){
		pii p = v[i].Y;
		if( uf.value(p.X) >= v[i].X ){
			safe[uf.root(p.X)] = true;
		}else if( !safe[uf.root(p.X)] ){
			ans++;
			while( st.size() && st.back().X >= i ) st.pop_back();
			uf = st.back().Y;
			for(int j=st.back().X; j<i; j++){
				pii p = v[j].Y;
				uf.unite(p.X, p.Y);
				push_st(j, uf, i);
			}
		}
	}

	cout << ans << endl;

	return 0;
}

