struct UnionFind {
    vector<int> par;
    vector<P> size;
    UnionFind(int x,vector<int> y) {
        par.resize(x);
        size.resize(x);
        for(int i = 0; i < x; i++) {
            par[i] = i;
        }
        for(int i = 0; i < x; i++) {
            size[i].first = 0;
            size[i].second = y[i];
        }
    }
    int find(int x) {
        if (par[x] == x)
            return x;
        return par[x] = find(par[x]);
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
    P consize(int x) {
        return {size[find(x)].first,size[find(x)].second};
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (size[x] < size[y]) {
            par[x] = y;
            size[y].first += size[x].first;
            size[y].second += size[x].second;
        }
         else {
            par[y] = x;
            size[x].first += size[y].first;
            size[x].second += size[y].second;
        }
    }
};
