struct UF{
    int par[MAX_N];
    int sizes[MAX_N];
    ll c[MAX_N];
    void init (int n){
        for (int i=0;i<n;i++){
            par[i]=i;
            sizes[i]=1;
            c[i]=X[i];
        }
    }
    int find (int x){
        if (par[x]==x){
            return x;
        }
        else{
            return par[x] = find(par[x]);
        }
    }
    void unite (int x, int y){
        x=find(x);
        y=find(y);
        if (x==y) return;
        if (sizes[x] < sizes[y]) swap(x,y);
        par[y]=x;
        sizes[x]+=sizes[y];
        c[x]+=c[y];
    }
    bool same (int x, int y){
        return find(x) == find(y);
    }
    int size(int x){
        return sizes[find(x)];
    }
};
