void make_set (int v) {
    parent[v] = v;
    rankk[v] = 0;
    sum[v] = w[v];
    bad[v] = 0;
}

int find_set (int v) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set (parent[v]);
}

void union_sets (int a, int b) {
    a = find_set (a);
    b = find_set (b);
    if (a != b) {
        if (rankk[a] < rankk[b])
            swap (a, b);
        parent[b] = a;
        if (rankk[a] == rankk[b])
            ++rankk[a];
        sum[a] += sum[b];
        bad[a] += bad[b];
    }
}

