class UnionFind
{
  public:
	explicit UnionFind(int size)
		: mParent(size, -1)
		, mRank(size, 0)
        , mData(size, 0)
		{}
	bool unionSet(int x, int y)
	{
		if ((x = root(x)) == (y = root(y)))
			return false;
		if( mRank[x] < mRank[y] )
		{
			mParent[y] += mParent[x];
			mParent[x] = y;
            unionData( mData[y], mData[x] );
		}
		else
		{
			mParent[x] += mParent[y];
			mParent[y] = x;
			if( mRank[x] = mRank[y] ) ++mRank[x];
            unionData( mData[x], mData[y] );
		}
		return true;
	}
	bool isEqualSet(int x, int y)
	{
		return root(x) == root(y);
	}
	int root(int x)
	{
		return mParent[x] < 0 ? x : mParent[x] = root(mParent[x]);
	}
	int size(int x)
	{
		return -mParent[root(x)];
	}

    void unionData( int& parent, int& child )
    {
        parent += child;
    }
    void setData( int x, int data )
    {
        mData[root(x)] = data;
    }
    int getData( int x )
    {
        return mData[root(x)];
    }

  public:
	vector<int> mParent; // = mSize
	vector<int> mRank;
	vector<int> mData;
};

struct St{
    int a = 0;
    int b = 0;
    int y = 0;
    bool is = false;
    bool iss = false;
};
bool operator<(const St& l, const St& r)
{ return l.y < r.y; }
bool operator>(const St& l, const St& r)
{ return l.y > r.y; }

int main()
{
    int n, m;
    cin >> n >> m;
    VEC(int, n, x, 0);
    REP(i,n) cin >> x[i];

    vector<St> edgeSt(m);
    REP( i, m )
    {
        cin >> edgeSt[i].a >> edgeSt[i].b >> edgeSt[i].y;
        edgeSt[i].a--;
        edgeSt[i].b--;
    }

    sort( edgeSt.begin(), edgeSt.end() );

    UnionFind uf( n );
    REP( i, n ) uf.setData( i, x[i] );
    REP( i, m )
    {
        uf.unionSet( edgeSt[i].a, edgeSt[i].b );
        int d = uf.getData( edgeSt[i].a );
        if( d >= edgeSt[i].y ) edgeSt[i].is = true;
    }

    sort( edgeSt.begin(), edgeSt.end(), greater<St>() );

    vector< vector<St*> > edge(n);
    REP( i, m )
    {
        edge[edgeSt[i].a].push_back( &edgeSt[i] );
        edge[edgeSt[i].b].push_back( &edgeSt[i] );
    }

    int ans = 0;
    REP( i,m )
    {
        if( edgeSt[i].iss ) { continue; }
        if( !edgeSt[i].is ) { ++ans; continue; }

        stack<int> st;
        VEC( bool, n, used, false );
        st.push( edgeSt[i].a ); used[edgeSt[i].a] = true;
        st.push( edgeSt[i].b ); used[edgeSt[i].b] = true;

        while( st.size() )
        {
            int t = st.top(); st.pop();
            for( auto pst : edge[t] )
            {
                if( !used[pst->b] && pst->y <= edgeSt[i].y )
                {
                    used[pst->b] = true;
                    pst->iss = true;
                    st.push( pst->b );
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

