	RREP(i, m) {
		if (b[i] == 0) {
			ans++;
			continue;
		}
		queue<int> q;
		q.push(e[i].from);
		while (!q.empty()) {
			int p = q.front();
			q.pop();
			REP(i, g[p].size()) {
				if (e[i].cost < g[p][i].cost)continue;
				b[g[p][i].index] = 1;
				if (visited[g[p][i].to] == 0) {
					q.push(g[p][i].to);
					visited[g[p][i].to] = 1;
				}
			}
		}
	}
	cout << ans << endl;
}

