    node() {}
    node(ll a, ll b, ll c) : to(a), cost(b), idx(c) {}
  };
  vector<vector<node>> g(n);
  REP(i, m) {
    cin >> a[i] >> b[i] >> c[i], a[i]--, b[i]--;
    g[a[i]].push_back(node(b[i], c[i], i));
    g[b[i]].push_back(node(a[i], c[i], i));
  }

  vector<ll> idx(m);
  iota(ALL(idx), 0);
  sort(ALL(idx), [&](ll l, ll r){
    return c[l] < c[r];
  });

  // idx順に追加していく
  stack<ll> st;
  UnionFind uf(n);
  REP(i, n) uf.cost[i] = x[i];
  REP(i, m) {
    uf.unite(a[idx[i]], b[idx[i]]);
    ll cost = uf.cost[uf.find(a[idx[i]])];
    if(cost >= c[idx[i]]) {
      st.push(idx[i]);
