void Union(int u,int v){
	if (rk[u]<rk[v]) swap(u,v);
	++tot;A[tot]=u;B[tot]=v;C[tot]=rk[u]==rk[v];
	f[v]=u;rk[u]+=C[tot];g[u]+=g[v];
}
int main(){
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;i++)
		scanf("%d",&a[i]);
