class union_find {
private:
    vector<int> parent, rank, gs;
    int size;

public:
    int count_group;
    union_find() = default;
    union_find(int n) { init(n); }

    void init(int n) {
        size = n;
        count_group = n;
        parent.resize(size);
        rank.assign(size, 0);
        gs.assign(size, 1);
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x)
            return x;
        else
            return parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            parent[x] = y;
            gs[y] += gs[x];
        } else {
            parent[y] = x;
            gs[x] += gs[y];
            if (rank[x] == rank[y]) ++rank[x];
        }
        --count_group;
    }

    bool is_same_group(int x, int y) {
        return find(x) == find(y);
    }

    int group_size(int x) {
        return gs[find(x)];
    };
};

void solve() {
    //const i64 mod = 1'000'000'007;
    i64 N,M;
    cin >> N >> M;

    vector<i64> X(N);
    i64 sumx=0;
    rep(i,0,N){
        cin >> X[i];
        sumx+=X[i];
    }

    using tup=tuple<i64,i64,i64>;
    vector<i64> A(M),B(M),Y(M);
    map<i64,vector<pair<i64,i64>>> edges;
    i64 maxy=0;
    rep(i,0,M){
        cin >> A[i] >> B[i] >> Y[i];
        --A[i];
        --B[i];
        edges[Y[i]].emplace_back(make_pair(A[i],B[i]));
        maxy=max(maxy,Y[i]);
    }


    i64 ans=M;
    union_find uf(N);
    vector<i64> sum(N),maxi(N);
    rep(i,0,N){
        sum[i]=X[i];
    }

    i64 cnt=0;

    for(auto &tmp:edges){
        vector<pair<i64,i64>> x,y;
        i64 c=tmp.first;
        for(auto &e:tmp.second){
            i64 u=e.first,v=e.second;
            if(uf.is_same_group(u,v)){
                x.push_back(make_pair(u,v));
            }else{
                y.push_back(make_pair(u,v));
            }
        }
        for(auto &e:y){
            i64 u=uf.find(e.first),v=uf.find(e.second);
            if(u!=v) {
                i64 su = sum[u], sv = sum[v];
                i64 ma = max({maxi[u], maxi[v], c});
                uf.unite(u, v);
                i64 w = uf.find(u);
                sum[w] = su + sv;
                maxi[w] = ma;
                ++cnt;
                if (sum[w] >= maxi[w]) ans = M - cnt;
            } else{
                i64 u=uf.find(e.first);
                maxi[u]=max(maxi[u],c);
                ++cnt;
                if(sum[u]>=maxi[u]) ans=M-cnt;
            }
        }
        for(auto &e:x){
            i64 u=uf.find(e.first);
            maxi[u]=max(maxi[u],c);
            ++cnt;
            if(sum[u]>=maxi[u]) ans=M-cnt;
        }
    }

    cout << ans << endl;
}

