void solve() {
	sort(allof(edge));

	vector< int > par(N, -1);
	vector< lint > w(N, -1), ew(N, -1);
	vector< vector< int > > group(N, vector< int >());

	//
	for (int v=0; v<N; ++v) {
		par[v] = v;
		w[v] = X[v];
		ew[v] = 0;
		group[v] = {v};
	}

	int BORDER_i = 0, violate = 0;
	for (int i=0; i<M; ++i) {
		Edge e = edge[i];

		int pu = par[e.u];
		int pv = par[e.v];

		if (pu != pv) {
			if (group[pu].size() > group[pv].size()) swap(pu, pv);
			if (ew[pv] > w[pv]) --violate;
			if (ew[pu] > w[pu]) --violate;

			w[pv] += w[pu];
			for (int v : group[pu]) {
				par[v] = pv;
				group[pv].push_back(v);
			}

			ew[pv] = max(ew[pv], ew[pu]);
			ew[pv] = max(ew[pv], e.Y);
			if (ew[pv] > w[pv]) ++violate;
		}

		if (violate == 0) BORDER_i = i+1;
	}

	//
	for (int v=0; v<N; ++v) {
		par[v] = v;
		w[v] = X[v];
		ew[v] = 0;
		group[v] = {v};
	}

	for (int i=0; i<BORDER_i; ++i) {
		Edge e = edge[i];

		int pu = par[e.u];
		int pv = par[e.v];

		if (pu != pv) {
			if (group[pu].size() > group[pv].size()) swap(pu, pv);
			w[pv] += w[pu];
			for (int v : group[pu]) {
				par[v] = pv;
				group[pv].push_back(v);
			}
		}
	}

	int ans = M - BORDER_i;
	for (int i=0; i<BORDER_i; ++i) {
		Edge e = edge[i];
		int pu = par[e.u];
		int pv = par[e.v];
		if (pu != pv) ++ans;
		else {
			if (w[pv] < e.Y) ++ans;
		}
	}
	cout << ans << endl;
}



