ll a[101010];
struct ppUF{
   vector<int> par,ti;
   vector<ll> cost;
   vector<vector<pint>> his;
   vector<vector<pair<ll,ll>>> costhis;
   ppUF(int n):ti(n,inf+1),par(n,-1),his(n),cost(n),costhis(n){
       for(auto &vs:his)vs.emplace_back(-1,-1);
       rep(i,n)costhis[i].emplace_back(-1,a[i]);
       rep(i,n)cost[i]=a[i];

   }
   int find(int t,int x){
       if(ti[x]>t)return x;
       return find(t,par[x]);
   }

   bool unite(int t,int x,int y){
       x=find(t,x);y=find(t,y);
       if(x==y)return false;
       if(par[x]>par[y])swap(x,y);
       par[x]+=par[y];
       cost[x]+=cost[y];
       his[x].emplace_back(t,par[x]);
       costhis[x].emplace_back(t,cost[x]);
       par[y]=x;
       ti[y]=t;
       return true;
   }

   bool same(int t,int x,int y){
       return find(t,x)==find(t,y);
   }
   int time(int x,int y){
       if(!same(inf,x,y))return -1;
       int ok=inf,ng=-1,mid=0;
       while(ok-ng>1){
           mid=(ok+ng)/2;
           if(same(mid,x,y))ok=mid;
           else ng=mid;
       }
       return ok;
   }

   int size(int t,int x){
       x = find(t,x);
       return -prev(lower_bound(his[x].begin(),his[x].end(),pint(t,0)))->second;
   }

   ll sum(int t,int x){
       x = find(t,x);
       return prev(lower_bound(costhis[x].begin(),costhis[x].end(),pair<ll,ll>{t,longinf}))->second;
   }
};

int main(){
