    rep(i,n)cin>>a[i];
    int l[m], r[m], w[m];
    rep(i,m){
        cin>>l[i]>>r[i]>>w[i];
        --l[i];
        --r[i];
    }
    vector<int> ord(m);
    iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int x,int y){
        return w[x]<w[y];
    });
    ppUF uf(n);
    rep(i,m){
        uf.unite(i+1,l[ord[i]],r[ord[i]]);
    }
    reverse(ord.begin(),ord.end());
    int ans=0;
    int Time=m;
    rep(i,m){
        int x =uf.find(Time,l[ord[i]]);
        if(uf.sum(Time,x)>=w[ord[i]])continue;
        ++ans;
        Time = m-i-1;
    }
    cout<<ans<<endl;
    return 0;
}

