struct UnionFind{
    vector<int> par,rank,ss;
    int size;
    vector<ll> nsum, ec,oec;
    UnionFind(int n):size(n){
        par=vector<int>(n);iota(ALL(par),0);
        rank = vector<int>(n);ss=vector<int>(n,1);
        ec = vector<ll>(n); oec = vector<ll>(n);
    }
    int root(int x){
      return par[x] = par[x] == x ? x: root(par[x]);
    }
    bool same(int x,int y){
      return root(x) == root(y);
    }
    void unite(int x,int y){
        x = root(x);y = root(y);
        if(x==y)return;
        if(rank[x]>rank[y])swap(x,y);
        par[x] = y;ss[y]+=ss[x]; nsum[y] += nsum[x]; ec[y] += ec[x]; oec[y] += oec[x];
        if(rank[x] == rank[y]) rank[x]++;
        size--;
    }
    int getS(int x){
      return ss[root(x)];
    }
};


