struct UnionFind {
    vector<int> par, w, sum;

    UnionFind(int n, vector<int> x) : par(n, -1), w(n, 0) { sum = x; }
    void init(int n) { par.assign(n, -1); w.assign(n, 0); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) {
            ++w[x];
            return false;
        }
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        sum[x] += sum[y];
        par[y] = x;
        w[x] += w[y];
        ++w[x];
        return true;
    }

    int xsum(int x) {
        return sum[root(x)];
    }

    int size(int x) {
        return -par[root(x)];
    }

    int wei(int x) {
        return w[root(x)];
    }
};

int n, m;
vector<int> x;
vector<vector<P>> g;

typedef pair<int, pair<int, int>> P2;

map<pair<int, int>, int> mp;

vector<bool> ok;

void dfs(int v, int val) {
    for(P e: g[v]) {
        if(e.sc <= val && !ok[mp[{v, e.fr}]]) {
            ok[mp[{v, e.fr}]] = 1;
            dfs(e.fr, val);
        }
    }
}

void solve() {
	cin >> n >> m;
    x.resize(n);
    rep(i, n) {
        cin >> x[i];
    }
    g.assign(n, vector<P>());
    vector<P2> es(m);
    rep(i, m) {
        int a, b, y; cin >> a >> b >> y;
        -- a, -- b;
        g[a].pb({b, y});
        g[b].pb({a, y});
        es[i] = {y, {a, b}};
    }
    UnionFind uf(n, x);
    sort(all(es));
    rep(i, m) {
        mp[{es[i].sc.fr, es[i].sc.sc}] = i;
        mp[{es[i].sc.sc, es[i].sc.fr}] = i;
    }
    vector<bool> cand(m, 0);
    rep(i, m) {
        int val = es[i].fr, a = es[i].sc.fr, b = es[i].sc.sc;
        uf.merge(a, b);
        if(uf.xsum(a) >= val) {
            cand[i] = 1;
        }
    }
    ok.assign(m, 0);
    per(i, m) {
        if(cand[i]) {
            if(!ok[i]) {
                dfs(es[i].sc.fr, es[i].fr);
            }
        }
    }
    int cnt = 0;
    rep(i, m) {
        if(!ok[i]) ++ cnt;
    }
    cout << cnt << endl;
}

