            size[Y]+=size[X];
            sum[Y]+=sum[X];
        }
        edge[i]=std::make_tuple(Z,X,Y);
    }
    reverse(ALL(mem));
    for(auto p:mem){
        ll X,Y,Z; std::tie(Z,X,Y)=edge[p];
        if(par[X]==Y) std::swap(X,Y);
        ll now=X;
        while(par[now]!=now) now=par[now];
        if(sum[now]<Z){
            par[Y]=Y;
            now=X;
            while(par[now]!=now){
                sum[now]-=sum[Y];
                now=par[now];
            }
            sum[now]-=sum[Y];
        }
    }
    ll ans=0;
    rep(i,0,M){
        ll X,Y,Z; std::tie(Z,X,Y)=edge[i];
        while(par[X]!=X) X=par[X];
        while(par[Y]!=Y) Y=par[Y];
        if(X==Y&&sum[X]>=Z){
            ans++;
        }
    }
    cout<<M-ans<<endl;
}

