struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  vector<ll> sum;
  UnionFind(const vector<ll>& vs)
      : parent(vs.size(), -1), sum(vs){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    sum[u] += sum[v];
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
  ll query(int x) {
    return sum[root(x)];
  }
};

struct Edge {
  int id, A, B;
  ll Y;
};

int main() {
  int N, M;
  while (cin >> N >> M) {
    vector<ll> X(N);
    for (int i = 0; i < N; i++) cin >> X[i];
    vec<Edge, 2> G(N);
    vector<Edge> edges;
    for (int i = 0; i < M; i++) {
      int A, B;
      ll Y;
      cin >> A >> B >> Y;
      --A;
      --B;
      G[A].push_back({i, A, B, Y});
      G[B].push_back({i, B, A, Y});
      edges.push_back({i, A, B, Y});
    }
    sort(edges.begin(), edges.end(), [&](auto& a, auto& b) {
      return a.Y < b.Y;
    });
    UnionFind uf(X);
    vector<Edge> remains;
    for (auto& e : edges) {
      uf.unite(e.A, e.B);
      if (uf.query(e.A) >= e.Y) {
        remains.push_back(e);
      }
    }
    vector<int> used(M, 0);
    function<void(int, ll)> dfs = [&](int v, ll c) {
      for (auto& e : G[v]) {
        if (e.Y <= c && !used[e.id]) {
          used[e.id] = 1;
          dfs(e.B, c);
        }
      }
    };
    reverse(remains.begin(), remains.end());
    for (auto& e : remains) dfs(e.A, e.Y);
    int res = count(used.begin(), used.end(), 0);
    cout << res << endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

class unionfind{
    int last;
    int *parent, *time;
    std::vector<std::pair<int, size_t>> *size;
    const size_t length;
public:
    unionfind(size_t n, int *w): last(0), length(n){
        parent = new int[n];
        time = new int[n];
        size = new std::vector<std::pair<int, size_t>>[n];
        for(size_t i=0;i<n;++i){
            parent[i] = w[i];
            time[i] = INT32_MAX;
            size[i].emplace_back(0, w[i]);
        }
    }
    size_t root(size_t v, int t){
        if(time[v] > t) return v;
        else return root(parent[v], t);
    }
    bool is_same(size_t u, size_t v, int t=-1){
        if(t < 0) t = last;
        return root(u, t) == root(v, t);
    }
    int merge(size_t u, size_t v){
        int t = ++last;
        u = root(u, t);
        v = root(v, t);
        if(u == v) return t;
        if(parent[u] < parent[v]) std::swap(u, v);
        parent[u] += parent[v];
        size[u].emplace_back(t, parent[u]);
        parent[v] = u;
        time[v] = t;
        return t;
    }
    size_t count(size_t v, int t=-1){
        if(t < 0) t = last;
        v = root(v, t);
        return std::prev(std::lower_bound(size[v].begin(), size[v].end(), std::pair<int, size_t>{ t, length + 1 }))->second;
    }
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, m;
    static int vw[100000];
    static vector<pair<int, int>> edges[100000];
    static pair<int, pair<int, int>> ew[100000];
    static bool ok[100000];

    cin >> n >> m;
    for(int i=0;i<n;++i) cin >> vw[i];
    for(int i=0;i<m;++i){
        int a, b, y;
        cin >> a >> b >> y;
        --a; --b;
        edges[a].emplace_back(b, y);
        edges[b].emplace_back(a, y);
        ew[i] = {y, {a, b}};
    }
    sort(ew, ew+m);
    unionfind uf(n, vw);
    for(int i=0;i<m;++i){
        uf.merge(ew[i].second.first, ew[i].second.second);
    }
    int ans = 0;
    for(int t=m;t>0;--t){
        int u, v, w;
        w = ew[t-1].first;
        tie(u, v) = ew[t-1].second;
        if(ok[u]) continue;
        if(uf.count(u, t+1) < w) ++ans;
        else{
            queue<int> q;
            q.emplace(u);
            q.emplace(v);
            ok[u] = ok[v] = true;
            while(!q.empty()){
                int f = q.front();
                q.pop();
                for(auto e: edges[f]){
                    if(e.second > w) continue;
                    if(ok[e.first]) continue;
                    ok[e.first] = true;
                    q.emplace(e.first);
                }
            }
        }
    }
    cout << ans << endl;

    return 0;
}

