class Disjoint_Set {
    private:
        int parent[N_MAX]; //parent node of the node x
    public:
        Int node_weight[N_MAX]; //weight of the node
        int edge_num[N_MAX]; //the number of edge in the node x

        Disjoint_Set(int n) {
            for(int i = 0;i < n;i++) {
                parent[i] = i;
                node_weight[i] = A[i];
                edge_num[i] = 0;
            }
        }

        int root(int x) {
            return parent[x] == x ? x : parent[x] = root(parent[x]);
        }

        void merge(int x,int y) {
            x = root(x);
            y = root(y);
            if(x != y) {
                parent[x] = y;
                node_weight[y] += node_weight[x];
                edge_num[y] += edge_num[x];
                node_weight[x] = edge_num[x] = 0;
            }
            edge_num[y]++;
        }
};

