struct UF2 {  //with pop  partially persistent
	vector<vector<int> > belong;
	vector<vector<int> > dep;
	vector<vector<long long int> > sum;
	void resize(int n) {
		vector<int> f;
		f.push_back(-1);
		belong.assign(n, f);
		f[0] = 1;
		dep.assign(n, f);
		f[0] = 0;
		sum.assign(n, vector<long long int>() );
		for (int i = 0; i < n; i++) {
			sum[i].push_back(node[i]);
		}
	}
	int root(int b) {
		if (belong[b].back() == -1) {
			return b;
		}
		return root(belong[b].back());
	}
	vector<pair<int, int> > op;
	int push(int a, int b) {  //merge
		a = root(a);
		b = root(b);
		int f = op.size();
		if (a == b) {
			op.push_back(make_pair(-1, -1));
			return f;
		}
		if (dep[a].back() > dep[b].back()) {
			swap(a, b);
		}
		belong[a].push_back(b);
		dep[b].push_back(max(dep[b].back(), dep[a].back() + 1));
		long long int R = sum[a].back() + sum[b].back();
		sum[b].push_back(R);
		op.push_back(make_pair(a, b));
		return f;
	}
	void pop(int id) {
		belong[op[id].first].pop_back();
		dep[op[id].second].pop_back();
		sum[op[id].second].pop_back();
		//op.pop_back();
	}
};
