        if (uf.size(a)>=G[i][0]) candidate.push_back(i);
    }
    reverse(candidate.begin(),candidate.end());
    vector<vector<edge>> es(N);
    rep(i,M){
        ll a=G[i][1],b=G[i][2],y=G[i][0];
        es[a].push_back(edge{b,y,i});
        es[b].push_back(edge{a,y,i});
    }
    vector<bool> ok(M,false);
    for (auto i:candidate){
        ll a=G[i][1],b=G[i][2],y=G[i][0];
        queue<Pll> que;
        que.push(Pll(i,a));
        que.push(Pll(i,b));
        ok[i]=true;
        while(!que.empty()){
            Pll p=que.front();
            que.pop();
            ll n=p.first,v=p.second;
            for (auto e:es[v]){
                if (e.num==n) continue;
                if (ok[e.num]||e.cost>y) continue;
                ok[e.num]=true;
                que.push(Pll(e.num,e.to));
            }
        }
    }
    ll ans=0;
    rep(i,M) if (!ok[i]) ++ans;
    cout << ans << endl;
}

