    FOR(i, M) {
        read(E[i].s, E[i].f);
        --E[i].s.f;
        --E[i].s.s;
    }
    sort(E, E + M, greater<pair<ll, pii>>());
    auto f = [&] (int ind) {
        CC.clear();
        CC.init(N);
        For(i, ind, M) CC.addEdge(E[i].s.f, E[i].s.s);
        CC.assign(N);
        fill(sum, sum + sz(CC.components), 0);
        FOR(i, N) sum[CC.id[i]] += W[i];
        For(i, ind, M) if (sum[CC.id[E[i].s.f]] < E[i].f) return false;
