struct UnionFind {
  vector<int> data; // 根の場合は集合の大きさ*-1、子の場合は親の番号が入る
  UnionFind(int size) : data(size, -1) { }
  bool link(int x, int y) { //新たな併合を行うとtrue
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  int root(int x) { // 代表元を返す
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) { // 要素xが含まれる集合の大きさ
    return -data[root(x)];
  }
  bool same(int x, int y) { // 同じ集合ならtrue
    return root(x) == root(y);
  }
  int num() { // 異なる集合の数
    int res = 0;
    REP(i, data.size()) res += root(i) == i;
    return res;
  }
};

ll S[MAX_N];
bool check(int N) {
  REP(i, N) S[i] = X[i];
  UnionFind uf(N);

  REP(i, edge.size()) {
    if (edge[i].alive) {
      ll s1 = S[uf.root(edge[i].a)];
      ll s2 = S[uf.root(edge[i].b)];
      if (uf.link(edge[i].a, edge[i].b)) {
        S[ uf.root(edge[i].a) ] = s1 + s2;
      }
    }
  }
  bool ok = true;
  // cout << "--" << endl;
  // cout << "mid=" << mid << endl;
  REP(i, edge.size()) {
    Edge &e = edge[i];
    if (e.alive) {
      int r = uf.root(e.a);
      if (S[r] < e.w) {
        ok = false;
        e.alive = false;
      }
    }
  }
  return ok;
}

