const int N=1e5+5;

typedef struct data
{
	int u, v, w, idx;

	data() {}

	data(int u, int v, int w, int idx) : u(u), v(v), w(w), idx(idx) {}
}edge;

int n, m;
int connected;
int root[N], sz[N], x[N], sum[N];
vector<pair<int, int> > g[N];
data edges[N];

void init()
{
	for(int i=1;i<=n;i++)
	{
		root[i]=i;
		sz[i]=1;
		sum[i]=x[i];
	}
	connected=n;
}

int rt(int k)
{
	while(k!=root[k])
	{
		root[k]=root[root[k]];
		k=root[k];
	}
	return k;
}

void merge(int u, int v)
{
	int rt1=rt(u);
	int rt2=rt(v);

	if(rt1==rt2)
		return;

	connected--;

	if(sz[rt1]>sz[rt2])
		swap(rt1, rt2);

	sz[rt2]+=sz[rt1];
	sz[rt1]=0;
	root[rt1]=root[rt2];
	sum[rt2]+=sum[rt1];
}

void add_edge(int idx, int u, int v, int w)
{
	g[u].push_back({v, w});
	g[v].push_back({u, w});
	edges[idx]=edge(u, v, w, idx);
}

bool comp(data &d1, data &d2)
{
	return d1.w < d2.w;
}	

bool kruskalMST(int lim)
{	
	init();
	int cost=0;
	sort(edges+1, edges+m+1, comp);
	for(int i=1;i<=lim;i++)
	{
		int u=edges[i].u, v=edges[i].v, w=edges[i].w;
		int rt1=rt(u), rt2=rt(v);
		if(rt1==rt2)
			continue;
		else
			merge(rt1, rt2);
	}
	for(int i=1;i<=lim;i++)
	{
		int w=edges[i].w + x[edges[i].u] + x[edges[i].v];
		int rt1=rt(edges[i].u);
		if(sum[rt1]<w)
			return 0;
	}
	return 1;
}

int check(int x)
{
	return kruskalMST(m-x);
}

int binsearch(int lo, int hi)
{
	while(lo<hi)
	{
		int mid=(lo+hi)/2;
		if(check(mid))
			hi=mid;
		else
			lo=mid+1;
	}
	return lo;
}

