{
	IOS;
	cin>>n>>m;
	for(int i=1;i<=n;i++)
		cin>>x[i];
	init();
	for(int i=1;i<=m;i++)
	{
		int u, v, w;
		cin>>u>>v>>w;
		add_edge(i, u, v, w-x[u]-x[v]);
	}
	int ans=binsearch(0, m);
	cout<<ans;
	return 0;
}

