#define MN 101000

int fa[MN];
long long v[MN];
bool used[MN], ok[MN], del[MN];
int h[MN], nxt[2 * MN], to[2 * MN], K = 1;

void ins(int u, int v) {nxt[++K] = h[u]; h[u] = K; to[K] = v;}

struct xxx{int x, y, c;} e[MN];

int Find(int x) {return fa[x] == x ? x : fa[x] = Find(fa[x]);}

bool cmp(xxx a, xxx b) {return a.c < b.c;}

void dfs(int x, int now)
{
	if(used[x]) return; 
	used[x] = 1;
	for(int i = h[x]; i; i = nxt[i])
	{
		if(i / 2 > now) continue;
		ok[i >> 1] = 1;
		dfs(to[i], now);
	}
}

