{
	int n, m; scanf("%d%d", &n, &m);
	for(int i = 1; i <= n; i++) scanf("%lld", &v[i]), fa[i] = i;
	for(int i = 1; i <= m; i++) scanf("%d%d%d", &e[i].x, &e[i].y, &e[i].c);
	std::sort(e + 1, e + m + 1, cmp);
	for(int i = 1; i <= m; i++)
	{
		int X = Find(e[i].x), Y = Find(e[i].y);
		ins(e[i].x, e[i].y); ins(e[i].y, e[i].x);
		if(X != Y) fa[X] = Y, v[Y] += v[X];
		if(v[Y] < e[i].c) del[i] = 1;
	}
	int ans = 0;
	for(int i = m; i >= 1; i--)
	{
		if(del[i] && !ok[i]) ans++;
		if(!del[i] && !ok[i]) dfs(e[i].x, i);
	}
	printf("%d\n", ans);
}

