using namespace std;

class UnionFind
{
public:
    vector<int> parent;
    vector<int> rank;

    UnionFind(int n): parent(n), rank(n)
    {
        for(int i=0;i<n;i++)
            parent[i] = i,
            rank[i] = 0;
    }

    int root(int x)
    {
        return parent[x]==x ? x : parent[x] = root(parent[x]);
    }

    bool same(int x, int y)
    {
        return root(x)==root(y);
    }

    void unite(int x, int y)
    {
        x = root(x);
        y = root(y);
        if (x != y)
        {
            if (rank[x] < rank[y])
                parent[x] = y;
            else
                parent[y] = x;
            if (rank[x]==rank[y])
                rank[x]++;
        }
    }
};

int main()
{
    int N, M;
    cin>>N>>M;
    vector<long long> X(N);
    for (int i=0; i<N; i++)
        cin>>X[i];
    vector<int> A(M);
    vector<int> B(M);
    vector<long long> Y(M);
    for (int i=0; i<M; i++)
    {
        cin>>A[i]>>B[i]>>Y[i];
        A[i]--;
        B[i]--;
    }

    vector<pair<long long, pair<int, int>>> T;
    for (int i=0; i<M; i++)
        T.push_back(make_pair(Y[i], make_pair(A[i], B[i])));
    sort(T.begin(), T.end());
    for (int i=0; i<M; i++)
    {
        A[i] = T[i].second.first;
        B[i] = T[i].second.second;
        Y[i] = T[i].first;
    }

    vector<int> S(M);

    vector<long long> W(N);
    for (int i=0; i<N; i++)
        W[i] = X[i];
    UnionFind UF(N);
    for (int i=0; i<M; i++)
    {
        if (!UF.same(A[i], B[i]))
        {
            long long w = W[UF.root(A[i])] + W[UF.root(B[i])];
            UF.unite(A[i], B[i]);
            W[UF.root(A[i])] = w;
        }
        if (W[UF.root(A[i])] >= Y[i])
            S[i] = 1;
    }

    vector<vector<int>> E(N);
    vector<vector<long  long>> EI(N);
    for (int i=0; i<M; i++)
    {
        E[A[i]].push_back(B[i]);
        E[B[i]].push_back(A[i]);
        EI[A[i]].push_back(i);
        EI[B[i]].push_back(i);
    }

    function<void(int, int, long long)> mark = [&](int c, int p, long long w)
    {
        for (int i=0; i<(int)E[c].size(); i++)
        if (E[c][i] != p && Y[EI[c][i]] <= w && S[EI[c][i]] != 2)
        {
            S[EI[c][i]] = 2;
            mark(E[c][i], c, w);
        }
    };

    for (int i=M-1; i>=0; i--)
        if (S[i] == 1)
        {
            S[i] = 2;
            mark(A[i], B[i], Y[i]);
            mark(B[i], A[i], Y[i]);
        }

    int ans = 0;
    for (int i=0; i<M; i++)
        if (S[i] == 0)
            ans++;
    cout<<ans<<endl;
}

