struct UF {
	int par[100000];
	int sum[100000];
	int maxi[100000];
	void init(int x[]) { int i; rep(i, 100000) { par[i] = i; sum[i] = x[i]; maxi[i] = 0; } }
	int root(int x) { if (par[x] == x) return x; return par[x] = root(par[x]); }
	void unit(int x, int y, int cst) {
		x = root(x);
		y = root(y);
		if (x != y) {
			par[x] = y;
			sum[y] += sum[x];
		}
		maxi[y] = max({cst, maxi[x], maxi[y]});
	}
	bool same(int x, int y) { return root(x) == root(y); }
	int rootSum(int x) { return sum[root(x)]; }
	int rootMax(int x) { return maxi[root(x)]; }
};

