struct edge
{
  int a, b, c;
  int num;
  edge(int A, int B, int C, int NUM)
  {
    a = A;
    b = B;
    c = C;
    num = NUM;
  }

  edge()
  {

  }

  bool operator<(const edge & x)const
  {
    if(c != x.c)
      return c < x.c;
    if(a != x.a)
      return a < x.a;
    return b < x.b;
  }
};

