int fin(int x)
{
  if(F[x] != x)
    return fin(F[x]);
  return x;
}

vector<vector<int> > zmiany;

void uni(int a, int b, int c)
{
  a = fin(a);
  b = fin(b);
  if(r[a] < r[b])
    swap(a, b);
  if(a != b)
  {
    suma[a] += suma[b];
    r[a] += r[b] + 1;
    F[b] = F[a];
    zmiany.pb({c, a, b});
  }
  else
  {
    r[a]++;
    zmiany.pb({c, a, -1});
  }
}

void cofnij()
{
  assert(SZ(zmiany));
  if(zmiany.back()[2] == -1)
  {
    r[zmiany.back()[1]]--;
    zmiany.pop_back();
    return;
  }
  int a = zmiany.back()[1];
  int b = zmiany.back()[2];
  r[a] -= r[b] + 1;
  suma[a] -= suma[b];
  F[b] = b;
  zmiany.pop_back();
}

set<edge> roz;
set<edge> elo;
edge kraw[maxn];
int vis[maxn];
int numer = 1;

void dfs(int x)
{
  vis[x] = numer;
  for(auto s : wek[x])
    elo.insert(kraw[s.se]);
  for(auto s : wek[x])
    if(vis[s.fi] < numer)
      dfs(s.fi);
}

void usun(edge x)
{
  wek[x.a].erase({x.b, x.num});
  wek[x.b].erase({x.a, x.num});
}

void rek(set<edge> zb, bool buduj = 0)
{
  if(buduj)
  {
    while(SZ(zmiany))
      cofnij();
    for(auto s : zb)
      uni(s.a, s.b, s.num);
  }
  // dbg(SZ(zb), buduj);
  if(SZ(zb) == 0)
    return ;
  auto it = zb.end();
  it--;
  while(SZ(zb) && suma[fin(it->a)] < it->c)
  {
    // dbg(it->a, it->b, it->c, it->num);
    while(zmiany.back()[0] != it->num)
      cofnij();
    // dbg(it->a, it->b, it->c, it->num);
    assert(SZ(zmiany) > 0);
    cofnij();
    // dbg(it->a, it->b, it->c, it->num);
    if(fin(it->a) == fin(it->b))
    {
      roz.erase(*it);
      usun(*it);
      zb.erase(*it);
      it = zb.end();
      it--;
    }
    else
    {
      roz.erase(*it);
      usun(*it);
      int a = it->a;
      int b = it->b;
      zb.erase(*it);
      if(r[fin(a)] < r[fin(b)])
        swap(a, b);
      numer++;
      elo.clear();
      // dfs(b);
      for(auto s : elo)
        zb.erase(s);
      auto cnt = elo;
      rek(zb, 0);
      rek(cnt, 1);
      return;
    }
  }
  return;
}

