/* UnionFind */

struct UnionFind{
  vector<int> data;
  vector<ll> sum, sum2, sum3;
  vector<priority_queue<pair<int,pair<int,int> > > > pqs;

  UnionFind(int s):data(s, -1), sum(s, 0), sum2(s), sum3(s), pqs(s) {}

  int root(int x){
    if(data[x] < 0) return x;
    return data[x] = root(data[x]);
  }

  bool set(int x, int y){
    x = root(x); y = root(y);
    if(x == y) return false;
    data[x] += data[y];
    sum[x] += sum[y];
    sum2[x] += sum2[y];
    sum3[x] += sum3[y];

    while(pqs[y].size()) {
      pqs[x].push(pqs[y].top());
      pqs[y].pop();
    }

    data[y] = x;
    sum[y] = sum2[y] = 0;
    return true;
  }

  bool check(int x, int y){
    return root(x) == root(y);
  }

  int size(int x){
    return -data[root(x)];
  }
};



int main(){
  int n, m;
  int x[SIZE];
  vector<pair<int,pair<int,int> > > vec;

  scanf("%d%d", &n, &m);

  UnionFind uf(n);

  for(int i=0;i<n;i++){
    scanf("%d", x+i);
    uf.sum[i] = x[i];
  }

  for(int i=0;i<m;i++){
    int a, b, y;
    scanf("%d%d%d", &a, &b, &y);
    vec.push_back({y, {a-1, b-1}});
  }

  sort(vec.begin(), vec.end());

  int ans = 0;

  for(int i=0;i<m;i++){
    int a = vec[i].second.first;
    int b = vec[i].second.second;
    int y = vec[i].first;

    uf.set(a, b);

    int r = uf.root(a);

    auto &pq = uf.pqs[r];
    uf.sum3[r]++;

    if(uf.sum[r] < y)
      pq.push({-y, {a, b}});

    while(pq.size()){
      if(uf.sum[r] >= -pq.top().first)
        pq.pop();
      else
        break;
    }

    if(pq.size() == 0) {
      ans += uf.sum3[r] - uf.sum2[r];
      uf.sum2[r] = uf.sum3[r];
    }

  }

  cout << m - ans << endl;


  return 0;
}

