struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

vi X;
using Edge = tuple<int, int, int>;
vector<Edge> edges;
vector<vi> G;
vll xsum;
vi tbl;

void dfs(int v, int k, int pk){
	if(tbl[v] != pk) return;
	tbl[v] = k;
	xsum[k] += X[v];

	for(auto & nv : G[v]){
		dfs(nv, k, pk);
	}
}

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m; cin >> n >> m;
    xsum = vll(n);
    X = vi(n); for(auto& e : X) cin >> e, xsum[0] += e;
    rep(i, m){
    	int a, b, y; cin >> a >> b >> y;
    	a--, b--;
    	edges.emplace_back(Edge(y, a, b));
    }
    sort(_all(edges));

    G = vector<vi>(n);
    UnionFind uf(n);
    vi used(m);
    rep(i, m){
    	auto& e = edges[i];
    	int a, b, y; tie(y, a, b) = e;
    	if(uf.findSet(a, b)) continue;

    	uf.unionSet(a, b);
    	G[a].emplace_back(b);
    	G[b].emplace_back(a);
    	used[i] = true;
    }

    int idx = 0;
    tbl = vi(n);
    rrep(i, m){
    	if(not used[i]) continue;

    	int a, b, y; tie(y, a, b) = edges[i];
    	assert(tbl[a] == tbl[b]);

    	int ck = tbl[a];
    	if(xsum[ck] >= y) continue;

    	using Pair = tuple<int, int>;
    	queue<Pair> qa, qb;
    	qa.push(Pair(a, b));
    	qb.push(Pair(b, a));
    	while(true){
    		if(qa.empty() || qb.empty()){
    			if(qb.empty()) swap(a, b);
    			tbl[b] = -1;
    			dfs(a, ++idx, ck);
    			tbl[b] = ck;
    			xsum[ck] -= xsum[idx];
    			break;
    		}

    		int v, pv; tie(v, pv) = qa.front(); qa.pop();
    		for(auto& nv : G[v]){
    			if(tbl[nv] != tbl[v] or nv == pv) continue;
    			qa.push(Pair(nv, v));
    		}
    		tie(v, pv) = qb.front(); qb.pop();
    		for(auto& nv : G[v]){
    			if(tbl[nv] != tbl[v] or nv == pv) continue;
    			qb.push(Pair(nv, v));
    		}
    	}
    }

    // rep(i, n){
    // 	cerr << tbl[i] << endl;
    // }
    int res = 0;
    rep(i, m){
    	int a, b, y; tie(y, a, b) = edges[i];
    	if(tbl[a] != tbl[b] or xsum[tbl[a]] < y){
    		res++;
    	}
    }
    cout << res << endl;

    return 0;
}

