vector<pii> T[N];
int vv[N];
int dv[N];

int par[N];

int fin(int x){
  if(x==par[x]) return x;
  return par[x]=fin(par[x]);
}

void unite(int a, int b){
  a=fin(a);
  b=fin(b);
  if(a==b)return;
  dv[b]+=dv[a];
  par[a]=b;
}

struct Edge{
  int ai;
  int bi;
  int wei;
  bool operator< (const Edge &R) const {
    return wei < R.wei;
  }
};

