  vector<bool> cool(m);
  for(int i = 0 ; i < m ; i ++ ){
    cin >> edg[i].ai >> edg[i].bi >> edg[i].wei;
  }
  sort(edg.begin(), edg.end());
  for(int i = 0 ; i < m ; i ++ ){
    unite(edg[i].ai, edg[i].bi);
