const int N = 100005;

random_device rd;
mt19937 mt(rd());
uniform_int_distribution<int> dis(0, 1);

int n, m, u, v, w, ans = 0;
long long dsu[N];

struct SEdge
{
    int u, v;
    long long w;
};
vector<SEdge> ed, tr;
vector<pair<int, long long>> ch;

int trace(int u)
{
    return dsu[u] < 0 ? u : trace(dsu[u]);
}

bool unity(SEdge cur)
{
    if ((cur.u = trace(cur.u)) == (cur.v = trace(cur.v)))
        return false;
    ch.push_back(make_pair(cur.v, dsu[cur.v]));
    dsu[cur.u] += dsu[cur.v];
    dsu[cur.v] = cur.u;
    return true;
}

int main()
{
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
    {
        scanf("%lld", dsu + i);
        dsu[i] = -dsu[i];
    }
    while (m--)
    {
        scanf("%d%d%d", &u, &v, &w);
        if (dis(mt))
            swap(u, v);
        ed.push_back((SEdge){u, v, w});
    }
    sort(ed.begin(), ed.end(), [](const SEdge &a, const SEdge &b) {
        return a.w < b.w;
    });
    for (SEdge &v : ed)
        if (unity(v))
            tr.push_back(v);
    for (int i = n - 2; i >= 0; i--)
    {
        SEdge cur = tr[i];
        int u = trace(cur.u);
        if (-dsu[u] < cur.w)
            dsu[u] -= (dsu[ch[i].first] = ch[i].second);
    }
    for (SEdge &v : ed)
        if (trace(v.u) != trace(v.v) || -dsu[trace(v.u)] < v.w)
            ans++;
    printf("%d", ans);
}

#include <bits/stdc++.h>
using namespace std;
int N, M;
vector<long long> X;
vector<long long> E;
vector<vector<pair<int,int>>> G;
int ans = 0;
vector<int> a;
vector<bool> fix;
vector<bool> used;
long long ss, mm;
void f(int v, int id, long long limit) {
	if (a[v] == id) return;
	a[v] = id;
	ss += X[v];
	for (auto p : G[v]) {
		if (E[p.second] <= limit) {
			mm = max(mm, E[p.second]);
			f(p.first, id, limit);
		}
	}
}
void g(int v, int id, long long limit) {
	if (a[v] == id) return;
	a[v] = id;
	fix[v] = true;
	for (auto p : G[v]) {
		if (E[p.second] <= limit) {
			used[p.second] = true;
			g(p.first, id, limit);
		}
	}
}
int main() {
	cin >> N >> M;
	X = vector<long long>(N);
	E = vector<long long>(M);
	G.resize(N);
	long long sum = 0;
	for (int i = 0; i < N; ++ i) {
		cin >> X[i];
		sum += X[i];
	}
	for (int i = 0; i < M; ++ i) {
		int u, v;
		cin >> u >> v >> E[i];
		-- u; -- v;
		G[u].push_back({v,i});
		G[v].push_back({u,i});
	}
	int id = 0;
	a.resize(N);
	fix.resize(N);
	used.resize(M);
	for (int i = 0; i < N; ++ i) if (!fix[i]) {
		auto limit = sum;
		for (;;) {
			ss = 0; mm = 0;
			f(i, ++id, limit);
			if (mm <= ss) break;
			limit = ss;
		}
		sum -= ss;
		//cerr << i << " " << limit << " " << ss << endl;
		g(i, ++id, limit);
	}
	int res = 0;
	//for (auto x : used) cerr << x; cerr << endl;
	for (auto x : used) if (!x) ++ res;
	cout << res << endl;
}

