struct UnionFind{
    vector<int> par;
    UnionFind(int N){
        par.resize(N);
        for(int i=0;i<N;i++){
            par[i] = i;
        }
    }
    void Union(int x,int y){
        par[Get(x)] = Get(y); 
    }
    bool Same(int x,int y){
        return Get(x) == Get(y);
    }
    int Get(int x){
        if(x != par[x]){
            par[x] = Get(par[x]);
        }
        return par[x];
    }
};
long Cost[200010];
long CostE[200010];
pair<long,pair<int,int>> edge[100000];
int par[100000];
pair<int,int> G[200010];
void Calc(){
	int N = rei();
	int M = rei();
	for(int i=0;i<N;i++){
		par[i] = i;
		Cost[i] = rel();
	}
	for(int i=0;i<M;i++){
		int a = rei()-1;
		int b = rei()-1;
		long c = rel();
		edge[i] = {c,{a,b}};
	}
	sort(edge,edge+M);
	UnionFind U(N);
	int p = N;
	for(int i=0;i<M;i++){
		int f = edge[i].second.first;
		int t = edge[i].second.second;
		if(!U.Same(f,t)){
			int fp = U.Get(f);
			int tp = U.Get(t);
			Cost[p] = Cost[par[fp]] + Cost[par[tp]];
			CostE[p] = edge[i].first;
			G[p] = {par[fp],par[tp]};
			U.Union(f,t);
			par[U.Get(f)] = p;
			p++;
		}
	}
	stack<pair<int,long>> sp;
	sp.push({p-1,Cost[p-1]});
	while(!sp.empty()){
		int v = sp.top().first;
		long c = sp.top().second;
		sp.pop();
		Cost[v] = max(Cost[v],c);
		if(v >= N){
			if(CostE[v] > Cost[v]){
				sp.push({G[v].first,0});
				sp.push({G[v].second,0});
			}
			else{
				sp.push({G[v].first,Cost[v]});
				sp.push({G[v].second,Cost[v]});
			}
		}
	}
	int ans = 0;
	for(int i=0;i<M;i++){
		long ec = edge[i].first;
		long vc = Cost[edge[i].second.first];
		if(ec > vc){
			ans++;
		}
	}
	cout << ans << endl;
}
int main(int argc,char** argv){
	ios::sync_with_stdio(false), cin.tie(0);
	cout.tie(0); Calc(); return 0;
}

