typedef long long ll;
int const maxn = 1e5 + 5, K = 330;
int x[maxn], used[maxn], cur, oks[maxn], tmp;
unordered_set < int > g[maxn];
multiset < int > G[maxn];
ll sum[maxn], f;

void dfs1(int v) {
    oks[v] = tmp;
    f += sum[v];
    for (auto u : G[v]) {
        if (oks[u] != tmp) dfs1(u);
    }
}

void dfs(int v) {
    used[v] = cur, sum[cur] += (ll)x[v];
    for (auto u : g[v]) if (used[u] == 0) dfs(u);
}

