  return f[x];
}

void join(int x, int y, int z) {
  int rx = find(x), ry = find(y);
  if (rx != ry) {
    f[ry] = rx;
    sum[rx] += sum[ry];
    bad[rx] += bad[ry];
  }
  if (z > sum[rx]) {
    ++bad[rx];
  } else {
    bad[rx] = 0;
  }
}

