    EDGE.resize(n);
    P.resize(n,-1);

    auto F=[](ll a,ll b){return a+b;};
    auto G=[](ll a,ll b,ll l,ll r,int children){return a+b*children;};
    auto H=[](ll a,ll b){return a+b;};
    vector<LCT<ll,ll,ll>> A(n,LCT<ll,ll,ll>(0,greater<ll>(),0,0,F,G,H));
    for(int i=0;i<n;i++){
        A[i].key=i;
        A[i].RENEW();
    }

    vector<pair<ll,pll>> edge(m);
    for(auto &I:edge){
        cin>>I.S.F>>I.S.S>>I.F;
        I.S.F--;
        I.S.S--;
    }
    sort(edge.begin(),edge.end());
    priority_queue<pll> Q;
    vector<bool> used(m,false);
    for(int i=0;i<m;i++){
        if(parent(edge[i].S.F)!=parent(edge[i].S.S)){
            used[i]=true;
            merge(edge[i].S.F,edge[i].S.S);
            EDGE[edge[i].S.F].push_back(edge[i].S.S);
            EDGE[edge[i].S.S].push_back(edge[i].S.F);
            Q.push({edge[i].F,i});
        }
    }
    dfs(0,-1);
    for(int i=1;i<n;i++){
        A[i].P=&A[P[i]];
    }
    for(int i=0;i<n;i++){
        A[i].update(X[i]);
    }
    ll ans=n-1;
    while(!Q.empty()){
        pll w=Q.top();
        Q.pop();
        if(P[edge[w.S].S.F]!=edge[w.S].S.S){
            swap(edge[w.S].S.F,edge[w.S].S.S);
        }
