        if(p->item<edge[w.S].F){
            A[edge[w.S].S.S].expose();
            A[edge[w.S].S.F].Splay();
            A[edge[w.S].S.F].down();
            A[edge[w.S].S.S].update(-A[edge[w.S].S.F].item);
            A[edge[w.S].S.F].P=NULL;
            ans--;
        }
        else{
            merge2(edge[w.S].S.S,edge[w.S].S.F);
        }
    }
    for(int i=0;i<m;i++){
        if(used[i]){continue;}
        if(parent2(edge[i].S.F)==parent2(edge[i].S.S) && uft2[parent2(edge[i].S.S)].S>=edge[i].F){ans++;}
    }
    cout<<m-ans<<endl;




    return 0;
}

