class UnionFind {
  vector<ll> par, rank, size; // par > 0: number, par < 0: -par
public:
  UnionFind(ll n) : par(n, 1), rank(n, 0), size(n, 0) {
    for (ll i = 0; i < n; i++) size[i] = x[i];
  }
  ll getSize(ll x) {
    return size[find(x)];
  }
  ll find(ll x) {
    if (par[x] > 0) return x;
    return -(par[x] = -find(-par[x]));
  }
  void merge(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
      par[y] += par[x];
      size[y] += size[x];
      par[x] = -y;
    } else {
      par[x] += par[y];
      size[x] += size[y];
      par[y] = -x;
      if (rank[x] == rank[y]) rank[x]++;
    }
  }
  bool isSame(ll x, ll y) {
    return find(x) == find(y);
  }
};

