    G[u].erase(id); G[v].erase(id ^ 1);
    ans++;
}

int n, x[N];
void dfs(const vector<int>& ids) {
    if (ids.size() <= 1) return;
    LL sum = 0;
    for (int u: ids) sum += x[u];
    dbg(sum);

    vector<bool> vis(n + 1);
    vector<vector<int>> comps;
    for (int s: ids) {
        if (vis[s]) continue;
        comps.emplace_back();
        queue<int> q;

        q.push(s); vis[s] = 1;
        comps.back().push_back(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            // dbg(s, u);
            for (auto it = G[u].begin(); it != G[u].end(); ) {
                const E& e = edges[*it];
                if (e.cost > sum) {
                    deledge(u, *it++);
                } else {
                    if (!vis[e.to]) {
                        q.push(e.to); vis[e.to] = 1;
                        comps.back().push_back(e.to);
                    }
                    it++;
                }
            }
        }
    }
    if (comps.size() == 1) return;
    for (const auto& comp: comps) {
        // dbg(comp);
        dfs(comp);
    }
}

