class UnionFind {
private:
	int n;
	vector<int> a;
public:
	UnionFind(int n) : n(n), a(n, -1) {}
	int find(int x) { return a[x] < 0 ? x : (a[x] = find(a[x])); }
	bool same(int x, int y) { return find(x) == find(y); }
	bool same(Pii& p) { return same(p.first, p.second); }
	bool unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y) return false;
		if (a[x] > a[y]) swap(x, y);
		a[x] += a[y];
		a[y] = x;
		n--;
		return true;
	}
	bool unite(Pii& p) { return unite(p.first, p.second); }
	int size() const { return n; }
	int size(int x) { return -a[find(x)]; }
};

int main() {
	int n, m; reader(n, m);
	vector<ll> x(n);
	FOR(i, n) reader(x[i]);

	vector<tuple<ll, int, int>> vp;

	FOR(i, m) {
		int a, b; ll y;
		reader(a, b, y);
		a--; b--;
		vp.emplace_back(y, a, b);
	}
	sort(vp.begin(), vp.end());

	vector<tuple<int, int, ll>> others;
	vector<tuple<int, int, ll>> tree;

	{
		UnionFind uf(n);
		for (auto& yab : vp) {
			int a, b; ll y;
			tie(y, a, b) = yab;
			if (uf.unite(a, b)) {
				tree.emplace_back(a, b, y);
			} else {
				others.emplace_back(a, b, y);
			}
		}
	}

	vector<pair<Pll, int>> nodes;
	vector<vector<int>> edges(2 * n - 1);

	{
		FOR(i, n) nodes.emplace_back(Pll(0, x[i]), -1);
		vector<int> nid;
		FOR(i, n) nid.push_back(i);
		UnionFind uf(n);

		FOR(treeId, sz(tree)) {
			int a, b; ll y;
			tie(a, b, y) = tree[treeId];
			a = uf.find(a);
			b = uf.find(b);
			uf.unite(a, b);

			const int nextId = sz(nodes);
			edges[nextId] = { nid[a], nid[b] };

			ll nextHev = max(nodes[nid[a]].first.first, nodes[nid[b]].first.first);
			nextHev = max(nextHev, y);
			ll nextH = nodes[nid[a]].first.second + nodes[nid[b]].first.second;

			nodes.emplace_back(Pll(nextHev, nextH), treeId);
			nid[a] = nid[b] = nextId;
		}
	}

	int ans = 0;
	UnionFind finalUf(n);
	for (int i = 2 * n - 2; i >= n; i--) {
		if (nodes[i].first.first > nodes[i].first.second) {
			ans++;
			continue;
		}

		for (auto to : edges[i]) {
			nodes[to].first.second = nodes[i].first.second;
		}

		int a, b; ll y;
		tie(a, b, y) = tree[nodes[i].second];
		finalUf.unite(a, b);
	}

	map<int, ll> finalH;
	FOR(i, n) finalH[finalUf.find(i)] += x[i];

	for (auto& aby : others) {
		int a, b; ll y;
		tie(a, b, y) = aby;
		if (!finalUf.same(a, b)) continue;
		a = finalUf.find(a);
		if (finalH[a] < y) {
			ans++;
		}
	}

	writerLn(ans);

	return 0;
}

