			auto dfs = [&](auto&& f, int v) -> void {
				for (auto& e : g[v]) if(!uf.same(v, e.to) && y[i] >= e.cost) {
					uf.unite(v, e.to);
					f(f, e.to);
				}
			};
			dfs(dfs, a[i]);
		}
	}

	OUT(ans)BR;

	return 0;
}

