};

int N, M;
lint X[100005];
vector< Edge > edge;
vector< vector< pii > > adj;
bool use[100005];



void dfs(int v, lint maxY) {
	for (pii p : adj[v]) {
		int u = p.first;
		int i = p.second;
		if (use[i]) continue;
		if (edge[i].Y > maxY) continue;
		use[i] = true;
		dfs(u, maxY);
	}
}

void detect(vector< int > base) {
	for (int i : base) {
		if (use[i]) continue;
		dfs(edge[i].u, edge[i].Y);
	}
}

vector< int > findBase() {
	vector< int > par(N, -1);
	vector< lint > w(N, -1), ew(N, -1);
	vector< vector< int > > group(N, vector< int >());

	//
	for (int v=0; v<N; ++v) {
		par[v] = v;
		w[v] = X[v];
		group[v] = {v};
	}

	vector< int > ret;
	for (int i=0; i<M; ++i) {
		Edge e = edge[i];

		int pu = par[e.u];
		int pv = par[e.v];

		if (pu != pv) {
			if (group[pu].size() > group[pv].size()) swap(pu, pv);
			w[pv] += w[pu];
			for (int v : group[pu]) {
				par[v] = pv;
				group[pv].push_back(v);
			}
		}

		if (w[pv] >= e.Y) ret.push_back(i);
	}
	reverse(allof(ret));
	return ret;
}

void solve() {
	sort(allof(edge));
	memset(use, 0, sizeof(use));

	adj.assign(N, vector< pii >());
	for (int i=0; i<M; ++i) {
		Edge e = edge[i];
		adj[e.u].push_back(pii(e.v, i));
		adj[e.v].push_back(pii(e.u, i));
	}

	vector< int > base = findBase();
	detect(base);

	int ans = 0;
	for (int i=0; i<M; ++i) if (!use[i]) ++ans;
	cout << ans << endl;
}



int main() {
	cin >> N >> M;
	for (int i=0; i<N; ++i) cin >> X[i];
	for (int i=0; i<M; ++i) {
		int a, b;
		lint y;
		cin >> a >> b >> y;
		--a; --b;
		edge.push_back(Edge{a,b,y});
	}
	solve();
}
