class Union_find
{
public:
    vector<int> par;
    vector<int> sz, dat;
    vector<priority_queue<Pii, vector<Pii>, greater<Pii>>> que;

    Union_find(int N, vector<int> v){
        par = vector<int>(N);
        REP(i, N) par[i] = i;
        sz = vector<int>(N, 1);
        dat = v;
    }

    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(sz[x] < sz[y]) swap(x, y);

        par[y] = x;
        sz[x] += sz[y];
        dat[x] += dat[y];
        unite_que(que[x], que[y]);
    }

    bool is_union(int x, int y){
        x = find(x);
        y = find(y);
        return x == y;
    }

    int union_size(int x){
        return sz[find(x)];
    }

};

