    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void dfs(int v, int w, Union_find &UF){
        if(UF.union_size(v) > 1) return;
        while(!UF.que[UF.find(v)].empty()){
            int par = UF.find(v);
            Pii p = UF.que[par].top();
            if(p.first > UF.dat[par] + w) break;
            UF.que[par].pop();
            UF.unite(par, p.second);
        }
    }

};

void init(Graph &G, Union_find &UF, vec &A, int N){
    UF.que = vector<priority_queue<Pii, vector<Pii>, greater<Pii>>>(N);
    REP(i, N) REP(k, G.G[i].size()) UF.que[i].push(Pii(A[G.G[i][k].to], G.G[i][k].to));
}

