struct UnionFind{
    vector<int> p,r;
    vector<ll> sum; // ノードの和
    vector<int> cnt;
    UnionFind(){}
    UnionFind(int n){ init(n); }

    void init(int n){
        p.resize(n,-1);
        r.resize(n,0);
        sum.resize(n,0);
        cnt.resize(n,0);
        for(int i=0;i<n;i++) sum[i] = x[i];
    }

    int find(int x){
        if(p[x] < 0) return x;
        else return p[x] = find(p[x]);
    }

    void merge(int x,int y){
        x = find(x);
        y = find(y);
        if(x==y) return;
        if(r[x] < r[y]){    // y <-- x
            p[x] = y;
            r[x]++;
            sum[y] += sum[x];
            sum[x] = 0;
            cnt[y] += cnt[x];
            cnt[x] = 0;
        }else{ // x <-- y
            p[y] = x;
            if(r[x] == r[y]) r[x]++;
            r[y]++; 
            sum[x] += sum[y];
            sum[y] = 0;
            cnt[x] += cnt[y];
            cnt[y] = 0;
        }
    }

    ll get(int x){
        return sum[find(x)];
    }

    void inc(int x){
        cnt[find(x)]++;
    }

    int add(int x){
        x = find(x);
        int ret = cnt[x];
        cnt[x] = 0;
        return ret;
    }
};

