struct union_find_tree {
    vector<int> data;
    union_find_tree() = default;
    explicit union_find_tree(size_t n) : data(n, -1) {}
    bool is_root(int i) { return data[i] < 0; }
    int find_root(int i) { return is_root(i) ? i : (data[i] = find_root(data[i])); }
    int tree_size(int i) { return - data[find_root(i)]; }
    int unite_trees(int i, int j) {
        i = find_root(i); j = find_root(j);
        if (i != j) {
            if (tree_size(i) < tree_size(j)) swap(i,j);
            data[i] += data[j];
            data[j] = i;
        }
        return i;
    }
    bool is_same(int i, int j) { return find_root(i) == find_root(j); }
};

int solve(int n, int m, vector<ll> const & vw, vector<tuple<int, int, ll> > const & edges) {
    vector<int> order(m);
    iota(ALL(order), 0);
    sort(ALL(order), [&](int i, int j) {
        return get<2>(edges[i]) < get<2>(edges[j]);
    });

    union_find_tree uft(n);
    vector<ll> sum_vw = vw;
    vector<int> unused(n);

    for (int i : order) {
        int a, b; ll ew; tie(a, b, ew) = edges[i];
        a = uft.find_root(a);
        b = uft.find_root(b);
        if (a == b) {
            if (ew <= sum_vw[a]) {
                // nop
            } else {
                ++ unused[a];
            }
        } else {
            int c = uft.unite_trees(a, b);
            if (c != a) swap(a, b);
            assert (c == a);
            sum_vw[a] += exchange(sum_vw[b], 0ll);
            unused[a] += exchange(unused[b], 0);
            if (ew <= sum_vw[a]) {
                unused[a] = 0;
            } else {
                ++ unused[a];
            }
        }
    }

    return accumulate(ALL(unused), 0);
}

int main() {
    int n, m; cin >> n >> m;
    vector<ll> vw(n);
    REP (i, n) cin >> vw[i];
    vector<tuple<int, int, ll> > edges;
    REP (i, m) {
        int a, b; ll ew; cin >> a >> b >> ew;
        -- a; -- b;
        edges.emplace_back(a, b, ew);
    }
    cout << solve(n, m, vw, edges) << endl;
    return 0;
}

