    }
    int cnt = n;
    int tt = 0;
    pr[1] = 1;
    dfs(1);
    for (auto i: newedges){
        int u = i.S.F;
        int v = i.S.S;
        if (pr[u] == v) swap(u, v);
        u = gt(u);
        cnt--;
        pv[cnt] = wg[u];
        pc[cnt] = wg[v];
        merg(u, v);
        tt = wg[u];
    }
    build(1, 1, n);
    int ans = 0;
    cnt = 0;
  //  cout << w[1] << endl;
