      //  cout << getsum(1, 1, n, 4, lb[4], rb[4]) << endl;
        if (w >= i.F) continue;
        ans++;
        if (u == pr[v]){
            ww[r] = pv[cnt];
            ww[v] = pc[cnt];
            cc[v] = 1;
            events.pb(v);

         //   cout << "v = " << v << " " << lb[v] << " " << rb[v] << endl;
        } else
        if (v == pr[u]){
            ww[r] = pv[cnt];
            ww[u] = pc[cnt];
            cc[u] = 1;
            events.pb(u);
         //   cout << "u = " << u << " " << lb[u] << " " << rb[u] << endl;
