int Root(int x)
{
    if (x == root[x]) return x;
    return root[x] = Root(root[x]);
}

void Merge(Edge A)
{
    int u = A.u, v = A.v;
    u = Root(u);
    v = Root(v);
    if (u == v)
    {
        if (A.w <= s[v]) ans++;
        else cnt[v]++;
        return;
    }
    if (sz[u] > sz[v])
    {
        swap(v, u);
    }
    sz[v] += sz[u];
    s[v] += s[u];
    cnt[v] += cnt[u] + 1;
    root[u] = v;
    if (A.w <= s[v])
    {
        ans += cnt[v];
        cnt[v] = 0;
    }
    return;
}

