		cin >> a[i];
	}
	for (int i = 0; i < m; i++) {
		int u, v, w;
		cin >> u >> v >> w;
		u--;
		v--;
		E.push_back(Edge({u, v, w}));
	}
	sort(E.begin(), E.end());
	Dsu D(n);
	for (int i = 0; i < m; i++) {
		if (D.merge(E[i].u, E[i].v)) {
			edge_comp[0].insert({E[i], i});
			g[E[i].v].insert(i);
			g[E[i].u].insert(i);
		}
	}
	size_comp[0] = n;
	for (int i = 0; i < n; i++) {
		sum_a_comp[0] += a[i];
	}
	if (!edge_comp[0].empty() && sum_a_comp[0] < edge_comp[0].rbegin()->first.w) {
		bad_comps.push(0);
	}
	while (!bad_comps.empty()) {
		int v = bad_comps.front();
		bad_comps.pop();
		split(edge_comp[v].rbegin()->second);
	}
	int ans = 0;
	for (auto t : E) {
		if (comp[t.u] == comp[t.v] && sum_a_comp[comp[t.u]] >= t.w) ans++;
	}
	cout << m - ans << '\n';
}

