class UnionFind {
	vector<int> par;
	vector<int> rank;
	vector<long long> weight;
public:
	UnionFind(int max_n) :par(max_n), rank(max_n), weight(max_n){}
	void init(int n, int w[]) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
			weight[i] = w[i];
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (rank[x] < rank[y]) {
			par[x] = y;
			weight[y] += weight[x];
		}
		else {
			par[y] = x;
			weight[x] += weight[y];
			if (rank[x] == rank[y])rank[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	long long w(int u)  {
		return weight[find(u)];
	}
};





