struct DSU {
	int N, pa[MAXN], sz[MAXN];
	LL sum[MAXN];
	vector<int> who[MAXN];

	void init(int _N, int *x) {
		N = _N;
		for (int i = 1; i <= N; i++) {
			pa[i] = i;
			sz[i] = 1;
			sum[i] = x[i];
		}
	}

	int find(int x) {
		return x == pa[x] ? x : find(pa[x]);
	}

	void merge(int x, int y) {
		x = find(x);
		y = find(y);
		if (sz[x] < sz[y]) swap(x, y);
		if (x == y) {
			who[x].push_back(-1);
		}
		else {
			who[x].push_back(y);
			sum[x] += sum[y];
			sz[x] += sz[y];
			pa[y] = x;
		}
//		cout << "AFTER " << x << " " << sum[x] << '\n';
	}

	void undo(int x) {
		x = find(x);
		if (who[x].back() != -1) {
			int y = who[x].back();
			pa[y] = y;
			sum[x] -= sum[y];
			sz[x] -= sz[y];
		}
		who[x].pop_back();
	}
} dsu;

