struct unionfind{
	vector<int> data;
	vector<int> size;
	vector<long long> potential;
	unionfind(int n){
		for(int i=0;i<n;i++){
			data.push_back(i);
			size.push_back(1);
		}
		potential.resize(n,0);
	}

	unionfind(int n,vector<long long> p){
		for(int i=0;i<n;i++){
			data.push_back(i);
			size.push_back(1);
		}
		potential = p;
	}

	int find(int x){
		if(data[x]==x)return x;
		return data[x]=find(data[x]);
	}

	bool unite(int x,int y){
		x=find(x);y=find(y);
		if(x==y)return false;
		if(size[x]>size[y])swap(x,y);
		data[x]=y;
		size[y]+=size[x];
		potential[y] += potential[x];
		return true;
	}

	bool check(int x,int y){
		return (find(x)==find(y));
	}

	int get_size(int x){
		int X = find(x);
		return size[X];
	}

	long long get_potential(int x){
		return potential[find(x)];
	}

};

