   while (M--) {
      scanf("%d %d %d", &A, &B, &Y);
      V.push_back(make_tuple(Y, A, B));
   }//while
   sort(V.begin(), V.end());
   for (int i = 0; i < (int)V.size(); i++) {
      int p1 = U.findSet(get<1>(V[i]));
      int p2 = U.findSet(get<2>(V[i]));
      U.unite(p1, p2);
      if (U.getSize(p1) < get<0>(V[i]))
         U.incBad(p1);
      else
         U.clearBad(p1);
   }//for
   int ans = 0;
   for (int i = 1; i <= N; i++)
      if (!seen[U.findSet(i)])
         seen[U.findSet(i)] = 1, ans += U.getBad(i);
   printf("%d\n", ans);
