    cin>>T[i];
    int t=T[i];
    if(t==1){
      cin>>A[i]>>B[i];
      int x=A[i],e=B[i];
      x--;
      add_edge(x,e);
    }
    if(t==2){
      cin>>A[i]>>B[i];
    }
    if(t==3){
      cin>>A[i];
    }
  }

  using Node = NodeBase<int>;
  constexpr size_t LIM = 1e6;
  using LCT = SubTree<Node, LIM>;
  LCT lct;

  vector<LCT::Node*> vs(sz);
  for(int i=0;i<sz;i++) vs[i]=lct.create(i,1);

  vector<int> used(sz,0),ps(sz);
  auto calc=[](ll x)->ll{return x*(x-1)/2;};

  for(int i=0;i<n;i++){
    for(auto x:R[i]){
      if(used[x.second]) continue;
      int c=x.first;
      queue<P> q;
      q.emplace(i,-1);
      used[R[i][c]]=1;
      ps[R[i][c]]=-1;
      while(!q.empty()){
        int v,p;
        tie(v,p)=q.front();q.pop();
        if(~p) lct.link(vs[R[p][c]],vs[R[v][c]]);
        for(int u:G[v][c]){
          if(u==p||used[R[u][c]]) continue;
          q.emplace(u,v);
          used[R[u][c]]=1;
          ps[R[u][c]]=R[v][c];
        }
      }
      bit.add(c,calc(lct.query(vs[R[i][c]])));
    }
  }

  auto cut=[&](int x,int e){
             int p=R[as[x]][e],q=R[bs[x]][e];
             if(ps[q]!=p) swap(p,q);
             bit.add(e,-calc(lct.query(vs[p])));

             lct.cut(vs[q]);

             bit.add(e,calc(lct.query(vs[p])));
             bit.add(e,calc(lct.query(vs[q])));
           };

  auto con=[&](int x,int e){
             int p=R[as[x]][e],q=R[bs[x]][e];
             if(ps[q]!=p) swap(p,q);
             bit.add(e,-calc(lct.query(vs[p])));
             bit.add(e,-calc(lct.query(vs[q])));

             lct.link(vs[p],vs[q]);

             bit.add(e,calc(lct.query(vs[p])));
           };

  sort(edges.begin(),edges.end());
  edges.erase(unique(edges.begin(),edges.end()),edges.end());
  for(auto p:edges){
    int x=p.first,e=p.second;
    if(cs[x]!=e) cut(x,e);
  }

  for(int i=0;i<Q;i++){
    int t=T[i];
    if(t==1){
      int x=A[i],e=B[i];
      x--;
      if(cs[x]==e) continue;
      cut(x,cs[x]);
      con(x,e);
      cs[x]=e;
    }
    if(t==2){
      int l=A[i],r=B[i];
      cout<<bit.query(l,r+1)<<"\n";
    }
    if(t==3){
      int x=A[i];
      x--;
      int p=R[as[x]][cs[x]];
      cout<<calc(lct.query(vs[p]))<<"\n";
    }
  }
  cout<<flush;
  return 0;
}
