int N, M;
const int H = MD;
GraphE graph;
vector<GraphE::Edge> edges;
int W[100010];
char eFlg[100010];


int bound;
void markdfs(int idx) {
    for (int i : graph.vertex_to[idx]) {
        if (eFlg[i] == 1 || graph.edges[i].value > bound) continue;
        eFlg[i] = 1;
        markdfs(graph.edges[i].to(idx));
    }
}

int main() {

    scanner >> N >> M;
    graph.resize(N);
    edges.reserve(M + 2);
    graph.edges.reserve(M + 2);

    scanner.in(W, W + N);
    repeat(i, M) {
        int a, b; ll c;
        scanner >> a >> b >> c;
        --a; --b;
        edges.emplace_back(a, b, c);
    }

    sort(ALL(edges), [](GraphE::Edge l, GraphE::Edge r) {return l.value < r.value; });

    graph.connect(move(edges));
    Unionfind uf(N);

    repeat(i, M) {
        auto edge = graph.edges[i];
        int ur = uf.root(edge.u);
        int vr = uf.root(edge.v);

        if (uf.connect(edge.u, edge.v))
            W[uf.root(edge.u)] = min(H, W[ur] + W[vr]);
        if (W[uf.root(edge.u)] >= edge.value) {
            bound = edge.value;
            eFlg[i] = 1;
            markdfs(edge.u);
            markdfs(edge.v);
        }
    }

    int ans = 0;

    repeat(i, M) {
        ans += eFlg[i] == 0;
    }

    cout << ans << endl;


    return 0;
}

