    x = find(x);
    y = find(y);

    if (x == y) return;

    if (r[x] > r[y]) swap(x, y);

    par[x] = y;
    r[y] += r[x];
    sum[y] += sum[x];
    v[y].push_back(x);
    if (z == 1) f[y] = v[y].size();
