    struct UnionFindTree {
        vector<ll> parent, rank;
        int operator [](int x) { return find(x); }
        void init(int n) { parent.assign(n, -1); rank.assign(n, 0); }
        int find(int x) { return parent[x] < 0 ? x : (parent[x] = find(parent[x])); }
        bool same(int x, int y) { return find(x) == find(y); }
        ll size(int x) { return -parent[find(x)]; }
        bool unite(int x, int y) {
            if ((x = find(x)) == (y = find(y))) return 0;
            rank[x] = max(rank[x], rank[y] + 1); parent[x] += parent[y]; parent[y] = x; return 1;
        }
        bool uniteByRank(int x, int y) {
            if ((x = find(x)) == (y = find(y))) return 0; else if (rank[x] < rank[y]) swap(x, y);
            else if (rank[x] == rank[y]) rank[x]++; parent[x] += parent[y]; parent[y] = x; return 1;
        }
        bool uniteBySize(int x, int y) {
            if ((x = find(x)) == (y = find(y))) return 0; else if (size(x) < size(y)) swap(x, y);
            rank[x] = max(rank[x], rank[y] + 1); parent[x] += parent[y]; parent[y] = x; return 1;
        }
    };

int dfs(vector<vector<pair<int, int>>>& graph, vector<bool>& visited, int v, int weightLimit) {
    visited[v] = true;
    int n_edge = 0;
    for (auto& u : graph[v]) {
        if (u.first > weightLimit) continue;
        n_edge++;
        if (!visited[u.second]) {
            n_edge +=dfs(graph, visited, u.second, weightLimit);
        }
    }
    return n_edge;
}

int main() {
    int N, M;
    cin >> N >> M;

    UnionFindTree uf;
    uf.init(N);
    rep(i, N) {
        int x;
        cin >> x;
        uf.parent[i] = -x;
    }

    vector<pair<int, pair<int, int>>> edge(M);
    vector<vector<pair<int, int>>> graph(N);
    rep(i, M) {
        int a, b, y;
        cin >> a >> b >> y;
        a--; b--;
        edge[i] = mp(y, mp(a, b));
        graph[a].emplace_back(y, b);
        graph[b].emplace_back(y, a);
    }

    sort(all(edge));
    vector<bool> canbeLargest(M);

    for (int i = 0; i < M; ) {
        int j = i + 1;
        for (; j < M; ++j) {
            if (edge[j].first > edge[i].first) break;
        }

        for (int k = i; k < j; ++k) {
            uf.uniteByRank(edge[k].second.first, edge[k].second.second);
        }

        for (int k = i; k < j; ++k) {
            if (uf.size(edge[k].second.first) >= edge[k].first) {
                canbeLargest[k] = true;
            }
        }

        i = j;
    }

    vector<bool> visited(N);
    int ans = M;
    for (int i = M - 1; i >= 0; --i) {
        if (canbeLargest[i] && !visited[edge[i].second.first]) {
            ans -= dfs(graph, visited, edge[i].second.first, edge[i].first) / 2;
        }
    }

    write(ans);
}

