int pred(int a){
	if(a == dsu[a]) return a;
	else return dsu[a] = pred(dsu[a]);
}
void unite(int a, int b)
{
	a = pred(a);
	b = pred(b);
	if(a != b)
	{
		if(rang[a] < rang[b])
		{
			swap(a, b);
		}
		dsu[b] = a;
		last[a] = max(last[a], last[b]);
		sum[a] += sum[b];
		if(rang[a] == rang[b])
		{
			rang[a]++;
		}
	}
}
