#include <bits/stdc++.h>

using namespace std;

const int N = 100 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;
const int MAGIC = 370;

struct edge {
    int u, v;
    bool f;
    long long w;
};

int n, m;
int p[N], P[N], w[N], W[N], U[N];
long long X[N], wgt[N], Wgt[N];
vector<int> L;
edge E[N];

bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> X[i];

    for (int i = 0; i < m; ++i) {
        cin >> E[i].u >> E[i].v >> E[i].w;
        --E[i].u, --E[i].v;
        E[i].f = 1;
    }

    return true;
}

void init_dsu() {
    iota(p, p + n, 0);
    fill(w, w + n, 1);
    fill(U, U + n, 0);
    L.clear();
    L.reserve(n);

    for (int i = 0; i < n; ++i) {
        wgt[i] = Wgt[i] = X[i];
        P[i] = p[i];
        W[i] = w[i];
    }
}

inline void mark(int i) {
    if (!U[i]) {
        U[i] = 1;
        L.emplace_back(i);
    }
}

int getp(int v) {
    if (p[v] == v)
        return p[v];

    mark(v);
    return p[v] = getp(p[v]);
}

int getw(int v) { return wgt[getp(v)]; }

void join(int u, int v) {
    if ((u = getp(u)) == (v = getp(v)))
        return ;

    if (w[u] < w[v])
        swap(u, v);

    p[v] = u;
    w[u] += w[u] == w[v];
    wgt[u] += wgt[v];
    mark(u);
    mark(v);
}

void rollback() {
    for (const auto& i : L) {
        U[i] = 0;
        p[i] = P[i];
        w[i] = W[i];
        wgt[i] = Wgt[i];
    }

    L.clear();
}

void fix() {
    for (const auto& i : L) {
        U[i] = 0;
        P[i] = p[i];
        W[i] = w[i];
        Wgt[i] = wgt[i];
    }

    L.clear();
}

void solve() {
    sort(E, E + m, [](const edge& e1, const edge& e2) {
        return e1.w < e2.w;
    });

    for (int t = m - 1; t >= 0; --t)
        if (t % MAGIC == 0) {
            auto l = t;
            auto r = min(m - 1, t + MAGIC - 1);
            init_dsu();

            for (int i = 0; i < m; ++i)
                if (i < l || (i > r && E[i].f))
                    join(E[i].u, E[i].v);

            fix();

            for (int i = r; i >= l; --i) {
                for (int j = l; j <= i; ++j)
                    join(E[j].u, E[j].v);

                if (getw(E[i].u) < E[i].w)
                    E[i].f = 0;

                rollback();

                if (E[i].f) {
                    join(E[i].u, E[i].v);
                    fix();
                }
            }
        }

    auto ans = 0;

    for (int i = 0; i < m; ++i)
        if (!E[i].f)
            ++ans;

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

#include "bits/stdc++.h"
using namespace std;

int par[100010];
long long tot[100010];

stack <pair <int, int>> s;
stack <pair <int, long long>> t;

int root(int x) {
	if(x == par[x]) return par[x];
	int val = root(par[x]);
	s.emplace(x, par[x]);
	return par[x] = val;
}

void join(int x, int y) {
	x = root(x);
	y = root(y);
	if(x != y) {
		s.emplace(x, par[x]);
		t.emplace(y, tot[y]);
		par[x] = y;
		tot[y] += tot[x];
	}
}

int c[100010];
int l[100010], r[100010], w[100010];
int ans;
int n, m;

bool cmp(int p, int q) {
	return w[p] < w[q];
}
void solve() {
	for(int i = 1; i <= n; i++) {
		par[i] = i;
		tot[i] = c[i];
	}
	vector <int> can;
	for(int i = 1; i <= m; i++) {
		can.emplace_back(i);
	}
	sort(can.begin(), can.end(), cmp);

	stack <int> tm1, tm2;
	for(auto i : can) {
		tm1.push(s.size());
		tm2.push(t.size());
		join(l[i], r[i]);
	}
	reverse(can.begin(), can.end());
	for(auto i : can) {
		if(tot[root(l[i])] < w[i]) {
			while(s.size() > tm1.top()) {
				par[s.top().first] = s.top().second;
				s.pop();
			}
			while(t.size() > tm2.top()) {
				tot[t.top().first] = t.top().second;
				t.pop();
			}
			tm1.pop();
			tm2.pop();
			++ans;
		} else {
			break;
		}
	}
}

