	return par[u] = fin(par[u]);
}
ll uni(int u,int v){
	u = fin(u),v = fin(v);
	if(u == v){
		return x[u];
	}else{
		if(hei[u] < hei[v]){
			par[u] = v;
			x[v] += x[u];
			x[u] = 0;
