class TreeParent{
public:
  Int V;                        //ノード数
  Int root;                     //根
  vector<vector<Int> > G;       //Graph
  vector<Int> parent;           //親
  Int ok;
  TreeParent():V(-1){};
  TreeParent(Int V,Int root = 0):V(V),root(root),G(V),parent(V),ok(0){}
  TreeParent(vector<vector<Int> > G,Int root = 0):V(G.size()),root(root),G(G),parent(V),ok(0){}
  void resize(Int n){*this = TreeParent(n);}
  void add_edge(Int a,Int b){
    ok = false;
    assert(a < V && b < V);
    assert(a >= 0 && b >= 0);
    G[a].push_back(b);
    G[b].push_back(a);
  }
  void build(Int root = -1){
    ok = 1;
    if(root != -1) this->root = root;
    function<void(Int,Int)> dfs = [&](Int pos,Int pre){
      parent[pos] = pre;
      for(Int to:G[pos]) if(to != pre) dfs(to, pos);
    };
    dfs(this->root, -1);
  }
  Int get(Int u){assert(ok); assert(0 <= u && u < V); return parent[u];}

};

class UF{
public:
  Int V;
  vector<Int> par,rnk,sz;
  UF(){}
  UF(Int V):V(V),par(V),rnk(V,0),sz(V,1){for(Int i=0;i<V;i++)par[i]=i;}

  Int find(Int x){
    assert(x < V);
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }

  void unite(Int x,Int y){
    x=find(x), y=find(y);
    if(x==y)return;
    if(rnk[x]<rnk[y])par[x]=y, sz[y] += sz[x];
    else{
      par[y]=x;
      sz[x] += sz[y];
      if(rnk[x]==rnk[y])rnk[x]++;
    }
  }

  bool same(Int x,Int y){return find(x)==find(y);}

  Int size(Int x){return sz[find(x)];}
};

Int N, M;
