using T = tuple<Int,Int,Int>;
vector<Int> kurasukal(vector<T> &edge){
  sort(edge.begin(), edge.end());
  UF uf(N);
  vector<Int> used(M);
  for(Int i=0;i<M;i++){
    Int c, a, b;
    tie(c, a, b) = edge[i];
    if(uf.same(a, b)) continue;
    uf.unite(a, b);
    used[i] = 1;
  }
  return used;
}


vector<Int> calcDepth(vector<vector<P> > &G){
  vector<Int> depth(N);
  function<void(Int,Int,Int)> dfs = [&](Int pos,Int pre,Int dep){
    depth[pos] = dep;
    for(auto p:G[pos]){
      Int to = p.first;
      if(to != pre) dfs(to, pos, dep+1);
    }
  };
  dfs(0, -1, 0);
  return depth;
}

Int solve(vector<T> &edge){
  //木を作る
  vector<Int> used = kurasukal(edge);
  //pr(edge);
  //pr(used);
  vector<vector<P> > G(N);
  TreeParent tp(N);
  vector<map<Int,Int> > mG(N);

  for(Int i=0;i<M;i++){
    if(used[i] == 0) continue;
    Int c, a, b;
    tie(c, a, b) = edge[i];
    G[a].push_back(P(b, c));
    G[b].push_back(P(a, c));
    mG[a][b] = c;
    mG[b][a] = c;
    tp.add_edge(a, b);
  }

  //for(Int i=0;i<N;i++){for(auto p:G[i]) cout<<i+1<<" "<<p.first+1<<endl;}

  vector<Int> depth = calcDepth(G);
  //pr(depth);
  tp.build(0);
  vector<P> ord(N);
  for(Int i=0;i<N;i++) ord[i] = P(depth[i], i);
  sort(ord.begin(), ord.end(), greater<P>());
  //pr(ord);

  UF uf(N);
  Int sum = 0;
  for(Int i=0;i<N;i++) sum += w[i];
  for(Int i=0;i<N;i++) uf.sz[i] = w[i];

  for(Int i=0;i<N;i++){
    Int x = ord[i].second;
    Int par = tp.get(x);
    Int cost = mG[x][par];
    if(cost <= sum) {
      if(par != -1) uf.unite(x, par);
    }
    else sum -= uf.size(x);
  }

  //for(Int i=0;i<N;i++) pr(i, uf.size(i));

  Int ans = 0;
  for(Int i=0;i<M;i++){
    Int c, a, b;
    tie(c, a, b) = edge[i];
    //pr(a, b, uf.same(a, b), uf.size(a), uf.size(b));
    if(!(uf.same(a, b) && uf.size(a) >= c)) ans++;
  }
  return ans;
}

