	UF uf(n);
	REP(i,n)uf.val[i] = x[i];
	vector<P> mp;

	REP(i,m){
		ll a = v[i].SE.FI;
		ll b = v[i].SE.SE;
		if(!uf.same(a,b)){
			uf.unite(a,b);
			mp.PB(MP(i,uf.val[uf.find(a)]));
		}
	}

	UF uf2(n);
	REP(i,n)uf2.val[i] = x[i];
	for(ll i = mp.size() - 1;i >= 0;i--){
		ll id = mp[i].FI;
