/* UnionFind */

struct UnionFind{
  vector<int> data;
  vector<ll> sum, sum2, sum3;
  vector<priority_queue<pair<int,pair<int,int> > > > pqs;

  UnionFind(int s):data(s, -1), sum(s, 0), sum2(s), sum3(s), pqs(s) {}

  int root(int x){
    if(data[x] < 0) return x;
    return data[x] = root(data[x]);
  }

  bool set(int x, int y){
    x = root(x); y = root(y);
    if(x == y) return false;
    if (pqs[x].size() < pqs[y].size()) swap(x, y);

    data[x] += data[y];
    sum[x] += sum[y];
    sum2[x] += sum2[y];
    sum3[x] += sum3[y];

    while(pqs[y].size()) {
      pqs[x].push(pqs[y].top());
      pqs[y].pop();
    }

    data[y] = x;
    sum[y] = sum2[y] = 0;
    return true;
  }

  bool check(int x, int y){
    return root(x) == root(y);
  }

  int size(int x){
    return -data[root(x)];
  }
};



