class UnionFind{
public:
	vector<int> ran, par, cnt, weight;
	void init(int n){
		for(int i = 0;i < n;i++){
			par.push_back(i);
			ran.push_back(0);
      weight.push_back(0);
      cnt.push_back(0);
		}
	}

  void set_weight(int u, int w){
    weight[u] = w;
  }

	int find(int x){
		if(par[x] == x)return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y){
		x = find(par[x]);
		y = find(par[y]);
    if(x == y)cnt[x]++;
		if(x == y)return;
		if(ran[x] < ran[y]){
			par[x] = y;weight[y] += weight[x];cnt[y] += cnt[x] + 1;cnt[x] = 0;
		}else{
			par[y] = x;weight[x] += weight[y];cnt[x] += cnt[y] + 1;cnt[y] = 0;
			if(par[x] == par[y])ran[x]++;
		}
	}

	bool same(int x, int y){
		return find(par[x]) == find(par[y]);
	}
};

