class UnionFind {
    vector<int> par, Size;
    vector<ll> omomi;

  public:
    UnionFind(int n, vector<ll> v) : par(n), Size(n), omomi(v) {
        rep(i, n) {
            par[i] = i;
            Size[i] = 1;
        }
    }

    int root(int x) {
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool same(int x, int y) { return root(x) == root(y); }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y) return;
        if(Size[x] > Size[y]) {
            Size[x] += Size[y];
            par[y] = x;
            omomi[x] += omomi[y];
        } else {
            Size[y] += Size[x];
            par[x] = y;
            omomi[y] += omomi[x];
        }
    }

    int size(int x) { return Size[root(x)]; }
    ll weight(int x) { return omomi[root(x)]; }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n, m;
    cin >> n >> m;
    vector<ll> x(n);
    rep(i, n) cin >> x[i];
    UnionFind UF(n, x);
    struct Edge {
        int a, b, idx;
        ll y;
        Edge(int a, int b, ll y, int idx) : a(a), b(b), y(y), idx(idx) {}
    };
    struct Edge2 {
        int to, idx;
        ll cost;
        Edge2(int to, ll cost, int idx) : to(to), cost(cost), idx(idx) {}
    };
    vector<Edge> e;
    vector<vector<Edge2>> G(n);
    rep(i, m) {
        int a, b;
        ll y;
        cin >> a >> b >> y;
        a--;
        b--;
        e.push_back(Edge(a, b, y, i));
        G[a].push_back(Edge2(b, y, i));
        G[b].push_back(Edge2(a, y, i));
    }
    sort(ALL(e), [&](Edge a, Edge b) { return a.y < b.y; });
    vector<Edge> e2;
    for(Edge i : e) {
        UF.unite(i.a, i.b);
        if(UF.weight(i.a) >= i.y) e2.push_back(i);
    }
    sort(ALL(e2), [&](Edge a, Edge b) { return a.y > b.y; });
    vector<bool> use(m);
    for(Edge i : e2) {
        if(use[i.idx]) continue;
        queue<int> que;
        que.push(i.a);
        while(!que.empty()) {
            int v = que.front();
            que.pop();
            for(Edge2 j : G[v]) {
                if(j.cost <= i.y && !use[j.idx]) {
                    use[j.idx] = true;
                    que.push(j.to);
                }
            }
        }
    }
    int ans = 0;
    rep(i, m) ans += 1 - use[i];
    cout << ans << endl;

    return 0;
}

