			par[u] = v;
			x[v] += x[u];
			x[u] = 0;
			return x[v];
		}else{
			par[v] = u;
			x[u] += x[v];
			x[v] = 0;
			if(hei[u] == hei[v]) hei[u]++;
			return x[u];
		}
	}
}
