class UnionFind {

	vector<int> unions, talls, sents, dists, sizes;
	int size;
public:
	UnionFind() {}
	UnionFind(int size) :size(size) {
		init();
	}
	void init() {
		unions = vector<int>(size);
		talls = vector<int>(size);
		sents = vector<int>(size);
		dists = vector<int>(size);
		sizes = vector<int>(size);
		FOR(i, 0, size) {
			unions[i] = i;
			sents[i] = 0;
			sizes[i] = 0;
			//			ns[i].PB(pr(0,1));
			talls[i] = 1;
		}
	}
	int find(int x, int t = 0) {
		if (unions[x] == x || sents[x] > t) return x;
		return find(unions[x], t);

	}
	int minisize(int x) {
		if (x == unions[x]) return sizes[x];
		return minisize(find(x));
	}
	bool isFriend(int a, int b, int t = 0) {
		return find(a, t) == find(b, t);
	}
	void unite(int a, int b,LL y, int t = 0) {
		a = find(a, t);
		b = find(b, t);
		if (talls[a] < talls[b]) unite(b, a, t);
		if (isFriend(a, b, t)) {
			sizes[a] += 1;
			MX(maxim[a], y);
			assert(maxim[a] <= y);
			if (maxim[a] <= X[a]) {
				assert(sizes[a] == 1);
				anses += sizes[a];
				sizes[a] = 0;
			}
			return;
		}
		else {

			MX(maxim[a], maxim[b]);
			//cout << maxim[a] << " " << y << endl;
			assert(maxim[a] <= y);
			MX(maxim[a], y);
			sizes[a] += sizes[b]+1;
			sizes[b] = 0;
			X[a] += X[b];
			X[b] = 0;
			if (maxim[a] <= X[a]) {
				anses += sizes[a];
				sizes[a] = 0;
			}
			sents[b] = t;
			talls[a] = max(talls[a], talls[b] + 1);
			unions[b] = a;
			dists[b] = 1;
			//			ns[a].PB(pr(t,ns[b].back().second+ns[a].back().second));
		}
	}
};
