		if (p!=q) kruskal_tree::link(p,q,i),fa[p]=fa[q]=id[i],flag[i]=1;
	}
	kruskal_tree::build();
	kruskal_tree::del();
	for (int i=1;i<=cnt;i++) fa[i]=i;
	for (int i=1;i<=cnt;i++)
	if (!kruskal_tree::degree[i]) dfs(i);
	for (int i=1;i<=m;i++)
	if (find(e[i].x)==find(e[i].y)&&kruskal_tree::size[find(e[i].x)]>=e[i].z) ans++;
	cout<<m-ans;
	return 0;
}

