// Disjoint Set DataStructure
int parent[100001];         // reserve space for map if n > 10000
int urank[100001];
ll sum[100001],ar[100001];
ll sz[100001],nt[100001];

void create(ll x)
{
    parent[x] = x ;
    urank[x] = 1 ;         // rank = no. of nodes in its subtree
    sz[x]=0;
    nt[x]=0;
    sum[x]=ar[x];
}

ll find(ll x)
{
    if( parent[x] != x )    //path compression
    {
        parent[x] = find(parent[x]) ;
    }
    return parent[x];
}

void merge(ll x, ll y,ll z)
{
    ll xroot = find(x);
    ll yroot = find(y);

    if( urank[xroot] <= urank[yroot] )    // Union by rank
    {
        parent[xroot] = yroot ;
        urank[yroot] = urank[yroot] + urank[xroot] ;
        sum[yroot]+=sum[xroot];
        nt[yroot]+=nt[xroot];
        sz[yroot]+=sz[xroot]+1;
        //cout<<sum[yroot]<<"............"<<z<<endl;
        if(sum[yroot]>=z)
            nt[yroot]=0;
        else
            ++nt[yroot];
    }
    else
    {
        //cout<<sum[xroot]<<"::::"<<sum[yroot]<<endl;
        parent[yroot] = xroot;
        urank[xroot] = urank[xroot] + urank[yroot] ;
        sum[xroot]+=sum[yroot];
        nt[xroot]+=nt[yroot];
        sz[xroot]+=sz[yroot]+1;
        //cout<<sum[xroot]<<"............"<<z<<endl;
        if(sum[xroot]>=z)
            nt[xroot]=0;
        else
            ++nt[xroot];
    }
}

