const int maxn = 1e5 + 7;

int prev[maxn], rank[maxn];

int getPrev(int v){
    if (v == prev[v])
        return v;
    prev[v] = getPrev(prev[v]);
    return prev[v];
}

ll summa[maxn];

void join(int a, int b){
    a = getPrev(a);
    b = getPrev(b);
    if (a == b)
        return;
    if (rank[a] < rank[b])
        swap(a, b);
    prev[b] = a;
    summa[a] += summa[b];
    if (rank[a] == rank[b])
        rank[a]++;
}

ll kek[maxn];

vector<pair<int, int> > g[maxn];
bool ok[maxn];

void dfs(int v, ll x){
    ok[v] = 1;
    for (pair<int, int> u : g[v]){
        if (!ok[u.second] && u.first <= x)
            dfs(u.second, x);
    }
}

