int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, N, M );
	VI X( N );
	cin >> X;
	VI A( M ), B( M ), Y( M );
	VVI G( N );
	REP( i, M )
	{
		cin >> A[i] >> B[i] >> Y[i];
		--A[i], --B[i];
		G[ A[i] ].PB( i );
		G[ B[i] ].PB( i );
	}

	VI E( M );
	iota( ALL( E ), 0 );
	sort( ALL( E ), [&]( const int e, const int f ){ return Y[e] < Y[f]; } );

	VI possibly_heaviest( M );

	{
		UnionFind uf( N );
		VT< LL > weights( ALL( X ) );

		FOR( e, E )
		{
			const int u = A[e], v = B[e];

			if ( !uf.same( u, v ) )
			{
				const LL w = weights[ uf.find( u ) ] + weights[ uf.find( v ) ];
				uf.unite( u, v );
				weights[ uf.find( u ) ] = w;
			}

			const LL w = weights[ uf.find( u ) ];
			possibly_heaviest[e] = Y[e] <= w;
		}
	}

	reverse( ALL( E ) );

	VI use_edge( M );
	FOR( e, E )
	{
		if ( use_edge[e] || !possibly_heaviest[e] )
		{
			continue;
		}

		use_edge[e] = true;

		queue< int > que;
		que.push( A[e] );
		que.push( B[e] );

		VI visited( N );
		visited[ A[e] ] = visited[ B[e] ] = true;

		while ( !que.empty() )
		{
			const int u = que.front();
			que.pop();

			FOR( f, G[u] )
			{
				const int v = A[f] == u ? B[f] : A[f];

				if ( Y[e] < Y[f] || visited[v] )
				{
					continue;
				}

				use_edge[f] = visited[v] = true;
				que.push( v );
			}
		}
	}

	cout << count( ALL( use_edge ), 0 ) << endl;

	return 0;
}

