int main() {
    class union_find{
        vector<long> parent, tree_size, tree_cost, e_below_c, e_kakutei;
    public:
        union_find(unsigned long _n) : parent(_n), tree_size(_n, 1), tree_cost(_n), e_below_c(_n, 0), e_kakutei(_n, 0){
            for(unsigned long i = 0; i < _n; ++i)parent[i] = i;
        }
        void init(vector<long long> &cost){
            for(int i = 0; i < cost.size(); ++i) tree_cost[i] = cost[i];
        }
        ll find(ll x){
            while(parent[x] != x)x = parent[x] = parent[parent[x]];
            return x;
        }
        void merge(ll a, ll b){
            a = find(a);
            b = find(b);
            if(a==b) return;
            if(tree_size[a] < tree_size[b])swap(a, b);
            tree_size[a] += tree_size[b];
            tree_cost[a] += tree_cost[b];
            e_below_c[a] += e_below_c[b];
            e_kakutei[a] += e_kakutei[b];
            parent[b] = a;
            return;
        }
        bool same(ll a, ll b){
            a = find(a);
            b = find(b);
            return a == b;
        }
        void plus_e(int cost, int a){
            a = find(a);
            ++e_below_c[a];
            if(tree_cost[a] >= cost) e_kakutei[a] = e_below_c[a];
        }
        ll get_edgenum(int a) {
            return find(a) == a ? e_kakutei[a] : 0;
        }
    };
