        int u = uf.find(a[i].u),v = uf.find(a[i].v);
        if (uf.same(u,v)) {
            if (w[u] >= a[i].w) t[u] = 0;
            else t[u]++;
        } else {
            if (uf.size(u) < uf.size(v)) swap(u,v);
            if (w[u]+w[v] >= a[i].w) t[u] = 0;
            else t[u] += t[v]+1;
            w[u] += w[v];
            uf.unite(u,v);
        }
    }
    cout << t[uf.find(0)] << endl;
    return 0;
}

