            sm[i] = w[i];
        }


    }

    long long get(long long v) {
        if (cmp[v] == v) {
            return v;
        }
        long long x = get(cmp[v]);
        cmp[v] = x;
        return x;
    }

    bool join(long long j) {
        long long u = y[j].first, v = y[j].second;
        u = get(u), v = get(v);

        if (u == v) {
            if (d[j] <= sm[u]) {
                bl[u] = 0;
            } else {
                ++bl[u];
            }
        } else {

            if (h[v] == h[u]) {
                cmp[u] = v;
                ++h[v];

                bl[v] += bl[u];
                sm[v] += sm[u];

                if (d[j] <= sm[v]) {
                    bl[v] = 0;
                } else {
                    ++bl[v];
                }
            } else {
                if (h[v] < h[u]) {
                    cmp[u] = v;

