                    bl[u] += bl[v];
                    sm[u] += sm[v];

                    if (d[j] <= sm[u]) {
                        bl[u] = 0;
                    } else {
                        ++bl[u];
                    }
                }

            }
        }
        return true;
    }

    bool check(long long v, long long u) {
