int fd(int v){ return gp[v] == v ? v : gp[v] = fd(gp[v]); }
void uni(int u, int v) {
	u = fd(u);
	v = fd(v);
	if (u == v) return ;
	if (siz[u] > siz[v]) swap(u, v);
	for (int x : mem[u]) {
		gp[x] = v;
		mem[v].pb(x);
	}
	siz[v] += siz[u];
	sum[v] += sum[u];
}
