ll dfs(int i, vector<int>& x, vector<map<int, int>>& e, int t, vector<int>& o)
{
	ll r = x[i];
	o[i] = t;
	for (auto& f : e[i])
	{
		if (o[f.first])
			continue;
		r += dfs(f.first, x, e, t, o);
	}
	return r;
}

int visit(int n, int i, vector<int>& x, vector<map<int, int>>& e, vector<int>& o, ll w, int t)
{

	int r = 0;

	REP (j, n)
	{
		if (o[j] != t)
			continue;

		for (auto it = e[j].begin(); it != e[j].end();)
			if (it->second > w)
			{
				it = e[j].erase(it);
				++r;
			}
			else
				++it;
	}

	vector<int> p(n);
	ll v = dfs(i, x, e, i + 1, p);

	if (v == w)
		return r;

	r += visit(n, i, x, e, p, v, i + 1);

	REP (j, n)
	{
		if (o[j] != t)
			continue;
		if (p[j])
			continue;

		ll v = dfs(j, x, e, j + 1, p);

		r += visit(n, j, x, e, p, v, j + 1);
	}

	return r;
}

