const ll mod = 1e9+7;
const int maxn = 1e6 + 5;



int n, m;
ll x[maxn];
ll cc[maxn];
int par[maxn], siz[maxn];
int edge_deletes[maxn];

int parent(int v) {
    if (par[v]==v) return v;
    return par[v] = parent(par[v]);
}


void join(int u, int v, ll wei) {
    u = parent(u);
    v = parent(v);

    if (u == v) {
	if (wei > cc[u]) {
	    edge_deletes[u]++;
	} else {
	    edge_deletes[u]=0;
	}
    } else {
	if (siz[u]<siz[v]) swap(u,v);
	cc[u] += cc[v];
	siz[u] += siz[v];
	edge_deletes[u] += edge_deletes[v];
	par[v] = u;

	// Even if we can't defeat this edge, it's in our best interest to still join the
	// nodes so we can hopefully overpower the edge with future joins.
	if (wei > cc[u]) {
	    edge_deletes[u]++;
	} else {
	    edge_deletes[u]=0;
	}
    }
}

