int N, M;
int X[100000];

int U[100000], R[100000];
long long T[100000];
int MX[100000];

int find(int x) {
  if (U[x] == x) return x;
  return U[x] = find(U[x]);
}

void unite(int x, int y) {
  x = find(x), y = find(y);
  if (x == y) return;
  if (R[x] < R[y]) swap(x, y);
  U[y] = x;
  R[x] += R[y]; R[y] = 0;
  T[x] += T[y]; T[y] = 0;
  MX[x] = max(MX[x], MX[y]);
}
bool f(int x) {
  x = find(x);
  return T[x] >= MX[x];
}

signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N >> M;
  rep(i, N) cin >> X[i];
  vector<pair<int, P > > edges;
  rep(i, M) {
    int a, b,y;
    cin >> a >> b>>y;a--,b--;
    edges.pb(make_pair(y,P(a,b)));
  }
  sort(all(edges));
  int m = 0;
  int unstable = 0;
  rep(i, N) U[i] = i, R[i] = 1, T[i] = X[i];
  rep(i, M) {
    int a = edges[i]._2._1, b = edges[i]._2._2, y = edges[i]._1;
    if (find(a)!=find(b)) {
      if (!f(a)) unstable--;
      if (!f(b)) unstable--;
      unite(a, b);
    }
    MX[find(a)] = max(MX[find(a)], y);
    if (!f(b)) unstable++;
    if (unstable == 0) m = i+1;
    //cout<<a<<"<->"<<b<<", y="<<y<<": unstable="<<unstable<<"\n";
  }

  cout << M-m << "\n";
