	if (child[f][c]) fa[child[f][c]] = f;
	fa[x] = g;
	fa[f] = x;
	Update(f);
}
inline void Splay(int x) {
	int y = x; top = 0;
	stk[++top] = y;
	while (!Isroot(y)) stk[++top] = y = fa[y];
	while (top) Pushdown(stk[top--]);
	while (!Isroot(x)) {
		y = fa[x];
		if (!Isroot(y))
			Rotate((lc(y) == x) == (lc(fa[y]) == y) ? y : x);
		Rotate(x);
	}
