		if (!same(u, v)) {
			int Ru = root(u);
			int Rv = root(v);
			unite(u, v);
		}

		int Ru = root(u);
		cn[Ru]++;

		if (X[Ru] >= w) {
			ans -= cn[Ru];
			cn[Ru] = 0;
		}
	}

	cout << ans << endl;

	return 0;
}

