int find_fa (int x)	{return fa[x]==x?x:fa[x]=find_fa(fa[x]);}
int in[N];
int ans=0,sum=0;
struct qt
{
	int son[2],fa;
	int val;
	LL sum,sum1;//权值和   轻儿子的权值和 
	bool rev;
}tr[N];
void Push_down (int now)
{
	int s1=tr[now].son[0],s2=tr[now].son[1];
	if (tr[now].rev)
	{
		tr[now].rev^=1;tr[s1].rev^=1;tr[s2].rev^=1;
		swap(tr[now].son[0],tr[now].son[1]);
	}
}
void update (int x)
{
	int s1=tr[x].son[0],s2=tr[x].son[1];
	tr[x].sum=tr[s1].sum+tr[s2].sum+tr[x].sum1+tr[x].val;
}
bool Is_root (int x)	{int ff=tr[x].fa;return (tr[ff].son[0]!=x&&tr[ff].son[1]!=x);}
void rotate (int x)
{
    int y=tr[x].fa,z=tr[y].fa,r,R;
    int w=(tr[y].son[0]==x);

    r=tr[x].son[w];R=y;
    tr[R].son[1-w]=r;
    if (r!=0) tr[r].fa=R;

    r=x;R=z;
    if (!Is_root(y))
    {
        if (tr[R].son[0]==y) tr[R].son[0]=r;
        else tr[R].son[1]=r;
    }
    if (r!=0) tr[r].fa=R;

    r=y;R=x;
    tr[R].son[w]=r;
    if (r!=0) tr[r].fa=R;

    update(y);update(x);update(z);
}
void PD (int x)
{
	if (!Is_root(x)) 
	{
		PD(tr[x].fa);
	}
	Push_down(x);
}
void Splay (int x)
{
	update(x);PD(x);
	while (!Is_root(x))
	{
		int y=tr[x].fa,z=tr[y].fa;
		update(x);update(y);update(z);
		if (!Is_root(y))
		{
			if ((tr[z].son[0]==y)==(tr[y].son[0]==x)) rotate(y);
			else rotate(x);
		}
		rotate(x);
	}
}
void Access (int x)
{
	int last=0;
	while (x!=0)
	{
		Splay(x);
		int xx=tr[x].son[1];
		tr[x].sum1=tr[x].sum1+tr[xx].sum-tr[last].sum;
		tr[x].son[1]=last;last=x;
		update(x);
		x=tr[x].fa;
	}
}
void make_root (int x)
{
	Access(x);
	Splay(x);
	tr[x].rev^=1;
	Push_down(x);
}
void link (int x,int y)
{
	make_root(x);
	make_root(y);
	tr[x].fa=y;
	tr[y].sum1+=tr[x].sum;
	update(y);
}
void cut (int x,int y)
{
	make_root(x);Access(y);Splay(y);
	if (tr[x].fa==y)	tr[x].son[1]=0;

	tr[x].fa=0;tr[y].son[0]=0;
	update(x);update(y);
	make_root(x);make_root(y);
}
