        edge_num[find(x)]++;
        if (!Same(x, y)) {
            Merge(x, y);
        }
    }
    inline bool Same(li x, li y) {
        return (find(x) == find(y));
    }
    inline void Merge(li x, li y) {
        li parent_x = find(x);
        li parent_y = find(y);
        parent[parent_x] = parent_y;
        value[parent_y] += value[parent_x];
        edge_num[parent_y] += edge_num[parent_x];
    }
    inline li find(li x) {
        if (parent[x] == x)return x;
        else return (parent[x] = find(parent[x]));
    }
    vector<li> parent;
    vector<li> value;
    vector<li> edge_num;
};

