    u = _u;
    v = _v;
    w = _w;
  }
};

int roll[N];
pair <int, int> asd[N];
int cnt = 0;

struct DSU {
  int par[N], siz[N];
  ll sum[N];
  DSU() {
    iota(par, par + N, 0);
    fill(siz, siz + N, 1);
  }
  int getpar(int a) {
    if (par[a] == a) return a;
    return getpar(par[a]);
  }
  void connect(int a, int b) {
    a = getpar(a);
    b = getpar(b);
    if (a != b) {
      if (siz[a] > siz[b]) swap(a, b);
      asd[cnt] = {a, b};
      roll[cnt++] = par[a];
      par[a] = b;
      sum[b] += sum[a];
      siz[b] += siz[a];
    }
  }
  void rollback() {
    int a = asd[cnt].first;
    int b = asd[cnt].second;
    siz[b] -= siz[a];
    sum[b] -= sum[a];
    par[a] = roll[cnt];
  }
};
DSU dsu;

