        ind.push_back(i);
        dsu.connect(a, b);
      }
      i++;
    }
  }
  reverse(ind.begin(), ind.end());
  for (int i = 0; i < ind.size(); i++) {
    cnt--;
    if (vec[ind[i]].w > dsu.sum[dsu.getpar(vec[ind[i]].u)]) {
