    for (int i = 0; i < M; i++) {
        int a = e[i].second.first, b = e[i].second.second;
        ll x = e[i].first;
        if (uf.same(a, b)) {
            g[dummy].push_back(top[uf.find(a)]);
            w[dummy] = x;
            top[uf.find(a)] = dummy;
            dummy++;
        } else {
            g[dummy].push_back(top[uf.find(a)]);
            g[dummy].push_back(top[uf.find(b)]);
            uf.unite(a, b);
            top[uf.find(a)] = dummy;
            w[dummy] = x;
            dummy++;
        }
    }
    const int root = dummy - 1;
    std::vector<ll> sub(M + N, 0);
    auto dfs1 = [&](auto&& self, const int s) -> void {
        if (s < N) {
            sub[s] = X[s];
        } else {
            for (const int to : g[s]) {
                self(self, to);
                sub[s] += sub[to];
            }
        }
    };
    dfs1(dfs1, root);
    int ans = 0;
    auto dfs2 = [&](auto&& self, const int s, const ll v) -> void {
        if (w[s] > v) {
            ans++;
            for (const int to : g[s]) {
                self(self, to, sub[to]);
            }
        } else {
            for (const int to : g[s]) {
                self(self, to, v);
            }
        }
    };
    dfs2(dfs2, root, sub[root]);
    std::cout << ans << std::endl;
    return 0;
}

