template<class T>
struct union_find{
    int N;
    vector<int> par, rank;
    vector<T> sz;

    union_find(int N) : N(N), par(N + 1), rank(N + 1, 1), sz(N + 1, 1){
        for(int i = 0; i <= N; ++i) par[i] = i;
    }

    void init(int n, T s){sz[n] = s;}

    int find(int v){
        return (v == par[v] ? v : find(par[v]));
    }

    void unite(int x, int y, int t){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] > rank[y]){
            par[y] = x;
            sz[x] += sz[y];
        }else{
            par[x] = y;
            sz[y] += sz[x];
            if(rank[x] == rank[y]) rank[y]++;
        }
    }

    T get_sz(int x){
        return sz[find(x)];
    }
};

struct arc{
    int from, to, idx;
    ll Y;
    arc(int from, int to, int idx, ll Y) : from(from), to(to), idx(idx), Y(Y) {}

    bool operator < (const arc& e1) const {
        return Y < e1.Y;
    }
    bool operator > (const arc& e1) const {
        return Y > e1.Y;
    }
};

struct edge{
    int to, idx;
    ll Y;
};

int N, M;
ll X[100010];
bool ok[100010], used[100010];
vector<edge> G[100010];

void dfs(int v, ll Y){
    if(used[v]) return;
    used[v] = true;

    for(auto u : G[v]){
        if(u.Y > Y) continue;
        ok[u.idx] = true;
        dfs(u.to, Y);
    }
}


int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N >> M;

    union_find<ll> uf(N);
    for(int i = 1; i <= N; ++i){
        cin >> X[i];
        uf.init(i, X[i]);
    }

    vector<arc> as;
    for(int i = 1; i <= M; ++i){
        int A, B;
        ll Y;
        cin >> A >> B >> Y;
        as.emplace_back(arc{A, B, i, Y});
        G[A].emplace_back(edge{B, i, Y});
        G[B].emplace_back(edge{A, i, Y});
    }

    sort(as.begin(), as.end());
    vector<arc> mx;
    for(int i = 0; i < M; ++i){
        uf.unite(as[i].to, as[i].from, i);
        if(uf.get_sz(as[i].to) >= as[i].Y) mx.emplace_back(as[i]);
    }

    for(int i = (int)mx.size() - 1; i >= 0; --i){
        dfs(mx[i].to, mx[i].Y);
    }

    int ans = M;
    for(int i = 1; i <= M; ++i) ans -= ok[i]; 
    cout << ans << endl;
    return 0;
}

