        sz[i] = 1;
    }
    for(int i=1;i<=m;i++){
        scanf("%d%d%d",&a[i],&b[i],&c[i]);
        p[i] = make_pair(c[i] , i);
    }
    sort(p + 1 , p + m + 1);
    int ind = -1;
    for(int i=1;i<=m;i++){
        int x = p[i].first;
        int id = p[i].second;
        int aa = a[id] , bb = b[id];
        if(findher(aa) != findher(bb)){
            tmerge(aa , bb);
        }
        int P = findher(aa);
        ++edge[P];
        if(sum[P] >= 1ll * x){
            mark[i] = true;
            ind = i;
        }
    }
    if(ind == -1){
        cout<<m<<endl;
        return 0;
    }
    for(int i=1;i<=n;i++){
        parent[i] = i;
        sum[i] = cnt[i];
        sz[i] = 1;
        g[i].push_back(i);
        edge[i] = 0;
    }
    for(int i=1;i<=ind;i++){
        int x = p[i].first;
        int id = p[i].second;
        int aa = a[id] , bb = b[id];
        if(findher(aa) != findher(bb)){
            tmerge(aa , bb);
        }
        int p = findher(aa);
        edge[p]++;
    }
    int answ = 0;
    for(int i=ind;i>=1;i--){
        int v = a[ p[i].second ];
        if(mark[i] && used[v] == false){
            v = findher(v);
            answ += edge[v];
            for(int j=0;j<(int)g[v].size();j++){
                int to = g[v][j];
                used[to] = true;
            }
        }
    }
    cout<<m - answ<<endl;
