ll find(ll x) {
	//cout << x << endl;
	if (lead[x] == x)
		return x;
	return lead[x] = find(lead[x]);
}

void unite(ll a, ll b) {
	ll x = find(a);
	ll y = find(b);
	if (x == y)
		return;
	if (rang[x] >= rang[y])
		swap(x, y);
	lead[x] = y;
	if (rang[x] == rang[y])
		rang[y]++;
	w[y] += w[x];
}


void dfs(int v, int val) {
	for (auto c : g[v]) {
		if (c.ff <= val && used[c.ff] == 0) {
			used[c.ff] = 1;
			dfs(c.ss, val);
			ans++;
		}
	}
}



