        if (u == pp) continue;
        pr[u] = v;
        dfs(u, v);
        w[v] += w[u];
    }
    rb[v] = timer;
    time2++;
    tout[v] = time2;
}
int getsum(int v, int tl, int tr, int x, int l, int r){
    if (l > r || (a[v] != 0 && a[v] != x)) return 0;
   // cout << tl << " " << tr << " " << x << "  " << l << " " << r << endl;
    if (a[v] == x && tl == l && tr == r){
        return c[v];
    }
    push(v);
    int mid = (tl + tr) / 2;;
    return getsum(v + v, tl, mid, x, l, min(mid, r)) +
    getsum(v + v + 1, mid + 1, tr, x, max(l, mid + 1), r);
    if (a[v + v] == a[v + v + 1] && a[v + v] != 0) a[v] = a[v + v];
}
int root(int v){
    int u = rm[v];
    for (auto i: events){
        if (tin[i] >= tin[u] && tout[i] <= tout[u] && tin[i] <= tin[v] && tout[i] >= tout[v]) rm[v] = i;
    }
    return rm[v];
}
void calcroot(){
    events.clear();
    queue < pair < int, int > > q;
    q.push({1, 1});
    while(!q.empty()){
        auto it = q.front();
        int v = it.F;
        int x = rm[it.S];
        if (cc[v]) x = v;
        rm[v] = x;
        for (auto u: g[v]){
            if (u != it.S){
                q.push({u, v});
            }
        }
    }
}
