void dfs2(llint v){
	if(tree[v].w == -1) return;
	vec.push_back(tree[v].id);
	dfs2(tree[v].left), dfs2(tree[v].right);
}


llint dfs(llint v)
{
	if(tree[v].w == -1) return 0;
	if(tree[v].sum >= tree[v].w){
		dfs2(v);
		return tree[v].sz-1;
	}
	return dfs(tree[v].left) + dfs(tree[v].right);
}


