//UnionFind
//How to use
//unite(x,y) : 集合 x と y を併合する. 併合済のとき false, 未併合のとき true が返される
//find(k) : 要素 k が属する集合を求める
//size(k) : 要素 k が属する集合の要素の数を求める
//UnionFind
//How to use
//unite(x,y) : 集合 x と y を併合する. 併合済のとき false, 未併合のとき true が返される
//find(k) : 要素 k が属する集合を求める
//size(k) : 要素 k が属する集合の要素の数を求める
struct UnionFind {
    vector<int> data;

    UnionFind(int sz) {
        data.assign(sz, -1);
    }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y)
            return (false);
        if (data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }

    int find(int k) {
        if (data[k] < 0)
            return (k);
        return (data[k] = find(data[k]));
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int k) {
        return (-data[find(k)]);
    }
};

int N, M;
int nouse[101010];        //使わない辺
int used[101010];         //使った頂点
int used_edge[101010];    //使った辺
itn maybe_nouse[101010];  //辺
int W[101010];
vector<vector<pair<int, int>>> G;
struct Edge {
    int A, B, Y;
};
vector<Edge> V;
vector<int> X;

void f(int idx) {
    if (used[idx])
        return;
    used[idx] = 1;
    for (auto& nxt : G[idx]) {
        if (!nouse[nxt.second]) {
            used_edge[nxt.second] = 1;
            f(nxt.first);
        }
    }
    return;
}


void solve() {
    UnionFind uf(N);
    sort(all(V), [](Edge a, Edge b) { return a.Y < b.Y; });
    FOR(M) {
        Edge v = V[i];
        int wei = W[uf.find(v.A)];
        if (!uf.same(v.A, v.B)) {
            wei += W[uf.find(v.B)];
            uf.unite(v.A, v.B);
        }
        if (wei < v.Y) {
            maybe_nouse[i] = 1;
        }
        W[uf.find(v.A)] = wei;
        G[v.A].pb({v.B, i});
        G[v.B].pb({v.A, i});
    }
    int ans = 0;
    for (int i = M - 1; i >= 0; i--) {
        auto v = V[i];
        if (!used_edge[i] && maybe_nouse[i]) {
            nouse[i] = 1;
            ans++;
            continue;
        }
        f(v.A);
    }
    cout << ans << endl;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    cin >> N >> M;
    X.resize(N);
    G.resize(N);
    FOR(N) {
        cin >> X[i];
        W[i] = X[i];
    }
    FOR(M) {
        int a, b, y;
        cin >> a >> b >> y;
        a--;
        b--;
        V.pb({a, b, y});
    }


    solve();
    return 0;
}

