                valid[i]=0;
        }
        else
        {
            if(size[rx]<size[ry])
                swap(rx,ry);
            dsu[ry]=rx;
            suw[rx]+=suw[ry];
            med[rx]=max(med[rx],med[ry]);
            size[rx]+=size[ry];
            med[rx]=max(med[rx],w);
            if(med[rx]<=suw[rx]){
                valid[i]=1;
            }
            else
                valid[i]=0;
        }
    }
    for(int i=m-1;i>=0;--i)
    {
        if(valid[i]==0)
            continue;
        int x,y,w;
        x=ed[i].S.F;
        y=ed[i].S.S;
        w=ed[i].F;
        if(vis[x]==1||vis[y]==1)
            continue;
        dfs(x,w);
    }
    int ans=0;
    for(int i=0;i<m;++i)
        ans+=!e[i];
    cout<<ans;
}

