  return U[x] = find(U[x]);
}

void unite(int x, int y) {
  x = find(x), y = find(y);
  if (x == y) return;
  if (R[x] < R[y]) swap(x, y);
  U[y] = x;
  R[x] += R[y]; R[y] = 0;
  T[x] += T[y]; T[y] = 0;
  num_e[x] += num_e[y];
  MX[x] = max(MX[x], MX[y]);
}
bool f(int x) {
  x = find(x);
  return T[x] >= MX[x];
}

