int Root(int x)
{
    if (x == root[x]) return x;
    return root[x] = Root(root[x]);
}

int Merge(Edge A)
{
    int u = A.u, v = A.v, w = A.w;
    u = Root(u);
    v = Root(v);
    if (u == v) return 1;
    if (sz[u] > sz[v])
    {
        v = v + u;
        u = v - u;
        v = v - u;
    }
    sz[v] += sz[u];
    s[v] += s[u];
    cnt[v] += cnt[u] + 1;
    root[u] = v;
    if (A.w <= s[v])
    {
        ans += cnt[v];
        cnt[v] = 0;
    }
    return 0;
}

