class UF_pop {
public:
    int sz;
    vector<int> par,nrank; vector<vector<int> > hist;
    UF_pop(int node_size) : sz(node_size), par(sz), nrank(sz, 0){
        for(int i = 0; i < sz; i++){
            par[i] = i;
        }
    }
    void reinit(){
        for(int i = 0; i < sz; i++){
            nrank[i] = 0; par[i] = i;
        }
    }
    int find(int x){
        return (par[x] == x)?(x):find(par[x]);
    }
    void pop(){
        if(!hist.empty()){
            auto& a = hist.back();
            par[a[0]] = a[0], nrank[a[0]] = a[1], par[a[2]] = a[2];
            if(!same(a[0],a[2])){
                if(get_sum(a[0]) > get_sum(a[2])){
                    sum[find(a[0])] -= sum[find(a[2])];
                }else{
                    sum[find(a[2])] -= sum[find(a[0])];
                }
            }
            hist.pop_back();
        }
    }
    void unite(int x,int y) {
        x = find(x); y = find(y);
        hist.push_back({x,nrank[x],y});
        if(x == y) return;
        if(nrank[x] < nrank[y]){
            par[x] = y;
            sum[y] += sum[x];
        }else{
            nrank[x] += (nrank[x] == nrank[y]);
            par[y] = x;
            sum[x] += sum[y];
        }
    }
    ll get_sum(int x){
        x = find(x);
        return sum[x];
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};
