class UFtree {
    class UFnode {
    public:
        UFnode *p;
        int rank{0};
        ll max_edge;
        ll weight;
        explicit UFnode() : p{nullptr}, max_edge{0}, weight{0} {}
        explicit UFnode(UFnode *pa) : p{pa}, max_edge{0} {}
    };

    std::vector<UFnode> nodes;
    UFnode *parent(UFnode *x) {
        // xの親ノードの探索
        x->rank = 0;
        if (x->p == nullptr){ return x; }
        x->p = parent(x->p);
        x->p->max_edge = max(x->p->max_edge, x->max_edge);
        return x->p;
    }
public:
    explicit UFtree(std::vector<UFnode>::size_type n) : nodes{n} {};
    bool same(int a, int b) {
        // aとbが同じグループに属せばTRUE
        return this->parent(&nodes[a]) == this->parent(&nodes[b]);
    }
    void join(int a, int b, ll Y) {
        // aとbの属すグループを結合
        auto ap = this->parent(&nodes[a]);
        auto bp = this->parent(&nodes[b]);
        auto max_edge = max(ap->max_edge, bp->max_edge);
        max_edge = max(max_edge, Y);
        ap->max_edge = max_edge;
        bp->max_edge = max_edge;
        if (ap == bp) return;

        if (ap->rank < bp->rank) {
            ap->p = bp; return;
        }
        if (ap->rank == bp->rank)
            bp->rank += 1;
        bp->p = ap;
    }
    void set_empty(){
        for (int i = 0; i < nodes.size(); ++i) {
            nodes[i].p = nullptr;
            nodes[i].max_edge = 0;
        } // end i
    }
    void set_weight(int i, ll w){
        nodes[i].weight = w;
    }

    bool solve(const vector<ll> & X){
        map<UFnode*, ll> p_sum;
        for (int i = 0; i < nodes.size(); ++i) {
            p_sum[parent(&nodes[i])] += X[i];
        } // end i
        for (auto &&oo : p_sum) {
            if(oo.first->max_edge > oo.second){
                return false;
            }
        } // end oo
        return true;
    }
};


