        A.push_back(a); B.push_back(b); Y.push_back(y);
        pr.emplace_back(y, j);
    } // end j
    sort(pr.begin(), pr.end());
    /////////////////////////////////////
    auto can = [&](ll m){
        uft.set_empty();
        if(m < 0) return false;
        ll end = M - m;
        for (int i = 0; i < end; ++i) {
            ll t = pr[i].second;
            uft.join(A[t], B[t], Y[t]);
        } // end i
        return uft.solve(X);
    };

    ll ok = M;
    ll ng = -1;
    while(abs(ng - ok) > 1){
        ll mid = (ok + ng)/2;
        if(can(mid)){ ok = mid; }
        else { ng = mid; }
    }
    cout << ok << endl;
}

