struct PartiallyPersistentUnionFind {
  vector< int > data;
  vector< int > last;
  vector< ll> cost;
  vector< vector< pair< int, int > > > add;
  vector< vector< pair< int, int > > > add2;

  PartiallyPersistentUnionFind() {}

  PartiallyPersistentUnionFind(int sz, vector<ll> costs) : cost(sz, -1), data(sz, -1), last(sz, 1e9), add(sz), add2(sz) {
    for(auto &vs : add) vs.emplace_back(-1, -1);
    for(auto &vs : add2) vs.emplace_back(-1, -1);
    for(int i = 0; i < costs.size(); i++) {
        cost[i + 1] = -costs[i];
    }
  }

  bool merge(int t, int x, int y) {
    x = root(t, x);
    y = root(t, y);
    if(x == y) return false;
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    cost[x] += cost[y];
    add[x].emplace_back(t, data[x]);
    add2[x].emplace_back(t, cost[x]);
    data[y] = x;
    cost[y] = x;
    last[y] = t;
    return true;
  }

  int root(int t, int x) {
    if(t < last[x]) return x;
    return root(t, data[x]);
  }

  int size(int t, int x) {
    x = root(t, x);
    return -prev(lower_bound(begin(add[x]), end(add[x]), make_pair(t, 0)))->second;
  }
  int Cost(int t, int x) {
    x = root(t, x);
    return -prev(lower_bound(begin(add2[x]), end(add2[x]), make_pair(t, 0)))->second;
  }

    bool issame(int t, int x, int y){
        return root(t, x) == root(t, y);
    }
};

