class RollbackableUnionFind {
  struct Changes {
    bool is_changed;
    ll u, v, parv, wu, hu, hv;
  };
  stack<Changes> s;
  vector<ll> par, h, w;
public:
  RollbackableUnionFind(vector<ll> w) : par(w.size(), 0), h(w.size(), 0), w(w) {
    rep(i, w.size()) par[i] = i;
  }
  void unite(ll u, ll v) {
    u = root(u), v = root(v);
    if (u == v) {
      s.push({false});
      return;
    }
    if (h[u] < h[v]) {
      s.push({true, v, u, par[u], w[v], h[v], h[u]});
      par[u] = v;
      w[v] += w[u];
    }
    else {
      s.push({true, u, v, par[v], w[u], h[u], h[v]});
      par[v] = u;
      w[u] += w[v];
    }
    if (h[u] == h[v]) ++h[u];
  }
  ll sum(ll v) const {
    return w[root(v)];
  }
  bool isUnited(ll u, ll v) const {
    return root(u) == root(v);
  }
  ll root(ll v) const {
    if (par[v] == v) return v;
    return root(par[v]);
  }
  void rollback() {
    assert(s.size() > 0);
    Changes c = s.top();
    if (!c.is_changed) return;
    par[c.v] = c.parv;
    w[c.u] = c.wu;
    h[c.u] = c.hu;
    h[c.v] = c.hv;
    s.pop();
  }
};


