            visit[i] = false;
        }
        rep(i,n){
            if(!visit[i] && !ed[i]){
                set<int> es;
                vector<int> ver;
                ll val = 0;
                dfs(i, es, ver, val);
                int res = 0;
                each(p, es){
                    int u = (info[p].fi).fi, v = (info[p].fi).se;
                    if(val < info[p].se){
                        G[u].erase(p), G[v].erase(p);
                        res++;
                    }
                }
                if(res == 0){
                    each(v,ver){
                        ed[v] = true;
                    }
                }
                ans += res;
            }
        }
        bool br = true;
        rep(i,n){
            if(!ed[i]){
                br = false;
                break;
            }
        }
        if(br) break;
    }
    cout << ans << "\n";
    return 0;
}

