{
	while(1)
	{
		int ns = qmx(root, dfn[top[x]], dfn[x]);
		if(ns != -1) return tr[ns];
		x = pre[top[x]];
	}
}
void cut(int u, int v)
{
	if(pre[v] == u) swap(u, v);
	if(pre[u] != v) while(1);
	ll n1 = sum[u] - qsum(root, dfn[u]);
	int rf = gf(u);
	ins(root, u);
	u = pre[u];
	while(dep[u] >= dep[rf])
	{
		if(dep[top[u]] >= dep[rf])
			push(root, dfn[top[u]], dfn[u], n1), 
			u = pre[top[u]];
		else
		{
			if(top[rf] != top[u]) while(1);
			push(root, dfn[rf], dfn[u], n1), 
			u = pre[rf];
		}
	}
}
ll q(int pl)
{
	int rf = gf(pl);
	return sum[rf] - qsum(root, dfn[rf]);
}
int fa[maxn];
int gfa(int a)
{
	if(fa[a] == a) return a;
	return fa[a] = gfa(fa[a]);
}
struct eg
{
	int u, v, w, fl;
	bool operator < (const eg &x)const
	{
		return w < x.w;
	}
}p[maxn];
