    edges.emplace_back(a, b, c);
  }
  sort(edges.begin(), edges.end(), [](auto a, auto b) {
    return a.cost < b.cost;
  });

  // X[i]とY[i]の連結成分
  UnionFind uf(N);
  vector< int64 > hashed(M);
  for(int i = 0; i < M; i++) {
    auto e = edges[i];
    p[e.src].emplace(e.to, i);
