struct edge { ll from; ll to; ll v; ll i; };
vector<vector<edge>> adj;
vector<bool> used_v, used_e;

void dfs(int n, ll v) {
  used_v[n] = true;
  for (auto x: adj[n]) {
    if (x.v<=v) {
      if (used_v[x.to]) continue;
      used_e[x.i] = true;
      dfs(x.to,v);
    }
  }
}

int main() {
  int N, M; cin >> N >> M;
  UnionFind uf(N); rep(i,N) { ll X; cin >> X; uf.s[i] = X; }
  edge e[M]; adj.resize(N);
  rep(i,M) { 
    ll A, B, Y; cin >> A >> B >> Y; A--; B--; e[i] = {A,B,Y,i}; 
    adj[A].push_back({A,B,Y,i}); adj[B].push_back({B,A,Y,i});
  }

  sort(e,e+M,[](const edge &x, const edge &y){return x.v<y.v;});
  used_v.resize(N,false); used_e.resize(M,false); 
  rep(i,M) {
    uf.unite(e[i].from, e[i].to);
    if (uf.size(e[i].from)>=e[i].v) used_e[e[i].i] = true;
  }

  per(i,M) if (used_e[e[i].i]) dfs(e[i].from, e[i].v);
  // debug(all(used_e));

  ll result = 0; rep(i,M) result += !used_e[i];
  cout << result << endl;
  return 0;
}

