using namespace std;

int n, m;
class UF {
private:
  vector<ll> data; // parent or size
  vector<int> next;
  vector<int> last;
  void init(int n) {
    data.assign(n, -1);
    next.assign(n, -1);
    last.resize(n);
    for (int i = 0; i < n; ++i) {
      last[i] = i;
    }
  }

public:
  UF() {}
  UF(int n) {
    init(n);
  }
  bool apply_x(vll& x) {
    rep (i, n) {
      data[i] = -x[i];
    }
    return true;
  }
  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y); // data[x] and data[y] are negative.
    data[x] += data[y];
    data[y] = x;
    next[last[x]] = y;
    last[x] = last[y];
    return true;
  }
  ll size(int x) {
    return -data[root(x)];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int get_next(int x) {
    return next[x];
  }
};

vll x;
vvll g;
vvec<vll> adj;

int main() {
  scan(n, m);
  x.resize(n);
  scan(x);
  g.resize(m);
  adj.resize(n);
  auto uf = UF(n);
  uf.apply_x(x);
  rep (i, m) {
    ll a, b, y;
    scan(a, b, y);
    a -= 1; b -= 1;
    g[i] = {y, a, b};
    adj[a].push_back({b, y});
    adj[b].push_back({a, y});
  }
  sort(all(g));
  vvll remaining_edges;
  rep (i, m) {
    uf.unite(g[i][1], g[i][2]);
    if (uf.size(g[i][1]) >= g[i][0]) {
      remaining_edges.push_back(g[i]);
    }
  }
  reverse(all(remaining_edges));
  //debug(remaining_edges);

  vll vl_max_cost(n, 0);
  for (auto&& me : remaining_edges) {
    if (vl_max_cost[me[1]] > 0) { continue; }
    ll max_cost = me[0];
    vl_max_cost[me[1]] = max_cost;
    deque<ll> q = {me[1]};
    while (!q.empty()) {
      ll u = q.front();
      q.pop_front();
      for (auto&& e : adj[u]) {
        if (e[1] > max_cost) { continue; }
        ll v = e[0];
        if (vl_max_cost[v] > 0) { continue; }
        vl_max_cost[v] = max_cost;
        //debug3(u, v, vl_max_cost[v]);
        q.push_back(v);
      }
    }
  }
  //debug(vl_max_cost);
  int ans = 0;
  rep (i, m) {
    if (g[i][0] > vl_max_cost[g[i][1]] || g[i][0] > vl_max_cost[g[i][2]]) {
      ans += 1;
    }
  }

  print(ans);

  return 0;
}

#include <bits/stdc++.h>
typedef long long ll;
#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)

using namespace std;
const int MAX_N=1e5,MAX_M=1e5;
int N,M;
ll X[MAX_N];
struct edge{
	int s,t;
	ll cst;
	int inx;
	edge(int s=-1,int t=-1,ll c=0,int i=-1):s(s),t(t),cst(c),inx(i){}
	bool operator < (const edge &e)const{
		return cst<e.cst;
	}
};
struct edge2{
	int to;
	ll cst;
	int inx;
	edge2(int t=-1,ll c=0,int i=-1):to(t),cst(c),inx(i){}
};
edge E[MAX_M];
vector<edge2> G[MAX_N];
bool used[MAX_M];
bool koho[MAX_M];
bool visit[MAX_N];
int par[MAX_N];
ll sm[MAX_N];
int fndpar(int v){
	if(par[v]==v){
		return v;
	}
	return par[v]=fndpar(par[v]);
}
void unite(int s,int t){
	s=fndpar(s);
	t=fndpar(t);
	par[t]=s;
	sm[s]+=sm[t];
}
void dfs(int v,ll c){
	visit[v]=true;
	for(auto e:G[v]){
		if(e.cst<=c && !visit[e.to] && !used[e.inx]){
			used[e.inx]=true;
			dfs(e.to,c);
		}
	}
}
int main(){
	cin>>N>>M;
	REP(i,N)cin>>X[i];
	REP(i,M){
		int a,b;
		ll y;
		cin>>a>>b>>y;
		a--;
		b--;
		E[i]=edge(a,b,y,i);
		G[a].push_back(edge2(b,y,i));
		G[b].push_back(edge2(a,y,i));
	}
	sort(E,E+M);
	REP(i,N){
		par[i]=i;
		sm[i]=X[i];
	}
	for(auto e:E){
		if(fndpar(e.s)!=fndpar(e.t)){
			unite(e.s,e.t);
		}
		if(sm[fndpar(e.s)]>=e.cst){
			koho[e.inx]=true;
		}
	}
	reverse(E,E+M);
	int ans=0;
	for(auto e:E){
		if(used[e.inx])continue;
		if(koho[e.inx]){
			dfs(e.s,e.cst);
		}else{
			ans++;
		}
	}
	cout<<ans<<endl;
}

