ll X[100010];

class persistentUF {
public:
    explicit persistentUF(int N) : V_NUM(N), now(0) {
        par.resize(V_NUM);
        rank.resize(V_NUM);
        num.resize(V_NUM);
        tim.resize(V_NUM);
        c.resize(V_NUM);
        g.resize(V_NUM);

        for (int i = 0; i < V_NUM; ++i) {
            par[i] = i;
        }
        fill(rank.begin(), rank.end(), 0);
        fill(tim.begin(), tim.end(), INF);
        for (int i = 0; i < V_NUM; ++i) {
            num[i].push_back(make_pair(0, 1));
            c[i].push_back(make_pair(0, X[i]));
            g[i].push_back(make_pair(0, vector<int>({i})));
        }
    }

    // 時刻tにおけるxの親を返す
    int find(int x, int t) {
        if (tim[x] > t) return x;
        return find(par[x], t);
    }

    // xとyを含む集合を統合する
    void unite(int x, int y) {
        ++now;
        x = find(x, now);
        y = find(y, now);

        if (x == y) return;

        if (rank[x] < rank[y]) swap(x, y);

        num[x].push_back(make_pair(now, size(x, now) + size(y, now)));
        c[x].push_back(make_pair(now, cost(x, now) + cost(y, now)));

        auto gx = group(x, now), gy = group(y, now);
        gx.insert(gx.begin(), gy.begin(), gy.end());
        g[x].push_back(make_pair(now, gx));

        par[y] = x;
        tim[y] = now;
        if (rank[x] == rank[y]) ++rank[x];
    }

    // xとyが時刻tにて同じ集合に属するか判定
    bool same(int x, int y, int t) {
        return find(x, t) == find(y, t);
    }

    // 時刻tにてxが集合の親か判定
    bool ispar(int x, int t) {
        return x == find(x, t);
    }

    // 時刻tにおけるxを含む集合の要素数を返す
    int size(int x, int t) {
        x = find(x, t);
        int ok = 0, ng = num[x].size();

        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
            if (num[x][mid].first <= t) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return num[x][ok].second;
    }

    ll cost(int x, int t) {
        x = find(x, t);
        int ok = 0, ng = c[x].size();

        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
            if (c[x][mid].first <= t) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return c[x][ok].second;
    }

    vector<int> group(int x, int t) {
        x = find(x, t);
        int ok = 0, ng = g[x].size();

        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
            if (g[x][mid].first <= t) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return g[x][ok].second;
    }

    const int INF = 1 << 25;
    int V_NUM, now;
    vector<int> par, rank, tim;
    vector<vector<pair<int, int>>> num;
    vector<vector<pair<ll, ll>>> c;
    vector<vector<pair<int, vector<int>>>> g;
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;
    for (int i = 0; i < N; ++i) cin >> X[i];

    pair<ll, pair<int, int>> edges[M + 1];
    for (int i = 1; i <= M; ++i) {
        cin >> edges[i].second.first >> edges[i].second.second >> edges[i].first;
        --edges[i].second.first, --edges[i].second.second;
    }

    sort(edges + 1, edges + M + 1);
    persistentUF uf(N);
    for (int t = 1; t <= M; ++t) {
        uf.unite(edges[t].second.first, edges[t].second.second);
    }

    int ans = 0;
    bool ok[N];
    fill(ok, ok + N, false);
    for (int t = M; t > 0; --t) {
        if (ok[edges[t].second.first]) continue;

        if (edges[t].first > uf.cost(edges[t].second.first, t)) {
            ++ans;
        } else {
            for (int i : uf.group(edges[t].second.first, t)) {
                ok[i] = true;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

