  }
  lint query(int a,int b,int i,int l,int r){
    if(a<=l && r<=b) return val[i];
    if(b<=l || r<=a) return 0;
    int md=(l+r)>>1;
    return query(a,b,i*2+1,l,md)+query(a,b,i*2+2,md,r);
  }
  lint query(int a,int b){
    return query(a,b,0,0,n);
