        sx[i] = x[i];
    }
    rep(i, m) {
        li a, b, y;
        cin >> a >> b >> y;
        a--;
        b--;
        links[i] = {y, {a, b}};
    }
    sort(links, links + m);
    rep(i, m) {
        edges[links[i].S.F].pb({links[i].S.S, {links[i].F, i}});
        edges[links[i].S.S].pb({links[i].S.F, {links[i].F, i}});
    }
    init_uf();
    rep(i, m) {
        if (find(links[i].S.F) != find(links[i].S.S)) {
            li sum = sx[find(links[i].S.F)] + sx[find(links[i].S.S)];
            union_(find(links[i].S.F), find(links[i].S.S));
            sx[find(links[i].S.F)] = sum;
        }
        if (sx[find(links[i].S.F)] >= links[i].F) {
            cand[i] = true;
        }
    }

    li res = 0;
    for (li i = m - 1; i >= 0; --i) {
        if (use[i]) continue;
        if (!cand[i]) {
            ++res;
            continue;
        }

        // dfs
        stack<li> stk;
        li w_lim = links[i].F;
        stk.push(links[i].S.F);
        stk.push(links[i].S.S);
        use[i] = true;
        while (!stk.empty()) {
            li now = stk.top();
            stk.pop();
            if (visited[now])continue;
            visited[now] = true;
            for (auto && link : edges[now]) {
                li next = link.F;
                li w = link.S.F;
                li idx = link.S.S;
                if (w > w_lim || use[idx]) {
                    continue;
                }
                use[idx] = true;
                stk.push(next);
            }
        }
    }

    cout << res << endl;

    return 0;
}

