            ll ans_total = ans_sum[uf.find(e.from)] + ans_sum[uf.find(e.to)];
            ll weight_total = weight_sum[uf.find(e.from)] + weight_sum[uf.find(e.to)];
            uf.unite(e.from, e.to);
            weight_sum[uf.find(e.from)] = weight_total;
            ans_sum[uf.find(e.from)] = ans_total;
        }
        if(e.cost <= weight_sum[uf.find(e.from)]){
