struct UF{
    vector<int> par;
    vector<int> sz;
    vector<int> sum;
    UF(){}
    UF(int n){
        par.resize(n);
        sz.resize(n, 1);
        sum.resize(n);
        rep(i, 0, n) par[i] = i;
    }
    int find(int x){
        if(x == par[x]) return x;
        // return par[x] = find(par[x]);
        return find(par[x]);
    }
    void unite(int x, int y){
        // x = find(x); y = find(y);
        // if(x == y) return;
        if(sz[x] < sz[y]) swap(x, y);
        sz[x] += sz[y];
        sum[x] += sum[y];
        par[y] = x;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
    int dec(int x, int s){
        if(x == par[x]){
            return x;
        }else{
            sum[par[x]] -= s;
            return dec(par[x], s);
        }
    }
};

