    vector<ll> par,sizes;
    UnionFind(int nn):par(nn+1),sizes(nn+1,1){
        rep2(i,1,nn)par[i]=i;
    }
    int find(int x){
        return (x==par[x]?x:par[x]=find(par[x]));
    }
    void unite(int x,int y){
        x=find(x);y=find(y);
        if(x==y)return ;
        if(sizes[x]<sizes[y]){
            swap(x,y);
        }
        par[y]=x;
        sizes[x]+=sizes[y];
    }
    bool same(int x,int y) {return (find(x)==find(y));}
    ll size(int x) {return sizes[find(x)];}
};
