void cut(int n,int a,int b){
	if(tree[a].count(b) == 0) return;
	tree[a].erase(b);
	tree[b].erase(a);

	const int basis = idx[a];
	rep(i,2) vs[i].clear();

	queue<int> q[2];
	q[0].push(a);
	q[1].push(b);

	while(!q[0].empty() and !q[1].empty()){
		rep(i,2){
			if(!q[i].empty()){
				int v = q[i].front(); q[i].pop();
				visited[v] = true;
				vs[i].push_back(v);
				for(auto &v2:tree[v]){
					if(visited[v2]) continue;
					q[i].push(v2);
				}
			}
		}
	}

	const int pos = (vs[0].size() + q[0].size()) > (vs[1].size() + q[1].size());

	for(auto &v: vs[pos]){
		idx[v] = sz;
		total[basis] -= X[v];
		total[sz] += X[v];
	}

	rep(i,2){
		for(auto &v:vs[i]){
			visited[v] = false;
		}
	}

	sz++;
}

