const int MAX = 1e5;
lct_node lct[MAX];

int main()
{
	int N, M;
	cin >> N >> M;
	vector<ll> X(N);
	for (int i = 0; i < N; i++) {
		cin >> X[i];
	}
	vector<tuple<int, int, int>> tps;
	for (int i = 0; i < M; i++) {
		int A, B, Y;
		cin >> A >> B >> Y; --A, --B;
		tps.emplace_back(Y, A, B);
	}
	sort(tps.begin(), tps.end());
	ll all = accumulate(X.begin(), X.end(), 0LL);
	int res = 0;
	vector<tuple<int, int, int>> tes, oth;
	union_find uf(N);
	graph G(N);
	for (auto tp : tps) {
		int A, B, Y;
		tie(Y, A, B) = tp;
		if (!uf.same(A, B)) {
			uf.unite(A, B);
			if (Y > all) {
				++res;
				continue;
			}
			tes.emplace_back(Y, A, B);
			lct[A].link(lct + B);
			G[A].insert(B);
			G[B].insert(A);
		}
		else {
			oth.emplace_back(Y, A, B);
		}
	}
	function<ll(int, int)> calc = [&](int v, int prev) {
		ll sum = X[v];
		for (auto to : G[v]) if (to != prev) {
			sum += calc(to, v);
		}
		return sum;
	};
	vector<ll> sum(N);
	function<void(int, int, ll)> paste = [&](int v, int prev, ll val) {
		sum[v] = val;
		for (auto to : G[v]) if (to != prev) {
			paste(to, v, val);
		}
	};
	for (int i = 0; i < N; i++) if (!sum[i]) {
		paste(i, -1, calc(i, -1));
	}
	reverse(tes.begin(), tes.end());
	for (auto tp : tes) {
		int Y, A, B;
		tie(Y, A, B) = tp;
		int v = lct[A].root() - lct;
		if (sum[v] < Y) {
			++res;
			sum[A] = sum[v];
			lct[A].evert();
			lct[B].cut();
			G[A].erase(B);
			G[B].erase(A);
			ll aa = sum[v], bb = aa - calc(A, -1);
			sum[A] = aa - bb;
			sum[lct[B].root() - lct] = bb;
		}
	}
	for (auto tp : oth) {
		int Y, A, B;
		tie(Y, A, B) = tp;
		int a = lct[A].root() - lct;
		int b = lct[B].root() - lct;
		if (a != b || sum[a] < Y) {
			++res;
		}
	}
	cout << res << endl;
	return 0;
}

