			sum[uf.root(a)] = sa + sb;
			used[i] = true;
		}
	}

	for(int i=0; i<m; i++){
		ll y = get<0>(yab[i]);
		int a = get<1>(yab[i]);
		int b = get<2>(yab[i]);
		if(!uf.same(a, b)) continue;
		if(sum[uf.root(a)]>=y){
			used[i] = true;
		}
	}


	int ans = 0;
	for(int i=0; i<m; i++){
		if(!used[i]) ans++;
	}
	cout << ans << endl;

	return 0;
}

