class UnionFind
{
  public:
	explicit UnionFind(ll size)
		: mParent(size, -1)
		, mRank(size, 0)
        , mData(size, 0)
		{}
	bool unionSet(ll x, ll y)
	{
		if ((x = root(x)) == (y = root(y)))
			return false;
		if( mRank[x] < mRank[y] )
		{
			mParent[y] += mParent[x];
			mParent[x] = y;
            unionData( mData[y], mData[x] );
		}
		else
		{
			mParent[x] += mParent[y];
			mParent[y] = x;
			if( mRank[x] = mRank[y] ) ++mRank[x];
            unionData( mData[x], mData[y] );
		}
		return true;
	}
	bool isEqualSet(ll x, ll y)
	{
		return root(x) == root(y);
	}
	ll root(ll x)
	{
		return mParent[x] < 0 ? x : mParent[x] = root(mParent[x]);
	}
	ll size(ll x)
	{
		return -mParent[root(x)];
	}

    void unionData( ll& parent, ll& child )
    {
        parent += child;
    }
    void setData( ll x, ll data )
    {
        mData[root(x)] = data;
    }
    ll getData( ll x )
    {
        return mData[root(x)];
    }

  public:
	vector<ll> mParent; // = mSize
	vector<ll> mRank;
	vector<ll> mData;
};

struct St{
    ll a = 0;
    ll b = 0;
    ll y = 0;
    bool is = false;
    bool iss = false;
};
bool operator<(const St& l, const St& r)
{ return l.y < r.y; }
bool operator>(const St& l, const St& r)
{ return l.y > r.y; }

int main()
{
    ll n, m;
    cin >> n >> m;
    VEC(ll, n, x, 0);
    REP(i,n) cin >> x[i];

    vector<St> edgeSt(m);
    REP( i, m )
    {
        cin >> edgeSt[i].a >> edgeSt[i].b >> edgeSt[i].y;
        edgeSt[i].a--;
        edgeSt[i].b--;
    }

    sort( edgeSt.begin(), edgeSt.end() );

    UnionFind uf( n );
    REP( i, n ) uf.setData( i, x[i] );
    REP( i, m )
    {
        uf.unionSet( edgeSt[i].a, edgeSt[i].b );
        auto d = uf.getData( edgeSt[i].a );
        if( d >= edgeSt[i].y ) edgeSt[i].is = true;
    }

    sort( edgeSt.begin(), edgeSt.end(), greater<St>() );

    vector< vector<St*> > edge(n);
    REP( i, m )
    {
        edge[edgeSt[i].a].push_back( &edgeSt[i] );
        edge[edgeSt[i].b].push_back( &edgeSt[i] );
    }

    ll ans = 0;
    REP( i,m )
    {
        if( edgeSt[i].iss ) { continue; }
        if( !edgeSt[i].is ) { ++ans; continue; }

        stack<ll> st;
        VEC( bool, n, used, false );
        st.push( edgeSt[i].a ); used[edgeSt[i].a] = true;
        st.push( edgeSt[i].b ); used[edgeSt[i].b] = true;

        while( st.size() )
        {
            ll t = st.top(); st.pop();
            for( auto pst : edge[t] )
            {
                if( !used[pst->b] && pst->y <= edgeSt[i].y )
                {
                    used[pst->b] = true;
                    pst->iss = true;
                    st.push( pst->b );
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

