bool unite(int x, int y) {
    x = root(x), y = root(y);
    if (x != y) {
        if (F[y] < F[x]) swap(x, y);
        F[x] += F[y], F[y] = x, X[x] += X[y], C[x] += C[y];
    }
    return x != y;
}

