	edge(int s=-1,int t=-1,ll c=0,int i=-1):s(s),t(t),cst(c),inx(i){}
	bool operator < (const edge &e)const{
		return cst<e.cst;
	}
};
struct edge2{
	int to;
	ll cst;
	int inx;
	edge2(int t=-1,ll c=0,int i=-1):to(t),cst(c),inx(i){}
};
edge E[MAX_M];
vector<edge2> G[MAX_N];
bool used[MAX_M];
bool koho[MAX_M];
bool visit[MAX_N];
int par[MAX_N];
ll sm[MAX_N];
int fndpar(int v){
	if(par[v]==v){
		return v;
	}
	return par[v]=fndpar(par[v]);
}
void unite(int s,int t){
	s=fndpar(s);
	t=fndpar(t);
	par[t]=s;
	sm[s]+=sm[t];
}
void dfs(int v,ll c){
	visit[v]=true;
	for(auto e:G[v]){
		if(e.cst<=c && !visit[e.to] && !used[e.inx]){
			used[e.inx]=true;
			dfs(e.to,c);
		}
	}
}
