	REP(i,M){
		auto e=E[i];
		if(fndpar(e.s)!=fndpar(e.t)){
			unite(e.s,e.t);
		}
		if(sm[fndpar(e.s)]>=e.cst){
			koho[e.inx]=true;
		}
	}
	reverse(E,E+M);
	int ans=0;
	REP(i,M){
		auto e=E[i];
		if(used[e.inx])continue;
		if(koho[e.inx]){
			dfs(e.s,e.cst);
		}else{
			ans++;
		}
	}
	cout<<ans<<endl;
}

