struct UnionFind {
  vector<int> par, s;
  vector<ll> cost;
  UnionFind(int n=2e5) { init(n); }
  void init(int n) { 
    s.assign(n, 1); par.resize(n); 
    iota(par.begin(), par.end(), 0);
    cost.resize(n);
  }
  int find(int x) {
    if(par[x] == x) return x;
    return par[x] = find(par[x]);
  }
  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if(x == y) return;
    if(s[x] < s[y]) par[x] = y, s[y] = s[x] + s[y], cost[y] = cost[x] + cost[y];
    else par[y] = x, s[x] = s[x] + s[y], cost[x] = cost[x] + cost[y];
  }
  bool same(int x, int y) { return find(x) == find(y); }
  int size(int x) { return s[find(x)]; }
};

int main(void) {
    ll n, m;
