        a[i]--, b[i]--;
        g[a[i]].push_back({b[i], i});
        g[b[i]].push_back({a[i], i});
    }

    vector<ll> ord(m);
    iota(ALL(ord), 0LL);
    sort(ALL(ord), [&](ll l, ll r){ return y[l] < y[r]; });

    // 重みがy[i]以下の辺が全て追加された状態 
    // 辺iが属する連結成分の頂点重みがy[i]以上 → iから重みy[i]以下の辺をたどって到達できる辺は残せる 
    vector<ll> ok;
    UnionFind uf(n);
    REP(i, n) uf.cost[i] = x[i];
    for(auto i: ord) {
        uf.unite(a[i], b[i]);
        if(uf.cost[uf.find(a[i])] >= y[i]) ok.push_back(i);
    }
