  int *PRIMELIST(const int til, int *length=NULL){
    int *foo=(int*)malloc(sizeof(int)*(til+1));
    int len=0;
    memset(foo, 0, sizeof(int)*(til+1));
    for(int i=2; i<=til; i++){
      if(!foo[i])foo[len++]=i;
      for(int j=0; j<len && foo[j]<=til/i; j++){
        foo[foo[j]*i]=1;
        if(i%foo[j]==0)break;
      }
    }
    if(length!=NULL){
      *length=len;
    }
    foo[len++]=0;
    foo=(int*)realloc(foo, sizeof(int)*len);
