  inline lld MODL_MUL(lld x, lld y, const lld m=MOD){
    MOD_STD(&x, m);
    MOD_STD(&y, m);
    if(x<y)swap(x, y);
    lld z=0LL;
    while(y>0){
      if(y&1){
        MOD_ADD(&z, x, m);
      }
      MOD_ADD(&x, x, m);
      y>>=1;
    }
    return z;
  }
