      scanf("%lld", &prf[i]);
    }
    for (int i = 0; i < m; ++i) {
      scanf("%d%d%lld", &pool[i].src, &pool[i].dst, &pool[i].wht);
      pool[i].src--;
      pool[i].dst--;
      pool[i].key = 0;
    }
    sort(pool, pool + m);
    for (int i = 0; i < n; ++i) {
      f[i] = i;
      sum[i] = prf[i];
      top[i] = -1;
    }
    for (int i = 0; i < m; ++i) {
      int lhs = find(pool[i].src);
      int rhs = find(pool[i].dst);
      if (lhs != rhs) {
        //set key
        pool[i].key = 1;
        //record
        lhk[i] = top[lhs]; 
        rhk[i] = top[rhs];
        lhp[i] = sum[lhs];
        rhp[i] = sum[rhs];
        //union
        f[lhs] = rhs;
        sum[rhs] += sum[lhs];
        sum[lhs] = 0LL;
        top[rhs] = i;
      }
    }
    foo = 0;
    process(top[find(0)]);
    for (int i = 0; i < n; ++i) {
      f[i] = i;
      sum[i] = 0LL;
    }
    for (int i = 0; i < m; ++i) {
      if (pool[i].key == 1) {
        const int lhs = find(pool[i].src);
        const int rhs = find(pool[i].dst);
        f[lhs] = rhs;
      }
    }
    for (int i = 0; i < n; ++i) {
      sum[find(i)] += prf[i];
    }
    for (int i = 0; i < m; ++i) {
      if (pool[i].key == 0) {
        const int lhs = find(pool[i].src);
        const int rhs = find(pool[i].dst);
        if (lhs != rhs || pool[i].wht > sum[lhs]) {
          foo++;
        }
      }
    }
    printf("%d\n", foo);
  }
  return 0;
}

