typedef struct UnionFindTree{
    vector<int> par;
    vector<lint> sum;

    UnionFindTree(int n){
        par.resize(n, -1);
        sum.resize(n, 0);
    }

    bool is_root(int x){
        return par[x]<0;
    }

    int find(int x){
        if(is_root(x)) return x;
        return par[x] = find(par[x]);
    }

    int size(int x){
        return -par[find(x)];
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(size(x) < size(y)) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        sum[x] += sum[y];
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
}UF;

