	cin >> n >> m;
	FOR(i, 0, n)
		cin >> x[i];
	FOR(i, 0, m)
	{
		cin >> E[i].u >> E[i].v >> E[i].y;
		E[i].u--;
		E[i].v--;
		g[E[i].u].PB(MP(MP(E[i].v, E[i].y), i));
		g[E[i].v].PB(MP(MP(E[i].u, E[i].y), i));
	}
	sort(E, E + m);
	FOR(i, 0, n)
	{
		par[i] = i;
		sz[i] = 1;
		s[i] = x[i];
	}
	FOR(i, 0, m)
	{
		unite(E[i].u, E[i].v, E[i].y);
	}
	FOR(i, 0, n)
		order[i] = MP(W[i], i);
	sort(order, order + n);
	RFOR(i, n, 0)
	{
		int v = order[i].second;
		if(!used[v])
			dfs(v, -1, W[v]);
	}
	cout << m - SZ(good);
	return 0;
}

