std::vector<int> par,num,var,sum,rem;
//num -> rank sum->tot joined vertices
std::vector<tuple<int,int,int>> edg;
bool cmp(tuple<int,int,int> q,tuple<int,int,int> w)
{
	return ((get<2>(q))<(get<2>(w)));
}
int findpar(int a)
{
	if(a==par[a]){return a;}
	return findpar(par[par[a]]);
}
int unite(int a, int b)
{
	int p1=findpar(a),p2=findpar(b);
	if(num[p1]<num[p2]){SWAP(p1,p2);}
	num[p1]+=num[p2];
	sum[p1]+=sum[p2];
	rem[p1]+=rem[p2];
	par[p2]=p1;
	return 0;
}
int solve()
{
	int n,m;cin>>n>>m;
	par.resize(n+1);num.resize(n+1,1);sum.resize(n+1,0);
	rem.resize(n+1,0);
	iota(par.begin(),par.end(),0);
	var.resize(n+1);
	REP(i,1,n)
	{
		cin>>var[i];sum[i]=var[i];
	}
	REP(i,1,m)
	{
		int a,b,c;cin>>a>>b>>c;
		edg.pb(make_tuple(a,b,c));
	}
	sort(edg.begin(),edg.end(),cmp);
	int ans=0;
	for(auto it:edg)
	{
		int a=get<0>(it),b=get<1>(it),c=get<2>(it);
		if(findpar(a)!=findpar(b))
		{
			unite(a,b);
		}
		++rem[findpar(a)];
		if(sum[findpar(a)]>=c)
		{
			ans+=rem[findpar(a)];
			rem[findpar(a)]=0;
		}
	}
	cout<<(m-ans)<<"\n";
}
signed main(){
	speed
	int tt=1;
	//cin>>tt;
	while(tt--)
	{
		solve();
	}
	return 0;
}

