const int limit = 100010;
int A[limit],B[limit],X[limit],Y[limit];


int sz = 1;
set<int> tree[limit];
int idx[limit];
ll total[limit];


vector<int> vs[2];
bool visited[limit];

void dfs(int i,int v){
	if(visited[v]) return;
	visited[v] = true;
	vs[i].push_back(v);

	for(auto &v2:tree[v]){
		if(visited[v2]) continue;
		dfs(i,v2);
	}
}	

void cut(int n,int a,int b){
	if(tree[a].count(b) == 0) return;
	tree[a].erase(b);
	tree[b].erase(a);

	const int basis = idx[a];
	vs[0].clear();
	dfs(0,a);
	vs[1].clear();
	dfs(1,b);

	const int pos = (vs[0].size() > vs[1].size());
	for(auto &v: vs[pos]){
		idx[v] = sz;
		total[basis] -= X[v];
		total[sz] += X[v];
	}

	rep(i,2){
		for(auto &v:vs[i]){
			visited[v] = false;
		}
	}

	sz++;
}

// Description: 素集合を管理するデータ構造
// TimeComplexity: 初期化$\mathcal{O}(n)$ 更新$\mathcal{O}(\log n)$
// Verifyed: AOJ DSL_1_A

struct Union_find {
	Union_find(int n) {data.assign(n, -1);}
	int find(int x) {return (data[x] < 0) ? x : data[x] = find(data[x]);}
	void unite(int a, int b) {
		a = find(a), b = find(b);
		if (a != b) {
			if (data[a] < data[b]) swap(a, b);
			data[a] += data[b], data[b] = a;
		}
	}
	bool same(int a, int b) {return find(a) == find(b);}
	int size(int x) {return -data[x];}
	vector<int> data;
};

int main(void){
	int n,m;
	cin >> n >> m;
	rep(i,n) cin >> X[i];

	using edge = tuple<ll,int,int>;
	vector<edge> graph;

	rep(i,m){
		cin >> A[i] >> B[i] >> Y[i];
		A[i]--,B[i]--;
		graph.push_back(edge(Y[i],A[i],B[i]));
	}

	Union_find uf(n);
	sort(begin(graph),end(graph));

	for(auto &e:graph){
		int y,a,b;
		tie(y,a,b) = e;
		if(uf.same(a,b)) continue;
		tree[a].insert(b);
		tree[b].insert(a);
		uf.unite(a,b);
	}

	reverse(begin(graph),end(graph));

	rep(i,n) total[0] += X[i];

	int ans = 0;
	for(auto &e:graph){
		int y,a,b;
		tie(y,a,b) = e;
		const ll cur = total[idx[a]];
		if(cur >= y) continue;
		ans++;
		cut(n,a,b);
	}

	cout << ans << endl;

	return 0;
}

