vector<ll> listen[MAXN];
ii edge[MAXN];

ll find(ll x) {
	return par[x] == x? x: par[x] = find(par[x]);
}

void merge(ll x, ll y) {
	x = find(x), y = find(y);
	if (x == y) return;
	par[x] = y;
	sum[y] += sum[x];
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	cin >> N >> M;
	for (ll i = 1; i <= N; i++) cin >> poin[i];
