	int num;
	int from, to;
	ll w;
};
typedef vector<vector<Edge>> Graph;

struct UnionFind_P {
private:
	vector<int> data, sz;
	int root(int x) {
		return data[x] < 0 ? x : root(data[x]);
	}

public:
	vector<vector<pii>> tb;
	vector < vector <pair<int, ll> >> tsz;
	int s_cou = 0;
	UnionFind_P(int size) : tb(size, vector<pii>(1)), data(size, -1), sz(size, 0), tsz(size, vector<pair<int,ll>>(1)) {
		REP(i, size) {
			tb[i][0] = { 0, i };
		}
	}

	void Initsz(vector<ll> szarr) {
		REP(i, data.size()) {
			sz[i] = szarr[i];
			tsz[i][0] = { 0,szarr[i] };
		}
	}

	//tを小さい順にやるならおｋだよ お祭りで使った
	//bool unionSet(int x, int y, int t) { //ｘの入ってる集合と yの入ってる集合を併合
	//	x = root(x); y = root(y);
	//	s_cou++;
	//	if (x != y) {
	//		if (data[y] < data[x]) swap(x, y);
	//		data[x] += data[y]; data[y] = x;
	//		if (tb[y][tb[y].size() - 1].first != t)
	//			tb[y].push_back({ t,x });
	//		else
	//			tb[y][tb[y].size() - 1].second = x;
	//	}
	//	return x != y;
	//}
	bool unionSet(int x, int y) { //ｘの入ってる集合と yの入ってる集合を併合
		x = root(x); y = root(y);
		s_cou++;
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
			tb[y].push_back({ s_cou,x });

			sz[x] += sz[y];
			sz[y] = 0;
			tsz[x].push_back({s_cou, sz[x]});

		}
		return x != y;
	}
	int findroot(int u, int t) {
		auto itr = --upper_bound(ALL(tb[u]), MP(t, INT_MAX));
		return itr->second == u ? u : findroot(itr->second, t);
	}

	int getsz(int u, int t) {
		int rt = findroot(u, t);
		auto itr = --upper_bound(ALL(tsz[rt]), MP(t, LLONG_MAX));
		return itr->second;
	}

};

signed main(void) {
	int n,m;
	cin >> n >> m;
	Graph g(n);
	vector<pair<ll ,pii>> edges(m);
	vector<ll> X(n);
	UnionFind_P ufp(n);

	REP(i, n) {
		scanf("%d", &X[i]);
	}

	ufp.Initsz(X);

	REP(i, m) {
		int a, b;
		ll c;
		scanf("%d %d %lld", &a, &b, &c);
		a--, b--;
		g[a].push_back({ i,a,b,c });
		g[b].push_back({ i,b,a,c });
		edges[i] = { c,{a,b} };
	}

	sort(ALL(edges));

	REP(i, m) {
		ufp.unionSet(edges[i].second.first, edges[i].second.second);
	}

	int ans = 0;

	vector<int> used(n),useded(m);

	function<void(int,int)> dfs = [&](int cur, int kyoyou) {
		used[cur] = 1;
		for (auto itr : g[cur]) {


			if (itr.w <= kyoyou) {

				if (useded[itr.num] == 0) {
					ans++;
					useded[itr.num] = 1;
				}

				int nex = itr.to;

				if (used[nex] == 0) {
					dfs(nex, kyoyou);
					used[nex] = 1;
				}

			}
		}
	};

	REP(v, n) {

		ll l = 0, r = m; //!!!!honsuu!!!!!

		while (r - l > 1) {

			ll mid = (l + r) / 2;


			ll sz = edges[mid - 1].first;

			ll realsz = ufp.getsz(v, mid);

			if (sz <= realsz) {
				l = mid;
			}
			else {
				r = mid;
			}
		}
		if(l == 0)
			dfs(v, 0);
		else
			dfs(v, edges[l - 1].first);

	}

	cout << m-ans << endl;

	return 0;
}

