bool operator < (const pp &a, const pp &b) {
	return a.cost < b.cost;
}

vector<set<pair<int, int> > > rem_e;
vector<set<int> > comps;
int comp_id[MAX_N];
long long comp_sum[MAX_N];

int nnew[MAX_N];
int DFS_FLAG = 0;

void dfs(int v, set<int> & cmp, long long & sum_V) {
	sum_V += cost[v];
	cmp.insert(v);
	nnew[v] = DFS_FLAG;
	for (set<pair<int, pair<int, int> > >::iterator iter = e[v].begin(); iter != e[v].end(); ++iter) {
		int new_v = iter->second.first;
		if (nnew[new_v] != DFS_FLAG)
			dfs(new_v, cmp, sum_V);
	}
}

void delete_back_edge(int c_index) {
	set<pair<int, int> >::iterator iter = rem_e[c_index].end();
	iter--;
	int edge_cost = iter->first;
	int edge_index = iter->second;
	rem_e[c_index].erase(iter);
	int a = e_list[edge_index].a;
	int b = e_list[edge_index].b;
	e[a].erase(make_pair(edge_index, make_pair(b, e_list[edge_index].cost)));
	e[b].erase(make_pair(edge_index, make_pair(a, e_list[edge_index].cost)));

	DFS_FLAG++;
	set<int> cmp;
	long long sum_V = 0;
	dfs(a, cmp, sum_V);

	if (cmp.size() != comps[c_index].size()) {
		set<pair<int, int> > e1, e2;
		for (set<pair<int, int> >::iterator iter = rem_e[c_index].begin(); iter != rem_e[c_index].end(); ++iter) {
			int edge_cost = iter->first;
			int edge_index = iter->second;
			int a = e_list[edge_index].a;
			int b = e_list[edge_index].b;
			if (cmp.find(a) != cmp.end()) {
				e2.insert(*iter);
			}
			else
				e1.insert(*iter);
		}
		set<int> v1;
		for (set<int>::iterator iter = comps[c_index].begin(); iter != comps[c_index].end(); ++iter)
			if (cmp.find(*iter) == cmp.end())
				v1.insert(*iter);
		comps.push_back(cmp);
		rem_e.push_back(e2);
		comps[c_index] = v1;
		rem_e[c_index] = e1;
		comp_sum[comps.size() - 1] = sum_V;
		comp_sum[c_index] -= sum_V;
	}
}

