	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	int n, m;
	scanf("%d%d", &n, &m);
	for (int i = 0; i < n; i++) scanf("%d", &cost[i]);
	for (int i = 0; i < m; i++) {
		int a, b, c;
		scanf("%d%d%d", &a, &b, &c);
		a--; b--;
		e_list[i].a = a; e_list[i].b = b; e_list[i].cost = c;
		e[a].insert(make_pair(i, make_pair(b, c)));
		e[b].insert(make_pair(i, make_pair(a, c)));
	}

	int ans = 0;

	for (int i = 0; i < n; i++) comp_sum[0] += cost[i];
	for (int i = 0; i < m; i++) comp_id[i] = 0;
	comps.clear();
	set<int> cur;
	for (int i = 0; i < n; i++) cur.insert(i);
	comps.push_back(cur);
	rem_e.resize(1);
	for (int i = 0; i < m; i++) rem_e[0].insert(make_pair(e_list[i].cost, i));

	while (!rem_e.empty()) {
		int fnd = 0;
		int old_size = (int)comps.size();
		for (int j=0; j<old_size; j++)
			if (rem_e[j].size() > 0) {
				set<pair<int, int> >::iterator iter = rem_e[j].end();
				iter--;
				if (iter->first > comp_sum[j]) {
					fnd = 1;
					delete_back_edge(j);
					ans++;
				}
			}
		if (!fnd)
			break;
	}
	cout << ans;
	return 0;
}

