void build(int v, int tl, int tr){
    a[v] = 1;
    if (tl == tr){
        a[v] = 1;
        c[v] = b[tl];
        return;
    }
    int mid = (tl + tr) / 2;;
    build(v + v, tl, mid);
    build(v + v + 1, mid + 1, tr);
    c[v] = c[v + v] + c[v + v + 1];
    if (a[v + v] == a[v + v + 1] && a[v + v] != 0) a[v] = a[v + v];
}
void push(int v){
    if (a[v] != 0)
        a[v + v] = a[v + v + 1] = a[v];
    a[v] = 0;
}
void update(int v, int tl, int tr, int x, int y, int l, int r){
    if (l > r || (a[v] != 0 && a[v] != y)) return;
    if (tl == l && tr == r && a[v] == y){
        a[v] = x;
        return;
    }
    push(v);
    int mid = (tl + tr) / 2;;
    update(v + v, tl, mid, x, y, l, min(mid, r));
    update(v + v + 1, mid + 1, tr, x, y, max(l, mid + 1), r);
    c[v] = c[v + v] + c[v + v + 1];
    if (a[v + v] == a[v + v + 1] && a[v + v] != 0) a[v] = a[v + v];
}
int root(int v, int tl, int tr, int x){
    if (tl == tr) return a[v];
    push(v);
    int mid = (tl + tr) / 2;;
    if (x <= mid) return root(v + v, tl, mid, x);
    else return root(v + v + 1, mid + 1, tr, x);
}
