using namespace std;

using ll = long long;
using P = pair<int, int>;
using T = tuple<ll, int, int>;

struct UnionFind {
    //各要素が属する集合の代表(根)を管理する
    //もし、要素xが根であればdata[x]は負の値を取り、-data[x]はxが属する集合の大きさに等しい
    vector<int> data;

    UnionFind(int sz) : data(sz, -1) {}

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        bool is_union = (x != y);
        if (is_union) {
            if (data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return is_union;
    }

    int find(int x) {
        if (data[x] < 0) { //要素xが根である
            return x;
        } else {
            data[x] = find(data[x]); //data[x]がxの属する集合の根でない場合、根になるよう更新される
            return data[x];
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return -data[find(x)];
    }
};

void bfs(int cur, ll lim, vector<int>& used, vector< vector<int> >& g, vector<T>& es) {
    queue<int> q;
    q.push(cur);

    while (!q.empty()) {
        int node = q.front();
        q.pop();

        for (int i : g[node]) {
            if (used[i]) continue;
            if (get<0>(es[i]) > lim) continue;
            used[i] = true;
            q.push((get<1>(es[i]) == node ? get<2>(es[i]) : get<1>(es[i])));
        }
    }
}

