struct UnionFind{
  Int n;
  vector<Int> r,v,p;
  using P = pair<Int, Int>;
  using T = tuple<Int, Int, Int>;
  map<P, T> st;
  UnionFind(){}
  UnionFind(Int sz,vector<Int> x):n(sz),r(sz,1),v(x),p(sz,0){
    iota(p.begin(),p.end(),0);
  }
  Int find(Int x){
    return (x==p[x]?x:find(p[x]));
  }
  bool same(Int x,Int y){
    return find(x)==find(y);
  }
  void unite(Int x,Int y){
    Int a=x,b=y;
    x=find(x);y=find(y);    
    if(x==y){
      st[P(a,b)]=T(x,y,-1);
      return;
    }
    if(r[x]<r[y]) swap(x,y);
    r[x]+=r[y];
    v[x]+=v[y];
    p[y]=x;
    st[P(a,b)]=T(x,y,v[y]);
  }
  void rollback(Int a,Int b){
    assert(!st.empty());
    Int x,y,z;
    tie(x,y,z)=st[P(a,b)];
    if(z<0) return;
    r[x]-=r[y];
    v[x]-=v[y];
    p[y]=y;
  }
};

