const int MAX = 100000;
/**
 * Union-Find木です。
 * クラスカル法でも扱う時にどうぞ
 */
typedef class unionFind {
	private:
		vector<int> parent; // 負数ならばデータ数、正数ならば親の場所
	public:
		unionFind(int n) : parent(n, -1){}
		int find(int n);
		void unite(int n, int m);
		bool isEqual(int n, int m);
		int getSize(int n);
} UnionFind;

/**
 * nの属している木の頂点を返します
 * @param n 調べるデータ
 * @return nが属している木の頂点
 */
int unionFind::find(int n) {
	if (parent[n] < 0) return n;
	return parent[n] = find(parent[n]);
}

/**
 * nの属する木とmの属する木を結合します
 * @param n 結合したいデータ
 * @param m 結合したいデータ
 */
void unionFind::unite(int n, int m) {
	n = find(n);
	m = find(m);
	if (n == m) return;
	if (parent[n] > parent[m]) {
		parent[m] += parent[n];
		parent[n] = m;
	} else {
		parent[n] += parent[m];
		parent[m] = n;
	}
}

/**
 * nとmが同じ木に属しているか調べます
 * @param n 調べるデータ
 * @param m 調べるデータ
 * @return 同じ木に属していたならtrue
 */
bool unionFind::isEqual(int n, int m) {
	return find(n) == find(m);
}

/**
 * nの属している木のデータ数を返します。
 * @param n 調べるデータ
 * @return nの属している木のデータ数
 */
int unionFind::getSize(int n) {
	return parent[find(n)];
}

int main() {
	int N, M;
	static int64_t X[MAX];
	static int E[MAX]; // その頂点に繋がる辺の数
	static pair<int, pair<int, int> > edge[MAX];
	cin >> N >> M;
	for (int i = 0;i < N;++ i) {
		cin >> X[i];
		E[i] = 0;
	}
	for (int i = 0;i < M;++ i) {
		cin >> edge[i].second.first >> edge[i].second.second >> edge[i].first;
		-- edge[i].second.first;
		-- edge[i].second.second;
	}
	sort(edge, edge + M);
	UnionFind uf(N);
	int connect = 0;
	for (int i = 0;i < M;++ i) {
		int l = uf.find(edge[i].second.first), r = uf.find(edge[i].second.second);
		uf.unite(l, r);
		int parent = uf.find(l);
		if (l != parent) {
			X[r] += X[l];
			E[r] += E[l] + 1;
			X[l] = E[l] = 0;
		} else if (r != parent) {
			X[l] += X[r];
			E[l] += E[r] + 1;
			X[r] = E[r] = 0;
		} else {
			++ E[parent];
		}
		if (X[parent] >= edge[i].first) { // そこまでの頂点をすべて繋げても大丈夫
			connect += E[parent];
			E[parent] = 0;
		}
		/*
		cout << i << "手目" << endl;
		cout << l + 1 << "<->" << r + 1 << ":" << edge[i].first << endl;
		for (int i = 0;i < N;++ i) {
			cout << X[i] << " ";
		}
		cout << endl;
		for (int i = 0;i < N;++ i) {
			cout << E[i] << " ";
		}
		cout << endl;
		*/
	}
	cout << M - connect;
	return 0;
}
