	{
		int ufa = gfa(p[i].u), vfa = gfa(p[i].v);
		if(ufa == vfa) p[i].fl = 0;
		else 
			p[i].fl = 1, 
			fa[ufa] = vfa, 
			addedge(p[i].u, p[i].v), 
			addedge(p[i].v, p[i].u);
	}
	dep[1] = 1, top[1] = 1;
	dfs1(1), dfs2(1);
	for(int i = 1; i <= n; i++)
		tr[dfn[i]] = i;
	root = &stp[stcnt++];
