struct UnionFind_P {
private:
	vector<int> data, sz;
	int root(int x) {
		return data[x] < 0 ? x : root(data[x]);
	}

public:
	vector<vector<pii>> tb;
	vector < vector <pair<int, ll> >> tsz;
	int s_cou = 0;
	UnionFind_P(int size) : tb(size, vector<pii>(1)), data(size, -1), sz(size, 0), tsz(size, vector<pair<int,ll>>(1)) {
		REP(i, size) {
			tb[i][0] = { 0, i };
		}
	}

	void Initsz(vector<ll> szarr) {
		REP(i, data.size()) {
			sz[i] = szarr[i];
			tsz[i][0] = { 0,szarr[i] };
		}
	}

	//tを小さい順にやるならおｋだよ お祭りで使った
	//bool unionSet(int x, int y, int t) { //ｘの入ってる集合と yの入ってる集合を併合
	//	x = root(x); y = root(y);
	//	s_cou++;
	//	if (x != y) {
	//		if (data[y] < data[x]) swap(x, y);
	//		data[x] += data[y]; data[y] = x;
	//		if (tb[y][tb[y].size() - 1].first != t)
	//			tb[y].push_back({ t,x });
	//		else
	//			tb[y][tb[y].size() - 1].second = x;
	//	}
	//	return x != y;
	//}
	bool unionSet(int x, int y) { //ｘの入ってる集合と yの入ってる集合を併合
		x = root(x); y = root(y);
		s_cou++;
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
			tb[y].push_back({ s_cou,x });

			sz[x] += sz[y];
			sz[y] = 0;
			tsz[x].push_back({s_cou, sz[x]});

		}
		return x != y;
	}
	int findroot(int u, int t) {
		auto itr = --upper_bound(ALL(tb[u]), MP(t, INT_MAX));
		return itr->second == u ? u : findroot(itr->second, t);
	}

	int getsz(int u, int t) {
		int rt = findroot(u, t);
		auto itr = --upper_bound(ALL(tsz[rt]), MP(t, LLONG_MAX));
		return itr->second;
	}

};

