            par[i]=i;  rank[i]=1;
            val[i]=0; nedge[i]=nedge_c[i]=0;
        }
    }

    long find(long x) {
        if(x==par[x]) return x;
        return par[x] = find(par[x]);
    }

    long unite(long x, long y) {
        x=find(x);
        y=find(y);
        if(x==y) return x;
        if(rank[x]<rank[y]) {
            par[x]=y;
            return y;
        }
        else {
            par[y]=x;
            if(rank[x]==rank[y]) rank[x]++;
            return x;
        }
    }

    bool same(long x, long y) {
        return find(x)==find(y);
    }

    long ngroup() {
        long count=0;
        long i;
        for(i=0; i<num; i++) {
            if(par[i]==i) count++;
        }
        return count;
    }
};



