struct persistentUnionFind {
    vector<int> parent;
    vector<int> sz;
    vector<int> height;
    vector<vector<plglg>> S;
    vector<ll> time;
    vector<ll> X;
    vector<ll> wt;
    vector<vector<plglg>> W;

    persistentUnionFind(int N, vector<ll> X) : parent(N, 0), sz(N, 1), height(N, 1),
                                 S(N, vector<plglg>(1, plglg(0, 1))),
                                 time(N, inf), X(X), wt(N),
                                 W(N, vector<plglg>()) {
        for (int i = 0; i < N; i++)
        {
            parent[i] = i;
            wt[i] = X[i];
            W[i].push_back(plglg(0, X[i]));
        }
    }

    int root(int x, ll t) {
        while (time[x] <= t) {
            x = parent[x];
        }
        return x;
    }

    bool unite(int x, int y, ll t) {
        int px = root(x, t);
        int py = root(y, t);
        if (px == py) {
            return false;
        }
        if (height[py] < height[px]) {
            parent[py] = px;
            time[py] = t;
            sz[px] += sz[py];
            S[px].push_back(plglg(t, sz[px]));
            wt[px] += wt[py];
            W[px].push_back(plglg(t, wt[px]));
        } else {
            parent[px] = py;
            time[px] = t;
            sz[py] += sz[px];
            S[py].push_back(plglg(t, sz[py]));
            wt[py] += wt[px];
            W[px].push_back(plglg(t, wt[py]));
            height[py] = max(height[py], height[px] + 1);
        }
        return true;
    }

    ll size(int x, ll t) {
        int y = root(x, t);
        int idx = lower_bound(S[y].begin(), S[y].end(), plglg(t, inf)) - S[y].begin() - 1;
        return S[y][idx].second;
    }

    ll weight(int x, ll t) {
        int y = root(x, t);
        int idx = lower_bound(W[y].begin(), W[y].end(), plglg(t, inf)) - W[y].begin() - 1;
        return W[y][idx].second;
    }
};

