    sz[x] += sz[y];
    wg[x] += wg[y];
}
void build(int v, int tl, int tr){
    a[v] = 1;
    if (tl == tr){
        a[v] = 1;
        c[v] = b[tl];
        return;
    }
    int mid = (tl + tr) / 2;;
    build(v + v, tl, mid);
    build(v + v + 1, mid + 1, tr);
    c[v] = c[v + v] + c[v + v + 1];
    if (a[v + v] == a[v + v + 1] && a[v + v] != 0) a[v] = a[v + v];
}
void push(int v){
    if (a[v] != 0)
        a[v + v] = a[v + v + 1] = a[v];
    a[v] = 0;
}
void update(int v, int tl, int tr, int x, int y, int l, int r){
    if (l > r || (a[v] != 0 && a[v] != y)) return;
    if (tl == l && tr == r && a[v] == y){
        a[v] = x;
        return;
    }
    push(v);
    int mid = (tl + tr) / 2;;
    update(v + v, tl, mid, x, y, l, min(mid, r));
    update(v + v + 1, mid + 1, tr, x, y, max(l, mid + 1), r);
    c[v] = c[v + v] + c[v + v + 1];
    if (a[v + v] == a[v + v + 1] && a[v + v] != 0) a[v] = a[v + v];
}
int root(int v, int tl, int tr, int x){
    if (tl == tr) return a[v];
    push(v);
    int mid = (tl + tr) / 2;;
    if (x <= mid) return root(v + v, tl, mid, x);
    else return root(v + v + 1, mid + 1, tr, x);
}
void dfs(int v, int pp = -1){
    timer++;
    time2++;
    tin[v] = time2;
    w[v] += b[v];
    lb[v] = timer;
    used[v] = 1;
    for (auto u: g[v]){
        if (u == pp) continue;
        pr[u] = v;
        dfs(u, v);
        w[v] += w[u];
    }
    rb[v] = timer;
    time2++;
    tout[v] = time2;
}
int getsum(int v, int tl, int tr, int x, int l, int r){
    if (l > r || (a[v] != 0 && a[v] != x)) return 0;
   // cout << tl << " " << tr << " " << x << "  " << l << " " << r << endl;
    if (a[v] == x && tl == l && tr == r){
        return c[v];
    }
    push(v);
    int mid = (tl + tr) / 2;;
    return getsum(v + v, tl, mid, x, l, min(mid, r)) +
    getsum(v + v + 1, mid + 1, tr, x, max(l, mid + 1), r);
    if (a[v + v] == a[v + v + 1] && a[v + v] != 0) a[v] = a[v + v];
}
int root(int v){
    for (auto i: events){
        if (tin[i] >= tin[rm[v]] && tout[i] <= tout[rm[v]] && tin[i] <= tin[v] && tout[i] >= tout[v]) rm[v] = i;
    }
    return rm[v];
}
void calcroot(){
    events.clear();
    queue < pair < int, int > > q;
    q.push({1, 1});
    while(!q.empty()){
        auto it = q.front();
        q.pop();
        int v = it.F;
        int x = rm[it.S];
        if (cc[v]) x = v;
        rm[v] = x;
        for (auto u: g[v]){
            if (u != it.S){
                q.push({u, v});
            }
        }
    }
}
