    u = Merge(u, v, std::make_pair(u, v));
    if (sum[u] >= w) {
      for (auto e : mg[u]) {
        uf2[Find(e.first, uf2)] = Find(e.second, uf2);
      }
      mg[u].clear();
    }
  }
  std::vector<int64_t> sum2(n);
