int bfs(int st, int lim) {
	queue<int> q;
	q.push(st);
	used[st] = 1;
	seen.push_back(st);
	while (!q.empty()) {
		int v = q.front();
		// cerr << "pop " << v << endl;
		q.pop();
		for (auto ind : g[v]) {
			Edge e = E[ind];
			int u = e.get(v);
			if (!used[u]) {
				used[u] = 1;
				seen.push_back(u);
				seen_e.push_back(ind);
				q.push(u);
				if ((int)seen.size() > lim) break;
			}
		}
		if ((int)seen.size() > lim) break;
	}
	return q.empty();
}

