void split(int ind) {
	Edge e = E[ind];
	g[e.u].erase(ind);
	g[e.v].erase(ind);
	cerr << "split " << e.u << ' ' << e.v << endl;
	assert(comp[e.u] == comp[e.v]);
	int W = comp[e.u];
	int lim = size_comp[comp[e.u]] / 2;
	cerr << "lim " << lim << endl;
	int fr = e.u;
	seen.clear();
	seen_e.clear();
	// exit(0);
	if (!bfs(e.u, lim)) {
		cerr << "bad " << endl;
		fr = e.v;
	}
	cerr << "fr " << fr << endl;
	for (auto t : seen) {
		used[t] = 0;
	}
	seen.clear();
	seen_e.clear();
	bfs(fr, N);
	cerr << "new seen " << seen.size() << endl;
	assert((int)seen.size() <= lim);
	for (auto t : seen) {
		size_comp[comp[t]]--;
		sum_a_comp[comp[t]] -= a[t];
		comp[t] = pnt;
		size_comp[comp[t]]++;
		sum_a_comp[comp[t]] += a[t];
	}
	for (auto t : seen_e) {
		edge_comp[W].erase({E[t], t});
		edge_comp[pnt].insert({E[t], t});
	}
	edge_comp[W].erase({E[ind], ind});
	if (!edge_comp[W].empty() && sum_a_comp[W] < edge_comp[W].rbegin()->first.w) {
		bad_comps.push(W);
	}
	if (!edge_comp[pnt].empty() && sum_a_comp[pnt] < edge_comp[pnt].rbegin()->first.w) {
		bad_comps.push(pnt);
	}
	pnt++;
	for (int i = 0; i < 4; i++) {
		cerr << comp[i] << ' ';
	}
	cerr << endl;
	// exit(0);
}

