        mp[make_pair(now,u)]=2;
        if(!used[u]) dfs(u,lim);
      }
    }else{
      if(g[now][i].second<=lim){
        mp[make_pair(u,now)]=2;
        if(!used[u]) dfs(u,lim);
      }
    }
  }
  return;
}

