struct union_find {
    int uf[100000];
    long long sum[100000];

    int id_[200000];
    int uf_[200000];
    long long sum_[200000];
    int k;

    int find(int x) {
        if (uf[x] < 0) return x;
        return uf[x] = find(uf[x]);
    }

    void store(int x) {
        id_[k] = x;
        uf_[k] = uf[x];
        sum_[k] = sum[x];
        k++;
    }

    void restore() {
        k--;
        int x = id_[k];
        uf[x] = uf_[k];
        sum[x] = sum_[k];
    }

    void skip() {
        k--;
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (-uf[x] < -uf[y]) swap(x, y);
        store(x);
        store(y);
        uf[x] += uf[y];
        sum[x] += sum[y];
        uf[y] = x;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
} uf;


int N, M;
