    for (int i = 0; i < M; i++) {
        scanf("%d %d %d", &A[i], &B[i], &Y[i]);
        A[i]--;
        B[i]--;
        P[i] = i;
    }
    sort(P, P + M, [&](int i, int j) { return Y[i] < Y[j]; });
    for (int i = 0; i < M; i++) {
        int j = P[i];
        if (!uf.same(A[j], B[j])) {
            uf.unite(A[j], B[j]);
            used[j] = 1;
        }
    }
    int ans = 0;
    for (int i = M - 1; i >= 0; i--) {
        int j = P[i];
        long long sum = uf.sum[uf.find(A[j])];
        if (used[j]) {
            if (sum < Y[j]) {
                ans++;
                uf.restore();
                uf.restore();
            } else {
                uf.skip();
                uf.skip();
            }
        } else {
            if (sum < Y[j]) {
                ans++;
            }
        }
