class Union_find
{
public:
    vector<int> par;
    vector<int> sz;

    Union_find(int N){
        par = vector<int>(N);
        REP(i, N) par[i] = i;
        sz = vector<int>(N, 1);
    }

    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(sz[x] < sz[y]){
            par[x] = y;
            sz[y] += sz[x];
        }else{
            par[y] = x;
            sz[x] += sz[y];
        }
    }

    bool is_union(int x, int y){
        x = find(x);
        y = find(y);
        return x == y;
    }

    int union_size(int x){
        return sz[find(x)];
    }

};


struct edge{int to, cost;};

class Graph
{
public:
    int V;
    vector<vector<edge>> G;

    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void erase_edge(int from, int to){
        vec e(0);
        REP(i, G[from].size()){
            if(G[from][i].to == to) e.push_back(i);
        }
        IREP(i, e.size()) G[from].erase(G[from].begin() + e[i]);
    }

    void erase_edge2(int v1, int v2){
        erase_edge(v1, v2);
        erase_edge(v2, v1);
    }

    void dfs(int v, map<Pii, bool> &used){
        REP(k, G[v].size()){
            int a = min(v, G[v][k].to), b = max(v, G[v][k].to);
            if(!used[Pii(a, b)]){
                used[Pii(a, b)] = true;
                dfs(G[v][k].to, used);
            }
        }
    }

};

signed main(){

    int N, M; cin >> N >> M;
    vec X(N); readv(X);

    vec A(M), B(M), Y(M);
    vector<PiP> p(M);
    Graph G(N);
    Union_find U(N);
    REP(i, M){
        cin >> A[i] >> B[i] >> Y[i];
        int a = min(A[i], B[i]) - 1, b = max(A[i], B[i]) - 1;
        p[i] = PiP(Y[i], Pii(a, b));
        G.add_edge2(a, b, 0);
    }

    Sort(p);
    vec sX(N), sXtmp(M);
    REP(i, N) sX[i] = X[i];
    REP(i, M){
        int a = p[i].second.first, b = p[i].second.second;
        if(U.is_union(a, b)){
            sXtmp[i] = sX[U.find(a)];
        }else{
            sXtmp[i] = sX[U.find(a)] + sX[U.find(b)];
            U.unite(a, b);
            sX[U.find(a)] = sXtmp[i];
        }
        //cout << sXtmp[i] << endl;
    }

    map<Pii, bool> used;
    int ans = 0;
    IREP(i, M){
        int y = p[i].first;
