bool mycmp(edge &a, edge &b) {
	return a.y < b.y;
}

vector<vector<int> > g;

int getfa(int u) {
	if (fa[u] != u)
		fa[u] = getfa(fa[u]);

	return fa[u];
}

void unify(int a, int b) {
	sum[b] += sum[a];
	sum[a] = 0;

	fa[a] = b;
}

void keepEdges(int u, int lim) {
	if (vis[u])
		return;

	vis[u] = true;
	for (int i = 0; i < g[u].size(); ++i) {
		int idx = g[u][i];
		if (edges[idx].y <= lim) {
			ok[idx] = true;
			keepEdges(edges[idx].v, lim);
		}
	}
}

