   }//while
   sort(V.begin(), V.end());
   for (int i = 0; i < (int)V.size(); i++) {
      int p1 = U.findSet(V[i].second.first);
      int p2 = U.findSet(V[i].second.second);
      if (p1 != p2) {
         U.unite(p1, p2);
         if (U.getSize(p1) < V[i].first)
            U.incBad(U.findSet(p1));
         else
            U.clearBad(U.findSet(p1));
      }//if
      else if (U.getSize(p1) < V[i].first)
         U.incBad(U.findSet(p1));
   }//for
   int ans = 0;
   for (int i = 1; i <= N; i++)
      if (!seen[U.findSet(i)])
         seen[U.findSet(i)] = 1, ans += U.getBad(U.findSet(i));
