void merge(int &ret,int x,int y,int wei) {
  x = f(x),y = f(y);
  if(x==y) {
    ++numUnsat[x];
  } else {
    sum[x] += sum[y];
    dsu[y] = x;
    numUnsat[x] = numUnsat[x] + numUnsat[y] + 1;
  }
