vector<vector<LL> > zmiany;

void uni(int a, int b, int c)
{
  a = fin(a);
  b = fin(b);
  if(r[a] < r[b])
    swap(a, b);
  if(a != b)
  {
    suma[a] += suma[b];
    r[a] += r[b] + 1;
    F[b] = F[a];
    zmiany.pb({c, a, b});
  }
  else
  {
    r[a]++;
    zmiany.pb({c, a, -1});
  }
}

void cofnij()
{
  assert(SZ(zmiany));
  if(zmiany.back()[2] == -1)
  {
    r[zmiany.back()[1]]--;
    zmiany.pop_back();
    return;
  }
  int a = zmiany.back()[1];
  int b = zmiany.back()[2];
  r[a] -= r[b] + 1;
  suma[a] -= suma[b];
  F[b] = b;
  zmiany.pop_back();
}

