}

void usun(edge x)
{
  roz.erase(x);
  wek[x.a].erase({x.b, x.num});
  wek[x.b].erase({x.a, x.num});
}

void rek(set<edge> * zb, bool buduj = 0)
{
  if(buduj)
  {
    while(SZ(zmiany))
      cofnij();
    for(auto s : (*zb))
      uni(s.a, s.b, s.num);
  }
  // dbg(SZ(*zb), buduj);
  if(SZ(*zb) == 0)
    return ;
  auto it = (*zb).end();
  it--;
  while(SZ(*zb) && suma[fin(it->a)] < it->c)
  {
    while(zmiany.back()[0] != it->num)
      cofnij();
    assert(SZ(zmiany) > 0);
    cofnij();
    if(fin(it->a) == fin(it->b))
    {
      usun(*it);
      (*zb).erase(*it);
      it = (*zb).end();
      it--;
    }
    else
    {
      usun(*it);
      int a = it->a;
      int b = it->b;
      (*zb).erase(*it);
      if(r[fin(a)] < r[fin(b)])
        swap(a, b);
      numer++;
