struct Ed {
  int u, v, w;

  Ed() {}

  Ed(int u, int v, int w) : u(u), v(v), w(w) {}

  bool operator<(const Ed &rhs) const {
    return w < rhs.w;
  }

  bool operator>(const Ed &rhs) const {
    return rhs < *this;
  }

  bool operator<=(const Ed &rhs) const {
    return !(rhs < *this);
  }

  bool operator>=(const Ed &rhs) const {
    return !(*this < rhs);
  }
};

