    for (int i = 0; i < m; i++){
        int a, b, x;
        cin >> a >> b >> x;
        lst[i] = {x, {a - 1, b - 1}};
        g[a - 1].push_back({x, b - 1});
        g[b - 1].push_back({x, a - 1});
    }
    sort(lst.begin(), lst.end());
    for (int i = 0; i < n; i++){
        prev[i] = i;
        summa[i] = s[i];
    }
    for (int i = 0; i < m; i++){
        join(lst[i].second.first, lst[i].second.second);
        kek[i] = summa[getPrev(lst[i].second.first)];
    }
    // for (int i = 0; i < m; i++)
    //     cout << kek[i] << " ";
    // cout << endl;
    int answer = 0;
    for (int i = m - 1; i >= 0; i--){
        int a = lst[i].second.first, b = lst[i].second.second;
        if (ok[a] && ok[b]){
            answer++;
            continue;
        }
        if (lst[i].first <= kek[i]){
            answer++;
            dfs(a, kek[i]);
        }
    }
    cout << m - answer << endl;
    return 0;
}

