vector<int> par;
vector<int> rak; // number of edges
vector<ll> sum; // sum of the weight of vertices
vector<int> ans; // number of edges satisfied

void init(int n) {
  par.resize(n+1);
  rak.resize(n+1);
  sum.resize(n+1);
  ans.resize(n+1);
  for(int i=1; i<=n; i++) {
    par.at(i) = i;
    rak.at(i) = 0;
    cin >> sum[i];
  }
}

int find(int x) {
  if (par.at(x) == x) {
    return x;
  } else {
    return par.at(x) = find(par.at(x));
  }
}

void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x==y) return;
  if (rak.at(x) < rak.at(y)) {
    rak[y] += rak[x];
    sum[y] += sum[x];
    ans[y] += ans[x];
    par.at(x) = y;
  } else {
    rak[x] += rak[y];
    sum[x] += sum[y];
    ans[x] += ans[y];
    par.at(y) = x;
  }
}

void calc(int x, ll len) {
  x = find(x);
  rak[x]++;
  if (len <= sum[x]) {
    ans[x] = rak[x];
  }
}

