bool Merge(int a, int b)
{
    a = Root(a), b = Root(b);
    if (a == b)
    {
        return 0;
    }
    if (sz[a] > sz[b])
    {
        sz[a] += sz[b];
        root[b] = a;
        return 1;
    }
    else
    {
        sz[b] += sz[a];
        root[a] = b;
        return 1;
    }
}

