int parent(int v) {
    if (par[v]==v) return v;
    return par[v] = parent(par[v]);
}


void join(int u, int v, ll wei) {
    u = parent(u);
    v = parent(v);

    if (u == v) {
	if (wei > cc[u]) {
	    edge_deletes[u]++;
	} else {
	    edge_deletes[u]=0;
	}
    } else {
	if (siz[u]<siz[v]) swap(u,v);
	cc[u] += cc[v];
	siz[u] += siz[v];
	edge_deletes[u] += edge_deletes[v];
	par[v] = u;

	if (wei > cc[u]) {
	    edge_deletes[u]++;
	} else {
	    edge_deletes[u]=0;
	}
    }
}

