struct uftree{
    int par[200005];
    priority_queue<int,vector<int>,greater<int> > que[200005];
    ll sum[200005];
    uftree(){
    }
    void init(int n){
        for(int i=0;i<n;i++){
            par[i]=i;
            while(que[i].size()){
                que[i].pop();
            }
            sum[i]=0;
        }
    }
    int find(int x){
        if(par[x]==x)return x;
        return par[x]=find(par[x]);
    }

    void insert(int x,ll y){
        x=find(x);
        //printf("ins %lld %lld\n",sum[x],y);
        if(sum[x]<y){
            que[x].push(y);
            cur++;
        }
    }

    void unite(int x,int y,ll c){
        x=find(x);
        y=find(y);
        if(x==y)return;
        if(que[x].size()<que[y].size()){
            par[x]=y;
            while(que[x].size()){
                que[y].push(que[x].top());
                que[x].pop();
            }
            sum[y]+=sum[x];
            que[y].push(c);
            cur++;
            if(sum[y]<c)return;
            while(que[y].size() && que[y].top()<=sum[y]){
                que[y].pop();
                cur--;
            }
        }else{
            par[y]=x;
            while(que[y].size()){
                que[x].push(que[y].top());
                que[y].pop();
            }
            sum[x]+=sum[y];
            que[x].push(c);
            cur++;
            if(sum[x]<c)return;
            while(que[x].size() && que[x].top()<=sum[x]){
                que[x].pop();
                cur--;
            }
        }
    }

    bool same(int x,int y){
        return find(x)==find(y);
    }
};


