signed main(){
    scanf("%lld%lld",&N,&M);
    rep(i,N)scanf("%lld",&X[i]);


    UnionFindTree uf(N);
    vector<tuple<int,int,int>>es;
    rep(i,M){
        int a,b,c;
        scanf("%lld%lld%lld",&a,&b,&c);
        a--;b--;
        es.eb(c,a,b);
    }
    sort(all(es));

    rep(i,M){
        int c,a,b;
        tie(c,a,b)=es[i];
        if(!uf.same(a,b)){
            uf.unite(a,b);
        }
        else{
            bucket[a].insert(pint(i,c));
            bucket[b].insert(pint(i,c));
        }
    }
    uf=UnionFindTree(N);

    int num=0;
    rep(i,M){
        int c,a,b;
        tie(c,a,b)=es[i];
        a=uf.find(a);
        b=uf.find(b);
        if(a==b)continue;

        uf.unite(a,b);
        if(uf.find(a)!=a)swap(a,b);
        X[a]+=X[b];
        if(que[a].size()<que[b].size())swap(que[a],que[b]);
        while(que[b].size()){
            que[a].push(que[b].top());
            que[b].pop();
        }
        que[a].emplace(c,0);        
        num++;


        if(bucket[a].size()<bucket[b].size()){
            swap(bucket[a],bucket[b]);
        }
        for(auto &p:bucket[b]){
            if(bucket[a].find(p)==bucket[a].end()){
                bucket[a].insert(p);
            }
            else{
                bucket[a].erase(p);
                que[a].emplace(p.se,1);
            }
        }


        while(que[a].size()&&que[a].top().fi<=X[a]){
            auto q=que[a].top();
            que[a].pop();
            if(q.se==0){ //spanning
                sat[num]++;
            }
            score[num]++;
        }
    }


    int ans=M;
    for(int i=0;i<=N-1;i++){
        sat[i+1]+=sat[i];
        score[i+1]+=score[i];

        if(sat[i]==i)chmin(ans,M-score[i]);
    }

    cout<<ans<<endl;
    return 0;
}

