        x=root(x);y=root(y);
        if(x==y)    return;
        if(siz[x]<siz[y]) swap(x,y);
        siz[x] += siz[y];par[y]=x;c--;
        a[x]+=a[y];
    }
    int size(int x){
        return siz[root(x)];
    }
};

