  for(int i=0;i<M;i++){
    int a,b,c;cin>>a>>b>>c;a--;b--;
    e[i]=PP(P(c,0),P(a,b));
    edge[a].push_back(P(b,c));
    edge[b].push_back(P(a,c));
  }
  sort(e.begin(),e.end());
  UnionFind uf(N);
  uf.init(w);
  for(int i=0;i<N;i++){
    int W=e[i].first.first,U=e[i].second.first,V=e[i].second.second;
    uf.unite(U,V);
    if(W<=uf.weight(U))e[i].first.second=1;
  }
  sort(e.rbegin(),e.rend());
  set<P> s;
  for(int i=0;i<M;i++){
    int W=e[i].first.first,A=e[i].first.second,U=e[i].second.first,V=e[i].second.second;
    if(s.count(P(U,V)))continue;
    if(A==0)continue;
    s.count(P(U,V));
    queue<int> que;
    que.push(U);
    que.push(V);
    while(que.size()){
      int p=que.front();que.pop();
      for(auto q:edge[p]){
        int t=q.first,WE=q.second;
        if(s.count(P(min(p,t),max(p,t))))continue;
        if(WE>W)continue;
        s.insert(P(min(p,t),max(p,t)));
        que.push(t);
      }
    }
  }
  cout<<M-s.size()<<endl;
}

