	for (auto p : a) {
		int i = p.second;
		if (!fix[i]) {
			auto limit = sum;
			for (;;) {
				ss = 0; mm = 0;
				f(i, ++id, limit);
				if (mm <= ss) break;
				limit = ss;
			}
			sum -= ss;
			//cerr << i << " " << limit << " " << ss << endl;
			g(i, ++id, limit);
		}
	}
	int res = 0;
	//for (auto x : used) cerr << x; cerr << endl;
	for (auto x : used) if (!x) ++ res;
	cout << res << endl;
}

