// Union-Find 木 (Verified: AtCoder Typical Contest 001 B)
struct UnionFind {
private:
    const int n;
    int __size;
public:
    vector<int> uf, pot;
    // 初期化 UnionFind uni(n) のように宣言すれば良い
    UnionFind(int _n, vector<int> pot_) : n(_n), __size(_n), uf(_n, -1), pot(pot_) {}
    // find (木の根を求める)
    int find(int x) {return (uf[x] < 0) ? x : uf[x] = find(uf[x]);}
    // x と y が同じ集合に属するかどうか
    bool same(int x, int y) {return find(x) == find(y);}
    // x が属する集合の要素数
    int size(int x) {return -uf[find(x)];}
    // 集合はいくつあるか
    int size()      {return __size;}
    // x と y の属する集合を併合
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        __size--;
        if(uf[y] < uf[x]) swap(x, y);
        uf[x] += uf[y]; pot[x] += pot[y]; uf[y] = x;
    }
};

int N, M;
signed main() {
    cin >> N >> M;

    vector<int> X(N);
    for(int i=0; i<N; i++) {
        cin >> X[i];
    }

    vector< tuple<int, int, int> > edges;
    for(int i=0; i<M; i++) {
        int u, v, w; cin >> u >> v >> w;
        u--; v--;
        edges.emplace_back(w, u, v);
    }
    sort(edges.begin(), edges.end());

    UnionFind uf(N, X);
    vector< tuple<int, int, int> > tmp;

    int ans = M;
    for(int i=0; i<M; i++) {
        int base = i;
        // 同じコストのものをまとめる
        int pre = get<0>(edges[i]);
        while(i < M and pre == get<0>(edges[i])) {
            tmp.emplace_back(edges[i]);
            i++;
        }

        // 全部追加する
        // 新たに追加したものについて全て条件を満たしているならば
        // そのようなとり方が可能
        for(auto e : tmp) {
            int w, u, v; tie(w, u, v) = e;
            uf.unite(u, v);
        }

        map<int, int> mp;
        map<int, vector< tuple<int, int> > > rec;
        for(auto e : tmp) {
            int w, u, v; tie(w, u, v) = e;

            int id = uf.find(u);
            // fprintf(stderr, "u = %lld, pot = %lld\n", u, uf.pot[id]);
            chmax(mp[id], w);
            rec[id].emplace_back(u, v);
        }
        tmp.clear();

        for(auto e : mp) {
            int id, val; tie(id, val) = e;
            if(uf.pot[id] >= val) {
                // fprintf(stderr, "i = %lld, id = %lld, val = %lld\n", i, id, val);
                base += rec[id].size();
                // fprintf(stderr, "add = %zu, base = %lld\n", rec[id].size(), base);
                chmin(ans, M - base);
            }
        }

        i--;
    }
    cout << ans << endl;
    return 0;
}

