    {
      cout << "child: " << child << ", total weight: " << total_weight << endl;
      if(child0 != NULL) child0->print();
      if(child1 != NULL) child1->print();
    }

    void propagate(i64 heaviest, vector<i64> &weights)
    {
      heaviest = ok ? max(heaviest, total_weight) : heaviest;
      if (child != -1) {
        weights[child] = heaviest;
      } else {
        child0->propagate(heaviest, weights);
        child1->propagate(heaviest, weights);
      }
    }
};

