            set<i64> all;
            queue<i64> q;
            for (auto c : npr) {
                q.push(c);
            }

            for (;;) {
                if (q.empty()) {
                    break;
                }
                i64 c = q.front();
                q.pop();
                for (auto aa : yy[c]) {
