struct UF {
    vector<int> d; // 根の場合は高さ*-1、子の場合は親の番号が入る
    vector<ll> sm;
    vector<pair<int, int>> history;
    vector<pair<int, ll>> smHis;

    UF() {}

    UF(int mx, vector<ll> S) : d(mx, -1), sm(S) {}

    int root(int x) {
        if (d[x] < 0) return x;
        return root(d[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (d[x] > d[y]) swap(x, y);
        if (d[x] == d[y]) {
            history.emplace_back(x, d[x]);
            d[x]--;
        }

        smHis.emplace_back(x, sm[x]);
        smHis.emplace_back(y, sm[y]);
        sm[x] += sm[y];

        history.emplace_back(y, d[y]);
        d[y] = x;

    }

    ll sum(int x) {
        return sm[root(x)];
    }

    void snapshot() {
        history.clear();
    }

    void rollback() {
        while (history.size()) {
            d[history.back().first] = history.back().second;
            history.pop_back();
        }
        while (smHis.size()) {
            sm[smHis.back().first] = smHis.back().second;
            smHis.pop_back();
        }
    }
};


struct Edge {

    int a, b;
    ll c;
    int id;

    Edge(int a, int b, ll c, int id) : a(a), b(b), c(c), id(id) {}

    bool operator<(const Edge &rhs) const {
        return c < rhs.c;
    }

};

vector<Edge> es;
