int SQRT = 318;

UF cpy[350];

void init() {
    UF uf(nn, ss);
//    cout << uf.d.size() << endl;
    for (int i = 0; i <= es.size(); i++) {
        if (i % SQRT == 0) {
            uf.snapshot();
            cpy[i / SQRT] = uf;
        }
        if (i < es.size()) uf.unite(es[i].a, es[i].b);
    }

}

UF &build(int until) {
    UF &uf = cpy[0];
//    cout << uf.history.size() << endl;
//    cout << until/SQRT << "<" << uf.d.size() << endl;
    for (int i = 0; i < until; i++) {
        uf.unite(es[i].a, es[i].b);
    }
    return uf;
}

