void dfs(int r, ll w) {
    for (auto i : G[r]) {
        if (i.c <= w && !dead[i.id]) {
            dead[i.id] = true;
            dfs(i.b, w);
        }
    }
}

void solve(long long N, long long M, std::vector<long long> X,
           std::vector<long long> A, std::vector<long long> B,
           std::vector<long long> Y) {

    for (int i = 0; i < A.size(); i++) {
        A[i]--, B[i]--;
        es.emplace_back(A[i], B[i], Y[i], i);
        G[A[i]].emplace_back(A[i], B[i], Y[i], i);
        G[B[i]].emplace_back(B[i], A[i], Y[i], i);
    }
    sort(es.begin(), es.end());

    nn = N;
    ss = X;
    init();


    int c = 0;
    UF uf(nn, ss);
    for (int i = es.size() - 1; i >= 0; i--) {
        int a = es[i].a;
        int b = es[i].b;
        auto &uf1 = build(i + 1);
        //auto uf2 = build(i);

        if (!dead[es[i].id] && uf1.sum(a) < es[i].c) {
            c++;
        } else {
            dfs(a, es[i].c);
            dfs(b, es[i].c);
        }
        uf1.rollback();
    }
    cout << c << endl;
    //cout << "No sub" << endl;
}

