		}

		for (ll i = 0; i <= M; i++) listen[i].clear();
		for (ll i = 0; i < M; i++) {
			if (ren[i].first == ren[i].second) continue;
			listen[(ren[i].first + ren[i].second)/2].push_back(i);
		}


		ll proses = 0;
		while (proses < M) {
			merge(edge[proses].b, edge[proses].c);
			ll akhir = proses;
			while (akhir < M-1 && edge[akhir+1].a == edge[akhir].a) {
				akhir++;
				merge(edge[akhir].b, edge[akhir].c);
			}

			for (int i = proses; i <= akhir; i++) {
				for (auto j: listen[i]) {
					ll x = find(edge[j].b);
					if (sum[x] >= edge[j].a) ren[j].second = i;
					else ren[j].first = i+1;
				}
			}

			proses = akhir+1;
		}
		//~ for (ll i = 0; i < M; i++) {
