struct UnionFind{
    vector<int> rank,parent;
    vector<ll> cost;
    UnionFind(){}
    UnionFind(int n){
        rank.resize(n,0);
        parent.resize(n,0);
        cost.resize(n,0);
        for(int i=0;i<n;i++){
            parent[i] = i;
            rank[i] = 0;
            cost[i] = X[i];
        }
    }

    int find(int x){
        if(parent[x] == x) return x;
        else return parent[x] = find(parent[x]);
    }

    void unite(int x,int y){
        x = find(x);
        y = find(y);
        if(x==y) return;
        if(rank[x] < rank[y]){
            parent[x] = y;
            cost[y] += cost[x];
            cost[x] = 0;
        }else{
            parent[y] = x;
            cost[x] += cost[y];
            cost[y] = 0;
        }
    }

    bool same(int x,int y){
        return find(x) == find(y);
    }

    ll sum(int x){
        return cost[find(x)];
    }
};

