		{
			swap(a, b);
		}
		dsu[b] = a;
		if(last[a] < last[b])
		{
			if(last[a] != -1)
			{
				used[last[a]] = false;
			}
		}
		else
		{
			if(last[b] != -1)
			{
				used[last[b]] = false;
			}
		}
		last[a] = max(last[a], last[b]);
		sum[a] += sum[b];
		if(rang[a] == rang[b])
		{
			rang[a]++;
		}
	}
}
