struct union_find {
    vector<int> parent;
    vector<int> size;
    vector<long long> weight_sum;
    int components = 0;

    union_find(int n = -1) {
        if (n >= 0)
            init(n);
    }

    void init(int n) {
        parent.resize(n + 1);
        size.assign(n + 1, 1);
        components = n;

        for (int i = 0; i <= n; i++)
            parent[i] = i;
    }

    int find(int x) {
        return x == parent[x] ? x : parent[x] = find(parent[x]);
    }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);

        if (x == y)
            return false;

        if (size[x] < size[y])
            swap(x, y);

        parent[y] = x;
        size[x] += size[y];
        weight_sum[x] += weight_sum[y];
        components--;
        return true;
    }
};


struct edge {
    int A, B, Y;
    bool heaviest_ok = false;
    bool keep = false;

    bool operator<(const edge &other) const {
        return Y < other.Y;
    }
};

struct adj_edge {
    int node, weight, index;
    bool keep = false;
};

int N, M;
vector<int> X;
vector<edge> edges;
vector<vector<adj_edge>> adj;

void dfs(int node, int maximum) {
    for (adj_edge &e : adj[node])
        if (e.weight <= maximum && !e.keep) {
            e.keep = true;
            edges[e.index].keep = true;
            dfs(e.node, maximum);
        }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M;
    X.resize(N);

    for (int &x : X)
        cin >> x;

    edges.resize(M);

    for (edge &e : edges) {
        cin >> e.A >> e.B >> e.Y;
        e.A--; e.B--;
    }

    sort(edges.begin(), edges.end());
    union_find UF(N);
    UF.weight_sum = vector<long long>(X.begin(), X.end());

    for (edge &e : edges) {
        UF.unite(e.A, e.B);
        e.heaviest_ok = e.Y <= UF.weight_sum[UF.find(e.A)];
    }

    reverse(edges.begin(), edges.end());
    adj.assign(N, {});

    for (int i = 0; i < (int) edges.size(); i++) {
        edge &e = edges[i];
        adj[e.A].push_back({e.B, e.Y, i});
        adj[e.B].push_back({e.A, e.Y, i});
    }

    int remove = 0;

    for (edge &e : edges) {
        if (!e.keep && e.heaviest_ok)
            dfs(e.A, e.Y);

        if (!e.keep)
            remove++;
    }

    cout << remove << '\n';
}

