// UnionFind木
// unite()で2つの集合を1つに統合する
// find()で2つの集合が同じ集合かどうかわかる
// root()で集合の識別番号(その集合のルートの番号)を求められる
struct UnionFind{

	std::vector<int> data;
	// dataの各要素について
	// 負の値:その集合のルートであること示す。また、その絶対値は集合の要素数となっている。
	// 正の値:親ノードの番号(dataのインデックス)。root()を呼び出すたびに集合のルートを指すように書きなおされるので木はそんなに深くならない
	std::vector<ll> Value;

	//初期化 size:最大要素数
	UnionFind(int size, vector<ll> val): data(size, -1), Value(val) {}

	// 集合を併合する
	// すでに同じ集合だった場合は、falseが返る
	bool unite(int x, int y){
		x=root(x);
		y=root(y);
		if( x != y ){
			// 要素数の大きな方へ合併するためのswap
			if( data[y] < data[x] ) std::swap(x, y);
			// 要素数を加算する
			data[x] += data[y];
			// yの属する集合のルートをxに変更
			data[y] = x;
			//
			Value[x] += Value[y];
		}
		return x!=y;
	}

	// 同じ集合かどうか判定
	bool find(int x, int y){
		return root(x) == root(y);
	}

	// 集合の識別番号を返す
	int root(int x){
		// 負の値を持つものがその集合のルート
		// 正の値は同じ集合に属するものを指す(辿ればいずれルートへ着く)
		return (data[x] < 0)? x : data[x]=root(data[x]);
	}

	// 集合の要素数を返す
	int size(int x){
		return -data[ root(x) ];
	}

	ll value(int x){
		return Value[root(x)];
	}
};


int main(){
	ios_base::sync_with_stdio(false);
	ll N, M, ans=0;
	ll A[100005], B[100005], Y[100005];
	vector<pair<ll,pii>> v;

	cin >> N >> M;
	vector<ll> X(N);
	rep(i,N) cin >> X[i];
	rep(i,M){
		cin >> A[i] >> B[i] >> Y[i];
		A[i]--;
		B[i]--;
		v.emplace_back(Y[i], pii(A[i], B[i]));
	}

	sort(all(v));

	UnionFind uf(N, X);
	priority_queue<pll, vector<pll>, greater<pll>> que[100005];
	ll req[100005];
	Fill(req, M);
	rep(i,M){
		pii p = v[i].Y;
		int r1 = uf.root(p.X);
		int r2 = uf.root(p.Y);

		uf.unite(p.X, p.Y);

		auto val = uf.value(p.X);
		if( r1 != uf.root(p.X) ) swap(r1, r2);
		while( que[r1].size() ){
			pll t = que[r1].top();
			if(t.X <= val){
				req[t.Y] = i;
				que[r1].pop();
			}else{
				break;
			}
		}
		while( que[r2].size() ){
			pll t = que[r2].top();
			que[r2].pop();
			if(t.Y <= val){
				req[t.Y] = i;
			}else{
				que[r1].push(t);
			}
		}

		if( val < v[i].X ){
			req[i] = -1;
			que[r1].emplace(v[i].X, i);
		}
	}

	bool safe[100005] = {};
	safe[M] = true;
	rrep(i,M){
		if( req[i] == -1 || !safe[req[i]] ){
			ans++;
		}else{
			safe[i] = true;
		}
	}

	cout << ans << endl;

	return 0;
}

