class UnionFind {
public:
	vector<int>s, p;
	UnionFind(int size) {
		s.resize(size, 0);
		p.resize(size, 0);
		for (int i = 0; i < size; i++)makeSet(i);
	}
	void makeSet(int x) {
		p[x] = x;
		s[x] = 1;
	}
	void setcost(int x, ll cost) { 
		s[x] = cost;
	}
	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}
	void unite(int x, int y) {
		x = findSet(x);
		y = findSet(y);
		if (x == y)return;
		if (s[x] < s[y])swap(x, y);
		p[y] = x;
		s[x] += s[y];
	}
	int findSet(int x) {
		if (x == p[x])return p[x];
		return p[x] = findSet(p[x]);
	}
	int getsize(int x) {
		return s[findSet(x)];
	}
};

vector<vector<ll>>E;
vector<pair<int, ll>>Eli[101010];
map<pair<int,int>, int>mpE;
int fl[101010];
int used[101010];

void dfs(int now,ll cost) {
	fore(x,Eli[now]){
		int to = x.first;
		ll c = x.second;
		int idx = mpE[{min(now,to),max(now,to)}];
		if (c <= cost) {
			if (!used[idx]) { used[idx] = 1; dfs(to, cost); }
		}
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int N, M;
