	for (int i = 0; i < M; i++) {
		int A, B, X;
		cin >> A >> B >> X;
		A--, B--;
		E.pb({X,A,B});
		Eli[A].pb({ B,X });
		Eli[B].pb({ A,X });
	}
	sort(all(E));


	queue<vector<ll>>q;
	for (int i = 0; i < M; i++) {
		ll X = E[i][0];
		int A = E[i][1];
		int B = E[i][2];
		mpE[{min(A, B), max(A, B)}] = i;
		ll S;
		while (q.size() && q.front()[0] < X) {
			S = un.getsize(q.front()[1]);
			fl[q.front()[3]] = (S >= q.front()[0]);
			q.pop();
		}
		un.unite(A, B);
		q.push({X,A,B,i});
	}

	while (q.size()) {
		ll S = un.getsize(q.front()[1]);
		fl[q.front()[3]] = (S >= q.front()[0]);
