template <typename T> vector<T> table(int n, T v) { return vector<T>(n, v); }

template <class... Args> auto table(int n, Args... args) {
  auto val = table(args...);
  return vector<decltype(val)>(n, move(val));
}

void solve(long long N, long long M, std::vector<long long> X,
           std::vector<long long> A, std::vector<long long> B,
           std::vector<long long> Y) {
  vector<tuple<int,int,int>> edge;
  edge.reserve(M);
  REP(i,M) edge.emplace_back(Y[i], A[i] - 1, B[i] - 1);
  sort(ALL(edge));

  vector<int> cnt(N);
  UnionFind uf(N);
  REP(i,M) {
    int cost, s, t;
    tie(cost, s, t) = edge[i];
    s = uf.root(s);
    t = uf.root(t);
    if (s == t) {
      if (cost > X[s]) cnt[s] += 1;
    }
    else {
      uf.unite(s, t);
      int v = uf.root(s);
      X[v] = X[s] + X[t];
      if (cost <= X[v]) {
        cnt[v] = 0;
      }
      else {
        cnt[v] = cnt[s] + cnt[t] + 1;
      }
    }
  }
  cout << cnt[uf.root(0)] << endl;
}

