    uftree(){
    }
    void init(int n){
        for(int i=0;i<n;i++){
            par[i]=i;
            rank[i]=0;
            maxi[i]=0;
            sum[i]=0;
            ng[i]=0;
        }
    }
    int find(int x){
        if(par[x]==x)return x;
        return par[x]=find(par[x]);
    }

    void add(int x,ll c){
        maxi[x]=max(maxi[x],c);
        if(ng[x]==0 && maxi[x]>sum[x]){
            ngsum++;
            ng[x]=1;
        }
        if(ng[x]==0 && c<=sum[x]){
            pl++;
        }
    }

    void unite(int x,int y,ll cost=-1){
        x=find(x);
        y=find(y);
        if(x==y)return;
        if(ng[x]==1 && ng[y]==1){
            ngsum--;
        }
        if(rank[x]<rank[y]){
            par[x]=y;
            sum[y]+=sum[x];
            maxi[y]=max(maxi[y],maxi[x]);
            ng[y]=max(ng[y],ng[x]);
            maxi[y]=max(cost,maxi[y]);
            if(ng[y]==0 && maxi[y]>sum[y]){
