            }
            if(ng[y]==1 && maxi[y]<=sum[y]){
                ng[y]=0;
                ngsum--;
            }
        }else{
            if(rank[x]==rank[y])rank[x]++;
            par[y]=x;
            sum[x]+=sum[y];
            maxi[x]=max(maxi[x],maxi[y]);
            ng[x]=max(ng[x],ng[y]);
            maxi[x]=max(cost,maxi[x]);
            if(ng[x]==0 && maxi[x]>sum[x]){
                ng[x]=1;
                ngsum++;
            }
            if(ng[x]==1 && maxi[x]<=sum[x]){
                ng[x]=0;
                ngsum--;
            }
        }
    }

    bool same(int x,int y){
