i64 n, m;

i64 a[MAXN];
i64 vs[MAXN];
i64 vm[MAXN];
bool pr[MAXN];

//pair<i64, pair<i64, i64>> e[MAXN];

map < i64, vector<pair<i64, i64>>> e;

inline void mem(set<i64>& ch, set<i64>& ppr, set<i64>& cpr, i64 t) {
    if (ch.find(t) != ch.end()) {
        return;
    }
    ch.insert(t);
    if (cpr.find(t) != cpr.end()) {
        ppr.insert(t);
    }
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0); cout.precision(15); cout.setf(ios::fixed);

    cin >> n >> m;

    for (i64 i = 1; i <= n; i++) {
        cin >> a[i];
    }

    for (i64 i = 0; i < m; i++) {
        i64 u, w, y;
        cin >> u >> w >> y;

        e[y].push_back({u, w});
    }


    for (i64 i = 1; i <= n; i++) {
        make_set(i);
    }

    for (i64 i = 1; i <= n; i++) {
        vs[i] = a[i];
        vm[i] = 0;
    }

    i64 R = 0;
    i64 cr = 0;
    set<i64> cpr;
    for (auto it = e.begin(); it != e.end(); it++) {
        map<i64, vector<i64>> h;
        set<i64> ch;
        set<i64> ppr;

        for (auto w : it->second) {
            i64 t1 = find_set(w.first);
            i64 t2 = find_set(w.second);
            if (t1 != t2) {
                i64 t = union_sets(w.first, w.second);
                h[t == t1 ? t1 : t2].push_back(t == t1 ? t2 : t1);

                vs[t] = vs[t1] + vs[t2];
                vm[t] = it->first;
                if (pr[t1]) {
                    mem(ch, ppr, cpr, t1);
                    cpr.erase(t1);
                }
                pr[t1] = 0;
                if (pr[t2]) {
                    mem(ch, ppr, cpr, t2);
                    cpr.erase(t2);
                }
                pr[t2] = 0;

                pr[t] = vs[t] < vm[t];
                if (pr[t]) {
                    mem(ch, ppr, cpr, t);
                    cpr.insert(t);
                }
            }
            else {
                if (pr[t1]) {
                    mem(ch, ppr, cpr, t1);
                    cpr.erase(t1);
                }
                vm[t1] = it->first;
                pr[t1] = vs[t1] < vm[t1];
                if (pr[t1]) {
                    mem(ch, ppr, cpr, t1);
                    cpr.insert(t1);
                }
            }
        }

        set<i64> npr;
        for (auto c : ch) {
            if (ppr.find(c) == ppr.end() && cpr.find(c) != cpr.end()) {
                npr.insert(c);
            }
        }

        if (npr.size() > 0 && cpr.size() == npr.size()) {
            set<i64> all;
            queue<i64> q;
            for (auto c : npr) {
                q.push(c);
            }

            for (;;) {
                if (q.empty()) {
                    break;
                }
                i64 c = q.front();
                q.pop();
                all.insert(c);

                for (auto e : h[c]) {
                    q.push(e);
                }
            }

            bool f = false;
            for (auto c : all) {
                if (ppr.find(c) != ppr.end()) {
                    f = true;
                    break;
                }
            }

            if (!f) {
                i64 rst = 0;
                for (auto w : it->second) {
                    if (all.find(w.first) != all.end() || all.find(w.second) != all.end()) {
                        rst++;
                    }
                }

                R = cr + it->second.size() - rst;
            }
        }

        cr += it->second.size();
        if (cpr.size() == 0) {
            R = cr;
        }
    }

    cout << m - R;

    return 0;
}

