typedef long long ll;

struct Treap {
    Treap *lc,*rc,*fa;
    ll pri,key,val,sum;
    Treap(ll _key,ll _val):lc(NULL),rc(NULL),fa(NULL),pri(rand()),key(_key),val(_val),sum(_val){}
};

ll Sum(Treap* t) {
    return t?t->sum:0;
}

void pull(Treap* t) {
    if (!t) return;
    t->sum = Sum(t->lc) + Sum(t->rc) + t->val;
    t->fa = NULL;
    if (t->lc) {
        t->lc->fa = t;
    }
    if (t->rc) {
        t->rc->fa = t;
    }
}

Treap* merge(Treap* a,Treap* b) {
    if (!a || !b) return a?a:b;
    else if (a->pri > b->pri) {
        a->rc = merge(a->rc,b);
        pull(a);
        return a;
    }
    else {
        b->lc = merge(a,b->lc);
        pull(b);
        return b;
    }
}

void split(Treap* t,int k,Treap* &a,Treap* &b) {
    if (!t) a=b=NULL;
    else if (t->key <= k) {
        a=t;
        split(t->rc,k,a->rc,b);
        pull(a);
    }
    else {
        b=t;
        split(t->lc,k,a,b->lc);
        pull(b);
    }
}

const int N = 200006;
