struct Edge {
    ll a,b,c;
    bool on_mst;
    Edge(ll _a,ll _b,ll _c):a(_a),b(_b),c(_c),on_mst(false){}
};

bool operator<(const Edge &e1,const Edge &e2) {
    return e1.c < e2.c;
}

vector<int> G[N];

struct DJS {
    static const int N = 200006;
    int p[N];
    void init() {
        for (int i=0;i<N;++i) {
            p[i] = i;
        }
    }
    int Find(int x) {
        return p[x] == x?x:p[x] = Find(p[x]);
    }
    void Union(int x,int y) {
        p[ Find(x) ] = Find(y);
    }
} djs;

int pin[N],pout[N];
int rev[2*N];
int stamp=0;

void dfs(int now,int par) {
    ++stamp;
    pin[now] = stamp;
    rev[stamp] = now;
    for (int i:G[now]) {
        if (i == par) continue;
        dfs(i,now);
    }
    ++stamp;
    pout[now] = stamp;
    rev[stamp] = now;
}

Treap* p[2*N];
bool okay[2*N];

bool is_anc(int par,int son) {
    return pin[par] <= pin[son] && pout[son] <= pout[par];
}

Treap* find_root(Treap* t) {
    while (t->fa != NULL) t = t->fa;
    return t;
}

void set_okay(Treap* t) {
    if (!t) return;
    okay[rev[t->key]] = true;
    set_okay(t->lc);
    set_okay(t->rc);
}

