struct D {
  int t;
  int d;
  ll s;
  D() {}
  D(int t, int d, ll s) : t(t), d(d), s(s) {}
};
bool operator<(const D& d1, const D& d2) {
  return d1.t < d2.t;
}

struct UF {
  vector<vector<D> > data;
  int nDistinct;
  UF() {}
  UF(int n) {
    data = vector<vector<D> >(n, vector<D>(1, D(-1, -1, 0)));
    REP(i, n) {
      data[i][0].s = xs[i];
    }
  }
  // void init(int n) { data.assign(n, -1); nDistinct = n; }
  // int size(void) const { return nDistinct; }
  // int count(int a) { return -data[rootOf(a)]; }
  // bool isSameGroup(int a, int b) { return rootOf(a) == rootOf(b); }
  int rootOf(int a) {
    D d = data[a].back();
    return d.d >= 0 ? rootOf(d.d) : a;
  }
  D rootD(int a, int t) {
    auto it = lower_bound(data[a].begin(), data[a].end(), D(t, -1, -1));
    --it;
    return it->d >= 0 ? rootD(it->d, t) : *it;
  }
  ll vsum(int a, int t) {
    return rootD(a, t).s;
  }
  bool unify(int a, int b, int t) {
    int ra = rootOf(a), rb = rootOf(b);
    if(ra == rb) return false;
    if(data[ra].back().d < data[ra].back().d) swap(ra, rb);
    data[rb].push_back(D(t, data[rb].back().d + data[ra].back().d, data[rb].back().s + data[ra].back().s));
    data[ra].push_back(D(t, rb, data[rb].back().s + data[ra].back().s));
    --nDistinct;
    return true;
  }
};


