class UnionFind {

	vector<int> unions, talls,sizes;
	int size;
public:
	UnionFind() {}
	UnionFind(int size) :size(size) {
		init();
	}
	void init() {
		unions = vector<int>(size);
		talls = vector<int>(size);
		sizes = vector<int>(size);
		FOR(i, 0, size) {
			unions[i] = i;
			sizes[i] = 0;
			talls[i] = 1;
		}
	}
	int find(int x) {
		if (unions[x] == x ) return x;
		return find(unions[x]);
	}
	bool isFriend(int a, int b) {
		return find(a) == find(b);
	}
	void unite(int a, int b, LL y) {
		a = find(a);
		b = find(b);
		if (talls[a] < talls[b]) unite(b, a, y);
		if (isFriend(a, b)) {
			sizes[a] += 1;
		}
		else {
			sizes[a] += sizes[b] + 1;
			X[a] += X[b];
			talls[a] = max(talls[a], talls[b] + 1);
			unions[b] = a;
		}
		if (y <= X[a]) {
			anses += sizes[a];
			sizes[a] = 0;
		}
	}
};
