    for(int i=1;i<=n;i++){
        scanf("%d",&cnt[i]);
        ///
        parent[i] = i;
        sum[i] = cnt[i];
        sz[i] = 1;
    }
    for(int i=1;i<=m;i++){
        scanf("%d%d%d",&a[i],&b[i],&c[i]);
        p[i] = make_pair(c[i] , i);
    }
    sort(p + 1 , p + m + 1);
    int ind = -1;
    vector <int> mas;
    for(int i=1;i<=m;i++){
        int id = p[i].second;
        int aa = a[id] , bb = b[id];
        if(findher(aa) != findher(bb)){
            tmerge(aa , bb);
        }
        int P = findher(aa);
        ++edge[P];
        if(sum[P] >= 1ll * c[id]){
            mark[i] = true;
            mas.push_back(i);
            ind = i;
        }
    }
    if(ind == -1){
        cout<<m<<endl;
        return 0;
    }
    int ina = 0 , inb = (int)mas.size() - 1;
    while(ina < inb){
        int mid = (ina + inb) / 2;
        if(f(mas[mid]) <= f(mas[mid + 1]))
            ina = mid + 1;
        else
            inb = mid;
    }
    cout<<m - f(mas[ina])<<endl;
    return 0;
}

