struct UnionFind {
	std::vector<int> par;
	std::vector<int> sizes;
	void init(int n) {
		par.resize(n);
		sizes.resize(n);
		for (int i = 0; i < n; ++i) {
			par[i] = i;
			sizes[i] = 1;
		}
	}

	int root(int a) {
		return par[a] == a ? a : par[a] = root(par[a]);
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y)return;
		if (sizes[x] < sizes[y]) std::swap(x, y);

		par[y] = x;
		sizes[x] += sizes[y];
	}
	int size(int x) {
		return sizes[root(x)];
	}
};

struct Edge { ll from, to, cost; };

bool comp(Edge &a, Edge &b) {
	return a.cost < b.cost;
}
vi v;
UnionFind uf;
int solve(vector<int> &vs, vector<Edge> &es) {
	ll sum = 0;
	REP(i, vs.size())sum += v[vs[i]];
	ll m = 0;
	REP(i, es.size())chmax(m, es[i].cost);
	if (sum >= m)return 0;
	int ret = 0;
	while (!es.empty() && es.back().cost > sum) {
		es.pop_back();
		ret++;
	}
	REP(i, vs.size()) {
		uf.par[vs[i]] = vs[i];
		uf.sizes[vs[i]] = 1;
	}
	REP(i, es.size()) {
		uf.unite(es[i].from, es[i].to);
	}
	set<int> st;
	REP(i, vs.size())st.insert(uf.root(vs[i]));
	map<int, vector<int>> mpv;
	map<int, vector<Edge>> mpe;
	REP(i, vs.size()) {
		mpv[uf.root(vs[i])].push_back(vs[i]);
	}
	REP(i, es.size()) {
		mpe[uf.root(es[i].from)].push_back(es[i]);
	}

	for (auto a : st) {
		ret += solve(mpv[a], mpe[a]);
	}
	return ret;

}
