ll find(ll x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}
void unite(ll x, ll y){
	x = find(x);
	y = find(y);
	if(x==y)return;
	if(rankk[x]<rankk[y]){
		par[x]=y;
		siz[y] = siz[x] + siz[y];
	}else{
		par[y]=x;
		siz[x] = siz[x] + siz[y];
		if(rankk[x]==rankk[y])rankk[x]++;
	}
}
