struct UF{
  int par[MAX];
  int ran[MAX];
  int val[MAX];
  ll dat[MAX];
  vector< int > G[MAX];
  vector< int > g[MAX];
  vector< ll > h[MAX];
  int t[MAX],u[MAX];
  void init(){
    for(int i=0;i<MAX;i++){
      par[i]=i;
      ran[i]=1;
      val[i]=-1;
      dat[i]=0;
      t[i]=u[i]=-1;
      G[i].push_back(0);
      g[i].push_back(1);
      h[i].push_back(-1);
    }
  }

  int find(int x){
    if(par[x]==x)return x;
    else return par[x]=find(par[x]);
  }

  void unite(int x,int y,int z=-1){
    x=find(x);y=find(y);
    if(x==y)return;
    if( ran[x] > ran[y] )swap(x,y);
    par[x]=y;
    t[x]=y;
    u[x]=z;
    G[y].push_back(z);
    g[y].push_back(ran[y]+ran[x]);
    h[y].push_back(dat[y]+dat[x]);
    ran[y]+=ran[x];
    dat[y]+=dat[x];
    val[y]=z;
  }

  bool same(int a,int b){
    return (find(a)==find(b));
  }

  int calc(vector<int> &V,vector<int> &v,int mid){
    vector<int> :: iterator it;
    it = upper_bound( V.begin(),V.end(),mid);
    if(it==V.begin())return 0;
    it--;
    int id= it-V.begin();
    return v[id];
  }
  ll calc(vector<int> &V,vector<ll> &v,int mid){
    vector<int> :: iterator it;
    it = upper_bound( V.begin(),V.end(),mid);
    if(it==V.begin())return 0;
    it--;
    int id= it-V.begin();
    return v[id];
  }
  int funcSize(int x,int mid){
    while( t[x]!=-1 && u[x] <= mid )x=t[x];
    return calc(G[x],g[x],mid);
  }
  ll funcDat(int x,int mid){
    while( t[x]!=-1 && u[x] <= mid )x=t[x];
    /*
    for(auto p:G[x])cout<<p<<' ';
    cout<<endl;
    for(auto p:h[x])cout<<p<<' ';
    cout<<endl;
    */
    return calc(G[x],h[x],mid);
  }

};

