typedef ll val_t;

struct graph_t {
	int n;           // |V|, index begins with 0
	int m;           // |E|
	vector<P> edges; // E
	vector<val_t> vals; // V
	vector<ll> costs; // cost or distance
	vector<ll> caps;  // capacity
};

class Prim {
private:
	// note: eid of dual_edge is negative
	struct node {
		int id; bool done; vi to_eid; vi to; vll costs; int from_eid; int from; ll d;
	};
	struct pq_t {
		int id; ll d;
		bool operator<(const pq_t & another) const {
			return d != another.d ? d > another.d : id > another.id;
		}
	};
	vector<node> nodes;
	int n, m, root;
public:
	Prim(graph_t G, int start) {
		n = G.n;
		m = G.edges.size();
		nodes.resize(n);
		Loop(i, n) nodes[i] = { i, false,{},{},{}, -1, -1, LLONG_MAX };
		Loop(i, m) {
			nodes[G.edges[i].first].to_eid.push_back(i);
			nodes[G.edges[i].first].to.push_back(G.edges[i].second);
			nodes[G.edges[i].first].costs.push_back(G.costs[i]);
			nodes[G.edges[i].second].to_eid.push_back(i - m);
			nodes[G.edges[i].second].to.push_back(G.edges[i].first);
			nodes[G.edges[i].second].costs.push_back(G.costs[i]);
		}
		root = start;
		nodes[root].d = 0;
		priority_queue<pq_t> pq;
		pq.push({ nodes[root].id, nodes[root].d });
		while (pq.size()) {
			node *a = &nodes[pq.top().id];
			pq.pop();
			if (nodes[a->id].done) continue;
			nodes[a->id].done = true;
			Loop(j, a->to.size()) {
				node *b = &nodes[a->to[j]];
				if (b->done) continue;
				ll buf = a->costs[j];
				if (buf < b->d) {
					b->d = buf;
					b->from_eid = a->to_eid[j];
					b->from = a->id;
					pq.push({ b->id, b->d });
				}
			}
		}
		return;
	}
	vector<P> get_tree_idpair() {
		vector<P> ret;
		Loop(i, n) {
			if (i != root) ret.push_back({ nodes[i].from, i });
		}
		return ret;
	}
	// here negative eid will transformed to non-negative eid
	vi get_tree_eid() {
		vi ret;
		Loop(i, n) {
			if (i != root) {
				ret.push_back(nodes[i].from_eid);
				if (ret.back() < 0) ret.back() += m;
			}
		}
		return ret;
	}
	ll get_weight() {
		ll ret = 0;
		Loop(i, n) {
			if (i != root) ret += nodes[i].d;
		}
		return ret;
	}
};

typedef ll nodeval_t;
typedef ll edgeval_t;

struct tree_t {
	int n;           // |V|, index begins with 0
	vector<P> edges; // E
	vector<nodeval_t> vals; // value of nodes
	vector<edgeval_t> costs; // cost, distance, or weight of edges
};

class Tree {
private:
	struct node {
		int id; vi childs; int parent = -1;
		int deg = -1; // the number of edges of the path to the root
		int eid = -1; // edge id of the edge connected by its parent and itself
		int subtree_n = 1; // the number of nodes of the partial tree rooted by itself
		nodeval_t val; // value of the node itself
		edgeval_t cost; // cost of the edge connected by its parent and itself
		bool operator<(const node & another) const {
			return deg != another.deg ? deg < another.deg : id < another.id;
		}
	};
	struct edgeinfo {
		int eid; int to; edgeval_t cost;
	};
	int n;
	static const nodeval_t init_val = 0;
	static const edgeval_t init_cost = 1;
	vector<vector<edgeinfo>> edges;
	void tree_construction() {
		leaves = {};
		queue<int> que;
		que.push(root);
		while (que.size()) {
			int a = que.front(); que.pop();
			deg_order.push_back(a);
			if (a == Tree::root) nodes[a].deg = 0;
			int leaf_flag = true;
			Loop(i, edges[a].size()) {
				int b = edges[a][i].to;
				if (nodes[b].deg != -1) {
					nodes[a].parent = b;
					nodes[a].eid = edges[a][i].eid;
					nodes[a].cost = edges[a][i].cost;
					nodes[a].deg = nodes[b].deg + 1;
				}
				else {
					leaf_flag = false;
					nodes[a].childs.push_back(b);
					que.push(b);
				}
			}
			if (leaf_flag) leaves.push_back(a);
		}
		Loopr(i, n) {
			int a = deg_order[i];
			Loop(j, nodes[a].childs.size()) {
				int b = nodes[a].childs[j];
				nodes[a].subtree_n += nodes[b].subtree_n;
			}
		}
	}
public:
	vector<node> nodes;
	vi deg_order; // node ids, sorted by deg
	vi leaves;
	int root;
	// T should be non-empty tree
	Tree(tree_t T, int root) {
		n = T.n;
		nodes.resize(n);
		Loop(i, n) {
			nodes[i].id = i;
			nodes[i].val = (int)(T.vals.size()) > i ? T.vals[i] : init_val;
			nodes[i].cost = init_cost;
		}
		edges.resize(n);
		Loop(i, n - 1) {
			edges[T.edges[i].first].push_back({ i, T.edges[i].second, ((int)(T.costs.size()) > i ? T.costs[i] : init_cost) });
			edges[T.edges[i].second].push_back({ i, T.edges[i].first, ((int)(T.costs.size()) > i ? T.costs[i] : init_cost) });
		}
		Tree::root = root;
		tree_construction();
		return;
	}
	ll get_sum(int a, int from) {
		ll ret = nodes[a].val;
		if (nodes[a].cost != -1 && a != root && nodes[a].parent != from) ret += get_sum(nodes[a].parent, a);
		Foreach(b, nodes[a].childs) {
			if (nodes[b].cost != -1 && b != from) ret += get_sum(b, a);
		}
		return ret;
	}
	void get_cc(int a, int from, vi &ret) {
		ret.push_back(a);
		if (nodes[a].cost != -1 && a != root && nodes[a].parent != from) get_cc(nodes[a].parent, a, ret);
		Foreach(b, nodes[a].childs) {
			if (nodes[b].cost != -1 && b != from) get_cc(b, a, ret);
		}
	}
	vector<pair<int, ll>> solve() {
		ll buf = get_sum(0, -1);
		vll sum(n, buf);
		vector<pair<ll, int>> w_costs;
		Loop(i, n) {
			if (i == root) continue;
			else w_costs.push_back({ nodes[i].cost, i });
		}
		sort(w_costs.begin(), w_costs.end());
		Loopr(i, w_costs.size()) {
			ll c = w_costs[i].first;
			ll a = w_costs[i].second;
			int b = nodes[a].parent;
			if (c <= sum[a]) continue;
			else {
				nodes[a].cost = -1;
				ll buf0 = get_sum(a, b), buf1 = get_sum(b, a);
				vi nbuf0, nbuf1;
				get_cc(a, b, nbuf0);
				get_cc(a, b, nbuf1);
				Loop(j, nbuf0.size()) sum[nbuf0[j]] = buf0;
				Loop(j, nbuf1.size()) sum[nbuf1[j]] = buf1;
			}
		}
		vector<pair<int, ll>> ret(n);
		vector<bool> done(n, false);
		int cnt = 0;
		Loop(i, n) {
			if (done[i]) continue;
			cnt++;
			ll buf0 = get_sum(i, -1);
			vi nbuf; get_cc(i, -1, nbuf);
			Loop(j, nbuf.size()) {
				done[nbuf[j]] = true;
				ret[nbuf[j]] = { cnt, buf0 };
			}
		}
		return ret;
	}
};

