struct UF {
    int N;
    vector<int> par;
    vector<int> rank;

    UF(int n) : N(n), par(N), rank(N,0) {
        rep(i,N) {par[i] = i;}
    }

    int root(int x) {
        if (par[x] == x) return x;
        else {
            int r = root(par[x]); //根まで遡りながら経路圧縮
            return par[x] = r;
        }
    }
    bool issame(int x, int y) {
        return root(x) == root(y);
    }
    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x; //ランクの小さい方に接続
        node[x]+=node[y];
        return true;
    }
};

