/*
任意のグラフの辺最大値が
グラフ内頂点の和をこえている場合
その辺を取り除く
その辺が橋だった場合、両端のグラフについて再計算
端でなかった場合、辺最大値を更新
*/

int N, M;
int X[100010];
vector<int>path[100010];
vector<IP>edge;
map<P, int>dame;

int removed = 0;

int main(){

    cin >> N >> M;
    for(int i=1;i<=N;i++)cin >> X[i];
    for(int i=1;i<=M;i++){
        int a, b, y;
        cin >> a >> b >> y;
        path[a].push_back(b);
        path[b].push_back(a);
        edge.push_back(IP(y, P(a, b)));
    }
    sort(edge.begin(), edge.end());
    reverse(edge.begin(), edge.end());
    for(int i=0;i<edge.size();i++){
        int line = edge[i].first;
        int a = edge[i].second.first;
        int b = edge[i].second.second;

        //cout <<"line : "<< line <<" -> "<<a<<" - "<<b<<", ";

        vector<int>flg(N+1, 0);
        int sum = 0;
        queue<int>Q;

        Q.push(a);
        flg[a] = 1;
        while(!Q.empty()){
            int id = Q.front();
            Q.pop();
            sum += X[id];
            for(int j=0;j<path[id].size(); j++){
                int nxt = path[id][j];
                if(dame[P(id, nxt)])continue;
                if(flg[nxt]==0){
                    flg[nxt]=1;
                    Q.push(nxt);
                }
            }
        }
        //cout << "sum : "<<sum <<" ";
        if(sum < line){
            //cout <<"X";
            removed++;
            dame[P(a, b)]=1;
            dame[P(b, a)]=1;
        }
        //cout << endl;
    }
    cout <<removed << endl;

    return 0;
}

