            int papa = find(a);
            if(sum[papa] >= y){
                ok[papa]++;
                tmp++;
                ans = max(ans,tmp);
            }else{
                ng[papa]++;
            }
        }else{
            int papa = find(a);
            int mama = find(b);
            if(sum[papa] + sum[mama] >= y){
                tmp += ng[papa] + ng[mama] + 1;
