inline void Pushdown(int x) {
	if (r[x]) {
		if (lc(x)) Reverse(lc(x));
		if (rc(x)) Reverse(rc(x));
		r[x] = 0;
	}
}
inline void Rotate(int x) {
	int f = fa[x], g = fa[f], c = rc(f) == x;
	if (!Isroot(f)) child[g][rc(g) == f] = x;
	child[f][c] = child[x][!c];
	child[x][!c] = f;
	if (child[f][c]) fa[child[f][c]] = f;
	fa[x] = g;
	fa[f] = x;
	Update(f);
}
inline void Splay(int x) {
	int y = x; top = 0;
	stk[++top] = y;
	while (!Isroot(y)) stk[++top] = y = fa[y];
	while (top) Pushdown(stk[top--]);
	while (!Isroot(x)) {
		y = fa[x];
		if (!Isroot(y))
			Rotate((lc(y) == x) == (lc(fa[y]) == y) ? y : x);
		Rotate(x);
	}
	Update(x);
}
inline void Access(int x) {
	for (RI y = 0; x; y = x, x = fa[x])
		Splay(x), Esize[x] += Rsize[rc(x)], Esize[x] -= Rsize[y], rc(x) = y, Update(x);
}
inline void Makeroot(int x) {
	Access(x), Splay(x), Reverse(x);
}
inline bool Unicom(int x, int y) {
	Makeroot(x), Access(y), Splay(y);
	int k = y;
	while (lc(k)) k = lc(k);
	return k == x;
}
inline void Link(int x, int y) {
	Makeroot(x), Splay(x);
	fa[x] = y, Esize[y] += Rsize[x];
}
inline void Cut(int x, int y) {
	Makeroot(x), Access(y), Splay(y);
	lc(y) = fa[x] = 0;
	Update(y);
}

int main() {
	//freopen("bridge.in", "r", stdin);
	//freopen("bridge.out", "w", stdout);
	int n, m, ans = 0; read(n), read(m);
	for (RI i = 1; i <= n; ++i) read(a[i]);
	for (RI i = 1; i <= m; ++i)
		read(e[i].x), read(e[i].y), read(e[i].val);
	sort(e + 1, e + 1 + m, cmp);
	for (RI i = 1; i <= m; ++i) {
		if (Unicom(e[i].x, e[i].y)) continue;
		Link(e[i].x, e[i].y), vis[i] = 1;
	}
	for (RI i = m; i; --i)
		if (vis[i]) {
			Makeroot(e[i].x), Splay(e[i].x);
			if (Rsize[e[i].x] < e[i].val) Cut(e[i].x, e[i].y);
		}
	for (RI i = 1; i <= m; ++i)
		if (!Unicom(e[i].x, e[i].y)) ++ans;
		else {
			Makeroot(e[i].x), Splay(e[i].x);
			if (Rsize[e[i].x] < e[i].val) ++ans;
		}
	printf("%d\n", ans);
	return 0;
}

