vector<bool> used2(100005);
vector<ll> x(100005), y(100005);
priority_queue<P> que;
ll sum;
vector<int> usedp;

void dfs(int s) {
  used[s] = true;
  usedp.push_back(s);
  //debug(s);  debugln(x[s]);
  sum += x[s];
  for(auto e: graph[s]) {
    int i = e.second;
    if (!removed[i]) {
      que.emplace(y[e.second], i);
      if (!used[e.first]) {
        dfs(e.first);
      }
    }
  }
}

void clearused() {
  for(auto e: usedp) {
    used[e] = false;
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, m; cin >> n >> m;
