  }
  rep(i, m) {
    int a, b; cin >> a >> b;
    graph[a].emplace_back(b, i);
    graph[b].emplace_back(a, i);
    cin >> y[i];
  }

  for(int i=1; i<=n; i++) {
    //debugln(i);
    if (used2[i]) continue;
    while(true) {
      sum = 0;
      clearused();
      usedp.resize(0);
      dfs(i);
      //debugln(sum);
      bool flag = false;
      while(!que.empty()) {
        P p = que.top(); que.pop();
        if (p.first > sum) {
          removed[p.second] = true;
          //debugln(p.second);
          flag = true;
        } else {
          while(!que.empty()) {
            que.pop();
          }
        }
      }
      if (!flag) {
        for(auto e: usedp) {
          used2[e] = true;
        }
        break;
      }
    }
  }

  int ans = 0;
  for(int i=0; i<m; i++) {
    if (removed[i]) {
      ans++;
    }
  }

  cout << ans << endl;
}

