struct uf {
	vector<int> par, r;
	uf(int n) {
		par.resize(n); r.resize(n, 0);
		rep(i, n)par[i] = i;
	}
	int find(int x) {
		if (par[x] == x)return x;
		else return find(par[x]);
	}
	int unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y)return 0;
		if (r[x] < r[y]) {
			par[x] = y;
			return x;
		}
		else {
			par[y] = x;
			if (r[x] == r[y])r[x]++;
			return y;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};
