int n, m;
int X[100005];
queue<pair<int,pair<int, int>>> e;

//-----UnionFind--------
vector<int> par, rk, sumw;

void initUnion(int n)
{
	for (int i = 0;i < n;i++) {
		par.push_back(i);
		rk.push_back(1);
		sumw.push_back(X[i]);
	}
}

int root(int x) {
	if (par[x] == x) return x;
	return par[x] = root(par[x]);
}

void unite(int x, int y) {
	int rx = root(x);
	int ry = root(y);
	if (rx == ry) return;

	if (rk[ry] < rk[rx]) swap(rx, ry);
	rk[ry] += rk[rx];
	sumw[ry] += sumw[rx];
	par[rx] = ry;
}

bool same(int x, int y) {
	int rx = root(x);
	int ry = root(y);
	return rx == ry;
}
//-----UnionFind--------


int main()
{
	cin >> n >> m;
	for (int i = 0;i < n;i++) cin >> X[i];
	for (int i = 0;i < m;i++) {
		int u, v, w;
		cin >> u >> v >> w;
		u--;
		v--;
		e.push(make_pair(w, make_pair(u, v)));
	}

	while (1) {
		initUnion(n);
		int l = e.size();

		for (int i = 0;i < l;i++) {
			int w = e.front().first;
			int v = e.front().second.first;
			int u = e.front().second.second;

			if (!same(u, v)) { 
				int Ru = root(u);
				int Rv = root(v);
				unite(u, v);
			}
			e.push(e.front());
			e.pop();
		}

		for (int i = 0;i < l;i++) {
			int w = e.front().first;
			int v = e.front().second.first;
			int Root = root(v);
			if (sumw[Root] < w) {
				e.pop();
			}
			else {
				e.push(e.front());
				e.pop();
			}
		}

		if (l == e.size()) break;
	}

	cout << n - e.size() << endl;

	return 0;
}

