class UF {
 public:
  vector<LL> parent;
  vector<LL> val;
  int N;

 public:
  UF(int n) {
    N = n;
    parent.resize(N);
    val.resize(N);
    for (int i = 0; i < N; i++) {
      parent[i] = i;
    }
  }
  int find(int v) {
    if (v == parent[v]) return v;
    return parent[v] = find(parent[v]);
  }

  bool Union(int v, int u) {
    v = find(v);
    u = find(u);
    if (v == u) return false;

    parent[u] = v;
    return true;
  }
};

void solve(long long N, long long M, std::vector<long long> X,
           std::vector<long long> A, std::vector<long long> B,
           std::vector<long long> Y) {
  for (int i = 0; i < M; i++) {
    A[i]--;
    B[i]--;
  }
  UF ufPre(N);

  vector<int> parent(2 * N - 1, 0);
  vector<int> values(2 * N - 1, 0);
  vector<pair<LL, PII>> data;
  for (int i = 0; i < M; i++) {
    data.push_back(make_pair(Y[i], PII(A[i], B[i])));
  }
  vector<vector<int>> child(2 * N - 1);
  vector<int> usedVal(M, -1);
  vector<LL> tree(2 * N - 1, 0);
  for (int i = 0; i < N; i++) tree[i] = X[i];

  sort(data.begin(), data.end());
  int ind = N;
  for (int i = 0; i < N; i++) ufPre.val[i] = i;
  for (int i = 0; i < data.size(); i++) {
    auto elem = data[i];
    int v = elem.second.first;
    int u = elem.second.second;
    int tv = ufPre.val[ufPre.find(v)];
    int tu = ufPre.val[ufPre.find(u)];

    if (ufPre.Union(v, u)) {
      child[ind].push_back(tv);
      child[ind].push_back(tu);
      tree[ind] = tree[tv] + tree[tu];
      parent[tv] = ind;
      parent[tu] = ind;
      ufPre.val[ufPre.find(v)] = ind;
      usedVal[i] = ind;
      ind++;
    }
  }
  vector<int> treeUsed(2 * N - 1, 1);
  for (int i = M - 1; i >= 0; i--)
    if (usedVal[i] >= 0) {
      int ind = usedVal[i];
      if (ind != 2 * N - 2 && treeUsed[parent[ind]] != 0) continue;
      if (tree[ind] < data[i].first) {
        usedVal[i] = -2;
        treeUsed[ind] = 0;
      }
    }

  UF uf(N);
  int ans = 0;
  for (int i = 0; i < N; i++) uf.val[i] = X[i];
  vector<int> finalUsed(M, 0);
  for (int i = 0; i < M; i++) {
    auto elem = data[i];
    int v = elem.second.first;
    int u = elem.second.second;
    int pv = uf.find(v);
    int pu = uf.find(u);
    // cout << v << " " << u << " " << usedVal[i] << endl;
    if (usedVal[i] < 0) continue;
    if (uf.Union(v, u)) {
      finalUsed[i] = true;
      uf.val[pv] += uf.val[pu];
      // cout << "  " << pv << " " << pu << " " << uf.val[pv] << " " <<
      // uf.val[pu]
      ans++;
    }
  }
  for (int i = 0; i < M; i++) {
    auto elem = data[i];
    int v = elem.second.first;
    int u = elem.second.second;
    if (usedVal[i] != -1) continue;
    LL cost = elem.first;
    // cout << v << " " << u << " " << cost << endl;
    if (cost <= uf.val[uf.find(v)]) ans++;
  }
  /*
  dump(parent);
  dump(uf.val);
  dump(tree);
  */
  cout << M - ans << endl;
}
int main() {
  long long N;
  scanf("%lld", &N);
  long long M;
  scanf("%lld", &M);
  std::vector<long long> X(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &X[i]);
  }
  std::vector<long long> A(M);
  std::vector<long long> B(M);
  std::vector<long long> Y(M);
  for (int i = 0; i < M; i++) {
    scanf("%lld", &A[i]);
    scanf("%lld", &B[i]);
    scanf("%lld", &Y[i]);
  }
  solve(N, M, std::move(X), std::move(A), std::move(B), std::move(Y));
  return 0;
}

