struct node{
    node *L = 0, *R = 0, *P = 0;
    lld data, lt;
    node(int x){ data = lt = x; }
    inline void up(){
        lt = data;
        if(L)lt += L->lt;
        if(R)lt += R->lt;
    }
    node*& child(node *x){ return x==L?L:R; }
    void rotateR(){
        node *r = R;
        if(P)P->child(this) = r;
        r->P = P;
        R = r->L;
        if(R)R->P = this;
        r->L = this;
        P = r;
        up();
        r->up();
    }
    void rotateL(){
        node *l = L;
        if(P)P->child(this) = l;
        l->P = P;
        L = l->R;
        if(L)L->P = this;
        l->R = this;
        P = l;
        up();
        l->up();
    }
    inline void rotate(){ P->L==this?P->rotateL():P->rotateR(); }
    node* splay(){
        while(P){
            if(P->P) ((P->L==this)^(P->P->L==P)?this:P)->rotate();
            this->rotate();
        }
        return this;
    }
    node* getR(){
        node *x = this;
        while(x->L)x = x->L;
        return x -> splay();
    }
    node* mergeL(node *x){
        node *y = getR();
        if(!x)return y;
        y->L = x;
        x->P = y;
        y->up();
        return y;
    }
    void cut(){
        splay();
        if(L)L->P = NULL;
        if(R)R->P = NULL;
    }
    void print(string s = ""){
        if(L)L->print(s+" ");
        cout << s << data << endl;
        if(R)R->print(s+" ");
    }
};
