class unionfind {
public:
	vector<int> par;
	vector<ll> sum;
	vector<int> cand;

	void init(int n, vector<ll> X) {
		par.resize(n);
		sum.resize(n);
		cand.resize(n);

		for (int i = 0; i < n; i++) {
			par[i] = i;
			sum[i] = X[i];
			cand[i] = 0;
		}
	}

	int find(int x) {
		if (par[x] == x) return x;
		else {
			int p = find(par[x]);
			if (par[x] != p) {
				cand[p] += cand[par[x]];
				sum[p] += sum[par[x]];
			}
			return par[x] = p;
		}
	}

	bool unite(int x, int y) {
		x = find(x);
		y = find(y);

		if (x == y) return true;
		cand[x] += cand[y];
		sum[x] += sum[y];
		par[y] = x; 
		cand[y] = 0; sum[y] = 0;
	}

	bool same(int x, int y) { return (find(x) == find(y)); }
} uf;

