const int N = 1e5 + 5;

int p[N], sum[N], mx[N], edgeCount[N];
int bad;

int getRoot(int v) {
    return v == p[v] ? v : p[v] = getRoot(p[v]);
}

void unite(int v, int u, int weight) {
    v = getRoot(v), u = getRoot(u);
    if (v == u) {
        if (mx[v] > sum[v]) {
            bad -= edgeCount[v];
        }
        mx[v] = max(mx[v], weight);
        edgeCount[v]++;
        if (mx[v] > sum[v]) {
            bad += edgeCount[v];
        }
        return;
    }
    if (mx[v] > sum[v]) bad -= edgeCount[v];
    if (mx[u] > sum[u]) bad -= edgeCount[u];
    p[u] = v;
    sum[v] += sum[u];
    mx[v] = max({ mx[v], mx[u], weight });
    edgeCount[v] += edgeCount[u] + 1;
    if (mx[v] > sum[v]) {
        bad += edgeCount[v];
    }
}

