template<int um> class UF_pop {
	public:
	vector<int> par,rank; vector<int> tot;vector<vector<ll>> hist;
	UF_pop() {par=rank=vector<int>(um,0); tot=vector<int>(um,0); for(int i=0;i<um;i++) par[i]=i;}
	int operator[](int x) {return (par[x]==x)?(x):operator[](par[x]);}
	void pop() {
		if(hist.size()) {
			auto a=hist.back();
			hist.pop_back();
			par[a[0]]=a[1]; rank[a[0]]=a[2];
			par[a[3]]=a[4]; rank[a[3]]=a[5];
			tot[a[0]]=a[6]; tot[a[3]]=a[7];
		}
	}
	void operator()(int x,int y,int id) {
		x=operator[](x); y=operator[](y);
		hist.push_back({x,par[x],rank[x],y,par[y],rank[y],tot[x],tot[y],id});
		if(x==y) return;
		tot[x]=tot[y]=tot[x]+tot[y];
		if(rank[x]<rank[y]) par[x]=y;
		else rank[x]+=(rank[x]==rank[y]), par[y]=x;
	}
};
