class UnionFind
{
public:
    explicit UnionFind(int n) : data_(n, -1) {}

    int root(int i) {
        return (data_[i] >= 0) ? (data_[i] = root(data_[i])) : i;
    }

    bool unify(int i, int j) {
        i = root(i);
        j = root(j);
        if (i == j)
            return false;
        if (-data_[i] >= -data_[j]) {
            data_[i] += data_[j];
            data_[j] = i;
        } else {
            data_[j] += data_[i];
            data_[i] = j;
        }
        return true;
    }

private:
    vector<int> data_;
};

