                merges[last[a]].l = merges.size();
            if (last[b] >= 0)
                merges[last[b]].l = merges.size();
            last[uf.root(a)] = merges.size();
            merges.push_back({e[i], z[a], z[b], -1});
            z[uf.root(a)] = z[a] + z[b];
        }
    }

    for (int i = merges.size() - 1; i >= 0; i--) {
        auto& mg = merges[i];
        if (mg.l >= 0 && merges[mg.l].za > 0)
            continue;
        if (mg.e.y <= mg.za + mg.zb)
            continue;
        mg.za = mg.zb = 0;
    }

    UnionFind uf2(n);
    for (auto& mg : merges) {
        if (mg.za > 0) {
            uf2.unify(mg.e.a, mg.e.b);
        }
    }
    vector<int> w(n, 0);
    for (int i = 0; i < n; i++)
        w[uf2.root(i)] += x[i];
    int ans = 0;
    for (int i = 0; i < m; i++)
        if (e[i].y > w[uf2.root(e[i].a)]) ++ans;
    printf("%d\n", ans);
    return 0;
}

