        return w < b.w;
    }
};
vector<Edg> edg;
struct UnionFind {
    vector<int> par, rank;
    vector<ll> sum;
    UnionFind(int n)
        : par(n), sum(n), rank(n, 0) {
        iota(all(par), 0);
        rep(i, n) sum[i] = x[i];
    }
    void join(int x, int y) {
        x = root(x);
        y = root(y);
        if (rank[x] < rank[y])
            par[x] = y, sum[y] += sum[x];
        else
            par[y] = x, sum[x] += sum[y];
        if (rank[x] == rank[y]) rank[x]++;
    }
    int root(int x) { return par[x] != x ? root(par[x]) : x; }
};
int main() {
