vector<ii> eg[N];

int find(int u) { return (pr[u].fi == u) ? u : (pr[u].fi = find(pr[u].fi)); }

void addeg(int u, int v)    {
    int nu = find(u), nv = find(v);
    if(nu == nv) return;
    pr[nu].fi = nv;
    pr[nv].se += pr[nu].se;
}

bool cmp(const int x, const int y)  { return edge[x].cost < edge[y].cost; }
void findedge() {
    vector<int> tmp; FOR(i, 1, m) tmp.pb(i);
    sort(tmp.begin(), tmp.end(), cmp);

    for(auto it: tmp)   {
        int nu = find(edge[it].u), nv = find(edge[it].v);
        if(nu == nv) {
            if(pr[nu].se >= edge[it].cost) check[it] = 1;
        } else {
            if(pr[nu].se + pr[nv].se >= edge[it].cost) check[it] = 1;
            addeg(nu, nv);
        }
    }
}

void dfs(int u, int cost)   {
    visit[u] = 1;
    for(auto it: eg[u]) if(edge[it.se].cost <= cost)    {
        ans[it.se] = 1;
        if(!visit[it.fi]) dfs(it.fi, cost);
    }
}

void spread()   {
    vector<int> tmp; FOR(i, 1, m) if(check[i]) tmp.pb(i);
    sort(tmp.begin(), tmp.end(), cmp);

    for(int i = tmp.size() - 1ll; i >= 0ll; --i)    {
        int id = tmp[i];
        if(!visit[edge[id].u]) dfs(edge[id].u, edge[id].cost);
        if(!visit[edge[id].v]) dfs(edge[id].v, edge[id].cost);
    }

    int cnt = 0;
    FOR(i, 1, m) if(!ans[i]) cnt ++;
    cout << cnt;
}

