        A--; B--;
        edges[i] = make_tuple(Y, A, B);
    }
    sort(edges.begin(), edges.end());

    long long ans = 0;
    for(auto edge : edges){
        int A, B;
        long long Y;
        tie(Y, A, B) = edge;
        uf.unite(A, B);

        if(Y <= uf.get_sum(A)){
            ans += uf.get_cnt(A);
            uf.reset_cnt(A);
        }
    }
    cout << M - ans << endl;
    return 0;
}

