struct UF{
  std::vector<ll> par, dep, dat;
  vector<deque<ll>> pre;
  UF(int n){
    par.resize(n+1), dep.resize(n+1), dat.resize(n+1);
    pre.resize(n+1);
    init(n);
  }
  void init(int nu){for(int iu=0;iu<=nu;iu++) par[iu] = iu, dep[iu] = 0;}
  ll get(ll a){return dat[find(a)];}
  bool same(int xu, int yu){return find(xu) == find(yu);}
  ll find(int xu){return (par[xu]==xu?xu:find(par[xu]));}

  void unite(int xu, int yu){
    xu=find(xu), yu=find(yu);
    if(xu == yu) return;
    if(dep[xu] < dep[yu]){
      par[xu] = yu;
      dat[yu] += dat[xu];
      pre[yu].push_front(xu);
    }else{
      par[yu] = xu;
      dat[xu] += dat[yu];
      pre[xu].push_front(yu);
      if(dep[xu] == dep[yu]) dep[xu]++;
    }
  }

  void decompose(ll a){
    ll parent = find(a);
    ll t = pre[parent].front();pre[parent].pop_front();
    par[t] = t;
    dat[parent] -= dat[t];
  }
};

