    vector<int> rank;
public:
    union_find(int n){  //初期化
        this->n=n;
        par = vector<int>(n,0);
        rep(i,n){
            par[i]=i;
        }
        rank = vector<int>(n,0);
    }
    int find(int x){    //親
        if(par[x]==x){
            return x;
        }else{
            par[x]=find(par[x]);
            return par[x];
        }
    }
    void unite(int x,int y){    //結合
        x=find(x);
        y=find(y);
        if(x==y){return;}
        if(rank[x]<rank[y]){
            par[x]=y;
        }else{
            par[y]=x;
            if(rank[x]==rank[y])rank[x]++;
        }
    }
    bool same(int x,int y){     //同じグループか判定
        return find(x)==find(y);
    }
};



