struct unionfind{
    vector<int> parent;
    vector<int> rank;
    vector<ll> size;

    unionfind (int N) {
        parent = vector<int>(N);
        iota(parent.begin(), parent.end(), 0);
        rank = vector<int>(N, 0);
        size = vector<ll>(N, 1);
    }
    int root(int x) {
        if (parent[x] == x) return x;
        parent[x] = root(parent[x]);
        return parent[x];
    }

    bool same(int x, int y){
        return root(x) == root(y);
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (rank[x] > rank[y]) {
            parent[y] = x;
            size[x] += size[y];
        }
        else {
            parent[x] = y;
            size[y] += size[x];
            if (rank[x] == rank[y]) rank[y] += 1;
        }
    }
};

int main() {
    int N, M;
    cin >> N >> M;
    unionfind pre(N+1);
    unionfind ans(N+1);
    for (int i = 1; i <= N; i++) cin >> pre.size[i];
    ans.size = pre.size;
    vector<pair<ll, pair<int, int>>> edge(M);
    vector<vector<pair<int, ll>>> nb(N+1);
    for (int i = 0; i < M; i++) {
        int A, B, Y;
        cin >> A >> B >> Y;
        edge[i] = {Y, {A, B}};
        nb[A].push_back({B, Y});
        nb[B].push_back({A, Y});
    }
    sort(edge.begin(), edge.end());

    vector<bool> cand(M, false);
    vector<bool> use(M, false);
    for (int i = 0; i < M; i++) {
        int A = edge[i].second.first;
        int B = edge[i].second.second;
        ll Y = edge[i].first;
        pre.unite(A, B);
        if (pre.size[pre.root(A)] >= Y) cand[i] = true;
    }

    for (int i = M-1; i >= 0; i--) {
        if (!cand[i] || use[i]) continue;
        use[i] = true;
        int A = edge[i].second.first;
        int B = edge[i].second.second;
        ll Y = edge[i].first;
        if (ans.same(A, B)) continue;
        ans.unite(A, B);
        queue<int> q;
        q.push(A);
        q.push(B);
        while (!q.empty()) {
            int now = q.front();
            q.pop();
            for (auto p : nb[now]) {
                int nxt = p.first;
                int c = p.second;
                if (c > Y) continue;
                if (ans.same(now, nxt)) continue;
                ans.unite(now, nxt);
                q.push(nxt);
            }
        }
    }
    int cut = 0;
    for (int i = 0; i < M; i++) {
        int A = edge[i].second.first;
        int B = edge[i].second.second;
        int Y = edge[i].first;
        if (!ans.same(A, B) || ans.size[ans.root(A)] < Y) {
            cut++;
        }
    }
    cout << cut << endl;
    return 0;
}

