class UnionFind
{
  public:
	explicit UnionFind(ll size)
		: mParent(size, -1)
		, mRank(size, 0)
        , mData(size, 0)
		{}
	bool unionSet(ll x, ll y)
	{
		if ((x = root(x)) == (y = root(y)))
			return false;
		if( mRank[x] < mRank[y] )
		{
			mParent[y] += mParent[x];
			mParent[x] = y;
            unionData( mData[y], mData[x] );
		}
		else
		{
			mParent[x] += mParent[y];
			mParent[y] = x;
			if( mRank[x] = mRank[y] ) ++mRank[x];
            unionData( mData[x], mData[y] );
		}
		return true;
	}
	bool isEqualSet(ll x, ll y)
	{
		return root(x) == root(y);
	}
	ll root(ll x)
	{
		return mParent[x] < 0 ? x : mParent[x] = root(mParent[x]);
	}
	ll size(ll x)
	{
		return -mParent[root(x)];
	}

    void unionData( ll& parent, ll& child )
    {
        parent += child;
    }
    void setData( ll x, ll data )
    {
        mData[root(x)] = data;
    }
    ll getData( ll x )
    {
        return mData[root(x)];
    }

  public:
	vector<ll> mParent; // = mSize
	vector<ll> mRank;
	vector<ll> mData;
};

struct St{
    ll a = 0;
    ll b = 0;
    ll y = 0;
    bool is = false;
    bool iss = false;
};
bool operator<(const St& l, const St& r)
{ 
if( l.y == r.y ) 
{ 
    if( l.a == r.a ) return l.b < r.b;
    else return l.a < r.a;
}
return l.y < r.y; }
bool operator>(const St& l, const St& r)
{ 
if( l.y == r.y ) 
{ 
    if( l.is && !r.is ) return true;
    if( !l.is && r.is ) return false;
    if( l.a == r.a ) return l.b > r.b;
    else return l.a > r.a;
}
return l.y > r.y; }

int main()
{
    ll n, m;
    cin >> n >> m;
    VEC(ll, n, x, 0);
    REP(i,n) cin >> x[i];

    vector<St> edgeSt(m, St());
    REP( i, m )
    {
        ll a, b, y;
        cin >> a >> b >> y;
        edgeSt[i].a = a-1;
        edgeSt[i].b = b-1;
        edgeSt[i].y = y;
    }

    sort( edgeSt.begin(), edgeSt.end(), less<St>() );

    UnionFind uf( n );
    REP( i, n ) uf.setData( i, x[i] );
    REP( i, m )
    {
        uf.unionSet( edgeSt[i].a, edgeSt[i].b );
        auto d = uf.getData( edgeSt[i].a );
        if( d >= edgeSt[i].y ) edgeSt[i].is = true;
    }

    sort( edgeSt.begin(), edgeSt.end(), greater<St>() );

    vector< vector<ll> > edge(n);
    REP( i, m )
    {
        edge[edgeSt[i].a].push_back( i );
        edge[edgeSt[i].b].push_back( i );
    }

    ll ans = 0;
    REP( i,m )
    {
        if( edgeSt[i].iss ) { continue; }
        if( !edgeSt[i].is ) { ++ans; continue; }

        stack<ll> st;
        VEC( bool, n, used, false );
        st.push( edgeSt[i].a ); used[edgeSt[i].a] = true;
        st.push( edgeSt[i].b ); used[edgeSt[i].b] = true;

        while( st.size() )
        {
            ll t = st.top(); st.pop();
            for( auto idx : edge[t] )
            {
                auto& e = edgeSt[idx];
                auto eb = e.b != t ? e.b : e.a;
                if( !used[eb] && e.y <= edgeSt[i].y )
                {
                    used[eb] = true;
                    e.iss = true;
                    st.push( eb );
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
#define RI register int
#define lc(x) child[x][0]
#define rc(x) child[x][1]
typedef long long LL;

using namespace std;

template <class T> inline void read(T &n) {
	n = 0; RI ch;
	while (!isdigit(ch = getchar()));
	for (n = ch ^ 48; isdigit(ch = getchar()); n = n * 10 + (ch ^ 48));
}

int const MAXN = 1e5 + 5;
struct Edges {
	int x, y;
	LL val;
} e[MAXN];
LL a[MAXN], Rsize[MAXN], Esize[MAXN];
int vis[MAXN], fa[MAXN], child[MAXN][2], r[MAXN], stk[MAXN], top;

inline bool cmp(Edges x, Edges y) { return x.val < y.val; }

inline void Update(int x) { Rsize[x] = Rsize[lc(x)] + Rsize[rc(x)] + Esize[x] + a[x]; }
inline bool Isroot(int x) { return lc(fa[x]) != x && rc(fa[x]) != x; }
inline void Reverse(int x) { swap(lc(x), rc(x)), r[x] ^= 1; }
inline void Pushdown(int x) {
	if (r[x]) {
		if (lc(x)) Reverse(lc(x));
		if (rc(x)) Reverse(rc(x));
		r[x] = 0;
	}
}
inline void Rotate(int x) {
	int f = fa[x], g = fa[f], c = rc(f) == x;
	if (!Isroot(f)) child[g][rc(g) == f] = x;
	child[f][c] = child[x][!c];
	child[x][!c] = f;
	if (child[f][c]) fa[child[f][c]] = f;
	fa[x] = g;
	fa[f] = x;
	Update(f);
}
inline void Splay(int x) {
	int y = x; top = 0;
	stk[++top] = y;
	while (!Isroot(y)) stk[++top] = y = fa[y];
	while (top) Pushdown(stk[top--]);
	while (!Isroot(x)) {
		y = fa[x];
		if (!Isroot(y))
			Rotate((lc(y) == x) == (lc(fa[y]) == y) ? y : x);
		Rotate(x);
	}
	Update(x);
}
inline void Access(int x) {
	for (RI y = 0; x; y = x, x = fa[x])
		Splay(x), Esize[x] += Rsize[rc(x)], Esize[x] -= Rsize[y], rc(x) = y, Update(x);
}
inline void Makeroot(int x) {
	Access(x), Splay(x), Reverse(x);
}
inline bool Unicom(int x, int y) {
	Makeroot(x), Access(y), Splay(y);
	int k = y;
	while (lc(k)) k = lc(k);
	return k == x;
}
inline void Link(int x, int y) {
	Makeroot(x), Splay(x);
	fa[x] = y, Esize[y] += Rsize[x];
}
inline void Cut(int x, int y) {
	Makeroot(x), Access(y), Splay(y);
	lc(y) = fa[x] = 0;
	Update(y);
}

int main() {
//	freopen("bridge.in", "r", stdin);
//	freopen("bridge.out", "w", stdout);
	int n, m, ans; read(n), read(m);
	for (RI i = 1; i <= n; ++i) read(a[i]);
	for (RI i = 1; i <= m; ++i)
		read(e[i].x), read(e[i].y), read(e[i].val);
	sort(e + 1, e + 1 + m, cmp);
	for (RI i = 1; i <= m; ++i) {
		if (Unicom(e[i].x, e[i].y)) continue;
		Link(e[i].x, e[i].y), vis[i] = 1;
	}
	for (RI i = m; i; --i)
		if (vis[i]) {
			Makeroot(e[i].x), Splay(e[i].x);
			if (Rsize[e[i].x] < e[i].val) Cut(e[i].x, e[i].y);
		}
	for (RI i = 1; i <= m; ++i)
		if (!Unicom(e[i].x, e[i].y)) ++ans;
		else {
			Makeroot(e[i].x), Splay(e[i].x);
			if (Rsize[e[i].x] < e[i].val) ++ans;
		}
	printf("%d\n", ans);
	return 0;
}

