const int N = 1e5 + 10;
ll par[N], height[N], sum[N], id2e[N], use[N];

int find(int x){
    if (par[x] == x) return x;
    return find(par[x]);
}

bool same(int x, int y){
    return find(x) == find(y);
}

void merge(int x, int y, int id){
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (height[x] < height[y]){
        par[x] = y;
        sum[y] += sum[x];
        id2e[id] = x;
    }else{
        par[y] = x;
        sum[x] += sum[y];
        id2e[id] = y;
        if (height[x] == height[y]) height[x]++;
    }
}

void split(int id){
    int x = id2e[id];
    int y = par[x];
    par[x] = x;
    sum[y] -= sum[x];
}

struct edge{ ll u, v, cost; };

bool comp(const pair<edge, int> &e1, const pair<edge, int> &e2){
    return e1.first.cost < e2.first.cost;
}

int main() {
    int n, m;
    cin >> n >> m;
    VL x(n);
    REP(i,n) x[i] = in();
    vector<pair<edge, int>> es(m);
    REP(i,m){
        int u = in() - 1, v = in() - 1, y = in();
        es[i] = make_pair(edge{u, v, y}, i);
    }

    REP(i,n){
        par[i] = i;
        height[i] = 1;
        sum[i] = x[i];
    }

    sort(ALL(es), comp);
    REP(i,m){
        edge e = es[i].first;
        if (same(e.u, e.v)) continue;

        merge(e.u, e.v, es[i].second);
        use[es[i].second] = 1;
    }


    int ans = 0;
    FORR(i,m-1,0){
        // cout << i << endl;
        edge e = es[i].first;
        int p = find(e.u);
        // cout << p << " " << sum[p] << " " << e.cost << endl;
        if (sum[p] < e.cost) ans++;
        else continue;
        if (!use[es[i].second]) continue;
        split(es[i].second);

        // cout << endl;
        // REP(j,n) cout << " " << j << " " << par[j] << " " << sum[j] << endl;
    }
    cout << ans << endl;

    return 0;
}

