  REP(i, N) S[i] = X[i];
  UnionFind uf(N);

  REP(i, edge.size()) {
    if (edge[i].alive) {
      ll s1 = S[uf.root(edge[i].a)];
      ll s2 = S[uf.root(edge[i].b)];
      if (uf.link(edge[i].a, edge[i].b)) {
        S[ uf.root(edge[i].a) ] = s1 + s2;
      }
    }
  }
  bool ok = true;
  // cout << "--" << endl;
  // cout << "mid=" << mid << endl;
  REP(i, edge.size()) {
