struct UnionFind{
	vi par,x;
	vector<vector<pi>> waf;

	UnionFind(vi xx){
		par.resize(xx.size(),-1);
		x=xx;
		waf.resize(xx.size());
	}

	int Find(int a){
		return par[a]==-1?a:(par[a]=Find(par[a]));
	}

	bool Same(int a,int b){
		return Find(a)==Find(b);
	}

	int Unite(int a,int b){
		a=Find(a);
		b=Find(b);
		if(a==b)return a;
		if(waf[a].size()<waf[b].size())
			swap(a,b);
		waf[a].insert(waf[a].end(),ALL(waf[b]));
		par[b]=a;
		x[a]+=x[b];
		return a;
	}

	int Size(int a){
		return x[Find(a)];
	}
};

signed main(){
	int n=read(),m=read();
	vi x(n);
	REP(i,n)
		x[i]=read();
	vector<tuple<int,int,int>> es;
	REP(i,m){
		int a=read()-1,b=read()-1,c=read();
		es.EB(c,a,b);
	}
	sort(ALL(es));
	UnionFind uf(x);
	UnionFind uf2(x);
	for(auto e:es){
		int c=get<0>(e),a=get<1>(e),b=get<2>(e);
		if(!uf.Same(a,b)){
			int root=uf.Unite(a,b);
			uf.waf[root].PB(pi(a,b));
			if(uf.Size(root)>=c){
				for(auto f:uf.waf[root])
					uf2.Unite(f.first,f.second);
				uf.waf[root].clear();
			}
		}
	}
	int ans=m;
	for(auto e:es){
		int c=get<0>(e),a=get<1>(e);
		if(uf2.Size(a)>=c)
			ans--;
	}
	print(ans);
}

