template<typename T>
struct edge {
    int src,to;
    T cost;

    edge() = default;
    edge(int to, T cost) : src(-1), to(to), cost(cost) {}
    edge(int src, int to, T cost) : src(src), to(to), cost(cost) {}
    bool operator<(const edge &e) const {
        return cost < e.cost;
    }
};

struct UnionFind {
    vector<int> node;

    UnionFind() = default;
    UnionFind(int x) {init(x);}

    void init(int x) {
        node.assign(x,-1);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (node[x] > node[y]) swap(x,y);
        node[x] += node[y];
        node[y] = x;
        return true; 
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        if (node[x] < 0) return x;
        return node[x] = root(node[x]);
    }

    int size(int x) {
        return -node[root(x)];
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N,M; cin >> N >> M;
    vector<ll> X(N+1);
    rep(i,N) cin >> X[i];
    vector<edge<ll>> E;
    rep(i,M) {
        int u,v,w; cin >> u >> v >> w;
        --u; --v;
        E.emplace_back(u,v,w);
    }

    sort(all(E));
    UnionFind uf(N);
    vector<int> cnt(N+1),ok(N+1);
    rep(i,M) {
        int p = uf.root(E[i].to);
        int q = uf.root(E[i].src);
        if (p == q) q = N;
        int c = cnt[p]+cnt[q];
        int o = ok[p]+ok[q];
        ll w = X[p]+X[q];
        cnt[p] = cnt[q] = ok[p] = ok[q] = X[p] = X[q] = 0;
        uf.merge(E[i].src,E[i].to);
        int v = uf.root(E[i].src);
        cnt[v] = c+1;
        X[v] = w;
        ok[v] = w >= E[i].cost ? cnt[v] : o;
    } 

    cout << M - accumulate(all(ok),0) << ln;
}

