struct UnionFind
{
	vector<int> par;
	vector<int> sizes;
	vector<ll>Xsum;
	vector<ll>Ymax;
	UnionFind(int n) : par(n), sizes(n, 1), Xsum(n), Ymax(n) {
		for (int i = 0; i < n; i++) par[i] = i;
		for (int i = 0; i < n; i++)Xsum[i] = X[i];
	}

	int find(int x) {
		if (x == par[x])return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y, ll w) {
		x = find(x);
		y = find(y);

		if (sizes[x] < sizes[y]) swap(x, y);

		if (x == y)
		{
			Ymax[x] = max(Ymax[x], w);
			return;
		}

		par[y] = x;
		sizes[x] += sizes[y];
		Xsum[x] += Xsum[y];
		Ymax[x] = max({ Ymax[x], Ymax[y], w });
	}

	bool pre_unite(int x, int y, ll w) {
		x = find(x);
		y = find(y);

		if (sizes[x] < sizes[y]) swap(x, y);

		if (x == y)
		{
			if (Xsum[x] < max(Ymax[x], w))return false;
			else return true;
		}

		if (Xsum[x] + Xsum[y] < max({ Ymax[x], Ymax[y], w }))return false;
		else return true;
	}

	bool is_ok(int x, int y) {
		x = find(x);
		y = find(y);

		if (sizes[x] < sizes[y]) swap(x, y);

		if (Xsum[x] < Ymax[x])return false;
		else return true;
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}

	int size(int x) {
		return sizes[find(x)];
	}
};

