using ll=long long;
enum{PAR,RANK,SUM};
struct Log{
    int type;
    int pos;
    ll val;
};
class GodUnion{
    vector<int> par;
    vector<int> rank;
    vector<ll> sum;
    vector<vector<Log>> vec;
    public:
    GodUnion(int n,int m,vector<ll> x):rank(n),par(n),sum(x),vec(m){
        iota(par.begin(),par.end(),0);
    }
    int find(int x){
        if(par[x]==x) return x;
        else return find(par[x]);
    }
    void unite(int x,int y,int t){
        x=find(x),y=find(y);
        // cerr<<x<<" "<<y<<endl;
        // cerr<<sum[x]<<" "<<sum[y]<<endl;
        if(rank[x]<rank[y]){
            vec[t].push_back(Log{PAR,x,x});
            vec[t].push_back(Log{SUM,y,sum[y]});
            par[x]=y;
            sum[y]+=sum[x];
        }
        else{
            vec[t].push_back(Log{PAR,y,y});
            vec[t].push_back(Log{SUM,x,sum[x]});
            if(rank[x]==rank[y]){
                vec[t].push_back(Log{RANK,x,rank[x]});
                rank[x]++;
            }
            par[y]=x;
            sum[x]+=sum[y];
        }
    }
    void RollBack(int t){
        for(auto l:vec[t]){
            if(l.type==PAR){
                par[l.pos]=l.val;
            }
            if(l.type==SUM){
                sum[l.pos]=l.val;
            }
            if(l.type==RANK){
                rank[l.pos]=l.val;
            }
        }
    }
    ll getSum(int v){
        return sum[find(v)];
    }
};
struct Edge{
    int a,b;
    ll y;
};
bool operator<(const Edge& lhs,const Edge& rhs){
    return lhs.y<rhs.y;
}
