    scanf("%d %d %d", &a, &b, &w);
    a--;
    b--;
    edg[i] = {w, {a, b}};
  }
  sort(edg.begin(), edg.end());
  vector<vector<int>> adj(n);
  for (int i = 0; i < m; i ++) {
    auto e = edg[i];
    int a = e.second.first;
    int b = e.second.second;
    adj[a].push_back(i);
    adj[b].push_back(i);
  }
  vector<int> cdd(m, 0);
  for (int i = 0; i < m; i++) {
    auto e = edg[i];
    int y = e.first;
    int a = e.second.first;
    int b = e.second.second;
    if (!djs.is_equiv(a, b)) {
      djs.unite(a, b);
    }
    if (y <= djs.wt[djs.p[a]]) {
      cdd[i] = true;
    }
  }
  vector<int> ckd(m, 0);
  stack<int> stk;
  for(int i = m - 1; i >= 0; i--) {
    if (cdd[i]) {
      int supw = edg[i].first;
      stk.push(i);
      ckd[i] = true;
      while (!stk.empty()) {
        int crr = stk.top();
        stk.pop();
        int crrs = edg[crr].second.first;
        int crrt = edg[crr].second.second;
        for (auto nxt : adj[crrs]) {
          int nxtw = edg[nxt].first;
          if (!ckd[nxt] && nxtw <= supw) {
            stk.push(nxt);
            ckd[nxt] = true;
          }
        }
        for (auto nxt : adj[crrt]) {
          int nxtw = edg[nxt].first;
          if (!ckd[nxt] && nxtw <= supw) {
            stk.push(nxt);
            ckd[nxt] = true;
          }
        }
      }
    }
  }
  int ans = 0;
  for (int i = 0; i < m; i++) {
    if (!ckd[i]) {
      ans++;
    }
  }
  cout << ans << '\n';
  return 0;
}

