int findher(int a){
    if(a == parent[a])return a;
    return parent[a] = findher(parent[a]);
}

void tmerge(int a,int b){
    a = findher(a);
    b = findher(b);
    if(sz[a] < sz[b])
        swap(a , b);
    parent[b] = a;
    sum[a] += sum[b];
    sz[a] += sz[b];
    edge[a] += edge[b];
    for(int j=0;j<(int)g[b].size();j++){
        g[a].push_back(g[b][j]);
    }
    g[b].clear();
}

int f(int ind){
    for(int i=1;i<=n;i++){
        parent[i] = i;
        sum[i] = cnt[i];
        sz[i] = 1;
        g[i].clear();
        g[i].push_back(i);
        edge[i] = 0;
        used[i] = false;
    }
    for(int i=1;i<=ind;i++){
        int id = p[i].second;
        int aa = a[id] , bb = b[id];
        if(findher(aa) != findher(bb)){
            tmerge(aa , bb);
        }
        int p = findher(aa);
        edge[p]++;
    }
    int answ = 0;
    for(int i=ind;i>=1;i--){
        int v = a[ p[i].second ];
        if(mark[i] && used[v] == false){
            v = findher(v);
            answ += edge[v];
            for(int j=0;j<(int)g[v].size();j++){
                int to = g[v][j];
                used[to] = true;
            }
        }
    }
    return answ;
}

