#define int long long

class DSU {
private:
    vector<int> parents;
    vector<int> sizes;
public:
    DSU(int n) {
        parents.resize(n+1);
        for(int i = 1; i <= n; ++i) parents[i] = i;
        sizes.resize(n+1);
        for(int i = 1; i <= n; ++i) sizes[i] = 1;
    }

    int root(int i) {
        while(parents[i] != i) {
            parents[i] = parents[parents[i]];
            i = parents[i];
        }
        return i;
    }

    bool find(int a, int b) {
        return root(a) == root(b);
    }

    void join(int a, int b) {
        int root_a = root(a);
        int root_b = root(b);

        if(root_a == root_b) return;

        if(sizes[root_a] < sizes[root_b]) {
            parents[root_a] = parents[root_b];
            sizes[root_b] += sizes[root_a];
        } else {
            parents[root_b] = parents[root_a];
            sizes[root_a] += sizes[root_b];
        }
    }

    vector<vector<int>> getComponents() {
        int n = parents.size()-1;
        vector<bool> seen(n+1);
        vector<vector<int>> ret;
        for(int i = 1; i <= n; ++i) {
            if(!seen[i]) {
                vector<int> component;
                int curroot = root(i);
                for(int j = 1; j <= n; ++j) {
                    if(root(j) == curroot) {
                        seen[j] = true;
                        component.push_back(j);
                    }
                }
                ret.push_back(component);
            }
        }
        return ret;
    }
};

struct edge {
    int dest;
    int weight;
};

edge make_edge(int d, int w) {
    edge e;
    e.dest = d;
    e.weight = w;
    return e;
}

int solve(vector<vector<edge>>& graph, vector<int>& x, vector<int>& component) {
    if(component.size() == 1) return 0;
    int ret = 0;

    int vertexSum = 0;
    for(int v : component) {
        vertexSum += x[v];
    }

    int numVs = component.size();
    unordered_map<int, int> compmap;
    for(int i = 1; i <= numVs; ++i) {
        compmap[component[i-1]] = i;
    }
    DSU dsu(numVs);
    for(int ci = 0; ci < numVs; ++ci) {
        int c = component[ci];
        vector<edge>& edges = graph[c];
        int numEdges = edges.size();
        for(int i = numEdges-1; i >= 0; --i) {
            if(edges[i].weight > vertexSum) {
                ret++;
                edges.erase(edges.begin() + i);
            } else {
                dsu.join(ci+1, compmap[edges[i].dest]);
            }
        }
    }
    if(ret > 0) {
        auto newcomponents = dsu.getComponents();
        for(vector<int>& newcomponent : newcomponents) {
            for(int& nc : newcomponent) {
                nc = component[nc-1];
            }
            ret += solve(graph, x, newcomponent);
        }
    }

    return ret;
}

int32_t main() {

    int n, m; cin >> n >> m;
    vector<int> x(n+1);
    for(int i = 1; i <= n; ++i) cin >> x[i];

    vector<vector<edge>> graph(n+1, vector<edge>());
    DSU dsu(n);

    for(int i = 0; i < m; ++i) {
        int a, b, y; cin >> a >> b >> y;
        graph[a].push_back(make_edge(b, y));
        dsu.join(a, b);
    }

    auto comps = dsu.getComponents();

    int ret = 0;
    for(vector<int>& component : comps) {
        ret += solve(graph, x, component);
    }

    cout << ret << endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 300 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;
const int MAGIC = 450;

struct edge {
    int u, v;
    bool f;
    long long w;
};

int n, m;
int p[N], P[N], w[N], W[N], U[N];
long long X[N], wgt[N], Wgt[N];
vector<int> L;
edge E[N];

bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> X[i];

    for (int i = 0; i < m; ++i) {
        cin >> E[i].u >> E[i].v >> E[i].w;
        --E[i].u, --E[i].v;
        E[i].f = 1;
    }

    return true;
}

void init_dsu() {
    iota(p, p + n, 0);
    fill(w, w + n, 1);
    fill(U, U + n, 0);
    L.clear();
    L.reserve(n);

    for (int i = 0; i < n; ++i) {
        wgt[i] = Wgt[i] = X[i];
        P[i] = p[i];
        W[i] = w[i];
    }
}

inline void mark(int i) {
    if (!U[i]) {
        U[i] = 1;
        L.emplace_back(i);
    }
}

int getp(int v) {
    if (p[v] == v)
        return p[v];

    mark(v);
    return p[v] = getp(p[v]);
}

int getw(int v) { return wgt[getp(v)]; }

void join(int u, int v) {
    if ((u = getp(u)) == (v = getp(v)))
        return ;

    if (w[u] < w[v])
        swap(u, v);

    p[v] = u;
    w[u] += w[u] == w[v];
    wgt[u] += wgt[v];
    mark(u);
    mark(v);
}

void rollback() {
    for (const auto& i : L) {
        U[i] = 0;
        p[i] = P[i];
        w[i] = W[i];
        wgt[i] = Wgt[i];
    }

    L.clear();
}

void fix() {
    for (const auto& i : L) {
        U[i] = 0;
        P[i] = p[i];
        W[i] = w[i];
        Wgt[i] = wgt[i];
    }

    L.clear();
}

void solve() {
    sort(E, E + m, [](const edge& e1, const edge& e2) {
        return e1.w < e2.w;
    });

    for (int t = m - 1; t >= 0; --t)
        if (t % MAGIC == 0) {
            auto l = t;
            auto r = min(m - 1, t + MAGIC - 1);
            init_dsu();

            for (int i = 0; i < m; ++i)
                if (i < l || (i > r && E[i].f))
                    join(E[i].u, E[i].v);

            fix();

            for (int i = r; i >= l; --i) {
                for (int j = l; j <= i; ++j)
                    join(E[j].u, E[j].v);

                if (getw(E[i].u) < E[i].w)
                    E[i].f = 0;

                rollback();

                if (E[i].f) {
                    join(E[i].u, E[i].v);
                    fix();
                }
            }
        }

    auto ans = 0;

    for (int i = 0; i < m; ++i)
        if (!E[i].f)
            ++ans;

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

