struct DSU {
  DSU(int n) : parent_(n) {
    for (int i = 0; i < n; i++) {
      parent_[i] = i;
    }
  }

  std::vector<int> parent_;
  int get(int x) {
    return parent_[x] = (x == parent_[x] ? x : get(parent_[x]));
  }
  int merge(int x, int y) {
    x = get(x);
    y = get(y);
    if (x == y) {
      return x;
    }
    if (rand() % 2 == 0) {
      parent_[x] = y;
      return y;
    }
    parent_[y] = x;
    return x;
  }
};
using int64 = long long;
struct Node {
  int64 sum_x{0};
  int bad_edges{0};
  void add_edge(int64 e) {
    if (e > sum_x) {
      bad_edges++;
    } else {
      bad_edges = 0;
    }
  }
  void merge(Node other) {
    sum_x += other.sum_x;
    bad_edges += other.bad_edges;
  }
};
int main(void) {
