struct unionfind {
    vector<int> par, t;
    vector<ll> s;
    unionfind(int n)
        : par(n, -1), s(n), t(n) {}

    int find(int x) {
        if (par[x] < 0)
            return x;
        else
            return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (par[x] > par[y])
            swap(x, y);
        par[x] += par[y];
        s[x] += s[y];
        t[x] += t[y];
        par[y] = x;
    }
    int size(int x) {
        return -par[find(x)];
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

