template <typename T>
class UnionFind{
    public:
        int n;
        vector<T> p, rank;

        UnionFind(int n)
            : n(n), p(n+1, -1), rank(n+1) {}

        int find(int v){
            if(p[v] == -1){
                return v;
            }
            p[v] = find(p[v]);
            return p[v];
        }

        bool unite(int u, int v){
            u = find(u);
            v = find(v);

            if(u == v){
                return false;
            }

            if(rank[u] < rank[v]){
                swap(u, v);
            }

            if(rank[u] == rank[v]){
                rank[u]++;
            }

            p[v] = u;
            return true;
        }
};

struct edge{
    int w, x, y;
};

bool compare(edge a, edge b){
    return a.w < b.w;
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    vector<int> x(n + 1);
    rep(i, n){
        cin >> x[i+1];
    }

    auto graph = initVec2<P>(n + 1, 0);
    vector<edge> ve(m);
    rep(i, m){
        int a, b, y;
        cin >> a >> b >> y;
        ve[i] = {y, a, b};
        graph[a].emplace_back(b, y);
        graph[b].emplace_back(a, y);
    }
    sort(ALL(ve), compare);

    UnionFind<int> uf(n + 1);
    vector<int> sum(n + 1);
    rep(i, n + 1){
        sum[i] = x[i];
    }

    stack<edge> st;
    rep(i, m){
        int rx = uf.find(ve[i].x);
        int ry = uf.find(ve[i].y);
        int s = sum[rx] + sum[ry];
        if(uf.unite(ve[i].x, ve[i].y)){
            sum[uf.find(rx)] = s;
            if(s >= ve[i].w){
                st.push(ve[i]);
            }
        }
    }

    vector<bool> used(n + 1, false);
    int ans = 0;
    while(not st.empty()){
        edge e = st.top();
        st.pop();

        stack<int> next;
        next.push(e.x);
        next.push(e.y);

        while(not next.empty()){
            int v = next.top();
            next.pop();

            if(used[v]){
                continue;
            }
            used[v] = true;

            for(P p : graph[v]){
                int u = p.first;
                int w = p.second;
                if(w <= e.w && not used[u]){
                    ans++;
                    next.push(u);
                }
            }
        }
    }

    cout << m - ans << endl;

    return 0;
}

