void dfs(int v, int p, int dd) {
	d[v] = dd;
	c[v] = 1;
	RF(e, g[v]) {
		if(e == p) { continue; }
		dfs(e, v, dd + 1);
		c[v] += c[e];
	}
}

void del_2(int L, int S, int v, int p) {
	id[v] = S;
	w[L] -= x[v];
	w[S] += x[v];
	RF(e, g[v]) {
		if(e == p || ! mp[MP(v, e)]) { continue; }
		del_2(L, S, e, v);
	}
}

void del(int rl, int rs, int v, int p) {
	int L = id[v];
	int S = SI(r);
	r.PB(-1);
	w.PB(0);
	r[L] = rl;
	r[S] = rs;
	del_2(L, S, v, p);
}

