void f(int v, int id, long long limit) {
	if (a[v] == id) return;
	a[v] = id;
	ss += X[v];
	for (auto it = G[v].begin(); it != G[v].end(); ) {
		if (E[it->second] <= limit) {
			mm = max(mm, E[it->second]);
			f(it->first, id, limit);
			++ it;
		} else {
			G[it->first].erase(v);
			G[v].erase(it++);
		}
	}
}
void g(int v, int id, long long limit) {
	if (a[v] == id) return;
	a[v] = id;
	fix[v] = true;
	for (auto p : G[v]) {
		if (E[p.second] <= limit) {
			used[p.second] = true;
			g(p.first, id, limit);
		}
	}
}
