bool lessPair(const edge& l, const edge& r){return l.second < r.second;}

struct UnionFind {
  vector<lint> par;
  vector<lint> weight;

  UnionFind(int N, vector<lint> X) : par(N), weight(N) {
    for(int i = 0; i < N; i++) {
      par[i] = i;
      weight[i] = X[i];
    }
  }

  int root(lint x) {
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(lint x, lint y) {
    lint rx = root(x);
    lint ry = root(y);
    if (rx == ry) return;
    weight[ry] = weight[rx] + weight[ry];
    par[rx] = ry;
  }

  bool same(lint x, lint y) {
    lint rx = root(x);
    lint ry = root(y);
    return rx == ry;
  }

  lint get_weight(lint x) {
    return weight[root(x)];
  }
};


