typedef struct UnionFind_ {
  vector<int> par;
  vector<int> rank_;
  vector<ll> w;
  UnionFind_(int n): rank_(n, 0), w(n, 0) {
    for(int i = 0; i < n; i++)par.push_back(i);
  }
  int find(int x) {
    if(par[x] == x)return x;
    else return par[x] = find(par[x]);
  }
  bool same(int x, int y) {
    if(find(x) == find(y))return true;
    else return false;
  }
  bool unite(int x, int y){
    int xp = find(x);
    int yp = find(y);
    if(xp == yp)return false;
    if(rank_[xp] > rank_[yp]){
      par[yp] = xp;
      w[xp] += w[yp];
    }
    else if(rank_[xp] < rank_[yp]){
      par[xp] = yp;
      w[yp] += w[xp];
    }
    else {
      par[yp] = xp;
      rank_[xp]++;
      w[xp] += w[yp];
    }
    return true;
  }
} UnionFind;

