#include <bits/stdc++.h>
using namespace std;

vector<long long int> x;

struct UnionFind{
    vector<int> parent;
    vector<int> size;
    vector<int> rank;
    vector<int> sum;

    /* constructor (initialize) */
    UnionFind(int n){
        parent.resize(n);
        size.resize(n);
        rank.resize(n);
        sum.resize(n);
        for(int i=0; i<n; i++){
            parent[i] = i;// completely-disjoint
            size[i] = 1;
            rank[i] = 0;// union by rank
            sum[i] = x[i];
        }
    }

    int root(int x){
        // terminal case
        if(parent[x] == x){
            return x;// by definition
        }

        // recursion
        parent[x] = root(parent[x]);// path compression : keep tree as shallow as possible
        return parent[x];
    }

    void merge(int x, int y){
        int rx = root(x);
        int ry = root(y);

        // if (root(x) == root(y)) do nothing;
        if (rx != ry){
            if(rank[rx] < rank[ry]){
                parent[rx] = ry;// root of merged tree = ry
                size[ry] += size[rx];
                sum[ry] += sum[rx];
            }
            else if(rank[rx] == rank[ry]){
                parent[rx] = ry;
                size[ry] += size[rx];
                sum[ry] += sum[rx];
                rank[ry] += 1;
            }
            else if(rank[rx] > rank[ry]){
                parent[ry] = rx;// root of merged tree = rx
                size[rx] += size[ry];
                sum[rx] += sum[ry];
            }
        }
        return;
    }

    bool same(int x, int y){ return root(x) == root(y); }

    int nodes(int x){ return size[root(x)]; }

    int total(int x){ return sum[root(x)]; }
};

