using ll = long long;

const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m;
ll cnt = 0;
ll x[MAXN];
bool used[MAXN];
vector< pair<int, ll> > g[MAXN];

bool read() {
    if (!(cin >> n >> m))
        return false;

    forn (i, n)
        cin >> x[i];

    forn (i, m) {
        int u, v;
        ll y;
        cin >> u >> v >> y;
        g[u - 1].pb(mp(v - 1, y));
        g[v - 1].pb(mp(u - 1, y));
    }

    return true;
}

vector<int> cur;

void dfs1(int v) {
    used[v] = true;
    cnt += x[v];
    cur.pb(v);

    for (auto to : g[v])
        if (!used[to.f])
            dfs1(to.f);
}

void solve() {
    int ans = 0;

    while (true) {
        fill(used, used + n, false);
        bool flag = false;

        forn (i, n)
            if (!used[i]) {
                cnt = 0;
                cur.clear();
                dfs1(i);

                for (auto& v : cur) {
                    vector< pair<int, ll> > nvec;

                    for (auto& e : g[v]) {
                        if (e.s <= cnt)
                            nvec.pb(e);
                        else
                            ++ans, flag = true;
                    }

                    g[v].swap(nvec);
                }
            }

        if (!flag)
            break;
    }

    cout << ans / 2 << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

