struct UnionFind{
   vector<int> par,cnt;
   vector<ll> sum;
   UnionFind(int n):par(n,-1),sum(n),cnt(n){
       rep(i,n)sum[i]=a[i];
   }
   int find(int x){
       if(par[x]<0)return x;
       return par[x]=find(par[x]);
   }
   bool unite(int x,int y){
       x=find(x);
       y=find(y);
       if(x==y){
           ++cnt[x];
           return false;
       }
       if(par[x]>par[y]){
           par[y]+=par[x];
           sum[y]+=sum[x];
           cnt[y]+=cnt[x]+1;
           par[x]=y;
       }
       else{
           par[x]+=par[y];
           sum[x]+=sum[y];
           cnt[x]+=cnt[y]+1;
           par[y]=x;
       }
       return true;
   }

   bool same(int x,int y){
       return find(x)==find(y);
   }
   ll get(int x){
       return sum[find(x)];
   }
};

