int N, M;
LL X[100000];
pair<LL, PP> T[100000];
vector<int> changes[100000];
int A[100000];
int B[100000];

LL Y[100000];
int ps[100000];
vector<int> groups[100000];
int root(int i) {
	if (ps[i] == i) return i;
	return root(ps[i]);
}


bool check(int i, int j, int k) {
	bool ok = true;
	LL c = T[k].first;
	if (c > Y[root(i)]) {
		ok = false;
	}

	if (!ok && !changes[k].empty()) {
		ps[B[k]] = B[k];
		LL sum = 0;
		for (int e : changes[k]) sum += X[e];
		Y[B[k]] = sum;
		Y[A[k]] -= sum;
	}
	return ok;
}

void merge(int i, int j, int k) {
	if (root(i) == root(j)) return;
	int ri = root(i);
	int rj = root(j);
	if (groups[ri].size() < groups[rj].size()) {
		swap(i, j);
		swap(ri, rj);
	}

	ps[rj] = ri;
	for (int e : groups[rj]) {
		groups[ri].push_back(e);
		changes[k].push_back(e);
	}
	A[k] = ri;
	B[k] = rj;
}

int main() {
	cin >> N >> M;
	REP(i, 0, N) cin >> X[i];
	REP(k, 0, M) {
		int a, b, c;
		cin >> a >> b >> c;
		--a; --b;
		T[k] = { c, PP(a, b) };
	}
	sort(T, T + M);

	REP(i, 0, N) ps[i] = i;
	REP(i, 0, N) groups[i].push_back(i);
	REP(k, 0, M) {
		int a = T[k].second.first;
		int b = T[k].second.second;
		merge(a, b, k);
	}

	Y[root(0)] = accumulate(X, X + N, 0LL);

	int cnt = 0;
	REM(k, 0, M) {
		int a = T[k].second.first;
		int b = T[k].second.second;
		if (!check(a, b, k)) {
			++cnt;
		}
	}

	cout << cnt << endl;
	return 0;
}

