struct UnionFindSize {
    vector<int> par;

    UnionFindSize(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N, M;
	cin >> N >> M;
	vector<ll> X(N);
	REP(i, N) cin >> X[i];

	vector<edge> E(M);
	REP(i, M){
		cin >> E[i].u >> E[i].v >> E[i].w;
		E[i].u--;
		E[i].v--;
	}

	sort(E.begin(), E.end(), [](const edge &x, const edge &y){
		return x.w < y.w;
	});

	UnionFindSize uf(N);

	vector<ll> sum(N, 0), enu(N, 0), ema(N, 0), sude(N, 0);
	REP(i, N) sum[i] = X[i];

	REP(i, M){
		//dump(i)
		//debug(sude, N);

		edge e = E[i];
		ll ru = uf.root(e.u);
		ll rv = uf.root(e.v);

		if(uf.issame(e.u, e.v)){
			//dump(1)
			if(e.w > ema[ru]){
				continue;
			}else{
				enu[ru]++;
				chmax(ema[ru], e.w);
				sude[ru]++;
			}
		}else{
			//dump(2)
			uf.merge(e.u, e.v);
			ll rr = uf.root(e.u);

			sum[rr] = sum[ru] + sum[rv];
			enu[rr] = enu[ru] + enu[rv] + 1;
			ema[rr] = max(max(ema[ru], ema[rv]), e.w);

			if(ema[rr] > sum[rr]){
				// fail
				sude[rr] = sude[ru] + sude[rv];
				if(rr == ru) sude[rv] = 0;
				if(rr == rv) sude[ru] = 0;
			}else{
				// success
				sude[ru] = 0;
				sude[rv] = 0;
				sude[rr] = enu[rr];
			}
		}
	}

	ll res = M;
	REP(i, N) res -= sude[i];
	cout << res << endl;

	//debug(sude, N);

	return 0;
}

