struct UnionFindTree {
  int size; 
  std::vector<int> parent;
  std::vector<int64> x;
  std::vector<int> edges;

  UnionFindTree() = default;
  UnionFindTree(int size): size(size), parent(size, -1) {}
  UnionFindTree(vector<int64>& x):
    size(x.size()), parent(x.size(), -1), x(x), edges(x.size(), 0) {}

  int Size() const { return size; }
  int Size(int e) { return -parent[Root(e)]; }

  bool Same(int e1, int e2) { return Root(e1) == Root(e2); }

  void Unite(int e1, int e2) {
    if ((e1 = Root(e1)) != (e2 = Root(e2))) {
      if (Size(e1) < Size(e2)) {
        std::swap(e1, e2);
      }
      // e1の属する集合にe2の属する集合を併合
      parent[e1] += parent[e2];
      x[e1] += x[e2];
      parent[e2] = e1;
      size--;
      edges[e1] += edges[e2];
    }
    edges[e1]++;
  }

  int Edges(int e) {
    e = Root(e);
    return edges[e];
  }

  void Kill(int e) {
    e = Root(e);
    edges[e] = 0;
  }

  int64 Weight(int e) {
    e = Root(e);
    return x[e];
  }

  int Root(int e) { 
    if (parent[e] < 0) return e;
    parent[e] = Root(parent[e]);
    return parent[e];
  }
};

struct Edge {
  using Weight = int64;

  int end1, end2;
  Weight weight;

  Edge() = default;
  Edge(int end1, int end2, Weight weight): end1(end1), end2(end2), weight(weight) {}

  bool operator<(const Edge& e) const {
    return weight < e.weight;
  }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);

  int n, m;
  cin >> n >> m;

  vector<int64> x(n);
  repeat (i, n) {
    cin >> x[i];
  }

  vector<Edge> edges;
  repeat (i, m) {
    int a, b, y;
    cin >> a >> b >> y;
    a--; b--;

    edges.emplace_back(a, b, y);
  }
  sort(begin(edges), end(edges));

  UnionFindTree union_find(x);

  int ans = m;

  repeat (i, m) {
    Edge& e = edges[i];

    union_find.Unite(e.end1, e.end2);

    if (union_find.Weight(e.end1) >= e.weight) {
      ans -= union_find.Edges(e.end1);
      union_find.Kill(e.end1);
    }
  }
  cout << ans << endl;

  return 0;
}

