public:
    DSU(int n, vector<int> w) {
        parents.resize(n+1);
        for(int i = 1; i <= n; ++i) parents[i] = i;
        sizes.resize(n+1);
        for(int i = 1; i <= n; ++i) sizes[i] = 1;
        weights = w;
    }

    int root(int i) {
        while(parents[i] != i) {
            parents[i] = parents[parents[i]];
            i = parents[i];
        }
        return i;
    }

    int getWeight(int i) {
        int r = root(i);
        return weights[r];
    }

    bool find(int a, int b) {
        return root(a) == root(b);
    }

    void join(int a, int b) {
        int root_a = root(a);
        int root_b = root(b);

        if(root_a == root_b) return;

        if(sizes[root_a] < sizes[root_b]) {
            parents[root_a] = parents[root_b];
            sizes[root_b] += sizes[root_a];
            weights[root_b] += weights[root_a];
        } else {
            parents[root_b] = parents[root_a];
            sizes[root_a] += sizes[root_b];
            weights[root_a] += weights[root_b];
        }
    }
};

struct edge {
    int a;
    int b;
    int weight;

    bool operator<(const edge& other) const {
        return weight < other.weight;
    }
};

edge make_edge(int aa, int bb, int w) {
    edge e;
    e.a = aa;
    e.b = bb;
    e.weight = w;
    return e;
}

int32_t main() {

    int n, m; cin >> n >> m;
    vector<int> x(n+1);
    for(int i = 1; i <= n; ++i) cin >> x[i];

    vector<vector<edge>> graph(n+1, vector<edge>());

    DSU dsu(n, x);
    vector<edge> edges(m);
    for(int i = 0; i < m; ++i)
        cin >> edges[i].a >> edges[i].b >> edges[i].weight;
    sort(edges.begin(), edges.end());

    vector<int> leftBehind(n+1, 0);
    int ret = 0;
    for(int i = 0; i < m; ++i) {
        edge& cur = edges[i];
        if(dsu.find(cur.a, cur.b)) {
            if(cur.weight > dsu.getWeight(cur.a)) {
                ret++;
                leftBehind[dsu.root(cur.a)]++;
            }
        } else {
            int ra = dsu.root(cur.a), rb = dsu.root(cur.b);
            dsu.join(cur.a, cur.b);
            int root = dsu.root(cur.a);
            int nw = dsu.getWeight(cur.a);
            leftBehind[root] = leftBehind[ra] + leftBehind[rb];
            //watch(root);
            //watch(nw);
            //watch(leftBehind[root]);
            //watch(cur.weight);

            if(cur.weight > nw) {
                leftBehind[root]++;
                ret++;
            } else {
                ret -= leftBehind[root];
                leftBehind[root] = 0;
            }
        }
    }

    cout << ret << endl;

    return 0;
}

