struct D{
	ll a,b,c,id;
};
bool operator<(const D &lhs, const D &rhs){//全順序を定めないと，{1,0,0}=={1,1,0}
	if(lhs.c < rhs.c){
		return true;
	}else if(lhs.c == rhs.c){
		if(lhs.id < rhs.id){
			return true;
		}
	}
	return false;
}

ll n,m,ans=0,use[100010]={},y[100010];
