int n,m,par[maxn],hei[maxn];
struct edge{
	int u,v,w;
	bool operator < (const edge &e)const
	{
		return w < e.w;
	}
}el[maxn];
void update(int id,int l,int r,int pos,ll val){
	if(l == r) dat[id] = val;
	else{
		int mid = (l + r) >> 1;
		if(pos <= mid) update(id << 1,l,mid,pos,val);
		else update(id << 1 | 1,mid + 1,r,pos,val);
		dat[id] = min(dat[id << 1],dat[id << 1 | 1]);
	}
}
void ini(){
	for(int i=1;i<=n;i++){
		par[i] = i;
		hei[i] = 1;
	}
}
int fin(int u){
	if(par[u] == u) return u;
	return par[u] = fin(par[u]);
}
void uni(int u,int v,int w){//edge weight = w.
	u = fin(u),v = fin(v);
	if(u == v){
		update(1,1,n,u,x[u] - w);
	}else{
		if(hei[u] < hei[v]){
			par[u] = v;
			update(1,1,n,u,0);
			x[v] += x[u];
			x[u] = 0;
			update(1,1,n,v,x[v] - w);
		}else{
			par[v] = u;
			update(1,1,n,v,0);
			x[u] += x[v];
			x[v] = 0;
			update(1,1,n,u,x[u] - w);
			if(hei[u] == hei[v]) hei[u]++;
		}
	}
}
bool check(int u,int v,int w){//edge weight = w.
	u = fin(u),v = fin(v);
	if(u == v){
		if(x[u] - w < 0) return false;
		update(1,1,n,u,x[u] - w);
	}else{
		if(hei[u] < hei[v]){
			if(x[v] + x[u] - w < 0) return false;
			x[v] += x[u];
			x[u] = 0;
			par[u] = v;
			update(1,1,n,u,0);
			update(1,1,n,v,x[v] - w);
		}else{
			if(x[u] + x[v] - w < 0) return false;
			par[v] = u;
			update(1,1,n,v,0);
			x[u] += x[v];
			x[v] = 0;
			update(1,1,n,u,x[u] - w);
			if(hei[u] == hei[v]) hei[u]++;
		}
	}
	return true;
}
