template <int T_size> class Union_Find{
	int p[T_size];
	LL x[T_size];
	int uni_count;

public:

	Union_Find(vector<LL> V){
		fill(p,p+T_size,-1);
		repp(i,0,V.size()) x[i] = V[i];
		uni_count = 0;
	}

	int boss(int a){
		return p[a] >= 0 ? boss(p[a]) : a;
	}

	tuple<LL,LL,int,int> uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		auto y = get_x(s);
		auto z = get_x(t);
		if(s != t){
			++uni_count;
			if(p[s] > p[t]){
				swap(s,t);
				swap(a,b);
				swap(y,z);
			}
			x[s] += x[t];
			p[s] += p[t];
			p[t] = s;
		}
		return make_tuple(y,z,s,t);
	}

	void cut(LL y, LL z, int s, int t){
		p[s] = -1;
		p[t] = -1;
		x[s] = y;
		x[t] = z;
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int count(){
		return uni_count;
	}

	int member(int a){
		return -p[boss(a)];
	}

	LL get_x(int a){
		return x[boss(a)];
	}
};

