	UnionFind(int n) { data.assign(n, -1); Mdata.assign(n, M::id()); }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			Mdata[x] = M::op(Mdata[x], Mdata[y]);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool same(int x, int y) { return root(x) == root(y); }
	t query(int x) { return Mdata[root(x)]; }
	int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
	int size(int x) { return -data[root(x)]; }
	void add(int x, const t val) { x = root(x); Mdata[x] = M::op(Mdata[x], val); }
	void update(int x, const t val) { x = root(x); Mdata[x] = M::upd(Mdata[x], val); }
};
int main() {
	LL N = in(), M = in();
	VL x(N);
	FOR(i, 0, N) {
		x[i] = in();
	}
	using tp = tuple<LL, LL, LL>;
	vector<tp>edges(M);
	FOR(i, 0, M) {
		int a = in() - 1, b = in() - 1, c = in();
		edges[i] = tp(c, a, b);
	}

	struct info {
		using t = struct node {
			LL xsum, edgecnt;
			node(LL a = 0, LL b = 0) :xsum(a), edgecnt(b) {}
		};
		static t op(const t& a, const t& b) {
			return { a.xsum + b.xsum, a.edgecnt + b.edgecnt };
		}
		static t upd(const t& a, const t& b) {
			return b;
		}
		static t id() { return node(); }
	};
	UnionFind<info> uf(N);
	FOR(i, 0, N) {
		uf.update(i, info::node(x[i], 0));
	}
	SORT(edges);
	LL ans = M;
	for (auto edge : edges) {
		LL c, a, b; tie(c, a, b) = edge;
		uf.unionSet(a, b);
		auto vinfo = uf.query(a);
		vinfo.edgecnt += 1;
		uf.update(a, vinfo);
		if (vinfo.xsum >= c) {
			ans -= vinfo.edgecnt;
			vinfo.edgecnt = 0;
			uf.update(a, vinfo);
		}
	}
	cout << ans << "\n";
}

