class union_find
{
private:
	std::vector<int>parent;
	std::vector<int>rank;
public:
	std::vector<int64_t>sum;
	std::vector<int64_t>edge_num;
	std::vector<int64_t>edge_oknum;

	union_find(int siz)
	{
		parent.resize(siz);
		rank.resize(siz);
		sum.resize(siz);
		edge_num.resize(siz);
		edge_oknum.resize(siz);
		for (int i = 0; i < siz; ++i)
		{
			parent[i] = i;
			rank[i] = 0;
		}
	}
	bool unite(int x, int y)
	{
		int xr = find(x);
		int yr = find(y);
		if (xr == yr) { return false; }
		if (rank[xr] > rank[yr])
		{
		}
		else if (rank[xr] > rank[yr])
		{
			std::swap(xr, yr);
		}
		else if (xr != yr)
		{
			++rank[xr];
		}

		parent[yr] = xr;
		sum[xr] += sum[yr];
		edge_num[xr] += edge_num[yr];
		edge_oknum[xr] += edge_oknum[yr];
		return true;
	}
	int find(int x)
	{
		if (parent[x] == x)
		{
			return x;
		}
		else
		{
			return parent[x] = find(parent[x]);
		}
	}
	bool check(int x, int y)
	{
		return find(x) == find(y);
	}
};



