    return (uft2[w].F==w?w:uft2[w].F=parent2(uft2[w].F));
}

void merge2(ll a,ll b){
    if(parent2(a)==parent2(b)){return;}
    uft2[parent2(b)].S+=uft2[parent2(a)].S;
