public class Uf{
	private int[] arr,hi;
	public List<int>[] li;
	public int all;
	public Uf(int n){
		arr=new int[n];
		hi=new int[n];
		li=new List<int>[n];
		all=n;
		for(int i=0;i<n;i++){
			arr[i]=-1;
			li[i]=new List<int>();li[i].Add(i);
		}
	}
	public bool Union(int a,int b){
		a=Root(a);
		b=Root(b);
		if(a!=b){
			if(hi[a]<hi[b]){
				int v=b;
				b=a;
				a=v;
			}
			arr[a]+=arr[b];
			hi[a]=Math.Max(hi[a],hi[b]+1);
			arr[b]=a;
			all--;
			li[a].AddRange(li[b]);
			return true;
		}
		return false;
	}
	public bool Same(int a,int b){return Root(a)==Root(b);}
	public int Size(int a){return -arr[Root(a)];}
	public int Root(int a){return arr[a]<0?a:arr[a]=Root(arr[a]);}
}
