    sort(edges.begin(), edges.end());
    for (auto i : edges) {
        int c = i.first, a = i.second.first, b = i.second.second;
        merge(a, b);
        int cur = find(a);
        if (c > gp[cur]) postp[cur]++;
        else postp[cur] = 0;
    }
    LL ans = 0;
    for (int i = 1; i <= N; i++) {
        int cur = find(i);
        if (visit[cur]) continue;
        visit[cur] = 1;
        ans += postp[cur];
    }
    printf("%lld\n", ans);
    return 0;
}

