int N, M;
ll xs[100000+10];
struct E {
  int a, b;
  ll c;
  E() {}
  E(int a, int b, ll c) : a(a), b(b), c(c) {}
};
bool operator<(const E& e1, const E& e2) {
  return e1.c < e2.c;
}
E es[100000+10];
struct D {
  int t;
  int d;
  ll s;
  D() {}
  D(int t, int d, ll s) : t(t), d(d), s(s) {}
};
bool operator<(const D& d1, const D& d2) {
  return d1.t < d2.t;
}

struct UF {
  vector<vector<D> > data;
  int nDistinct;
  UF() {}
  UF(int n) {
    data = vector<vector<D> >(n, vector<D>(1, D(-1, -1, 0)));
    REP(i, n) {
      data[i][0].s = xs[i];
    }
  }
  // void init(int n) { data.assign(n, -1); nDistinct = n; }
  // int size(void) const { return nDistinct; }
  // int count(int a) { return -data[rootOf(a)]; }
  // bool isSameGroup(int a, int b) { return rootOf(a) == rootOf(b); }
  int rootOf(int a) {
    D d = data[a].back();
    return d.d >= 0 ? rootOf(d.d) : a;
  }
  D rootD(int a, int t) {
    // auto it = lower_bound(data[a].begin(), data[a].end(), D(t, -1, -1));
    // --it;
    // return it->d >= 0 ? rootD(it->d, t) : *it;
    while(data[a].back().t >= t) {
      data[a].pop_back();
    }
    D d = data[a].back();
    return d.d >= 0 ? rootD(d.d, t) : d;
  }
  ll vsum(int a, int t) {
    return rootD(a, t).s;
  }
  bool unify(int a, int b, int t) {
    int ra = rootOf(a), rb = rootOf(b);
    if(ra == rb) return false;
    if(data[ra].back().d < data[ra].back().d) swap(ra, rb);
    data[rb].push_back(D(t, data[rb].back().d + data[ra].back().d, data[rb].back().s + data[ra].back().s));
    data[ra].push_back(D(t, rb, data[rb].back().s + data[ra].back().s));
    --nDistinct;
    return true;
  }
};


vector<E> g[100000+10];
bool marked[100000+10];
void mark(int u, int c) {
  if(marked[u]) {
    return;
  }
  // cerr << "mark! " << u+1 << endl;
  marked[u] = true;
  for(const E& e : g[u]) {
    if(e.c <= c) {
      mark(e.b, c);
    }
  }
}

int main(void) {
  scanf("%d%d", &N, &M);
  REP(i, N) {
    scanf("%lld", &xs[i]);
  }
  REP(i, M) {
    int a, b;
    ll c;
    scanf("%d%d%lld", &a, &b, &c);
    --a;
    --b;
    es[i] = E(a, b, c);
    g[a].push_back(E(a, b, c));
    g[b].push_back(E(b, a, c));
  }
  sort(es, es + M);
  UF uf(N);
  REP(t, M) {
    uf.unify(es[t].a, es[t].b, t);
  }
  int res = 0;
  for(int t = M-1; t >= 0; --t) {
    const E& e = es[t];
    // cerr << "e: " << e.a+1 << ", " << e.b+1 << ", " << e.c << endl;
    assert(marked[e.a] == marked[e.b]);
    if(marked[e.a]) {
      continue;
    }
    ll sum = uf.vsum(e.a, t+1);
    // cerr << "sum = " << sum << endl;
    if(sum >= e.c) {
      mark(e.a, e.c);
    } else {
      // cerr << "++res" << endl;
      ++res;
    }
  }
  cout << res << endl;
  return 0;
}

