struct UnionFind{
	vector<int> par,rank,cnt;
	V<ll> sum;
	UnionFind(int N){
		par.assign(N,0);
		rank.assign(N,0);
		cnt.assign(N,0);
		sum.assign(N,0);
		rep(i,N) par[i]=i;
	}
	int find(int x){
		if(par[x]==x) return x;
		return par[x]=find(par[x]);
	}
	bool same(int x,int y){
		return find(x)==find(y);
	}
	void unite(int x,int y){
		x=find(x),y=find(y);
		if(x==y) return;
		if(rank[x]<rank[y]) swap(x,y);

		//x becomes root
		par[y]=x;
		sum[x] += sum[y];
		cnt[x] += cnt[y];
		if(rank[x]==rank[y]) rank[x]++;
	}
};
