struct TEdge {
  ll a;
  ll b;
  ll w;
  TEdge() {}
  TEdge(ll a, ll b, ll w):
    a(a),
    b(b),
    w(w)
  {
  }

  void Load() {
    cin >> a >> b >> w;
    a--;
    b--;
  }

  bool operator <(const TEdge& other) const {
    return w < other.w;
  }
};

ll n, m;
ll x[maxn];

ll parent[maxn];
ll weight[maxn];

ll GetRoot(ll v) {
  if (v == parent[v]) return v;
  ll w = GetRoot(parent[v]);
  parent[v] = w;
  return w;
}

ll GetWeight(ll v) {
  ll root = GetRoot(v);
  return weight[root];
}

void Merge(ll v1, ll v2) {
  if (rand() % 2) {
    swap(v1, v2);
  }
  v1 = GetRoot(v1);
  v2 = GetRoot(v2);
  if (v1 == v2) return;
  parent[v2] = v1;
  weight[v1] += weight[v2];
}

bool visited[maxn];

void DFS(ll v, ll maxW, const vector<vector<pair<ll, ll>>>& g, const vector<TEdge>& e, vector<bool>& used) {
  //cerr << "v, maxW = " << v << " "<< maxW << endl;
  if (visited[v]) return;
  visited[v] = true;
  for (auto p : g[v]) {
    ll to = p.first;
    ll id = p.second;
    ll w = e[id].w;
    //cerr << " cur w, id = " << w << " " << id << " " << used[id] << endl;
    if (w > maxW) continue;
    used[id] = true;
    DFS(to, maxW, g, e, used);
  }
}

