  for (ll i = 0; i < m; ++i) {
    g[e[i].a].push_back({e[i].b, i});
    g[e[i].b].push_back({e[i].a, i});
  }

  vector<bool> used(m);

  for (ll i = m; i >= 0; --i) {
    if (!valid[i]) continue;
    //cerr << "DFS!\n";
    DFS(e[i].a, e[i].w, g, e, used);
  }

  //cerr << "Done\n";

  ll result = 0;
  for (ll i = 0; i < m; ++i) if (!used[i]) result++;

  cout << result << endl;

  return 0;
}

