  }
  sort(ALL(edges));
  int use = 0;
  queue<Edge> rem;
  for (Edge e: edges) {
    uf.unite(e.u, e.v);
    if (e.cost <= uf.ref1(e.u)) {
      use++;
      use += uf.ref2(e.u);
      uf.ref2(e.u) = 0;
    } else {
      uf.ref2(e.u)++;
    }
  }
  cout << m - use << endl;
}

