void reet(int x,int R,int bad)
{
    tt[x]=R;sum[R]+=1LL*w[x];
    for(int i=0;i<ad[x].size();i++)
      if(ad[x][i]!=bad&&(!interzis[x][ad[x][i]]))
    {
