class UnionFind2
{

public:

	vector <ll>pairent;
	vector <ll>depth;
	vector <ll>size;
	vector <ll>preans;
	vector <ll>value;
	vector <ll>horyuu;

	UnionFind2(ll Amount) : pairent(Amount, 1), depth(Amount, 1), size(Amount, 1),value(Amount,1),horyuu(Amount,0) {

		for (ll i = 0; i < Amount; i++) {
			pairent[i] = i;
		}
	}


	ll FindPairent(ll x) {
		if (pairent[x] == x)return x;
		else return pairent[x] = FindPairent(pairent[x]);
	}


	ll Merge(ll x, ll y,ll cost) {
		x = FindPairent(x);
		y = FindPairent(y);

		if (x != y) {
			if (depth[x] > depth[y]) {
				pairent[y] = pairent[x];
				horyuu[x] += horyuu[y] + 1;
				horyuu[y] = 0;
				value[x] += value[y];
				value[y] = 0;

				if (cost <= value[x]) {
					ans += horyuu[x];
					horyuu[x] = 0;
				}

				return size[x] += size[y];
			}
			else {
				pairent[x] = pairent[y];
				horyuu[y] += horyuu[x] + 1;
				horyuu[x] = 0;
				value[y] += value[x];
				value[x] = 0;

				if (cost <= value[y]) {
					ans += horyuu[y];
					horyuu[y] = 0;
				}


				if (depth[x] == depth[y]) {
					depth[y] ++;
				}
				return size[y] += size[x];
			}
		}
		else {
			horyuu[x]++;
			if (cost <= value[x]) {
				ans += horyuu[x];
				horyuu[x] = 0;
			}
			return -1;
		}
	}



	bool IsSame(ll x, ll y) {
		if (FindPairent(x) == FindPairent(y))return true;
		else return false;
	}


	ll GetSize(ll x) {
		x = FindPairent(x);
		return size[x];
	}


};


