#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define pb push_back
#define mp make_pair
#define ldb long double
#define mt make_tuple
const int N=200050;
ll X[N];
int p[N],sz[N];
vector<int> E[N];
bool was[N];
int Find(int x){ return p[x]==x?x:Find(p[x]);}
void Union(int x, int y)
{
	x=Find(x);y=Find(y);
	if(sz[x]<sz[y]) swap(x,y);
	X[x]+=X[y];
	p[y]=x;
	sz[x]+=sz[y];
	E[x].pb(y);
}
void Mark(int u)
{
	if(was[u]) return;
	was[u]=1;
	//printf("mark:%i\n",u);
	for(int v:E[u]) if(!was[v]) Mark(v);
}
int sol,bsol,n,m;
int U[N],V[N],W[N];
ll XX[N];
void input()
{
	scanf("%i %i",&n,&m);
	for(int i=1;i<=n;i++) scanf("%lld",&XX[i]);
	for(int i=1;i<=m;i++) scanf("%i %i %i",&U[i],&V[i],&W[i]);
}
void output()
{
	printf("%i\n",sol);
}
void Solve()
{
	int u,v,w;
	for(int i=1;i<=n;i++) sz[i]=1,p[i]=i,X[i]=XX[i],E[i].clear(),was[i]=0;
	vector<pair<int,pair<int,int> > > edges;
	vector<pair<ll,int> > ws;
	for(int i=1;i<=m;i++) u=U[i],v=V[i],w=W[i],edges.pb(mp(w,mp(u,v)));
	sort(edges.begin(),edges.end());
	for(int i=0;i<edges.size();i++)
	{
		u=edges[i].second.first;
		v=edges[i].second.second;
		//printf("%i %i\n",u,v);
		if(Find(u)!=Find(v)) Union(u,v);
		ws.pb(mp(X[Find(u)],Find(u)));
	}
	int ans=0;
	for(int i=m-1;i>=0;i--)
	{
		u=edges[i].second.first;
		v=edges[i].second.second;
		w=edges[i].first;
		if(w>ws[i].first && !was[u])
		{
			//printf("rem:%i %i\n",u,v);

			ans++;
		}
		else
		{
			Mark(ws[i].second);
		}
	}
	sol=ans;
}
void Run()
{
	input();
	Solve();
	output();
}
void BruteForce()
{
	bsol=m;
	for(int mask=0;mask<1<<m;mask++)
	{
		for(int i=1;i<=n;i++) p[i]=i,sz[i]=1,X[i]=XX[i];
		for(int i=1;i<=m;i++) if((mask>>(i-1))&1)
		{
			if(Find(U[i])!=Find(V[i])) Union(U[i],V[i]);
		}
		bool ok=1;
		int cnt=0;
		for(int i=1;i<=m;i++) if((mask>>(i-1))&1)
		{
			if(W[i]>X[Find(U[i])]) ok=0;
			cnt++;
		}
		if(ok) bsol=min(bsol,m-cnt);
	}
}
void MakeTestCase()
{
	n=rand()%10+1;
	m=rand()%10+n-1;
	for(int i=1;i<=n;i++) XX[i]=rand()%100+1;
	for(int i=1;i<=m;i++) U[i]=rand()%n+1,V[i]=rand()%n+1,W[i]=rand()%100+1;
}
bool Compare()
{
	return sol==bsol;
}
void Print()
{
	printf("%i %i\n",n,m);
	for(int i=1;i<=n;i++) printf("%i ",XX[i]);
	printf("\n");
	for(int i=1;i<=m;i++) printf("%i %i %i\n",U[i],V[i],W[i]);
	printf("Solve: %i\n",sol);
	printf("Brute: %i\n",bsol);
}
double GetTime(){ return (ldb)clock()/CLOCKS_PER_SEC;}
double s_time,e_time,d_time;
void Start(){ s_time=GetTime();}
void Stop(){ e_time=GetTime();d_time=e_time-s_time;}
void Test()
{
	cout<<fixed<<setprecision(4);
	int work=100000;
	double max_time=0;
	bool speed_only=0;
	for(int i=1;i<=work;i++)
	{
		MakeTestCase();
		if(!speed_only) BruteForce();
		Start();
		Solve();
		Stop();
		if(!speed_only && !Compare())
		{
			Print();
			return;
		}
		max_time=max(max_time,d_time);
		cout<<i<<":OK, max time so far="<<max_time<<"\n";
	}
	cout<<":D\n";
}
int main()
{
	bool test=0;
	if(test) Test();
	else Run();
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n,m,i,j,sz[100005],f[100005],sum[100005],fa[100005],px[100005],py[100005],pz[100005],vis[100005],tag[100005];
struct ed
{
	int id,z;
}a[100005];
bool cmp(ed x,ed y){return x.z<y.z;}
int fnd(int x)
{
	if (fa[x]==x) return x;
	return fnd(fa[x]);
}
stack<int> sx,sy;
void merge(int x,int y)
{
	x=fnd(x);y=fnd(y);
	if (sz[x]>sz[y]) swap(x,y);
	sum[y]+=sum[x];
	fa[x]=y;
	if (sz[x]==sz[y]) sz[y]++;
	sx.push(x);
	sy.push(y);
}
void chexiao()
{
	int x=sx.top(),y=sy.top();
	sx.pop();sy.pop();
	fa[x]=x;sum[y]-=sum[x];
	if (tag[y]) tag[x]=1;
}
int main()
{
	scanf("%d%d",&n,&m);
	for (i=1;i<=n;i++) {scanf("%d",&sum[i]);}
	for (i=1;i<=m;i++)
	{
		scanf("%d%d%d",&px[i],&py[i],&pz[i]);
		a[i]=(ed){i,pz[i]};
	}
	for (i=1;i<=n;i++) {sz[i]=1;fa[i]=i;}
	sort(a+1,a+m+1,cmp);
	for (i=1;i<=m;i++)
	{
		int t=a[i].id;
		if (fnd(px[t])!=fnd(py[t]))
		{
			merge(px[t],py[t]);
			vis[t]=1;
		}
	}
	int ans=0;
	for (i=m;i;i--)
	{
		int t=a[i].id;
		if (tag[fnd(px[t])]||sum[fnd(px[t])]>=pz[t]) tag[fnd(px[t])]=1; else ans++;
		if (vis[t]) chexiao();
	}
	cout<<ans<<endl;
	return 0;
}

