}

void unio(int u, int v, int typreb){
    if(sz[v] > sz[u]){
        swap(sz[v],sz[u]);
    }
    if(sz[v] == sz[u]){
        sz[u]++;
    }
    d[u].cost += d[v].cost;
    d[u].black += d[v].black;
    d[u].black*=typreb;
    d[u].black+=typreb;
    p[v] = u;
}


