    for(i=1;i<=m;i++)
    {
        if(finds(v[i].a)!=finds(v[i].b))
        {
            if(rg[finds(v[i].a)]>=rg[finds(v[i].b)])
                mare[i]=v[i].a;
            else mare[i]=v[i].b;
            unite(finds(v[i].a),finds(v[i].b));
            apm[i]=1;
            ad[v[i].a].push_back(v[i].b);
            ad[v[i].b].push_back(v[i].a);
        }
    }
    long long sumtot;
    for(i=m;i>=1;i--)
    {
        if(v[i].a==mare[i])
            swap(v[i].a,v[i].b);
        if(tt[v[i].b]==v[i].a) swap(v[i].a,v[i].b);
        if(apm[i]&&sum[finds(v[i].a)]<v[i].c)
        {
            sumtot=sum[finds(v[i].a)];
            sum[v[i].a]=0;
            reet(v[i].a,v[i].a,v[i].b);
            interzis[v[i].b][v[i].a]=1;
            sum[finds(v[i].b)]=sumtot-sum[v[i].a];
        }
    }
    ans=m;
    for(i=1;i<=m;i++)
       if(finds(v[i].a)==finds(v[i].b)&&sum[finds(v[i].a)]>=v[i].c)
         ans--;
    cout<<ans;
    return 0;
}

