struct UnionFind {
  vector<int> parent;
  vector<ll> weight;
  vector<ll> ok;
  UnionFind (int n) : parent(n, -1), weight(n, 0), ok(n, 0) {}
  int root(int x) { return parent[x] < 0 ? x : root(parent[x]); }
  bool merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (parent[y] < parent[x]) swap(x, y);
    if (parent[x] == parent[y]) --parent[x];
    parent[y] = x;
    weight[x] += weight[y];
    return true;
  }
  ll ok_max(int x) { return parent[x] < 0 ? ok[x] : max(ok[x], ok_max(parent[x])); }
};


