  sort(all(e));
  UF uf(n+1);
  rep(i, 1, n+1) uf.dat[i] = x[i];
  vvl br = vv(m, 2, 0, ll);
  re(i, m){
    ll a = e[i][1], b = e[i][2];
    if(!uf.same(a, b)) br[i][0] = uf.get(a), br[i][1] = uf.get(b);
    else br[i][0] = -1, br[i][1] = uf.get(a);
    uf.unite(a, b);
  }
  set<ll> lock;
  ll ans = 0;
  for(int i=m-1;i>=0;i--){
    //std::cout << i << " " << e[i][0] << '\n';
    //if(br[i][0]==-1) std::cout << -1 << " " << uf.get(e[i][1]) << '\n';
    //else std::cout << uf.get(e[i][1]) << " " << uf.get(e[i][2])  << '\n';
    if(lock.find(e[i][1])!=lock.end()) continue;


    if(br[i][0]==-1){
      if(uf.get(e[i][1])<e[i][0]) ans++;
      else lock.insert(uf.find(e[i][1]));
    }else{
      if(uf.get(e[i][1])<e[i][0]) {
        ans++;
        uf.decompose(e[i][1]);
      }else lock.insert(uf.find(e[i][1]));
    }
  }
  std::cout << ans << '\n';
  return 0;
}

