    for(int i=0;i<m;++i) {
        cin >> a >> b >> c;
        edges.push_back(Edge(a-1, b-1, c));
        G[a-1].emplace_back(b-1, c);
        G[b-1].emplace_back(a-1, c);
    }
    sort(all(edges));

    UnionFind uf = UnionFind(n);
    vector<Edge> candidates; // 連結成分内最大コストの辺の候補たち
    for(int i=0;i<m;++i) {
        Edge e = edges[i];
        uf.unite(e);
        if(uf.get_nodes_cost(e.from) >= e.cost) {
            candidates.push_back(e);
        }
    }

    if(candidates.empty()) {
        cout << 0 << endl;
        return 0;
    }

    int i = min(candidates.back().from, candidates.back().to);
    int j = max(candidates.back().from, candidates.back().to);
    used[Pii(i, j)] = 1;
    ans.emplace(i, j);
    dfs(i, candidates.back().cost);
    dfs(j, candidates.back().cost);

    cout << m-ans.size() << endl;


}

