int N,M;
LL X[100000];
vector<pair<pair<LL,int>, pair<int,int> > > hen;
bool ok[100000];
vector<pair<int,int> > tonari[100000];
int G = 1;
int groupN[100000], groupE[100000];
LL groupS[100000];

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> M;
    for(int i=0; i<N; i++){
        cin >> X[i];
        groupN[i] = 0;
        groupS[0] += X[i];
    }
    for(int i=0; i<M; i++){
        int a,b,y;
        cin >> a >> b >> y;
        a--; b--;
        hen.push_back(MP(MP(y,i), MP(a, b)));
        tonari[a].push_back(MP(b, i));
        tonari[b].push_back(MP(a, i));
        ok[i] = true;
        groupE[i] = 0;
    }
    sort(hen.begin(), hen.end());
    reverse(hen.begin(), hen.end());
    int ans = 0;
    for(int i=0; i<hen.size(); i++){
        if(groupS[groupE[hen[i].first.second]] < hen[i].first.first){
            ans++;
            ok[hen[i].first.second] = false;
            bool already[100000] = {};
            already[hen[i].second.first] = true;
            queue<int> que;
            que.push(hen[i].second.first);
            int sum = X[hen[i].second.first];
            while(!que.empty()){
                int now = que.front();
                que.pop();
                for(int i=0; i<tonari[now].size(); i++){
                    if(ok[tonari[now][i].second] && !already[tonari[now][i].first]){
                        already[tonari[now][i].first] = true;
                        sum += X[tonari[now][i].first];
                        que.push(tonari[now][i].first);
                        if(tonari[now][i].first == hen[i].second.second) break;
                    }
                }
            }
            if(!already[hen[i].second.second]){
                groupS[G] = groupS[groupE[hen[i].first.second]] - sum;
                groupS[groupE[hen[i].first.second]] = sum;
                que.push(hen[i].second.second);
                while(!que.empty()){
                    int now = que.front();
                    que.pop();
                    for(int i=0; i<tonari[now].size(); i++){
                        groupE[tonari[now][i].second] = G;
                        if(ok[tonari[now][i].second] && !already[tonari[now][i].first]){
                            already[tonari[now][i].first] = true;
                            que.push(tonari[now][i].first);
                            groupN[tonari[now][i].first] = G;
                        }
                    }
                }
                G++;
            }
        }
    }
    cout << ans << endl;

    return 0;
}


