{
   uint32_t w, x, y, z;
   XorShift(uint32_t seed = time(nullptr))
   {
       w = seed;
       x = w << 13;
       y = (w >> 9) ^ (x << 6);
       z = y >> 7;
   }

   uint32_t rand()
   {
       uint32_t t = x ^ (x << 11);
       x = y;
       y = z;
       z = w;
       return w = (w ^ (w >> 19) ^ (t ^ (t >> 8)));
   }

   // [min,max] の整数値乱数
   int randInt(int min = 0, int max = 0x7FFFFFFF)
   {
