//状態
struct STATE {
  vector<int> pos;
  vvi num;

  STATE() {
    pos.resize(n);
    num.resize(w);
  }
};

// 状態の初期化
void init (STATE& state) {
  for(int i=0;i<n;++i) {
    state.pos[i] = i%w;
    state.num[i%w].push_back(i);
  }
}

// 状態遷移
void update (STATE& state) {
  int num1 = 0, num2 = 0;
  while(state.pos[num1] == state.pos[num2]) {
    num1 = randgen.randInt(0, n-1);
    num2 = randgen.randInt(0, n-1);
  }

  //cout << "upd" << endl;

  auto it1 = find(state.num[state.pos[num1]].begin(), state.num[state.pos[num1]].end(), num1);
  auto it2 = find(state.num[state.pos[num2]].begin(), state.num[state.pos[num2]].end(), num2);
  //cout << distance(state.num[state.pos[num1]].begin(), it1) << " " << distance(state.num[state.pos[num2]].begin(), it2) << endl;
  //cout << num1 << endl;
  //printv(state.num[state.pos[num1]]);
  //cout << num2 << endl;
  //printv(state.num[state.pos[num2]]);
  //cout << "A" << endl;
  state.num[state.pos[num1]].erase(it1);
  //cout << "B" << endl;
  state.num[state.pos[num2]].erase(it2);
  //cout << "C" << endl;

  auto it3 = upper_bound(state.num[state.pos[num1]].begin(), state.num[state.pos[num1]].end(), num2);
  //it3--;
  auto it4 = upper_bound(state.num[state.pos[num2]].begin(), state.num[state.pos[num2]].end(), num1);
  //it4--;
  //cout << distance(state.num[state.pos[num1]].begin(), it3) << " " << distance(state.num[state.pos[num2]].begin(), it4) << endl;
  state.num[state.pos[num1]].insert(it3, num2);
  state.num[state.pos[num2]].insert(it4, num1);

  swap(state.pos[num1], state.pos[num2]);

  return;
}

// 状態のスコア計算
int score (STATE& state) {

  int minh = n/w;

  int res = 0;

  for(int i=0;i<minh;++i) {
    vi point(k);
    for(int j=0;j<w;++j) {
      //cout << SZ(state.num[j]) << endl;
      //assert(SZ(state.num[j]) == minh);
      //cout << i << ":" << j << endl;
      //cout << state.num[j][i] << endl;
      point[col[state.num[j][i]]] += val[state.num[j][i]];
    }
    int ma = 0;
    for(int j=0;j<SZ(point);++j) {
      ma = max(ma, point[j]);
    }
    res += ma;
  }
  return res;
}

