int N, M;
vector<long long> X;

using pint = pair<int,int>;
using Edge = pair<long long, pint>;

int main () {
    while (cin >> N >> M) {
        X.resize(N);
        vector<Edge> edges;
        for (int i = 0; i < N; ++i) cin >> X[i];
        for (int i = 0; i < M; ++i) {
            int a, b;
            long long w;
            cin >> a >> b >> w;
            --a, --b;
            edges.push_back(Edge(w, pint(a, b)));
        }
        sort(edges.begin(), edges.end());

        // queries
        vector<int> left(M, 0), right(M, M + 1);
        while (true) {
            map<int, vector<int> > distToQueries;
            bool update = false;
            for (int q = 0; q < M; ++q) {
                if (right[q] - left[q] > 1) {
                    update = true;
                    int mid = (left[q] + right[q]) / 2;
                    distToQueries[mid].push_back(q);
                }
            }
            if (!update) break;
            UnionFind uf(N, X);
            for (auto it = distToQueries.begin(); it != distToQueries.end(); ++it) {
                int mid = (it->first);
                for (int i = 0; i < mid; ++i) {
                    int u = edges[i].second.first, v = edges[i].second.second;
                    uf.merge(u, v);
                }
                for (auto q : it->second) {
                    Edge e = edges[q];
                    int u = edges[q].second.first, v = edges[q].second.second;
                    if (uf.issame(u, v) && 
                        uf.get(edges[q].second.first) >= e.first) right[q] = mid;
                    else left[q] = mid;
                }

            }
        }

        vector<vector<int> > G(M);
        queue<int> que;
        vector<int> dist(M, -1);
        for (int i = 0; i < M; ++i) {
            if (right[i] == M + 1) que.push(i), dist[i] = 0;
            else G[right[i]-1].push_back(i);
        }

        int res = que.size();
        while (!que.empty()) {
            int v = que.front(); que.pop();
            for (auto nv : G[v]) {
                if (dist[nv] == -1) {
                    dist[nv] = dist[v] + 1;
                    que.push(nv);
                    ++res;
                }
            }
        }
        cout << res << endl;
    }   
}

