		E[i]=edge(a,b,y,i);
		G[a].push_back(edge2(b,y,i));
		G[b].push_back(edge2(a,y,i));
	}
	sort(E,E+M);
	REP(i,N){
		par[i]=i;
		sm[i]=X[i];
	}
	REP(i,M){
		auto e=E[i];
		if(fndpar(e.s)!=fndpar(e.t)){
			unite(e.s,e.t);
		}
		if(sm[fndpar(e.s)]>=e.cst){
			koho[e.inx]=true;
		}
	}
	reverse(E,E+M);
	int ans=0;
	memset(used,-1,sizeof(used));
	REP(i,M){
		auto e=E[i];
		if(used[e.inx]!=-1)continue;
		if(koho[e.inx]){
			dfs(e.s,e.cst);
		}else{
			used[e.inx]=0;
			ans++;
		}
	}
	cout<<ans<<endl;
}

