namespace LinkCutTree{//{{{
    typedef ll Cost;
    struct Node{
        typedef Node* Ptr;
        Ptr ch[2]; // {left, right}. left : ancestor
        Ptr par;
        Node(Cost v) : par(0), size(1){ ch[0] = ch[1] = 0; init(v); }
        pair<int, int> id;
        string name; // 頂点名
        // path に対する操作で実装する所. //{{{
        // 注: splay の root は常に push 済みであるように.

        Cost val;
        bool reversed;

        inline void init(Cost v){ reversed = false; val = sum = v;}

        inline void push(){//{{{
            if(reversed){
                swap(ch[0], ch[1]);
                reversed = false;
                rep(i, 2) if(ch[i]) ch[i]->reversed ^= true;
            }
        }//}}}
        inline void update(){//{{{
            push();
        }//}}}

        //}}}
        // 部分木に対する操作で実装する所.//{{{
        int size;
        Cost sum;
        inline int get_size(){ expose(); return size - (ch[0] ? ch[0]->size : 0); }
        inline int get_sum(){ expose(); return sum - (ch[0] ? ch[0]->sum : 0); }
        inline void remove_ch(Ptr p, int lr){//{{{
            push();
            if(lr) ch[lr>0] = 0;
            if(p){
                size -= p->size;
                sum -= p->sum;
                p->par = 0;
                p->push();
            }
            update();
        }//}}}
        inline void add_ch(Ptr p, int lr){//{{{
            push();
            if(p && p->par) p->par->remove_ch(p, p->state());
            if(p){
                sum += p->sum;
            }
            if(lr) ch[lr>0] = p;
            if(p) p->par = this;
            update();
        }//}}}
        //}}}
        // splay 木に対する操作. 外から弄らない. //{{{
        inline int state(){//{{{
            if(par && par->ch[0] == this) return -1;
            if(par && par->ch[1] == this) return +1;
            return 0;
        }//}}}
        inline void rotate(){//{{{
            Ptr p = par, pp = p->par;
            if(pp) pp->push(); p->push(); push();
            int lr = state(), plr = p->state();
            Ptr c = ch[lr<0];
            //if(pp) pp->remove_ch(p, plr); コイツと
            p->remove_ch(this, lr);
            //remove_ch(c, -lr); コイツは無くても大丈夫なハズ.
            p->add_ch(c, lr);
            add_ch(p, -lr);
            if(pp) pp->add_ch(this, plr);
        }//}}}
        inline void splay(){//{{{
            while(state()){
                int s = state() * par->state();
                if(s) (s == 1 ? par : this)->rotate();
                rotate();
            }
            push();
        }//}}}
        //}}}
        // path 分解に対する操作. 外から呼んでよい. //{{{
        // コイツを仮想木の親までもって行く.
        // 右の子は切る. i.e. この仮想木はコイツから根までの path.
        inline Ptr expose(){//{{{
            Ptr res = 0;
            for(Ptr p = this; p; p = p->par){
                p->splay();
                p->add_ch(res, 1);
                res = p;
            }
            splay();
            add_ch(ch[1], 0);
            return res;
        }//}}}
        // コイツが根になるよう, (元の木を) reroot する.
        inline void evert(){//{{{
            expose();
            reversed ^= true;
        }//}}}
        // コイツを根とする部分木を切り出す.
        inline void cut(){//{{{
            expose();
            if(ch[0]) remove_ch(ch[0], -1);
        }//}}}
        // p の下にコイツを含む木をくっつける.
        inline void link_to(Ptr p){//{{{
            p->expose();
            expose();
            p->add_ch(this, 0);
        }//}}}
        // コイツを含む木の根を探す.
        inline Ptr find_root(){//{{{
            expose();
            Ptr p = this;
            while(p->ch[0]) p = p->ch[0];
            p->expose();
            return p;
        }//}}}
        // あればコイツと u の LCA. 無ければ 0.
        inline Ptr lca(Ptr u){//{{{
            expose();
            Ptr res = u->expose();
            return par ? res : 0;
        }//}}}
        //}}}
    };
};//}}}

bool solve(){
    int n, m;
    cin >> n >> m;
    UnionFind uf(n);
    UnionFind uf2(n);
    vector<tuple<int, int, int>> es;
