struct UnionFind {
    std::vector<int> data;
    std::vector<ll> w, max_w;

    UnionFind() {}
    UnionFind(int size) : data(size, -1), w(size), max_w(size, -1) {}

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) std::swap(x, y);
            data[x] += data[y]; data[y] = x;
            w[x] += w[y];
            max_w[x] = max(max_w[x], max_w[y]);
        }
        else max_w[x] = max(max_w[x], max_w[y]);
        return x != y;
    }
    bool find(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -data[root(x)]; }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
};

