int main() {
  int N, M;
  cin >> N >> M;
  vector<long long> X(N);
  for_each(begin(X), end(X), [](auto &e){cin >> e;});
  union_find<long long> uf(X);
  vector<tuple<long long, int, int>> edges;
  for (int i = 0; i < M; i++) {
    int a, b;
    long long y;
    cin >> a >> b >> y;
    a--;
    b--;
    edges.emplace_back(y, a, b);
  }
  sort(begin(edges), end(edges));
  int live = 0;
  for (auto e : edges) {
    int a, b;
    long long w;
    tie(w, a, b) = e;
    uf.unite(a, b);
    const int par = uf.find(a);
    if (uf.weight(par) >= w) {
      live += uf.edge_count_[par];
      uf.edge_count_[par] = 0;
    }
  }
  cout << M - live << endl;
}

