  UnionFindTree union_find(x);
  vector<Edge> bad_edges;

  int ans = m;
  repeat (i, m) {
    Edge& e = edges[i];
    union_find.Unite(e.end1, e.end2);

    // cerr << "weight 0 " << union_find.Weight(0) << endl;

    if (e.weight > union_find.Weight(e.end1)) {
      bad_edges.push_back(e);
    }
    while (!bad_edges.empty()) {
