template <class T>
class partially_persistent_union_find {
public:
  using value_type = T;

private:
  int size;
  value_type last_query;
  const value_type inf;
  std::vector<int> parent;
  std::vector<value_type> updated;
  std::vector<std::vector<std::pair<value_type, lint>>> history;

public:
  partially_persistent_union_find(): inf(std::numeric_limits<value_type>::max()) { }
  partially_persistent_union_find(int size_): 
    inf(std::numeric_limits<value_type>::max())
  { init(size_);}

  void init(int size_) {
    size = size_;
    last_query = std::numeric_limits<value_type>::min();
    parent.assign(size_, 1);
    updated.assign(size_, inf);
    history.assign(size_, { { last_query, 0 } });
    for (int i = 0; i < size_; ++i) {
      history[i].back().second = X[i];
    }
  }

  int find_parent(int i, const value_type &t) const {
    if (updated[i] > t) {
      return i;
    }
    else {
      return find_parent(parent[i], t);
    }
  }

  int component_weight(int i, const value_type &t) const {
    i = find_parent(i, t);
    return (--std::upper_bound(history[i].begin(), history[i].end(), std::make_pair(t, std::numeric_limits<lint>::max()))) -> second;
  }

  bool unite(int i, int j, const value_type &t) {
    i = find_parent(i, last_query);
    j = find_parent(j, last_query);
    last_query = t;
    if (i == j) {
      return false;
    }
    if (parent[i] < parent[j]) {
      std::swap(i, j);
    }
    parent[i] += parent[j];
    parent[j] = i;
    updated[j] = last_query;
    lint tmp = history[i].back().second + history[j].back().second;
    history[i].emplace_back(last_query, tmp);
    return true;
  }

};

void dfs(int v) {
  if (done[v]) {
    return;
  }
  done[v] = true;
  for (auto e: graph[v]) {
    if (std::get<3>(e) > now) {
      continue;
    }
    dfs(std::get<2>(e));
  }
}

