        }
    }
    ext[node]=tim-1;
}
const int N=100005;
int seg[4*N],lazy[4*N];
void build(int node,int start,int end){
    if(start==end){
        seg[node]=1;
        return;
    }
    int mid=(start+end)>>1;
    build(node<<1,start,mid);
    build(node<<1|1,mid+1,end);
    seg[node]=seg[node<<1]+seg[node<<1|1];
}
void update(int node,int start,int end,int l,int r,int val){
    if(lazy[node]!=0){
        seg[node]=lazy[node];
        if(start!=end){
            lazy[node<<1]=lazy[node];
            lazy[node<<1|1]=lazy[node];
        }
        lazy[node]=0;
    }
    if(start>end || start>r || end<l) return;
    if(l<=start && end<=r){
        seg[node]=val;
        if(start!=end){
            lazy[node<<1]=val;
            lazy[node<<1|1]=val;
        }
        return;
    }
    int mid=(start+end)>>1;
    update(node<<1,start,mid,l,r,val);
    update(node<<1|1,mid+1,end,l,r,val);
    seg[node]=seg[node<<1]+seg[node<<1|1];
}
int query(int node,int start,int end,int l,int r){
    if(start>end || start>r || end<l) return 0;
    if(lazy[node]!=0){
        seg[node]=lazy[node];
        if(start!=end){
            lazy[node<<1]=lazy[node];
            lazy[node<<1|1]=lazy[node];
        }
        lazy[node]=0;
    }
    if(start>=l && end<=r) return seg[node];
    int mid=(start+end)>>1;
    int q1=query(node<<1,start,mid,l,r);
    int q2=query(node<<1|1,mid+1,end,l,r);
    return q1+q2;
}
int seg2[N<<2];
int query2(int node,int start,int end,int l,int r){
    if(l<=start && r>=end) return seg2[node];
    if(r<start || l>end || l>r) return 0;
    int mid=(start+end)>>1;
    int ans1=query2(node<<1,start,mid,l,r);
    int ans2=query2(node<<1|1,mid+1,end,l,r);
    return (ans1+ans2);
}
void update2(int node,int start,int end,int pos,int val){
    if(start==end){
        seg2[node]+=val;
        return;
    }
    int mid=(start+end)>>1;
    if(start<=pos && pos<=mid) update2(node<<1,start,mid,pos,val);
    else update2(node<<1|1,mid+1,end,pos,val);
    seg2[node]=seg2[node<<1]+seg2[node<<1|1];
}
void solve(){
    cin>>n>>m;
    rep(i,1,n+1) cin>>x[i],par[i]=i;
    rep(i,0,m){
        int u,v,w;
        cin>>u>>v>>w;
        edges.pb({w,{u,v}});
    }
    sort(all(edges));
    for(auto i:edges){
        if(fp(i.y.x)==fp(i.y.y)) continue;
        merge(i.y.x,i.y.y);
        taken.insert(i);
        adj[i.y.x].pb(i.y.y);
        adj[i.y.y].pb(i.y.x);
        cost=i.x;
    }
    dfs(1);
    build(1,1,n);
    reverse(all(edges));
    for(auto i:edges){
        if(d[i.y.x]<d[i.y.y]) swap(i.y.x,i.y.y);
        int g=query(1,1,n,entry[i.y.x],entry[i.y.x]);
        int val=s[g]-query2(1,1,n,entry[g]+1,ext[g]);
        if(i.x>val){
            ans++;
            if(taken.count(i)==0) continue;
            int u=i.y.x,v=i.y.y;
            if(d[u]>d[v]) swap(u,v);
            update(1,1,n,entry[v],ext[v],v);
            update2(1,1,n,entry[v],s[v]);
        }
    }
    cout<<ans<<endl;
}

