const i64 MAXN = 100005;

map<i64, i64> parent[MAXN];

void make_set(i64 v) {
    parent[v][0] = v;
}

pair<i64, i64> find_set(i64 v, i64 ts) {
    auto it = parent[v].upper_bound(ts);
    it--;

    if (v == it->second) {
        return *it;
    }

    auto r = find_set(it->second, ts);
    if (it->second != r.second) {
        parent[v][ts] = r.second;
    }
    return r;
}

pair<i64, i64> union_sets(i64 a, i64 b, i64 ts) {
    auto na = find_set(a, ts);
    auto nb = find_set(b, ts);
    if (na.second != nb.second) {
        parent[b][ts] = na.second;
    }
    return na;
}

