    assert(0 <= from && from < n && 0 <= to && to < n);
    g[from].push_back(edges.size());
    g[to].push_back(edges.size());
    edges.push_back({from,to,cost});
  }
};

template <typename T>
class undigraph : public graph<T> {
  public:
  using graph<T>::edges;
  using graph<T>::g;
  using graph<T>::n;

  undigraph(int n) : graph<T>(n) {
  }

  void add(int from, int to, T cost = 1) {
    assert(0 <= from && from < n && 0 <= to && to < n);
    g[from].push_back(edges.size());
    g[to].push_back(edges.size());
    edges.push_back({from, to, cost});
  }
};

class UnionFind{
private:
  std::vector<int> par;
  std::vector<int> rnk;
  std::vector<LL> wei;
public:
  std::vector<LL> cap;
  UnionFind(int n,LL *x):par(n),rnk(n),wei(n),cap(n){
    for(int i=0;i<n;i++){
      par[i]=i;
      rnk[i]=0;
      wei[i]=x[i];
    }
  }

  int find(int x){
    if(par[x] == x)
      return x;
    else
      return find(par[x]);
  }

  LL weight(int x){
    return wei[find(x)];
  }

  void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)
      return;

    if(rnk[x] < rnk[y])swap(x,y);
    par[y] = x;
    if(rnk[x]==rnk[y]) rnk[x]++;
    wei[x]+=wei[y];
  }

  bool same(int x,int y){
    return find(x) == find(y);
  }

  int capfind(int x){
    if(x==par[x])return cap[x]?x:-1;
    int y = capfind(par[x]);
    if(y!=-1)return y;
    return cap[x]?x:-1;
  }
};

