#define DUMP(a) REP(d,a.size()){cout<<a[d];if(d!=a.size()-1)cout<<" ";else cout<<endl;}
#define ALL(v) v.begin(),v.end()
#define UNIQUE(v)  sort(ALL(v));v.erase(unique(ALL(v)),v.end());
#define pb push_back

class union_find {
public:
	union_find(vector<ll> v) {
		init(v);
	}
	void init(vector<ll> v) {
		ll n = v.size();
		par_.resize(n);
		REP(i, n) {
			par_[i].first = -1;
			par_[i].second.first = v[i];
			par_[i].second.second = 0;
		}
		return;
	}

	int root(int x) {
		return par_[x].first < 0 ? x : par_[x].first = root(par_[x].first);
	}

	bool unite(int x, int y) {
		x = root(x); y = root(y);
		if(x == y) {
			return false;
		} else {
			if(par_[x].first < par_[y].first) {
				par_[x].first += par_[y].first;
				par_[x].second.first += par_[y].second.first;
				par_[x].second.second += par_[y].second.second;
				par_[y].first = x;
			} else {
				par_[y].first += par_[x].first;
				par_[y].second.first += par_[x].second.first;
				par_[y].second.second += par_[x].second.second;
				par_[x].first = y;
			}
			return true;
		}
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void add_edge(int x) {
		par_[root(x)].second.second++;
	}

	ll get_edge(int x) {
		return par_[root(x)].second.second;
	}

	void rem_edge(int x) {
		par_[root(x)].second.second = 0;
	}

	ll get_sum(int x) {
		return par_[root(x)].second.first;
	}

	int size(int x) {
		return -par_[root(x)].first;
	}

private:
	std::vector<pair<int, pll>> par_;
	// first: 親
	// second.first: 重み和
	// second.second: 未確定辺
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll n, m;
	cin >> n >> m;
	vector<ll> x(n);
	REP(i, n) cin >> x[i];
	vector<pair<ll, pll>> edge;
	REP(i, m) {
		ll a, b, y;
		cin >> a >> b >> y;
		a--; b--;
		edge.pb(make_pair(y, pll(a, b)));
	}
	sort(ALL(edge));
	ll ans = 0;
	union_find uf(x);
	REP(i, m) {
		ll a = edge[i].second.first, b = edge[i].second.second;
		ll cost = edge[i].first;
		if(uf.same(a, b)) {
			if(uf.get_sum(a) >= cost) {
				ans++;
			} else {
				uf.add_edge(a);
			}
		} else {
			uf.unite(a, b);
			if(uf.get_sum(a) >= cost) {
				ans++;
				ans += uf.get_edge(a);
				uf.rem_edge(a);
			} else {
				uf.add_edge(a);
			}
		}
	}
	cout << m - ans << endl;
	return 0;
}

