  }

  void init(int aN)
  {
    par.clear(); cnt.clear(); nodeCost.clear(); unusedEdgeCnt.clear();
    par.resize(aN); cnt.resize(aN); nodeCost.resize(aN); unusedEdgeCnt.resize(aN);
    for (size_t i = 0; i < aN; i++) {
      par[i] = i;
      cnt[i] = 1;
      nodeCost[i] = X[i];
      unusedEdgeCnt[i] = 0;
    }
  }

  int find(int aX)
  {
    if(aX == par[aX]) return aX;
    else return par[aX] = find(par[aX]);
  }

  bool same(int aX, int aY)
  {
    return find(aX) == find(aY);
  }

  int size(int aX)
  {
    return cnt[find(aX)];
  }

  void addEdge(int aX, int aY, int cost)
  {
    aX = find(aX);
    aY = find(aY);

    if(aX == aY) {
      if(cost > nodeCost[aY]) {
        unusedEdgeCnt[aY]++;
      } else {
        unusedEdgeCnt[aY] = 0;
      }
    } else {
      //merge
      par[aX] = aY;
      cnt[aY] += cnt[aX];
      nodeCost[aY] += nodeCost[aX];
      unusedEdgeCnt[aY] += unusedEdgeCnt[aX];

      if(cost > nodeCost[aY]) {
        unusedEdgeCnt[aY]++;
      } else {
        unusedEdgeCnt[aY] = 0;
      }
    }
  }

  int getUnused(int x) {
    return unusedEdgeCnt[find(x)];
  }

  vector<int> par;
  vector<int> cnt;
  vector<int> nodeCost;
  vector<int> unusedEdgeCnt;
};

