class UnionFind {
public:
  int n;
  vi par; //親
  vi ran; //木の深さ
  vi num; //要素数
  vl ma;
  vl sum;
  vl ok_num;
  vl ng_num;

  UnionFind(int _n) {
    n = _n;
    par.resize(n); ran.resize(n); num.resize(n);
    ma.resize(n); sum.resize(n); ok_num.resize(n); ng_num.resize(n);
    for (int i = 0; i < n; i++) {
      par[i] = i; ran[i] = 0; num[i] = 1;
      sum[i] = x[i];
      ma[i] = 0;
      ok_num[i] = ng_num[i] = 0;
    }
  }

  //木の根を求める
  int find(int x) {
    if (par[x] == x) {
      return x;
    }
    else {
      return par[x] = find(par[x]);
    }
  }

  //xとyの属する集合を併合
  void unite(int x, int y, ll c) {
    x = find(x); y = find(y);
    int numsum = num[x] + num[y];
    ll s_sum = sum[x] + sum[y];
    ll ng_sum = ng_num[x] + ng_num[y];
    ll ok_sum = ok_num[x] + ok_num[y];
    if (x == y) {
      if (c <= sum[x]) ok_num[x]++;
      else ng_num[x]++;
      if (c > ma[x]) ma[x] = c;
      return;
    }
    if (ran[x]<ran[y]) {
      par[x] = y;
    }
    else {
      par[y] = x;
      if (ran[x] == ran[y]) {
        ran[x]++;
      }
    }
    x = find(x);
    num[x] = numsum;
    sum[x] = s_sum;
    ma[x] = c;
    ng_num[x] = ng_sum;
    ok_num[x] = ok_sum;
    if (ma[x] <= s_sum) {
      ok_num[x] += ng_num[x] + 1;
      ng_num[x] = 0;
    }
    else {
      ng_num[x]++;
    }
  }

  //xとyが同じ集合に属するか否か
  bool same(int x, int y) {
    return find(x) == find(y);
  }

};


