    if(g.edges[g.g[f][i]].cost<=cost){
      acm++;
      solve(g.edges[g.g[f][i]].from ^ g.edges[g.g[f][i]].to ^ f,cost,g);
    }
  }
}

int main(){
  cin>>n>>m;
  REP(i,m)visited[i]=false;
  undigraph<LL> g(n);
  REP(i,n)cin>>x[i];
  LL y;
  int a,b;
  REP(i,m){
    cin>>a>>b>>y;a--;b--;
    g.add(a,b,y);
  }
  vector<int> index(m);
  iota(index.begin(), index.end(), 0);
  sort(index.begin(), index.end(),[&](int x,int y){return g.edges[x].cost<g.edges[y].cost;});
  UnionFind un(n,x);
  REP(i,m){
    un.unite(g.edges[index[i]].from,g.edges[index[i]].to);
    if(un.weight(g.edges[index[i]].from) >= g.edges[index[i]].cost){
      un.cap[un.find(g.edges[index[i]].from)]=g.edges[index[i]].cost;
    }
  }
  REP(i,n){
    int f=un.capfind(i);
    if(f!=-1)solve(f,un.cap[f],g);
  }
  cout<<m-acm<<endl;
  return 0;
}

