//Union-Find
class UnionFind {
private:
	std::vector<int> parent;
	std::vector<int> height;
	std::vector<int> m_size;

public:
	UnionFind(int size_) : parent(size_), height(size_, 0), m_size(size_, 1) {
		for (int i = 0; i < size_; ++i) parent[i] = i;
	}
	void init(int size_) {
		parent.resize(size_);
		height.resize(size_, 0);
		m_size.resize(size_, 0);
		for (int i = 0; i < size_; ++i) parent[i] = i;
	}
	int find(int x) {
		if (parent[x] == x) return x;
		return parent[x] = find(parent[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		int t = size(x) + size(y);
		m_size[x] = m_size[y] = t;
		if (height[x] < height[y]) parent[x] = y;
		else parent[y] = x;
		if (height[x] == height[y]) ++height[x];
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		if (parent[x] == x) return m_size[x];
		return size(parent[x] = find(parent[x]));
	}
};

signed main() {
	INIT;

	VAR(int, n, m);
	VEC(int, x, n);
	VEC_ROW(int, m, a, b, y);

	{
		struct S { int a, b, y; };
		V<S> s(m);
		REP(i, m) s[i] = S{ a[i], b[i],y[i] };
		std::sort(ALL(s), [&](S& l, S& r) {
			return l.y < r.y;
		});
		REP(i, m) {
			a[i] = --s[i].a;
			b[i] = --s[i].b;
			y[i] = s[i].y;
		}
	}

	V<int> lo(n, 0), hi(n, m);

	bool changed = true;
	while (changed) {
		changed = false;
		UnionFind uf(n);
		V<int> cost(n);
		REP(i, n) cost[i] = x[i];
		V<int> max(n, -INFINT);

		VV<int> me(m + 1);
		REP(i, n) {
			if (hi[i] - lo[i] > 1) {
				changed = true;
				me[(lo[i] + hi[i]) / 2].emplace_back(i);
			}
		}

		REP(ii, m + 1) {
			int i = ii - 1;
			if (i >= 0){
				if (!uf.same(a[i], b[i])) {
					int c = cost[uf.find(a[i])] + cost[uf.find(b[i])];
					int ma = std::max({ y[i], max[uf.find(a[i])], max[uf.find(b[i])] });
					uf.unite(a[i], b[i]);
					cost[uf.find(a[i])] = c;
					max[uf.find(a[i])] = ma;
				}
				else {
					CHMAX(max[uf.find(a[i])], y[i]);
				}
			}

			for (auto& q : me[ii]) {
				int par = uf.find(q);
				if (max[par] <= cost[par]) lo[q] = ii;
				else hi[q] = ii;
			}
		}
	}

	//SHOWVECTOR(lo);

	int ans = m;
	REP(i, m) {
		int t = std::min(lo[a[i]], lo[b[i]]) - 1;
		if (i <= t) --ans;
	}
	OUT(ans)BR;
	return 0;
}

