	void init(){
		rep(i,100010){
			par[i] = i;
			r[i] = 0;
			par_cost[i] = 0;
			cnt[i] = 1;
			ret[i] = i;
		}
	}
	int find(int x){
		if(par[x] == x)return par[x];
		else find(par[x]);
	}
