	}
	void unit(int x,int y,ll c){
		x = find(x);
		y = find(y);
		if(x == y)return;
		if(r[x] < r[y]){
			par[x] = y;
			par_cost[x] = c;
			cnt[y] += cnt[x];
		}
		else {
			par[y] = x;
			par_cost[y] = c;
			cnt[x] += cnt[y];
			if(r[x] == r[y]){
				r[x] ++;
			}
		}
	}
	bool used[100010];
	void dfs_init(){
		rep(i,100010){
			used[i] = false;
		}
	}
	void dfs(int v){
		used[v] = true;
		if(!used[par[v]])dfs(par[v]);
		if(par_cost[v] <= ret[par[v]]){
			ret[v] = ret[par[v]];
		}
	}
