struct UnionFind{
   vector<int> par;
   vector<ll> sum;
   UnionFind(int n):par(n,-1),sum(n){
       rep(i,n)sum[i]=a[i];
   }
   int find(int x){
       if(par[x]<0)return x;
       return par[x]=find(par[x]);
   }
   bool unite(int x,int y){
       x=find(x);
       y=find(y);
       if(x==y)return false;
       if(par[x]>par[y]){
           par[y]+=par[x];
           sum[y]+=sum[x];
           par[x]=y;
       }
       else{
           par[x]+=par[y];
           sum[x]+=sum[y];
           par[y]=x;
       }
       return true;
   }

   bool same(int x,int y){
       return find(x)==find(y);
   }
   ll get(int x){
       return sum[find(x)];
   }
};

