		{
			if(Find(U[i])!=Find(V[i])) Union(U[i],V[i]);
		}
		bool ok=1;
		int cnt=0;
		for(int i=1;i<=m;i++) if((mask>>(i-1))&1)
		{
			if(W[i]>X[Find(U[i])]) ok=0;
			cnt++;
		}
		if(ok) bsol=min(bsol,m-cnt);
	}
}
