class UnionFind{ // findSet(a), isSameSet(a,b), unionSet(a,b), sizeOfSet(a)
private:
  vi parent, rank, size, val, sm;
public:
  UnionFind(ll n, vi &_val) {
    rank.assign(n, 0); parent.assign(n,0); size.assign(n, 1);
    val = _val; sm.assign(n,0);
    rep(i,0,n) sm[i] = val[i];
    rep(i,0,n) parent[i] = i;
  }
  ll findSet(ll i) {
    if (parent[i] == i) return i;
    else return parent[i] = findSet(parent[i]);
  }
  bool isSameSet(ll i, ll j) { return findSet(i) == findSet(j); }
  void unionSet(ll i, ll j) {
    if (!isSameSet(i, j)){
      ll x = findSet(i); ll y = findSet(j);
      if (rank[x] < rank[y]){
        parent[x] = y; size[y] += size[x];
        sm[y] += sm[x];
      }
      else {
        parent[y] = x;
        size[x] += size[y];
        sm[x] += sm[y];
        if (rank[x] == rank[y]) rank[x]++;
      }
    }
  }
  ll sizeOfSet(ll i) { return size[findSet(i)]; }
  ll smSet(ll i) { return sm[findSet(i)]; }
};

