template<class T>
struct union_find{
    int N;
    vector<int> par, rank;
    vector<int> time;
    vector<T> sz;

    union_find(int N, int M) : N(N), par(N + 1), rank(N + 1, 1), time(M + 1, 0), sz(N + 1, 1){
        for(int i = 0; i <= N; ++i) par[i] = i;
    }

    void init(int n, T s){sz[n] = s;}

    int find(int v){
        return (v == par[v] ? v : find(par[v]));
    }

    void unite(int x, int y, int t){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] > rank[y]){
            time[t] = y;
            par[y] = x;
            sz[x] += sz[y];
        }else{
            time[t] = x;
            par[x] = y;
            sz[y] += sz[x];
            if(rank[x] == rank[y]) rank[y]++;
        }
    }

    void cut(int t){
        int u = time[t];
        sz[par[u]] -= sz[u];
        par[u] = u;
    }

    T get_sz(int x){
        return sz[find(x)];
    }
};

