            if(x[a]>=cost)ok[a]++;
            else ng[a]++;
            return 1;
        }
        if(data[a]>data[b])swap(a,b);
        data[a]+=data[b];
        data[b]=a;
        x[a]+=x[b];
        if(x[a]>=cost){
            ok[a]+=ng[a]+ok[b]+ng[b]+1;
            ng[a]=ok[b]=ng[b]=0;
        }
        else{
            ok[a]+=ok[b];
            ng[a]+=ng[b]+1;
            ok[b]=ng[b]=0;
        }
        return 0;
    }
    bool Find(ll a,ll b){return root(a)==root(b);}
    ll root(ll a){return data[a]<0?a:root(data[a]);}
};
