    valid[u] = true;
    for(auto v: etree[u]) dfs(v);
    etree[u].clear();
}
void mergeS(int x,int y,int e){
    x = findS(x); y = findS(y);
    if(x == y){
        etree[e].push_back(ce[x]);
        ce[x] = e;
        return;
    }

    etree[e].push_back(ce[x]);
    etree[e].push_back(ce[y]);
    if(r[x] > r[y]){
        w[x] += w[y];
        p[y] = x;
        ce[x] = e;
    }else{
        w[y] += w[x];
        p[x] = y;
        ce[y] = e;
    }

    if(r[x] == r[y]) r[y] += 1;
}

