    }
    sort(ew, ew+m);
    unionfind uf(n, vw);
    for(int i=0;i<m;++i){
        uf.merge(ew[i].second.first, ew[i].second.second);
    }
    int ans = 0;
    for(int t=m;t>0;--t){
        int u, v, w;
        w = ew[t-1].first;
        tie(u, v) = ew[t-1].second;
        if(ok[u]) continue;
