vector<int> E[N];
bool was[N];
int Find(int x){ return p[x]==x?x:Find(p[x]);}
void Union(int x, int y)
{
	x=Find(x);y=Find(y);
	if(sz[x]<sz[y]) swap(x,y);
	X[x]+=X[y];
	p[y]=x;
	sz[x]+=sz[y];
	E[x].pb(y);
}
void Mark(int u)
{
	if(was[u]) return;
	was[u]=1;
	//printf("mark:%i\n",u);
	for(int v:E[u]) if(!was[v]) Mark(v);
}
