class UnionFind{
    public:
        ll size;
        vector<ll> rank;
        vector<ll> parent;
        vector<ll> cnt;
        vector<ll> weights;

        UnionFind(ll N){
            this->size = N;
            rank = vector<ll>(N, 0);
            parent = vector<ll>(N);
            cnt = vector<ll>(N, 0);
            weights = nodes;
            iota(parent.begin(), parent.end(), 0ll);
        }

        ~UnionFind(){
        }

        ll find(ll child){
            return (child == parent[child] ? child : parent[child] = find(parent[child]));
        }

        ll unit(ll x, ll y, ll w){
            ll ret = 0;
            x = find(x); 
            y = find(y);
            if(x == y){
                if(weights[x] >= w) ret++;
                else cnt[x]++;
                return ret;
            }
            if(rank[x] < rank[y]) swap(x, y);
            parent[y] = x;
            rank[x] += (rank[x] == rank[y]);
            weights[x] += weights[y];
            if(weights[x] >= w){
                ret = cnt[x] + cnt[y] + 1;
                cnt[x] = cnt[y] = 0;
            }else{
                cnt[x] = cnt[x] + cnt[y] + 1;
            }
            return ret;
        }

        bool same(ll x, ll y){
            return (find(x) == find(y));
        }

};

