class union_find{
public:
  int uf[100010];
  union_find(int n){
    for(int i=0;i<n;i++){
      uf[i]=-1;
    }
  }
  int root(int i)
  {
    return uf[i]<0?i:uf[i]=root(uf[i]);
  }
  int unite(int i,int j)
  {
    if(-uf[i]<-uf[j]){
      uf[i]=j;
      return j;
    }
    else if(-uf[i]>-uf[j]){
      uf[j]=i;
      return i;
    }
    else{
      uf[i]=j;
      uf[j]--;
      return j;
    }
  }
};

int main()
{
  int n,m;
  scanf("%d%d",&n,&m);
  vector<long long> d(n);
  for(int i=0;i<n;i++){
    scanf("%lld",&d[i]);
  }
  vector<pair<long long,pair<int,int> > > E(m);
  for(int i=0;i<m;i++){
    scanf("%d%d%lld",&(E[i].second.first),&(E[i].second.second),&(E[i].first));
    E[i].second.first--,E[i].second.second--;
  }
  sort(E.begin(),E.end());
  vector<int> A(2*n-1,-1),B(2*n-1,-1);
  vector<long long> X(2*n-1),Y(2*n-1),R(2*n-1),L(2*n-1);
  for(int i=0;i<n;i++){
    X[i]=d[i],Y[i]=0;
  }
  int t=n;
  union_find uf(n);
  vector<int> P(n);
  for(int i=0;i<n;i++)P[i]=i;
  vector<bool> use(m);
  for(int s=0;s<m;s++){
    int a=E[s].second.first,b=E[s].second.second;
    long long c=E[s].first;
    a=uf.root(a);
    b=uf.root(b);
    if(a!=b){
      int rt=uf.unite(a,b);
      X[t]=X[P[a]]+X[P[b]];
      Y[t]=c;
      R[t]=P[a];
      L[t]=P[b];
      P[rt]=t;
      t++;
      use[s]=true;
    }
    else{
      use[s]=false;
    }
  }
  queue<int> Q;
  Q.push(2*n-2);
  int ans=0;
  vector<long long> q(n);
  while(!Q.empty()){
    int i=Q.front();
    Q.pop();
    //printf("%d %lld %lld\n",i,X[i],Y[i]);
    if(X[i]>=Y[i]){
      queue<int> Q2;
      Q2.push(i);
      while(!Q2.empty()){
	int j=Q2.front();
	Q2.pop();
	if(j<n){
	  q[j]=X[i];
	}
	else{
	  Q2.push(R[j]);
	  Q2.push(L[j]);
	}
      }
    }
    else{
      Q.push(R[i]);
      Q.push(L[i]);
      ans++;
    }
  }
  for(int s=0;s<m;s++){
    if(!use[s]){
      if(E[s].first>min(q[E[s].second.first],q[E[s].second.second])){
	ans++;
      }
    }
  }
  printf("%d\n",ans);
  return 0;
}

