class UnionFind {
private:
    static const int MAX = 100100;
    info par[MAX];
    int r[MAX];
public:
    UnionFind(int n = MAX) {
        for (int i = 0; i < n; i++) {
            info v;
            v.w_sum = x[i];
            v.num_e = 0;
            v.num_inval_e = 0;
            v.y_max = 0;
            v.parent = -1;
            par[i] = v;
            r[i] = 0;
        }
    }

    int find(int x) {
        if (par[x].parent < 0) {
            return x;
        } else {
            return par[x].parent = find(par[x].parent);
        }
    }

    void unite(int x, int y, ll yw) {
        x = find(x);
        y = find(y);
        if (x == y) {
            par[x].num_e++;
            par[x].y_max = max(par[x].y_max, yw);
            if (par[x].y_max > par[x].w_sum) par[x].num_inval_e++;
            else par[x].num_inval_e = 0;
            return;
        }
        if (r[x] < r[y]) {
            par[y].w_sum += par[x].w_sum;
            par[y].num_e += par[x].num_e + 1;
            par[y].y_max = max(max(par[y].y_max, par[x].y_max), yw);
            if (par[y].y_max > par[y].w_sum) par[y].num_inval_e += par[x].num_inval_e + 1;
            else par[y].num_inval_e = 0;
            par[x].parent = y;
        } else {
            par[x].w_sum += par[y].w_sum;
            par[x].num_e += par[y].num_e + 1;
            par[x].y_max = max(max(par[x].y_max, par[y].y_max), yw);
            if (par[x].y_max > par[x].w_sum) par[x].num_inval_e += par[y].num_inval_e + 1;
            else par[x].num_inval_e = 0;
            par[y].parent = x;
            if (r[x] == r[y]) r[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    bool valid(int x) {
        int v = find(x);
        return par[v].w_sum >= par[v].y_max;
    }

    int num_e(int x) {
        return par[find(x)].num_e;
    }
    int num_inval_e(int x) {
        return par[find(x)].num_inval_e;
    }

    info get(int x) {
        return par[find(x)];
    }
};

int solve() {
    sort(ALL(es), [](const edge& e0, const edge& e1){ return e0.y < e1.y; });
    UnionFind uf(n);
    int res = 0;
    for (int i = 0; i < m; i++) {
        edge e = es[i];
        if (!uf.same(e.a, e.b)) {
            int inval_e = uf.num_inval_e(e.a) + uf.num_inval_e(e.b);
            uf.unite(e.a, e.b, e.y);

            if (uf.valid(e.a)) res += inval_e+1;
        } else {
            int inval_e = uf.num_inval_e(e.a);
            uf.unite(e.a, e.b, e.y);
            if (uf.valid(e.a)) res++;
        }
        //info v = uf.get(e.a);
        //cerr << temp << " " << v.w_sum << " "  <<v.num_e << " " << v.y_max << endl;
    }
    return m - res;
}

