template <class T = int>
class UF {
    T *par;
    std::vector<std::deque<T>> s;

    public:
    UF(T n) : par(new T[n]), s(std::vector<std::deque<T>>(n)) {
        for (T i = 0; i < n; i++) {
            par[i] = i;
            s[i].push_back(i);
        }
    }
    ~UF() { delete[] par; }

    T root(T x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool same(T x, T y) {
        return root(x) == root(y);
    }

    void unite(T x, T y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            par[x] = y;
            for (auto v : s[x]) s[y].push_back(v);
            s[x].clear();
        }
    }

    std::deque<T> get(T x) {
        return s[root(x)];
    }
};

