    std::sort(es.begin(), es.end());
    UF<> uft(n);
    std::vector<bool> cand(m), done(m);
    std::vector<std::deque<int>> r(m);
    for (int i = 0; i < m; i++) {
        auto a = es[i].second.first, b = es[i].second.second;
        auto y = es[i].first;
        auto xx = w[uft.root(a)] + (uft.same(a, b) ? 0 : w[uft.root(b)]);
        uft.unite(a, b);
        w[uft.root(a)] = xx;
        if (y <= xx) {
            cand[i] = true;
            r[i] = uft.get(i);
        }
    }

    int ret = 0;
    for (int i = m - 1; i >= 0; i--) {
        if (done[i]) continue;
        if (!cand[i]) { ret++; continue; }
        for (auto v : r[i]) done[v] = true;
    }

    std::cout << ret << std::endl;

    return 0;
}

