struct dsu {
	int par[N];
	long long sum[N];
	void init() {
		for (int i = 1; i <= n; ++i) par[i] = i, sum[i] = a[i];
	}
	int anc(int p) { return p == par[p] ? p : par[p] = anc(par[p]); }
	bool join(int p, int q) {
		p = anc(p), q = anc(q);
		if (p == q) return false;
		par[p] = q;
		sum[q] += sum[p];
		sum[p] = 0;
		return true;
	}
} d;

