        A[b - 1].emplace_back(a - 1, y);
    }
    auto comp = [](const edge &lhs, const edge &rhs){
        if(lhs.cost < rhs.cost) return true;
        else if(lhs.cost < rhs.cost) return false;

        if(lhs.u < rhs.u) return true;
        else if(lhs.u > rhs.v) return false;

