			sizes[i] = 0;
			//			ns[i].PB(pr(0,1));
			talls[i] = 1;
		}
	}
	int find(int x, int t = 0) {
		if (unions[x] == x || sents[x] > t) return x;
		return find(unions[x], t);

	}
	int minisize(int x) {
		if (x == unions[x]) return sizes[x];
		return minisize(find(x));
	}
	bool isFriend(int a, int b, int t = 0) {
		return find(a, t) == find(b, t);
	}
	void unite(int a, int b,LL y, int t = 0) {
		a = find(a, t);
		b = find(b, t);
		if (sizes[a] < sizes[b]) unite(b, a, t);
		if (isFriend(a, b, t)) {
			sizes[a] += 1;
			MX(maxim[a], y);
			if (maxim[a] <= X[a]) {
				anses += sizes[a];
				sizes[a] = 0;
			}
		//	cout << X[a] << endl;
			return;
		}
		else {

			MX(maxim[a], maxim[b]);
			MX(maxim[a], y);
			sizes[a] += sizes[b]+1;
			X[a] += X[b];
			if (maxim[a] <= X[a]) {
				anses += sizes[a];
				sizes[a] = 0;
			}
			sents[b] = t;
			talls[a] = max(talls[a], talls[b] + 1);
			unions[b] = a;
			dists[b] = 1;
			//			ns[a].PB(pr(t,ns[b].back().second+ns[a].back().second));
		}
	}
};
