struct unionfind {
	ll N;
	vector<ll> par;
	vector<ll> sz;//根の場合、その木のサイズ
	vector<ll> ed;

	unionfind(ll N0) {
		N = N0;
		par.assign(N + 1, -1);
		sz.assign(N + 1, 1);
		ed.assign(N + 1, 0);
		repn(i, N) ed[i] = i;
	}

	ll root(ll x) {
		if (par[x] == -1) { return x; }
		par[x] = root(par[x]);
		return par[x];
	}

	bool same(ll x, ll y) {
		return root(x) == root(y);
	}

	void unite(ll x, ll y, ll i) {
		ll a = root(x);
		ll b = root(y);
		if (a != b) {
			par[a] = b; sz[b] += sz[a];
			ed[b] = i;
		}

	}

	ll size(ll x) {
		ll r = root(x);
		return sz[r];
	}

	ll edge(ll x) {
		ll r = root(x);
		return ed[r];
	}
};


