    while(!q.empty()){
      int now=q.front();q.pop();
      r(j,v[now].size()){
        int nex=v[now][j].fi;
        int cost=v[now][j].se;
        if(U.same(now,nex))continue;
        if(U.num(now)>=cost){
          q.push(nex);
          U.unite(nex,i,0);
        }
      }
    }
  }

  r(i,n){


    int weight = U.num(i);
    int sum = 0;

    set<int>st;
    map<int,int>M,M2;
    vector<P2>A;
    vector<int>B;

    r(j,v[i].size()){

      int nex=v[i][j].fi;
      int cost=v[i][j].se;

      if(U.same(nex,i))continue;

      if(!st.count(U.find(nex))){
        B.push_back(U.find(nex));
        M[U.find(nex)] = U.num(nex);
        M2[U.find(nex)] = cost;
      }

      else{
        M2[U.find(nex)] = min(M2[U.find(nex)],cost);
      }
    }

    r(j,B.size()){
      A.push_back(P2(M2[B[j]],P(M[B[j]],B[j])));
      sum+=M[B[j]];
    }

    sort(A.begin(),A.end());

    for(int j=A.size()-1;j>=0;j--){

      if(sum+weight<A[j].fi){
        sum -= A[j].se.fi;
        continue;
      }
      for(int k=j;k>=0;k--){
        U.unite(i,A[k].se.se,(int)0);
      }
      break;
    }

  }
}
  int ANS=0;
  r(i,m){
    int x=a[i];
    int y=b[i];
    if(U.same(x,y)&&U.num(x)>=c[i])continue;
    ANS++;
  }
