  }
  vector<pair<int, pair<int, int>>> edg(m);
  for (int i = 0; i < m; i++) {
    int a, b, w;
    cin >> a >> b >> w;
    a--;
    b--;
    edg[i] = {w, {a, b}};
  }
  sort(edg.begin(), edg.end());
  int usd = 0;
  for (auto e : edg) {
    int w = e.first;
    int a = e.second.first;
    int b = e.second.second;
    int r = djs.find(a);
    djs.unite(r, b);
    djs.addCnt(r);
    if (w <= djs.getWt(r)) {
      usd += djs.getCnt(r);
      djs.clrCnt(r);
    }
  }
