class unionfind
{
public:
	int par[SIZE];
	int ran[SIZE];
	ll ren[SIZE];
	vector<int>ko[SIZE];
	bool isact[SIZE];
	int st[SIZE];
	void init()
	{
		for (int i = 0; i < SIZE; i++)
		{
			par[i] = i;
		}
	}
	int find(int a)
	{
		if (a == par[a])return a;
		else return find(par[a]);
	}
	int actfind(int a)
	{
		if (a == par[a] || !isact[a])return a;
		else return actfind(par[a]);
	}
	void unite(int a, int b)
	{
		a = find(a);
		b = find(b);
		if (a == b)return;
		if (ran[a]>ran[b])
		{
			par[b] = a;
			ren[a] += ren[b];
			ko[a].push_back(b);
		}
		else
		{
			par[a] = b;
			ren[b] += ren[a];
			ko[b].push_back(a);
		}
		if (ran[a] == ran[b])ran[b]++;
	}
	void activate(int a)
	{
		for (int i = st[a]; i < ko[a].size(); i++)
		{
			if (isact[ko[a][i]])continue;
			activate(ko[a][i]);
			isact[ko[a][i]] = true;
		}
		st[a] = ko[a].size();
	}
};
