    int temp = 0;
    for (int i = 0; i < m; i++) {
        edge e = es[i];
        if (!uf.same(e.a, e.b)) {
            int val_e = 0, inval_e = 0;
            if (uf.valid(e.a)) val_e += uf.num_e(e.a);
            else inval_e += uf.num_e(e.a);
            if (uf.valid(e.b)) val_e += uf.num_e(e.b);
            else inval_e += uf.num_e(e.b);

            uf.unite(e.a, e.b, e.y);
            if (uf.valid(e.a)) temp += uf.num_e(e.a) - val_e;
            else temp -= val_e;
        } else {
            int val_e = 0, inval_e = 0;
            if (uf.valid(e.a)) val_e += uf.num_e(e.a);
            else inval_e += uf.num_e(e.a);

            uf.unite(e.a, e.b, e.y);
            if (uf.valid(e.a)) temp += uf.num_e(e.a) - val_e;
            else temp -= val_e;            
        }
        res = max(res, temp);
        //info v = uf.get(e.a);
        //cerr << temp << " " << v.w_sum << " "  <<v.num_e << " " << v.y_max << endl;
    }
    return m - res;
}

