class DisjointSet{
public:
  vector<int> rank;
  vector<pair<int,ll>> p;

  DisjointSet(){}
  DisjointSet(int size){
    rank.resize(size,0);
    p.resize(size,make_pair(0,0));
    for(int i=0;i<size;i++) makeSet(i);
  }

  void makeSet(int x){
    p[x]=make_pair(x,X[x]);
    rank[x]=0;
  }

  bool same(int x,int y){
    return findSet(x)==findSet(y);
  }

  void unite(int x,int y){
    link(findSet(x),findSet(y));
  }

  void link(int x,int y){
    if(rank[x]>rank[y]){
      p[y].first=x;
      p[x].second+=p[y].second;
    }else{
      p[x].first=y;
