        rank[y]++;
      }
    }
  }

  int findSet(int x){
    if(x!=p[x].first){
      p[x].first=findSet(p[x].first);
    }
    return p[x].first;
  }

  ll findSecond(int x){
    return p[findSet(x)].second;
  }
};

