struct comp {
    vector <pair <int, int>> ver;
    vector <pair <pair <int, int>, int>> edge;
    vector <node> pred;
    void build() {
        map <int, int> ma;
        pred.resize(sz(ver) + 2);
        for (int i = 0; i < sz(ver); i++) {
            ma[ver[i].X] = i;
            pred[i].mxedge = 0;
            pred[i].cntedge = 0;
            pred[i].pr = i;
            pred[i].weight = ver[i].Y;
            pred[i].siz = 0;
            pred[i].rez = 0;
        }
        for (int i = 0; i < sz(edge); i++) {
            edge[i].X.X = ma[edge[i].X.X];
            edge[i].X.Y = ma[edge[i].X.Y];
        }
        sort(edge.begin(), edge.end(), cmp);
    }
    int fans = 0;
    int get(int x) {
        while (pred[x].pr != x)
            x = pred[x].pr;
        return x;
    }
    void un(int x, int y, int h) {
        x = get(x);
        y = get(y);
        if (x == y) {
            pred[x].mxedge = h;
            pred[x].cntedge++;
            if (pred[x].mxedge <= pred[x].weight)
                fans++;
            return;
        }
        if (pred[x].siz == pred[y].siz) {
            pred[x].siz++;
        }
        int kk = 0;
        if (pred[x].mxedge <= pred[x].weight) {
            fans -= pred[x].cntedge;
            kk += pred[x].cntedge;
        }
        if (pred[y].mxedge <= pred[y].weight) {
            fans -= pred[y].cntedge;
            kk += pred[y].cntedge;
        }
        if (pred[x].siz > pred[y].siz) {
            pred[y].pr = x;
            pred[x].cntedge += pred[y].cntedge + 1;
            pred[x].weight += pred[y].weight;
            pred[x].mxedge = h;
            if (pred[x].mxedge <= pred[x].weight) {
                fans += pred[x].cntedge;
                fans -= pred[x].rez;
                fans -= pred[y].rez;
                pred[x].rez = 0;
            } else {
                fans += kk;
                pred[x].rez += kk + pred[y].rez;
            }
        } else {
            pred[x].pr = y;
            pred[y].cntedge += pred[x].cntedge + 1;
            pred[y].weight += pred[x].weight;
            pred[y].mxedge = h;
            if (pred[y].mxedge <= pred[y].weight) {
                fans += pred[y].cntedge;
                fans -= pred[x].rez;
                fans -= pred[y].rez;
                pred[y].rez = 0;
            } else {
                fans += kk;
                pred[y].rez += kk + pred[x].rez;
            }
        }
    }
    int getans() {
        vector <pair <pair <int, int>, int>> gl;
        int mx = 0;
        for (int i = 0; i < sz(edge); i++) {
            un(edge[i].X.X, edge[i].X.Y, edge[i].Y);
            mx = max(mx, fans);
        }
        return mx;
    }
};

