class union_find {
private:
    vector<int> parent, rank, gs;
    int size;

public:
    int count_group;
    union_find() = default;
    union_find(int n) { init(n); }

    void init(int n) {
        size = n;
        count_group = n;
        parent.resize(size);
        rank.assign(size, 0);
        gs.assign(size, 1);
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x)
            return x;
        else
            return parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            parent[x] = y;
            gs[y] += gs[x];
        } else {
            parent[y] = x;
            gs[x] += gs[y];
            if (rank[x] == rank[y]) ++rank[x];
        }
        --count_group;
    }

    bool is_same_group(int x, int y) {
        return find(x) == find(y);
    }

    int group_size(int x) {
        return gs[find(x)];
    };
};

void solve() {
    //const i64 mod = 1'000'000'007;
    i64 N,M;
    cin >> N >> M;

    vector<i64> X(N);
    rep(i,0,N) cin >> X[i];

    vector<i64> A(M),B(M),Y(M);
    rep(i,0,M){
        cin >> A[i] >> B[i] >> Y[i];
        --A[i];
        --B[i];
    }

    using tup=tuple<i64,i64,i64>;
    using pq=priority_queue<tup,vector<tup>,greater<tup>>;

    union_find uf(N);
    vector<i64> sum(N),maxe(N);
    pq undecided,hold_diff;
    vector<pq> hold_same(N);
    set<i64> ok,no;
    i64 cnt=0,ans=0;

    rep(i,0,N){
        sum[i]=X[i];
        ok.insert(i);
    }
    rep(i,0,M){
        undecided.emplace(make_tuple(Y[i],A[i],B[i]));
    }

    while(true) {
        if(!undecided.empty()){
            auto e=undecided.top();
            undecided.pop();

            i64 c, u, v;
            tie(c, u, v) = e;
            u = uf.find(u);
            v = uf.find(v);
            if (u == v) {
                if (sum[u] >= c) {
                    ++cnt;
                    chmax(maxe[u], c);
                    if (no.size() == 0) chmax(ans, cnt);
                } else {
                    hold_same[u].push(make_tuple(c, u, v));
                }
            } else {
                if (sum[u] + sum[v] >= c) {
                    ++cnt;
                    uf.unite(u, v);
                    if (v == uf.find(u)) swap(u, v);
                    // uが親
                    ok.erase(v);
                    no.erase(v);

                    sum[u] += sum[v];
                    chmax(maxe[u],maxe[v]);
                    chmax(maxe[u], c);
                    if (sum[u] >= maxe[u]) {
                        no.erase(u);
                        ok.insert(u);
                    }
                    if (no.size() == 0) chmax(ans, cnt);

                    while(!hold_same[v].empty()){
                        auto e=hold_same[v].top();
                        hold_same[v].pop();
                        hold_same[u].push(e);
                    }

                    while(!hold_same[u].empty()){
                        auto c2=get<0>(hold_same[u].top());
                        if(c2>sum[u]) break;

                        hold_same[u].pop();
                        ++cnt;
                        chmax(maxe[u],c2);
                        if(no.size()==0) chmax(ans,cnt);
                    }
                } else {
                    hold_diff.push(make_tuple(c,u,v));
                }
            }
            continue;
        }

        if(!hold_diff.empty()){
            i64 c,u,v;
            tie(c,u,v)=hold_diff.top();
            hold_diff.pop();

            u=uf.find(u);
            v=uf.find(v);

            if(u==v){
                if (sum[u] >= c) {
                    ++cnt;
                    chmax(maxe[u], c);
                    if(sum[u]>=maxe[u]){
                        no.erase(u);
                        ok.insert(u);
                    }
                    if (no.size() == 0) chmax(ans, cnt);
                } else {
                    hold_same[u].push(make_tuple(c, u, v));
                }
                continue;
            }

            uf.unite(u,v);
            ++cnt;
            if(v==uf.find(u)) swap(u,v);
            // uが親
            ok.erase(v);
            no.erase(v);

            sum[u] += sum[v];
            chmax(maxe[u],maxe[v]);
            chmax(maxe[u], c);
            if (sum[u] >= maxe[u]) {
                no.erase(u);
                ok.insert(u);
            }else{
                ok.erase(u);
                no.insert(u);
            }
            if (no.size() == 0) chmax(ans, cnt);

            while(!hold_same[v].empty()){
                auto e=hold_same[v].top();
                hold_same[v].pop();
                hold_same[u].push(e);
            }

            while(!hold_same[u].empty()){
                auto c2=get<0>(hold_same[u].top());
                if(c2>sum[u]) break;
                hold_same[u].pop();
                ++cnt;
                chmax(maxe[u],c2);
                if(no.size()==0) chmax(ans,cnt);
            }

            continue;
        }

        rep(u,0,N){
            i64 u2=uf.find(u);
            while(!hold_same[u2].empty()){
                i64 c=get<0>(hold_same[u2].top());
                if(c>sum[u2]) break;
                hold_same[u2].pop();
                ++cnt;
                chmax(maxe[u2],c);
                if(no.size()==0) chmax(ans,cnt);
            }
        }

        break;
    }

    cout << M-ans << endl;
}

