void dfs(Graph &graph, ll v,ll ma) {
	used[v] = 1;

	REP(i, graph[v].size()) {
		ll to = graph[v][i].to;
		ll cap = graph[v][i].cap;
		if (cap > ma)continue;
		if (used[to]==0) {
			flag[make_pair(min(v, to), max(v, to))] = 1;
			dfs(graph, to, ma);
		}
	}
}


