		a = uni.root(a);
		b = uni.root(b);
		if (a != b) {
			sum[a] += sum[b];
			sum[b] = sum[a];
			uni.unite(edge[i].second.first, edge[i].second.second);
		}
		ll y = edge[i].first;
		if (sum[a] >= y)flag[make_pair(edge[i].second.first, edge[i].second.second)] = 1;
	}
