struct Union_Find_Tree{
    vector<int> par, rank;
    vector<ll> num;
    //要素数n(0〜n-1)の初期化されたUnion-Find木を構築
    Union_Find_Tree(int N){
        par.assign(N, -1);
        rank.assign(N, 0);
        rep(i, N) num.pb(X[i]);
    }
    //ノードxの根を取得
    int root(int x){
        if(par[x] < 0 || par[x] == x) return x;
        return root(par[x]);
    }
    //xとyの属する集合を併合
    void unite(int x, int y){
        x = root(x), y = root(y);
        if(x == y) return;
        elif(rank[x] < rank[y]){
            par[x] = y, num[y] += num[x];
        }
        else{
            par[y] = x, num[x] += num[y];
            if(rank[x] == rank[y]) rank[x]++;
        }
    }
    //xの属する集合の要素数を取得
    int size(int x){
        return num[root(x)];
    }
    //xとyが同じ集合に属するか判定
    bool same(int x, int y){
        return root(x) == root(y);
    }
    //初期化する
    void clear(){
        fill(par.begin(), par.end(), -1);
        fill(rank.begin(), rank.end(), 0);
        fill(num.begin(), num.end(), 1);
    }
};

