  stack<Changes> s;
  vector<ll> par, h, w;
public:
  RollbackableUnionFind(vector<ll> w) : par(w.size(), 0), h(w.size(), 0), w(w) {
    rep(i, w.size()) par[i] = i;
  }
  void unite(ll u, ll v) {
    u = root(u), v = root(v);
    if (u == v) {
      s.push({false});
      return;
    }
    if (h[u] < h[v]) {
      s.push({true, v, u, par[u], w[v], h[v], h[u]});
      par[u] = v;
      w[v] += w[u];
    }
    else {
      s.push({true, u, v, par[v], w[u], h[u], h[v]});
      par[v] = u;
      w[u] += w[v];
    }
    if (h[u] == h[v]) ++h[u];
  }
  ll sum(ll v) const {
    return w[root(v)];
  }
  bool isUnited(ll u, ll v) const {
    return root(u) == root(v);
  }
  ll root(ll v) const {
    if (par[v] == v) return v;
    return root(par[v]);
  }
  void rollback() {
    assert(s.size() > 0);
    Changes c = s.top();
    if (!c.is_changed) return;
    par[c.v] = c.parv;
    w[c.u] = c.wu;
    h[c.u] = c.hu;
    h[c.v] = c.hv;
    s.pop();
  }
};


struct Edge {
  ll a, b, c;
};
bool operator<(const Edge& e1, const Edge& e2) {
  return e1.c < e2.c;
}

void solve() {
  ll n, m; cin >> n >> m;
  vector<ll> w(n); cin >> w;
  vector<Edge> edges;
  rep(i, m) {
    ll a, b, c; cin >> a >> b >> c; --a, --b;
    edges.pb({a, b, c});
  }
  sort(all(edges));
  vector<vector<P>> G(n);
  each(e, edges) {
    G[e.a].eb(e.b, e.c);
  }
  vector<bool> ok(n, false);
  function<void(ll,ll)> dfs = [&](ll v, ll th) {
    ok[v] = true;
    each(e, G[v]) {
      if (e.second > th) continue;
      if (ok[e.first]) continue;
      dfs(e.first, th);
    }
  };
  RollbackableUnionFind uf(w);
  each(e, edges) uf.unite(e.a, e.b);
  ll ans = 0;
  rrep(i, m) {
    // cout << i << endl;
    Edge& e = edges[i];
    if (ok[e.a]) continue;
    assert(uf.isUnited(e.a, e.b));
    // cout << e.a+1 << " " << e.b+1 << " " << e.c << " " << uf.sum(e.a) << endl;
    if (e.c > uf.sum(e.a)) {
      ++ans;
    }
    else {
      dfs(e.a, e.c);
    }
    uf.rollback();
  }
  cout << ans << endl;
}

