	sort(p + 1, p + m + 1);
	for(int i = 1; i <= m; i++)
	{
		int ufa = gfa(p[i].u), vfa = gfa(p[i].v);
		if(ufa == vfa) p[i].fl = 0;
		else 
			p[i].fl = 1, 
			fa[ufa] = vfa, 
			addedge(p[i].u, p[i].v), 
			addedge(p[i].v, p[i].u);
	}
	dep[1] = 1, top[1] = 1;
	dfs1(1), dfs2(1);
	root = &stp[stcnt++];
	bdtree(root, 1, n);
	ins(root, 1);
	int cnt = 0;
	for(int i = m; i >= 1; i--)
	{
		ll ns = q(p[i].u);
	//	cout<<i<<" "<<ns<<endl;
		if(ns >= p[i].w) continue;
		else
		{
			cnt++;
			if(p[i].fl)
			{
				cut(p[i].u, p[i].v);
			}
		}
	}
