void union2(int A,int B)
{
    int root_A=root(A);
    int root_B=root(B);
    if(root_A==root_B)
    {
        return ;
    }
    if(siz[root_A]>siz[root_B])
    {
        siz[root_A]+=siz[root_B];
        bvertices[root_A]=0;
        svertices[root_A]+=svertices[root_B];
