void union1(int A,int B,long long int len)
{
    int root_A=root(A);
    int root_B=root(B);
    if(root_A==root_B)
    {
        if(svertices[root_A]>len)
        {
            bvertices[root_A]=0;
            return ;
        }
        else
        {
            bvertices[root_A]++;
        }
        return ;
    }
    long long sum=svertices[root_A]+svertices[root_B];
    if(sum>len)
    {

        if(siz[root_A]>siz[root_B])
        {
            siz[root_A]+=siz[root_B];
            bvertices[root_A]=0;
            svertices[root_A]+=svertices[root_B];
            par[root_B]=root_A;
        }
        else if(siz[root_A]<=siz[root_B])
        {
            siz[root_B]+=siz[root_A];
            bvertices[root_B]=0;
            svertices[root_B]+=svertices[root_A];
            par[root_A]=root_B;
        }

        return ;
    }
    else
    {
        if(siz[root_A]>siz[root_B])
        {
            siz[root_A]+=siz[root_B];

            bvertices[root_A]+=bvertices[root_B]+1;

            svertices[root_A]+=svertices[root_B];
            par[root_B]=root_A;
        }
        else if(siz[root_A]<=siz[root_B])
        {
            siz[root_B]+=siz[root_A];
            bvertices[root_B]+=bvertices[root_A]+1;

            svertices[root_B]+=svertices[root_A];
            par[root_A]=root_B;
        }
        return ;
    }
    return ;
}
