inline void bfs(int v) {
    int head = 0, R = 0, u;
    was[v] = timer;
    Q[R++] = v;
    while (head < R) {
        u = Q[head++];
        used[u] = cur;
        sum[cur] += x[v];
        for (auto to : g[v]) {
            if (was[to] != timer) {
                was[to] = timer, Q[R++] = to;
            }
        }
