      if(!erased[p.sc] && Y[p.sc] > S){
        vs.pb(v);
        vs.pb(p.fr);
        ans++;
        erased[p.sc]=1;
        er.push_back(p.sc);
      }
      if(used[v] == used[p.fr]) continue;
      used[p.fr]++;
      q.push(p.fr);
    }
    rep(i,er.size()){
      s[A[er[i]]].erase(LP(B[er[i]], er[i]));
      s[B[er[i]]].erase(LP(A[er[i]], er[i]));
    }
  }
  ll cnt = 0;
  // puts("a");
  rep(i,vs.size()){
    q.push(vs[i]);
    nums[vs[i]]=1;
  }
  while(!q.empty() && cnt + 1 < vs.size()){
    // puts("a1");
    ll v = q.front();
    // cout<<v<<"gaa"<<endl;
    q.pop();
    qlog[v]=1;
    nums[find(v)]--;
    for(ite[v]=s[v].begin();ite[v]!=s[v].end();++ite[v]){
      // puts("a2");
      x = find(v);
      y = find((*(ite[v])).fr);
      if(x==y) continue;
      if(x>y) swap(x,y);
      par[y] = x;
      sums[x] += sums[y];
      nums[x] += nums[y];
      if(!qlog[(*(ite[v])).fr]){
        nums[x]++;
        q.push((*(ite[v])).fr);
      }
      // puts("a3");
    }
    // puts("a4");
    if(nums[find(v)] == 0) cnt++;
  }
  // puts("v");
  ll s2=S;
  rep(i,vs.size()){
    if(vs[i]==find(vs[i]) && nums[find(vs[i])]==0) s2-=sums[find(vs[i])];
  }
  queue<P> q2;
  rep(i,vs.size()){
    if(used2[find(vs[i])]) continue;
    int w = find(vs[i]);
    int h = nums[w]!=0?s2:sums[w];
    q2.push(LP(w,h));
    used2[find(vs[i])]=1;
  }
  while(!q2.empty()){
    P p = q2.front();
    q2.pop();
    solve(p.fr,p.sc);
  }
}

