struct PartiallyPersistentUnionFind
{
    vector< long > data;
    vector< long > data2;
    vector< long > last;
    vector< vector< pair< long, long > > > add;
    vector< vector< pair< long, long > > > add2;

    PartiallyPersistentUnionFind() {}

    PartiallyPersistentUnionFind(long sz) : data(sz, -1l), last(sz, 1111100000l), add(sz), add2(sz)
    {
        for(auto &vs : add) vs.emplace_back(-1l, -1l);
        for(int i = 0; i < sz; i++) add2[i].push_back({-1l, -X[i]});
        for(int i = 0; i < sz; i++) data2.push_back(-X[i]);
    }

    bool unite(long t, long x, long y)
    {
        x = find(t, x);
        y = find(t, y);
        if(x == y) return false;
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data2[x] += data2[y];
        add[x].emplace_back(t, data[x]);
        add2[x].emplace_back(t, data2[x]);
        data[y] = x;
        last[y] = t;
        return true;
    }

    long find(long t, long x)
    {
        if(t < last[x]) return x;
        return find(t, data[x]);
    }

    long size(long t, long x)
    {
        x = find(t, x);
        return -prev(lower_bound(begin(add[x]), end(add[x]), make_pair(t, 0l)))->second;
    }

    long size2(long t, long x)
    {
        x = find(t, x);
        return -prev(lower_bound(begin(add2[x]), end(add2[x]), make_pair(t, 0l)))->second;
    }
};

