struct UnionFind {
    vector<int> par;
    vector<pair<P,int>> size;
    UnionFind(int x,vector<int> y) {
        par.resize(x);
        size.resize(x);
        for(int i = 0; i < x; i++) {
            par[i] = i;
        }
        for(int i = 0; i < x; i++) {
            size[i].first.second = y[i];
            size[i].second = 1;
        }
    }
    int find(int x) {
        if (par[x] == x)
            return x;
        return par[x] = find(par[x]);
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
    P consize(int x) {
        return {size[find(x)].first.first,size[find(x)].first.second};
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (size[x].second < size[y].second) {
            par[x] = y;
            size[y].first.first += size[x].first.first;
            size[y].first.second += size[x].first.second;
            size[y].second += size[x].second;
        }
        else {
            par[y] = x;
            size[x].first.first += size[y].first.first;
            size[x].first.second += size[y].first.second;
            size[x].second += size[y].second;
        }
    }
};
