vector <int> last;
vector <bool> used2;
int pred(int a){
	if(a == dsu[a]) return a;
	else return dsu[a] = pred(dsu[a]);
}
void unite(int a, int b)
{
	a = pred(a);
	b = pred(b);
	if(a != b)
	{
		if(rang[a] < rang[b])
		{
			swap(a, b);
		}
		dsu[b] = a;
		if(last[a] < last[b])
		{
			if(last[a] != -1)
			{
				used[last[a]] = false;
			}
		}
		else if(last[a] > last[b])
		{
			if(last[b] != -1)
			{
				used[last[b]] = false;
			}
		}
		last[a] = max(last[a], last[b]);
		sum[a] += sum[b];
		if(rang[a] == rang[b])
		{
			rang[a]++;
		}
	}
}
void dfs(int v)
{
	used1[v] = true;
	for(int i = 0; i < g[v].size(); i++)
	{
		int to = g[v][i].first;
		int ind = g[v][i].second;
		used2[ind] = true;
		if(!used1[to])
		{
			dfs(to);
		}
	}
}
