struct UnionFind{
    vector<int> par, sz;
    vector<long long> sum;
    UnionFind(){}
    UnionFind(int n, vector<long long> x):par(n), sz(n, 1), sum(x){
        iota(par.begin(), par.end(), 0);
    }
    int find(int x){
        if(x == par[x]) return x;
        return find(par[x]);
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
    void unite(int x, int y){
        x = find(x); y = find(y);
        if(x == y) return;
        if(sz[x] < sz[y]) swap(x, y);
        sz[x] += sz[y];
        sum[x] += sum[y];
        par[y] = x;
    }
    void split(int x, int y){
        sz[x] -= sz[y];
        sum[x] -= sum[y];
        par[y] = y;
    }
};

struct edge{
    int u, v, w;
    bool operator<(const edge &e)const{
        return w < e.w;
    }
};

