        int v = uf.find(e.v);
        if(u == v) continue;
        if(uf.sz[u] < uf.sz[v]) swap(u, v);
        uf.unite(u, v);
        h.push_back(T(u, v, e.w));
    }
    reverse(h.begin(), h.end());
    for(auto e : h){
        int u, v, w;
        tie(u, v, w) = e;
        if(uf.sum[uf.find(u)] < w) uf.split(u, v);
    }
    for(auto e : es){
        if(uf.sum[uf.find(e.u)] < e.w) ans++;
    }
