int N,M;
struct node {
	int to,next,val;
}E[MAXN * 2];
int head[MAXN],sumE;
int fa[MAXN];
int64 sum[MAXN],x[MAXN];
bool vis[MAXN];
struct Enode {
	int u,v,c;
}s[MAXN];
void add(int u,int v,int c) {
	E[++sumE].to = v;
	E[sumE].next = head[u];
	E[sumE].val = c;
	head[u] = sumE;
}
int getfa(int u) {
	return fa[u] == u ? u : fa[u] = getfa(fa[u]);
}
void dfs(int u,int c) {
	int p = getfa(u);
	for(int i = head[u] ; i ; i = E[i].next) {
		if(E[i].val <= c) {
			int q = getfa(E[i].to);
			if(q != p) {
				fa[q] = p;
				dfs(E[i].to,c);
			}
		}
	}
}
void Solve() {
	read(N);read(M);
	for(int i = 1 ; i <= N ; ++i) read(x[i]);
	int u,v,c;
	for(int i = 1 ; i <= M ; ++i) {
		read(u);read(v);read(c);
		add(u,v,c);add(v,u,c);
		s[i] = (Enode){u,v,c};
	}
	sort(s + 1,s + M + 1,[](Enode a,Enode b){return a.c < b.c;});
	for(int i = 1 ; i <= N ; ++i) {
		fa[i] = i;sum[i] = x[i];
	}
	int t = 1;
	for(int i = 1 ; i <= M ; ++i) {
		int p = getfa(s[i].u),q = getfa(s[i].v);
		if(p != q) {
			fa[q] = p;
			sum[p] += sum[q];
		}
		if(i == N || s[i].c != s[i + 1].c) {
			for(int j = t; j <= i; ++j) {
				p = getfa(s[j].u);
				if(sum[p] >= s[j].c) vis[j] = 1;
			}
			t = i + 1;
		}
	}
	for(int i = 1 ; i <= N ; ++i) fa[i] = i;
	int ans = 0;
	for(int i = M ; i >= 1 ; --i) {
		if(getfa(s[i].u) == getfa(s[i].v)) continue;
		if(!vis[i]) {++ans;continue;}
		dfs(s[i].u,s[i].c);
	}
	out(ans);enter;
}
