template<typename T>
struct edge {
  int from, to;
  T cost;

  edge(int to, T cost) : from(-1), to(to), cost(cost) {}

  edge(int from, int to, T cost) : from(from), to(to), cost(cost) {}

  bool operator<(const edge<T> &e) const {
    return cost < e.cost;
  }
};

template<typename T> using Edges = vector<edge<T>>;
template<typename T> using WeightedGraph = vector<vector<edge<T>>>;

struct UnionFind {
  vl data;

  UnionFind(vl &vec) {
    for (auto &v : vec) data.emplace_back(-v);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  int find(int k) {
    if (data[k] < 0) return k;
    return (data[k] = find(data[k]));
  }

  ll size(int k) {
    return -data[find(k)];
  }
};

template<typename T>
stack<pll> kruskal(Edges<T> &edges, vl &vec) {
  sort(edges.begin(), edges.end());
  UnionFind tree(vec);
  stack<pll> ret;
  for (auto &e : edges) {
    if (tree.unite(e.from, e.to)) {
      if (tree.size(e.from) >= e.cost) ret.emplace(e.from, tree.size(e.from));
    }
  }
  return ret;
}

void solve() {
  int n, m; cin >> n >> m;
  vl vrt(n); cin >> vrt;
  Edges<int> edges;
  WeightedGraph<int> g(n);
  rep(i,m) {
    int a, b, y; cin >> a >> b >> y; --a, --b;
    edges.emplace_back(a, b, y);
    g[a].emplace_back(b, y);
    g[b].emplace_back(a, y);
  }

  auto st = kruskal(edges, vrt);

  vb seen(n, false);
  int cnt = 0;
  const ll INFTY = 1e16;

  while (!st.empty()) {
    int x; ll w;
    tie(x, w) = st.top(); st.pop();

    if (seen[x]) continue;

    auto dfs = [&](auto dfs, int v) -> void {
      if (seen[v]) return;
      seen[v] = true;
      for (auto &e : g[v]) {
        if (e.cost <= w) {
          ++cnt;
          e.cost = INFTY;
          dfs(dfs, e.to);
        }
      }
    };

    dfs(dfs, x);
  }

  cout << m - cnt / 2 << endl;
}


