		ll S;
		while (q.size() && q.front()[0] < X) {
			S = un.getsize(q.front()[1]);
			fl[q.front()[3]] = (S >= q.front()[0]);
			q.pop();
		}
		un.unite(A, B);
		q.push({X,A,B,i});
	}

	while (q.size()) {
		ll S = un.getsize(q.front()[1]);
		fl[q.front()[3]] = (S >= q.front()[0]);
		q.pop();
	}


	for (int i = M - 1; i >= 0; i--) {
		ll X = E[i][0];
		int A = E[i][1];
		int B = E[i][2];
		if (fl[i] != 1)continue;
		used[i] = 1;
		dfs(A,X);
		dfs(B,X);
	}


	int ans = M;
	for (int i = 0; i < M; i++)ans -= (fl[i]||used[i]);
	puts(ans);

	return 0;
}

