		this->from = from;
		this->to = to;
		this->cost = cost;
	}
	bool operator<(Edge &r) {
		return cost < r.cost;
	}
};

struct UF {
	int par[100000];
	int sum[100000];
	int maxi[100000];
	int rank[100000];
	void init(int x[]) { int i; rep(i, 100000) { par[i] = i; sum[i] = x[i]; maxi[i] = 0; rank[i] = 0; } }
	int root(int x) { if (par[x] == x) return x; return par[x] = root(par[x]); }
	void unit(int x, int y, int cst) {
		x = root(x);
		y = root(y);
		if (x != y) {
			if (rank[x] > rank[y]) swap(x, y);
			par[x] = y;
			sum[y] += sum[x];
			rank[y] = max(rank[y], rank[x] + 1);
		}
		maxi[y] = max({cst, maxi[x], maxi[y]});
	}
	bool same(int x, int y) { return root(x) == root(y); }
	int rootSum(int x) { return sum[root(x)]; }
	int rootMax(int x) { return maxi[root(x)]; }
};

int n, m;
int x[100000];
Edge edges[100000];
UF uf;

int solve() {
	int i, j;
	int ret = 0;

	uf.init(x);
	for (i = 0; i < m; i++) {
		int u = edges[i].from;
		int v = edges[i].to;
		int c = edges[i].cost;
		uf.unit(u, v, c);

		rep(j, n) {
			if (uf.rootSum(j) < uf.rootMax(j)) {
				break;
			}
		}
		if (j == n) ret = i + 1;
	}
	return ret;
}

