    UnionFind uf = UnionFind(n);
    int ans = m;
    for(int i=0;i<m;++i) {
        Edge e = edges[i];
        uf.unite(e);
        if(is_ok(&uf, &e)) {
            ans = m-1-i;
        }
    }

    cout << ans << endl;


}

