struct union_find {
    vector<int> data;
    vector<int> w;
    union_find(int size) : data(size, -1), w(size) {}
    void set(int i, int x) {
        w[i] = x;
    }
    void unite(int x, int y) {
        x = root(x); y = root(y);
        if(x != y) {
            if(data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
            w[x] += w[y];
        }
    }
    int weight(int x) {
        x = root(x);
        return w[x];
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : (data[x] = root(data[x]));
    }
    int size(int x) {
        return -data[root(x)];
    }
};

