class UnionFind {
	vector<int>parent;
	vector<int>rank;

public:
	vector<long long int>v;
	vector<long long int>edge;
	vector<long long int>sum;
	vector<long long int>can;
	UnionFind(int num,vector<long long int>vv) {
		num++;
		v = vv;
		parent.resize(num);
		rank.resize(num);
		edge.resize(num);
		sum.resize(num);
		can.resize(num);
		for (int i = 0; i < num; i++) {
			parent[i] = i;
			rank[i] = 0;
		}
		for (int i = 1; i < num; i++)sum[i] = v[i];
	}
	int Find(int node) {
		if (parent[node] == node)return node;
		else return parent[node] = Find(parent[node]);
	}
	void Unite(int u, int v,long long int c) {
		u = Find(u);
		v = Find(v);
		if (u == v) {
			edge[u]++;
			if (c <= sum[u]) {
				can[u] = edge[u];
			}
			return;
		}
		if (rank[u] < rank[v]) {
			parent[u] = v;
			edge[v] += edge[u];
			edge[v]++;
			sum[v] += sum[u];
			can[v] += can[u];
			if (sum[v] >= c)can[v] = edge[v];
		}
		else {
			parent[v] = u;
			edge[u] += edge[v];
			edge[u]++;
			sum[u] += sum[v];
			can[u] += can[v];
			if (sum[u] >= c)can[u] = edge[u];
			if (rank[u] == rank[v])rank[u]++;
		}
	}
	bool Check_Same(int u, int v) {
		return Find(u) == Find(v);
	}
};

