    UnionFind uf(N, X);
    vector< tuple<int, int, int> > tmp;

    int ans = INF;
    for(int i=0; i<M; i++) {
        // 同じコストのものをまとめる
        int pre = get<0>(edges[i]);
        while(i < M and pre == get<0>(edges[i])) {
            tmp.emplace_back(edges[i]);
