        }

        // 全部追加する
        // 新たに追加したものについて全て条件を満たしているならば
        // そのようなとり方が可能
        for(auto e : tmp) {
            int w, u, v; tie(w, u, v) = e;
            uf.unite(u, v);
        }

        bool ok = true;
        for(auto e : tmp) {
            int w, u, v; tie(w, u, v) = e;
            int id = uf.find(u);
            ok &= (w <= uf.pot[id]);
        }
        tmp.clear();

        if(ok) {
            ans = min(ans, M - i);
        }

        i--;
    }
    cout << ans << endl;
    return 0;
}

