class UnionFind {
public:
	vector<ll>s, p;
	UnionFind(int size) {
		s.resize(size, 0);
		p.resize(size, 0);
		for (int i = 0; i < size; i++)makeSet(i);
	}
	void makeSet(int x) {
		p[x] = x;
		s[x] = 1;
	}
	void setcost(int x, ll cost) { 
		s[x] = cost;
	}
	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}
	void unite(int x, int y) {
		x = findSet(x);
		y = findSet(y);
		if (x == y)return;
		if (s[x] < s[y])swap(x, y);
		p[y] = x;
		s[x] += s[y];
	}
	int findSet(int x) {
		if (x == p[x])return p[x];
		return p[x] = findSet(p[x]);
	}
	int getsize(int x) {
		return s[findSet(x)];
	}
};

