    f[i]=i;
    sum[i]=a[i];
    vis[i]=false;
  }
  for(int i=1;i<=m;i++){
    can[i]=false;
    int px = pd(p[i].x);
    int py = pd(p[i].y);
    if(px!=py){
      f[px]=py;
      sum[py]+=sum[px];
      sum[px]=0;
    }
    if(sum[py]>=p[i].v){
      can[i]=true;
    }
  }
  int ret = 0;
  for(int i=m;i>=1;i--){
    if(vis[p[i].x])continue;
    if(!can[i]){
      ret++;
      continue;
    }
    dfs(p[i].x, p[i].v);
  }
  cout<<ret<<endl;
  return 0;
}

