	UnionFind_P ufp(n);

	REP(i, n) {
		scanf("%lld", &X[i]);
	}

	ufp.Initsz(X);

	REP(i, m) {
		int a, b;
		ll c;
		scanf("%lld %lld %lld", &a, &b, &c);
		a--, b--;
		g[a].push_back({ i,a,b,c });
		g[b].push_back({ i,b,a,c });
		edges[i] = { c,{a,b} };
	}

	sort(ALL(edges));

	REP(i, m) {
		ufp.unionSet(edges[i].second.first, edges[i].second.second);
	}

	int ans = 0;

	vector<int> used(n),useded(m);

	function<void(int,ll)> dfs = [&](int cur, ll kyoyou) {
		used[cur] = 1;
		for (auto itr : g[cur]) {


			if (itr.w <= kyoyou) {

				if (useded[itr.num] == 0) {
					ans++;
					useded[itr.num] = 1;
				}

				int nex = itr.to;

				if (used[nex] == 0) {
					dfs(nex, kyoyou);
					used[nex] = 1;
				}

			}
		}
	};

	REP(v, n) {

		ll l = 0, r = m; //!!!!honsuu!!!!!

		while (r - l > 1) {

			ll mid = (l + r) / 2;

			ll sz = edges[mid - 1].first;

			ll realsz = ufp.getsz(v, mid);

			if (sz < realsz) {
				l = mid;
			}
			else {
				r = mid;
			}
		}
		if(l == 0)
			dfs(v, 0);
		else
			dfs(v, edges[l - 1].first);

	}

	cout << m-ans << endl;

	return 0;
}

