//よく使うクラス、構造体
class UnionFind {
public:
    vi par, rank, sizes, suw, amae;
    int n, trees;
    UnionFind(int n) : n(n), trees(n) {
        par.resize(n), rank.resize(n), sizes.resize(n);
        suw.resize(n);
        amae.resize(n);
        rep(i, n)par[i] = i, sizes[i] = 1;
    }
    int root(int x) {
        if (par[x] == x)return x;
        else return par[x] = root(par[x]);
    }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (rank[x] < rank[y])swap(x, y);
        amae[x]++;
        if (x == y)return;
        trees--;
        par[y] = x;
        sizes[x] += sizes[y];
        suw[x] += suw[y];
        amae[x] += amae[y];
        if (rank[x] == rank[y])rank[x]++;
    }
    int rese(int v) {
        v = root(v);
        int ret = amae[v];
        amae[v] = 0;
        return ret;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return sizes[root(x)]; }
    //順不同 umapなので
    vec<vi> sets() {
        vec<vi> res(trees);
        umap<int, vi> map;
        rep(i, n) map[root(i)].push_back(i);
        int i = 0;
        for (auto &&p:map) {
            int r = p.F;
            res[i].push_back(r);
            for (auto &&v:p.S) {
                if (r == v)continue;
                res[i].push_back(v);
            }
            i++;
        }
        return res;
    }
    int wei(int i) {
        return suw[root(i)];
    }
};

