struct UF
{
	vector<ll> par; // 親のインデックスを記憶する配列
	vector<ll> sz; // サイズを記憶する。
	vector<ll> rank;
	vector<vector<int>> edge;
	// 初期化
	UF(int n):par(n),sz(n),rank(n),edge(n){
		for(int i = 0; i < n; i++){
			par[i] = i;sz[i] = 1;rank[i] = 0;
		}
	}
	// 親を求める
	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	// xとyの属する集合を併合
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return;
		if(rank[x] < rank[y]){
			par[x] = y;
			sz[y] += sz[x];
			REP(i,edge[x].size())edge[y].PB(edge[x][i]);
		}
		else{
			par[y] = x;
			sz[x] += sz[y];
			REP(i,edge[y].size())edge[x].PB(edge[y][i]);
			if(rank[x] == rank[y])rank[x]++;
		}
	}
	// xとyが同じ集合ならtrue
	bool same(int x, int y) { return find(x) == find(y); }
	// 素の集合のサイズを求める
	int size(int n){return sz[find(n)];}
};

