        int v, u, y;
        cin >> v >> u >> y;
        edges.emplace_back(--v, --u, y);
    }

    sort(all(edges));

    for (auto& e : edges) {
        if (par[e.v] == par[e.u]) {
            continue;
        }

        vector<int>& a = g[par[e.v]].size() >= g[par[e.u]].size() ? g[par[e.v]] : g[par[e.u]];
        vector<int>& b = g[par[e.v]].size() >= g[par[e.u]].size() ? g[par[e.u]] : g[par[e.v]];
        int s = sum[a[0]] + sum[b[0]];
        sum[a[0]] = s;
        for (int v : b) {
            a.push_back(v);
            par[v] = a[0];
        }

        // cerr << e.v << ' ' << e.u << ' ' << e.y << ' ' << s << '\n';

        if (s < e.y) {
            continue;
        }

        for (int i = (int) a.size() - 1; i >= 0; i--) {
            if (comp[a[i]] == comp[a[0]]) {
                break;
            }
            comp[a[i]] = comp[a[0]];
        }
    }

    memset(sum, 0, sizeof sum);
    for (int i = 0; i < n; i++) {
        sum[comp[i]] += x[i];
        // cerr << comp[i] << ' ';
    }
    // cerr << '\n';

    int ans = 0;
    for (auto& e : edges) {
        if (comp[e.v] == comp[e.u] && e.y <= sum[comp[e.v]]) {
            ans++;
        }
    }

    cout << m - ans << '\n';

    #ifdef LOCAL
        cerr << "\n== " << 1.0 * clock() / CLOCKS_PER_SEC << " sec.\n";
    #endif
    return 0;
}

