class UnionFind {
private:
	int n, s;
	vector<int> p_id;
	vector<vector<int>> v;
public:
	UnionFind(int n = 0) { init(n); }
	void init(int arg_n) {
		n = s = arg_n;
		p_id.clear();
		v.clear();
		inc(i, n) { p_id.PB(i); v.EB(1, i); }
	}
	int id(int i) { return p_id.at(i); }
	bool unite(int x, int y) {
		x = id(x);
		y = id(y);
		if(x == y) { return false; }
		if(v[x].size() < v[y].size()) { swap(x, y); }
		for(auto & e: v[y]) { v[x].PB(e); p_id[e] = x; }
		v[y].clear();
		s--;
		return true;
	}
	const vector<int> & operator[](int i) { return v[id(i)]; }
	int size() { return s; }
	int get_n() const { return n; }
	const vector<vector<int>> & get_v() const { return v; }
};
ostream & operator<<(ostream & os, const UnionFind & uf) {
	inc(i, uf.get_n()) { os << i << ": "; for(auto & e: uf.get_v()[i]) { os << e << " "; } os << "\n"; }
	return os;
}

