LL id[M], d[M], c[M];
vector<int> g[M], r, w;

void dfs(int v, int p, int dd) {
	d[v] = dd;
	c[v] = 1;
	RF(e, g[v]) {
		if(e == p) { continue; }
		dfs(e, v, dd + 1);
		c[v] += c[e];
	}
}

void del_2(int L, int S, int v, int p) { // L --> S
	id[v] = S;
	w[L] -= x[v];
	w[S] += x[v];
	RF(e, g[v]) {
		if(e == p) { continue; }
		del_2(L, S, e, v);
	}
}

void del(int rl, int rs, int v, int p) {
	int L = id[v];
	int S = SI(r);
	r.PB(-1);
	w.PB(0);
	r[L] = rl;
	r[S] = rs;
	del_2(L, S, v, p);
}

int main() {
	cin >> n >> m;
	inc(i, n) { cin >> x[i]; }
	inc(i, m) {
		LL a, b, y;
		cin >> a >> b >> y;
		a--; b--;
		yab[i] = { y, a, b };
	}
	sort(yab, yab + m);

	UnionFind uf(n);
	inc(i, m) {
		int a = yab[i][1];
		int b = yab[i][2];
		if(uf.unite(a, b)) {
			mst[i] = true;
			g[a].PB(b);
			g[b].PB(a);
		}
	}

	dfs(0, -1, 0);
	r.PB(0);
	w.PB(0);
	inc(i, n) { w[0] += x[i]; }

	int ans = 0;
	dec(i, m) {
		LL y = yab[i][0];
		LL a = yab[i][1];
		LL b = yab[i][2];
		if(w[id[a]] >= y) { continue; }

		if(mst[i]) {
			if(d[a] < d[b]) { swap(a, b); }
			int R = r[id[a]];
			if(c[a] < c[R] - c[a]) {
				del(R, a, a, b);
			} else {
				del(a, R, b, a);
			}
		}
		ans++;
	}

	cout << ans << endl;

	return 0;
}

