//Union-Find
class UnionFind {
private:
	std::vector<int> parent;
	std::vector<int> height;
	std::vector<int> m_size;

public:
	UnionFind(int size_) : parent(size_), height(size_, 0), m_size(size_, 1) {
		for (int i = 0; i < size_; ++i) parent[i] = i;
	}
	void init(int size_) {
		parent.resize(size_);
		height.resize(size_, 0);
		m_size.resize(size_, 0);
		for (int i = 0; i < size_; ++i) parent[i] = i;
	}
	int find(int x) {
		if (parent[x] == x) return x;
		return parent[x] = find(parent[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		int t = size(x) + size(y);
		m_size[x] = m_size[y] = t;
		if (height[x] < height[y]) parent[x] = y;
		else parent[y] = x;
		if (height[x] == height[y]) ++height[x];
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		if (parent[x] == x) return m_size[x];
		return size(parent[x] = find(parent[x]));
	}
};

signed main() {
	INIT;

	VAR(int, n, m);
	VEC(int, x, n);
	VEC_ROW(int, m, a, b, y);

	{
		struct S { int a, b, y; };
		V<S> s(m);
		REP(i, m) s[i] = S{ a[i], b[i],y[i] };
		std::sort(ALL(s), [&](S& l, S& r) {
			return l.y < r.y;
		});
		REP(i, m) {
			a[i] = --s[i].a;
			b[i] = --s[i].b;
			y[i] = s[i].y;
		}
	}

	int ok = -1;
	{
		UnionFind uf(n);
		V<int> cost(n, 0);
		REP(i, n) cost[i] = x[i];
		V<int> max(n, -INFINT);

		std::set<int> ngset;
		REP(i, m) {
			if (uf.same(a[i], b[i])) {
				continue;
			}
			else {
				int fa = uf.find(a[i]);
				int fb = uf.find(b[i]);
				ngset.erase(fa);
				ngset.erase(fb);
				int c = cost[fa] + cost[fb];
				int ma = std::max({ max[fa], max[fb], y[i] });

				uf.unite(a[i], b[i]);
				int newfa = uf.find(a[i]);
				cost[newfa] = c;
				max[newfa] = ma;
				if (ma > c) ngset.insert(newfa);
			}
			if (ngset.empty()) ok = i;
		}
	}

	UnionFind uf(n);
	V<int> cost(n, 0);
	REP(i, n) cost[i] = x[i];
	V<int> max(n, -INFINT);
	V<bool> used(m, false);

	REP(i, ok + 1) {
		if (uf.same(a[i], b[i])) {
			continue;
		}
		else {
			int fa = uf.find(a[i]);
			int fb = uf.find(b[i]);
			int c = cost[fa] + cost[fb];
			int ma = std::max({ max[fa], max[fb], y[i] });

			uf.unite(a[i], b[i]);
			used[i] = true;
			int newfa = uf.find(a[i]);
			cost[newfa] = c;
			max[newfa] = ma;
		}
	}

	REP(i, m) {
		if (used[i]) continue;
		if (uf.same(a[i], b[i])) {
			int fa = uf.find(a[i]);
			if (y[i] <= cost[fa]) {
				used[i] = true;
				CHMAX(max[fa], y[i]);
			}
		}
	}

	int ans = m;
	REP(i, m) ans -= used[i];

	OUT(ans)BR;

	return 0;
}

