class UnionFind
{
public:
  vector<long long> par;

  UnionFind(int n) : par(n, -1) {}
  void init(int n)
  {
    par.assign(n, -1);
  }

  int root(int x)
  {
    if (par[x] < 0)
    {
      return x;
    }
    return par[x] = root(par[x]);
  }

  bool is_same(int x, int y)
  {
    return root(x) == root(y);
  }

  bool merge(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
    {
      return false;
    }
    if (par[x] > par[y])
    {
      swap(x, y);
    }
    par[x] += par[y];
    par[y] = x;
    return true;
  }

  long long size(int x)
  {
    return -par[root(x)];
  }
};

int N, M;
ll X[100010];
int A[100010];
int B[100010];
ll Y[100010];
typedef tuple<ll, int, int, bool> edge;
vector<edge> V;
vector<int> W[100010];
bool visited[100010];
typedef tuple<ll, int> task;
vector<task> T;

void dfs(ll cost, int v)
{
#if DEBUG == 1
  cerr << "dfs(" << cost << ", " << v << ")" << endl;
#endif
  if (visited[v])
  {
    return;
  }
  visited[v] = true;
  for (auto i : W[v])
  {
    edge &x = V[i];
    ll score = get<0>(x);
    int a = get<1>(x);
    int b = get<2>(x);
    int dst = ((a == v) ? b : a);
#if DEBUG == 1
    cerr << "score = " << score << ", dst = " << dst << endl;
#endif
    if (get<3>(x))
    {
      continue;
    }
    if (cost >= score)
    {
      get<3>(x) = true;
      if (!visited[dst])
      {
        dfs(cost, dst);
      }
    }
  }
}

int main()
{
  cin >> N >> M;
  for (auto i = 0; i < N; i++)
  {
    cin >> X[i];
  }
  for (auto i = 0; i < M; i++)
  {
    cin >> A[i] >> B[i] >> Y[i];
    A[i]--;
    B[i]--;
    V.push_back(edge(Y[i], A[i], B[i], false));
  }
  sort(V.begin(), V.end());
  for (auto i = 0; i < M; i++)
  {
    edge x = V[i];
    int a = get<1>(x);
    int b = get<2>(x);
    W[a].push_back(i);
    W[b].push_back(i);
  }
  UnionFind UF(N);
  for (auto i = 0; i < N; i++)
  {
    UF.par[i] = -X[i];
  }
  for (auto i = 0; i < M; i++)
  {
    edge x = V[i];
    ll cost = get<0>(x);
    int a = get<1>(x);
    int b = get<2>(x);
    ll score = 0;
    if (UF.is_same(a, b))
    {
      score = UF.size(a);
    }
    else
    {
      score = UF.size(a) + UF.size(b);
      UF.merge(a, b);
    }
    if (score >= cost)
    {
      T.push_back(task(cost, a));
    }
  }
  reverse(T.begin(), T.end());
  fill(visited, visited + N, false);
  for (auto x : T)
  {
#if DEBUG == 1
    cerr << get<0>(x) << " " << get<1>(x) << endl;
#endif
    dfs(get<0>(x), get<1>(x));
  }
  int ans = 0;
  for (auto i = 0; i < M; i++)
  {
    if (!get<3>(V[i]))
    {
      ans++;
    }
  }
  cout << ans << endl;
}

