struct UnionFind {
    vector<ll> rank, parent, size;
    vector<int> cnt;

    // +1 for 1-indexed nodes
    UnionFind(int n) : rank(n + 1, 0), parent(n + 1), size(n + 1, 1), cnt(n + 1, 0) {
        iota(parent.begin(), parent.end(), 0); // parent is itself
    }
    int root(int x) {
        if (x != parent[x]) {
            parent[x] = root(parent[x]);
        }
        return parent[x];
    }
    bool isSame(int x, int y) { return root(x) == root(y); }
    bool unite(int x, int y) { return link(root(x), root(y)); }
    bool link(int x, int y) {
        if (x == y)
            return false;
        if (rank[x] > rank[y]) {
            parent[y] = x;
            size[x] += size[y];
            cnt[x] += cnt[y];
        } else {
            parent[x] = y;
            size[y] += size[x];
            cnt[y] += cnt[x];
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
        return true;
    }
    ll getSize(int x) { return size[root(x)]; }
    void add(int x, int a) { cnt[root(x)] += a; }
    int getCnt(int x) { return cnt[root(x)]; }
    void clr(int x) { cnt[root(x)] = 0; }
};

int main() {
    int n, m;
    cin >> n >> m;
    vl x(n);
    UnionFind uf(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i];
        uf.size[i] = x[i];
    }
    vector<pair<int, pii>> edges;
    for (int i = 0; i < m; ++i) {
        int a, b, y;
        cin >> a >> b >> y;
        a--, b--;
        edges.push_back({y, {a, b}});
    }
    sort(edges.begin(), edges.end());
    int ret = 0;
    for (int i = 0; i < m; ++i) {
        ll cost = edges[i].first;
        pii edge = edges[i].second;
        uf.unite(edge.first, edge.second);
        uf.add(edge.first, 1);
        if (cost <= uf.getSize(edge.first)) {
            ret += uf.getCnt(edge.first);
            uf.clr(edge.first);
        }
    }
    cout << m - ret << "\n";
    return 0;
}

