struct union_find {
    vector<int> data;
    vector<int> w;
    union_find(int size) : data(size, -1), w(size) {}
    void set(int i, int x) {
        w[i] = x;
    }
    void unite(int x, int y) {
        x = root(x); y = root(y);
        if(x != y) {
            if(data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
            w[x] += w[y];
        }
    }
    int weight(int x) {
        x = root(x);
        return w[x];
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : (data[x] = root(data[x]));
    }
    int size(int x) {
        return -data[root(x)];
    }
};

signed main() {
    int N, M;
    cin >> N >> M;
    vector<int> X(N);
    cin >> X;
    union_find uf(N);
    REP(i, N) uf.set(i, X[i]);

    vector<vi> E(M);
    vector<vector<pii>> g(N);
    REP(i, M) {
        int a, b, c;
        cin >> a >> b >> c;
        a--, b--;
        E[i] = {c, a, b};
        g[a].push_back({b, i});
        g[b].push_back({a, i});
    }
    sort(ALL(E));

    vector<int> wlog(M);
    REP(i, M) {
        int a = E[i][1];
        int b = E[i][2];
        if (!uf.same(a, b)) {
            uf.unite(a, b);
        }
        wlog[i] = uf.weight(a);
    }

    int ans = 0;
    vector<bool> alive(M, true);
    REPR(i, M - 1) {
        int c = E[i][0];
        int a = E[i][1];
        int b = E[i][2];
        if (!alive[i]) continue;

        auto w = wlog[i];
        if (w >= c) {
            queue<int> q;
            q.push(a);
            while (!q.empty()) {
                int v = q.front(); q.pop();
                FORE(e, g[v]) {
                    int w = e.first;
                    int idx = e.second;
                    if (!alive[idx]) continue;
                    alive[idx] = false;
                    q.push(w);
                }
            }
        } else {
            alive[i] = false;
            ans++;
        }
    }
    cout << ans << endl;
    return (0^_^0);
}

