	int u,v,w;
	bool operator < (const edge &e)const
	{
		return w < e.w;
	}
}el[maxn];
void build(int id,int l,int r){
	if(l == r) dat[id] = x[l];
	else{
		int mid = (l + r) >> 1;
		build(id << 1,l,mid);
		build(id << 1 | 1,mid + 1,r);
		dat[id] = min(dat[id << 1],dat[id << 1 | 1]);
	}
}
void update(int id,int l,int r,int pos,ll val){
	if(l == r) dat[id] = val;
	else{
		int mid = (l + r) >> 1;
		if(pos <= mid) update(id << 1,l,mid,pos,val);
		else update(id << 1 | 1,mid + 1,r,pos,val);
		dat[id] = min(dat[id << 1],dat[id << 1 | 1]);
	}
}
void ini(){
	for(int i=1;i<=n;i++){
		par[i] = i;
		hei[i] = 1;
	}
}
int fin(int u){
	if(par[u] == u) return u;
	return par[u] = fin(par[u]);
}
void uni(int u,int v,int w){//edge weight = w.
	u = fin(u),v = fin(v);
	if(u == v){
		y[u] = w;
		update(1,1,n,u,x[u] - y[u]);
	}else{
		if(hei[u] < hei[v]){
			par[u] = v;
			update(1,1,n,u,0);
			x[v] += x[u];
			y[v] = w;
			update(1,1,n,v,x[v] - y[v]);
		}else{
			par[v] = u;
			update(1,1,n,v,0);
			x[u] += x[v];
			y[u] = w;
			update(1,1,n,u,x[u] - y[u]);
			if(hei[u] == hei[v]) hei[u]++;
		}
	}
}
