int findher(int a){
    if(a == parent[a])return a;
    return parent[a] = findher(parent[a]);
}

void tmerge(int a,int b){
    a = findher(a);
    b = findher(b);
    if(sz[a] < sz[b])
        swap(a , b);
    parent[b] = a;
    sum[a] += sum[b];
    sz[a] += sz[b];
    edge[a] += edge[b];
    for(int j=0;j<(int)g[b].size();j++){
        g[a].push_back(g[b][j]);
    }
}

