/*他のライブラリを入れる場所*/
int solve(vl&vertex, vector<vector<pii>>&edge, vb isSearch, ll prevSum=LINF){

	int cnt=0;
	ll sum=0;
	rep(i,n)if(!isSearch[i])sum+=vertex[i];

	rep(i,n)if(!isSearch[i]){
		for(auto&e:edge[i]){
			if(e.sc>sum and e.sc<=prevSum)cnt++;
		}
	}
	if(cnt==0)return 0;

	vb isBFS=isSearch;
	rep(i,n)if(!isBFS[i]){
		vb nextis(n,true);
		queue<int> q;
		q.push(i);
		ll vsum=0;
		ll emax=0;
		while(!q.empty()){
			int p=q.front();
			q.pop();
			if(isBFS[p])continue;
			isBFS[p]=true;
			nextis[p]=false;
			vsum+=vertex[p];
			for(auto&e:edge[p]){
				int nxt; ll cst;
				tie(nxt,cst)=e;
				if(cst>sum)continue;
				chmax(emax,cst);
				if(isBFS[nxt])continue;
				q.push(nxt);
			}
		}
		if(vsum<emax) cnt+=solve(vertex,edge,nextis,sum);
	}
	return cnt;
}
