    for (int i = 0; i < n; i++) node_sum_tmp[i] = x[i];
    for (auto& pp : memo) {
        ll cost = pp.first;
        vector<P>& pv = pp.second;
        vector<int> idx;
        vector<ll> foo(pv.size(), 0), bar(pv.size(), 0);
        for (int i = 0; i < pv.size(); i++) {
            idx.push_back(i);
            bar[i] = (uf_tmp.same(pv[i].first, pv[i].second) ? node_sum_tmp[uf_tmp.find(pv[i].first)] : node_sum_tmp[uf_tmp.find(pv[i].first)] + node_sum_tmp[uf_tmp.find(pv[i].second)]);
            foo[i] = max({cost, edge_max_tmp[uf_tmp.find(pv[i].first)], edge_max_tmp[uf_tmp.find(pv[i].second)]});
            //cout << pv[i].first << " " << bar[i] << endl;
        }
        sort(idx.begin(), idx.end(), [&](const int i1, const int i2){return bar[i1] - foo[i1] >  bar[i2] - foo[i2];});

        for (int i : idx) {
            es.emplace_back(cost, pv[i].first, pv[i].second);
            if (uf_tmp.same(pv[i].first, pv[i].second)) {
                edge_max_tmp[uf_tmp.find(pv[i].first)] = max(cost, edge_max_tmp[uf_tmp.find(pv[i].first)]);
            } else {
                int ra = uf_tmp.find(pv[i].first), rb = uf_tmp.find(pv[i].second);
                uf_tmp.unite(pv[i].first, pv[i].second);
                int r = uf_tmp.find(pv[i].first);
                if (r == ra) {
                    node_sum_tmp[r] += node_sum_tmp[rb];
                    node_sum_tmp[rb] = 0;
                    edge_max_tmp[r] = max({cost, edge_max_tmp[r], edge_max_tmp[rb]});
                    edge_max_tmp[rb] = 0;
                } else {
                    node_sum_tmp[r] += node_sum_tmp[ra];
                    node_sum_tmp[ra] = 0; 
                    edge_max_tmp[r] = max({cost, edge_max_tmp[r], edge_max_tmp[ra]});
                    edge_max_tmp[ra] = 0;                 
                }                
            }
        }
    }

    int ok = 0, ng = m + 1;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;

        vector<ll> node_sum(n, 0);
        for (int i = 0; i < n; i++) node_sum[i] = x[i];

        vector<ll> edge_max(n, 0);
        UnionFind uf(n);

        for (int i = 0; i < mid; i++) {
            ll cost;
            int a, b;
            tie(cost, a, b) = es[i];

            if (uf.same(a, b)) {
                int r = uf.find(a);
                edge_max[r] = max(edge_max[r], cost);               
            } else {
                int ra = uf.find(a), rb = uf.find(b);
                uf.unite(a, b);
                int r = uf.find(a);
                if (r == ra) {
                    node_sum[r] += node_sum[rb];
                    node_sum[rb] = 0;
                    edge_max[r] = max({cost, edge_max[r], edge_max[rb]});
                    edge_max[rb] = 0;
                } else {
                    node_sum[r] += node_sum[ra];
                    node_sum[ra] = 0; 
                    edge_max[r] = max({cost, edge_max[r], edge_max[ra]});
                    edge_max[ra] = 0;                 
                }
            }
        }

        bool flag = true;
