UnionFindTree::UnionFindTree(int size) 
	: size_m(size), parent_m(size), card_m(size, 1) {
	for (int i = 0; i < size; ++i) {
		parent_m[i] = i;
	}
}

bool UnionFindTree::isValidIndex(int i) const {
	return i >= 0 && i < size();
}

int UnionFindTree::rootOf(int i) const {
	assert(isValidIndex(i));

	if (parent_m[i] == i) return i;
	return parent_m[i] = rootOf(parent_m[i]);
}

bool UnionFindTree::isSame(int i, int j) const {
	assert(isValidIndex(i) && isValidIndex(j));

	int ri = rootOf(i);
	int rj = rootOf(j);
	return ri == rj;
}

void UnionFindTree::unite(int i, int j) {
	assert(isValidIndex(i) && isValidIndex(j));

	int ri = rootOf(i);
	int rj = rootOf(j);

	if (ri == rj) return;
	if (card_m[ri] < card_m[rj]) {
		std::swap(ri, rj);
	}

	// assert(card_m[ri] >= card_m[rj]);
	parent_m[rj] = ri;
	card_m[ri] += card_m[rj];
}

int UnionFindTree::size() const {
	return size_m;
}

/* 頂点 i の属する集合のサイズ */
int UnionFindTree::cardinalityOf(int i) const {
	assert(isValidIndex(i));

	int ri = rootOf(i);
	return card_m[ri];
}

std::vector<std::vector<int>> UnionFindTree::toGroups() const {
	std::vector<std::vector<int>> groups(size_m);

	for (int i = 0; i < size_m; ++i) {
		int ri = rootOf(i);
		groups[ri].push_back(i);
	}

	std::vector<std::vector<int>> ret;
	for (int i = 0; i < size_m; ++i) {
		if (groups[i].empty()) continue;
		ret.push_back(groups[i]);
	}
	return ret;
}

WeightedUnionFindTree::WeightedUnionFindTree(int size)
	: size_m(size), parent_m(size), diff_m(size), card_m(size, 1) {
	for (int i = 0; i < size; ++i) {
		parent_m[i] = i;
	}
}

bool WeightedUnionFindTree::isValidIndex(int i) const {
	return i >= 0 && i < size();
}

int WeightedUnionFindTree::rootOf(int i) const {
	assert(isValidIndex(i));

	if (parent_m[i] == i) return i;

	diff_m[i] += weight(parent_m[i]);
	return parent_m[i] = rootOf(parent_m[i]);
}

bool WeightedUnionFindTree::isSame(int i, int j) const {
	assert(isValidIndex(i) && isValidIndex(j));

	return rootOf(i) == rootOf(j);
}

// weight[j] - weight[i] を返す
int64_t WeightedUnionFindTree::query(int i, int j) const {
	assert(isValidIndex(i) && isValidIndex(j));

	return weight(j) - weight(i);
}

bool WeightedUnionFindTree::unite(int i, int j, int64_t diff) {
	assert(isValidIndex(i) && isValidIndex(j));

	int64_t diff_roots = diff + weight(i) - weight(j);
	int ri = rootOf(i);
	int rj = rootOf(j);
	if (ri == rj) return false;
	if (card_m[ri] < card_m[rj]) {
		std::swap(ri, rj);
		diff_roots = -diff_roots;
	}

	// assert(card_m[ri] >= card_m[rj]);
	parent_m[rj] = ri;
	card_m[ri] += card_m[rj];
	diff_m[rj] = diff_roots;

	return true;
}

int64_t WeightedUnionFindTree::weight(int i) const {
	rootOf(i);		// 再計算のため
	return diff_m[i];
}

int WeightedUnionFindTree::size() const {
	return size_m;
}
