            queue<int> qu;
            qu.push(edges[i].src);
            qu.push(edges[i].dst);
            visit[edges[i].src] = visit[edges[i].dst] = 1;
            const int maxW = edges[i].w;
            int check = 0;
            while(!qu.empty()){
                int pos = qu.front(); qu.pop();
                for(auto& e : g[pos]){
                    if(e.w > maxW) continue;
                    check++;
                    if(!visit[e.dst]){
                        visit[e.dst] = 1;
                        qu.push(e.dst);
                    }
                }
            }
            res -= check/2;
        }
        cout << res << endl;
    }
}

