struct UF{
	int n;
	vector<int>parent,rank;
	vector<long>w;
	UF(int n_=0):n(n_),parent(n_),rank(n_,0),w(n_)
	{
		for(int i=0;i<n_;i++)
		{
			parent[i]=i;
			w[i]=x[i];
		}
	}
	int find(int a)
	{
		return parent[a]!=a?parent[a]=find(parent[a]):a;
	}
	bool same(int a,int b)
	{
		return find(a)==find(b);
	}
	bool unite(int a,int b)
	{
		a=find(a),b=find(b);
		if(a==b)return false;
		if(rank[a]<rank[b])
		{
			parent[a]=b;
			w[b]+=w[a];
		}
		else
		{
			parent[b]=a;
			w[a]+=w[b];
			if(rank[a]==rank[b])rank[a]++;
		}
		return true;
	}
};
