class persistentUF {
public:
  const static int MAX_N = 20;
  unordered_map<int, int> par[MAX_N];
  map<int, ll> sz[MAX_N];
  int rank[MAX_N];
  int fin[MAX_N];
  int idx;

  persistentUF() { init(); }
  void init() {
    idx = 0;
    rep(i, MAX_N) par[i][0] = i, rank[i] = 1, fin[i] = 0;
  }
  persistentUF(int n) { init(n); }
  void init(int n) {
    idx = 0;
    rep(i, n) par[i][0] = i, rank[i] = 1, fin[i] = 0;
  }

  int find(int x, int t) {
    if(t >= fin[x] && par[x][fin[x]] != x) return find(par[x][fin[x]], t);
    return x;
  }

  ll getsize(int x, int t){
	  x = find(x,t);
	  auto it = sz[x].upper_bound(t);
	  it--;
	  return it->sc;
  }

  void unite(int x, int y) {
    x = find(x, idx);
    y = find(y, idx);
	ll szx = getsize(x,idx);
	ll szy = getsize(y,idx);
    idx++;
    if(x == y) return;
    if(rank[x] < rank[y]) par[x][idx] = y, fin[x] = idx, sz[y][idx] = szx+szy;
    else {
      par[y][idx] = x, fin[y] = idx, sz[x][idx] = szx+szy;
      if(rank[x] == rank[y]) rank[x]++;
    }
  }

  bool same(int x, int y, int t) { return find(x, t) == find(y, t); }
};

