int get_root(int u) {
	if (parent[u] != u) {
		parent[u] = get_root(parent[u]);
	}
	return parent[u];
}

void merge(int u, int v, ll w) {
	u = get_root(u);
	v = get_root(v);
	if (u == v) {
		if (w > wt[u]) {
			pq[u].push(w);
		} else {
			clear_pq(u);
		}
		return;
	}
	if (sz[u] < sz[v]) {
		swap(u, v);
	}
	wt[u] += wt[v];
	sz[u] += sz[v];
	parent[v] = u;
	if (w > wt[u]) {
		while (!pq[v].empty()) {
			pq[u].push(pq[v].top());
			pq[v].pop();
		}
		pq[u].push(w);
	} else {
		clear_pq(u);
		clear_pq(v);
	}
}

void clear_pq(int i) {
	while (!pq[i].empty()) {
		pq[i].pop();
	}
}

