        if(uf.sz[u] < uf.sz[v]) swap(u, v);
        uf.unite(u, v);
        h.push_back(T(u, v, e.w));
    }
    reverse(h.begin(), h.end());
    for(auto e : h){
        int u, v, w;
        tie(u, v, w) = e;
        int p = uf.find(u);
        if(uf.sum[p] >= w) continue;
        uf.split(u, v);
