class UnionFind
{
    std::vector<P> data; // 要素数, 連結成分中の頂点重み和

public:
    UnionFind(int size, const vector<ll> &w) : data(size)
    {
        assert(size == w.size());
        for (int i = 0; i < size; i++)
        {
            data[i] = P(-1, w[i]);
        }
    }
    ll unite(int x, int y)
    {
        x = root(x).first;
        y = root(y).first;
        if (x != y)
        {
            if (data[y].first < data[x].first)
                std::swap(x, y);
            data[x].first += data[y].first;
            data[x].second += data[y].second;
            data[y].first = x;
            data[y].second = data[x].second;
        }
        return data[x].second;
    }
    bool find(int x, int y)
    {
        return root(x) == root(y);
    }
    P root(int x)
    {
        return data[x].first < 0 ? P(x, data[x].second) : data[x] = root(data[x].first);
    }
    int size(int x)
    {
        return -data[root(x).first].first;
    }
};

