struct UnionFind{
	vi parent,size;
	vl sum;
	map<tuple<int,int>,tuple<int,int,int>> logs;
	UnionFind(const vi& xs):parent(xs.size(),-1),size(xs.size(),1),sum(all(xs)){}
	int Find(int i){
		return parent[i]==-1?i:Find(parent[i]);
	}
	bool Unite(int a,int b){
		int ra=Find(a),rb=Find(b);
		if(ra==rb)
			return false;
		if(size[ra]<size[rb])
			swap(ra,rb);
		logs[mt(a,b)]=mt(ra,rb,parent[ra]);
		parent[rb]=ra;
		size[ra]+=size[rb];
		sum[ra]+=sum[rb];
		return true;
	}
	void Rollback(int a,int b){
		int ra,rb,pa; tie(ra,rb,pa)=logs[mt(a,b)];
		parent[rb]=pa;
		size[ra]-=size[rb];
		sum[ra]-=sum[rb];
	}
};

int main()
{
	#ifndef _GLIBCXX_DEBUG
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	constexpr char endl='\n';
	#endif

	for(int n,m;cin>>n>>m&&n|m;){
		vi xs(n);
		rep(i,n) cin>>xs[i];
		vi us(m),vs(m),ws(m);
		vector<tuple<int,int,int>> es(m);
		rep(i,m){
			int u,v,w; cin>>u>>v>>w; u--,v--;
			es[i]={u,v,w};
		}
		sort(all(es),[](auto a,auto b){return get<2>(a)<get<2>(b);});

		UnionFind uf(xs);

		vi used(m);
		rep(i,m){
			int u,v,w; tie(u,v,w)=es[i];
			used[i]=uf.Unite(u,v);
		}

		int res=0;
		per(i,m){
			int u,v,w; tie(u,v,w)=es[i];
			int ra=uf.Find(u),rb=uf.Find(v);
			assert(ra==rb);
			if(uf.sum[ra]>=w)
				continue;
			res++;
			if(!used[i])
				continue;
			if(uf.sum[ra]<w)
				uf.Rollback(u,v);
		}
		cout<<res<<endl;
	}
}

