ll ans = 0;
bool used[100010];
void dfs(int n,int w) {
	//pe(n); print(w);
	for (auto e : G[n]) {
		if (e.cost > w || used[e.index])continue;
		ans++; used[e.index] = true;
		dfs(e.to, w);
	}
}
void solve() {
	int N, M; cin >> N >> M;
	//es.resize(M);
	REP(i, N)cin >> X[i];
	REP(i, M) {
		int u, v, c; cin >> u >> v >> c; u--, v--;
		es.push_back({ u,v,c,i });
		G[u].push_back({ u,v,c,i });
		G[v].push_back({ v,u,c,i });
	}
	sort(all(es), comp);
	init(N);
	REP(i, N) {
		W[i] = X[i];
	}
	vector<edge>use;
	REP(i, M) {
		edge e = es[i];
		unite(e.from, e.to);
		if (W[find(e.from)] >= e.cost) {
			//pe(e.from); print(e.to);
			use.push_back(e);
		}
	}
	VREVERSE(use);
	REP(i,use.size()){
		dfs(use[i].from, use[i].cost);
	}
	print(M - ans);
}

