class DSU {
private:
    vector<int> parents;
    vector<int> sizes;
    vector<int> weights;
public:
    DSU(int n, vector<int> w) {
        parents.resize(n+1);
        for(int i = 1; i <= n; ++i) parents[i] = i;
        sizes.resize(n+1);
        for(int i = 1; i <= n; ++i) sizes[i] = 1;
        weights = w;
    }

    int root(int i) {
        while(parents[i] != i) {
            parents[i] = parents[parents[i]];
            i = parents[i];
        }
        return i;
    }

    int getWeight(int i) {
        int r = root(i);
        return weights[r];
    }

    bool find(int a, int b) {
        return root(a) == root(b);
    }

    void join(int a, int b) {
        int root_a = root(a);
        int root_b = root(b);

        if(root_a == root_b) return;

        if(sizes[root_a] < sizes[root_b]) {
            parents[root_a] = parents[root_b];
            sizes[root_b] += sizes[root_a];
            weights[root_b] += weights[root_a];
        } else {
            parents[root_b] = parents[root_a];
            sizes[root_a] += sizes[root_b];
            weights[root_a] += weights[root_b];
        }
    }
};

struct edge {
    int a;
    int b;
    int weight;

    bool operator<(const edge& other) const {
        return weight < other.weight;
    }
};

edge make_edge(int aa, int bb, int w) {
