}

int32_t main() {

    int n, m; cin >> n >> m;
    vector<int> x(n+1);
    for(int i = 1; i <= n; ++i) cin >> x[i];

    vector<vector<edge>> graph(n+1, vector<edge>());

    DSU dsu(n, x);
    vector<edge> edges(m);
    for(int i = 0; i < m; ++i)
        cin >> edges[i].a >> edges[i].b >> edges[i].weight;
    sort(edges.begin(), edges.end());

    vector<int> leftBehind(n+1, 0);
    int ret = 0;
    for(int i = 0; i < m; ++i) {
        edge& cur = edges[i];
        if(dsu.find(cur.a, cur.b)) {
            if(cur.weight > dsu.getWeight(cur.a)) {
                ret++;
            }
        } else {
            int ra = dsu.root(cur.a), rb = dsu.root(cur.b);
            dsu.join(cur.a, cur.b);
            int root = dsu.root(cur.a);
            int nw = dsu.getWeight(cur.a);
            leftBehind[root] = leftBehind[ra] + leftBehind[rb];
            //watch(root);
