	if (fa[u] < 0)
		return u;

	fa[u] = getfa(fa[u]);
	return fa[u];
}

void unify(int a, int b) {
	fa[b] += fa[a];
	fa[a] = b;
}

void keepEdges(int u, int lim) {
	if (vis[u])
		return;

	vis[u] = true;
	for (int i = 0; i < g[u].size(); ++i) {
		int idx = g[u][i];
		if (edges[idx].y <= lim) {
			ok[idx] = true;
			keepEdges(edges[idx].v, lim);
		}
	}
}

