struct UnionFind {
  vector<int> parent;
  vector<ll> sum;
  UnionFind (int n) : parent(n, -1), sum(n, 0) {}
  int root(int x) { return parent[x] < 0 ? x : parent[x] = root(parent[x]); }
  bool merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (parent[y] < parent[x]) swap(x, y);
    if (parent[x] == parent[y]) --parent[x];
    parent[y] = x;
    sum[x] += sum[y];
    return true;
  }
};

void dfs(const vector<vector<tuple<int,ll,int>>>& g, vector<bool>& save, vector<bool>& vis, int v, ll y) {
  vis[v] = true;
  for (auto&& e : g[v]) {
    int to,i;
    ll w;
    tie(to, w, i) = e;
    if (w > y) continue;
    save[i] = true;
    if (vis[to]) continue;
    dfs(g, save, vis, to, y);
  }
}

