struct UF{
	vector<int> par, sz;
	vector<LL> xs;
	VV(int) attr;
	explicit UF(const vector<LL> &xs_){
		int n = xs_.size();
		par.resize(n);
		sz.assign(n, 1);
		attr.resize(n);
		xs = xs_;
		iota(ALL(par), 0);
	}
	int find(int x){
		while(x != par[x]){ x = par[x]; }
		return x;
	}
	bool unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y){ return false; }
		if(sz[x] < sz[y]){ swap(x, y); }
		sz[x] += sz[y];
		par[y] = x;
		xs[x] += xs[y];

		if(attr[x].size() < attr[y].size()){
			attr[x].swap(attr[y]);
		}
		attr[x].insert(attr[x].end(), ALL(attr[y]));
		vector<int>().swap(attr[y]);
		return true;
	}
};

