struct UnionFind{
    vector<int> par;
    vector<int> dep;
    vector<ll> ma,sum;
    UnionFind(int siz){
        par.assign(siz,0);
        dep.assign(siz,0);
        ma.assign(siz,0);
        sum.assign(siz,0);
        for(int i=0;i<siz;i++){
            par[i]=i;
            sum[i]=x[i];
        }
    };
    int find(int x){
        if(par[x]==x){
            return x;
        }else{
            return par[x]=find(par[x]);
        }
    }
    bool unite(int x,int y,ll c){
        int u=x,v=y;
        x=find(x);
        y=find(y);        
        if(x==y){
            ma[y]=max(ma[y],max(ma[x],c));
            return false;
        }
        if(dep[x]<dep[y]){
            par[x]=y;
            ma[y]=max(ma[y],max(ma[x],c));
            sum[y]+=sum[x];
        }else{
            par[y]=x;
            ma[x]=max(ma[x],max(ma[y],c));
            sum[x]+=sum[y];
            if(dep[x]==dep[y]){
                dep[x]++;
            }
        }
        return true;
    }
    bool same(int x,int y){
        return find(x)==find(y);
    }
};
