void dfs(int x, int now)
{
	if(used[x]) return; 
	used[x] = 1;
	for(int i = h[x]; i; i = nxt[i])
	{
		if(i / 2 > now) continue;
		ok[i >> 1] = 1;
		dfs(to[i], now);
