lint vw[100010];
lint edge_no[100010];

vector<int> pending[100010];

class UnionFind {
    vector<int> par;

    public:
    int root(int a) {
        if(a == par[a]) return a;
        return par[a] = root(par[a]);
    }

    UnionFind(int size) : par(size) {iota(begin(par), end(par), 0);}
    void unite(int A, int B) {
        int rb = root(B);
        int ra = root(A);
        if(rb != ra) {
            lint tmp = vw[rb] + vw[ra];
            vw[rb] = vw[ra] = tmp;
            tmp = edge_no[ra] + edge_no[rb];
            edge_no[ra] = edge_no[rb] = tmp;
        }
        par[root(B)] = root(A);
    }
    bool eq(int A, int B) { return root(B) == root(A);}
};

