    UnionFind uf(n+5);
    for(const edge &e: es) {
        int pv = uf.root(e.v);
        if(uf.eq(e.v, e.w)) {
            if(vw[pv] >= e.cost) {
                // edge_no[pv] = 0;
                continue;
            } else {
                edge_no[pv]++;
            }
        } else {
            uf.unite(e.v, e.w);
            if(vw[pv] >= e.cost) {
                edge_no[pv] = 0;
            } else {
                edge_no[pv]++;
            }
        }
    }

    int ans = 0;
    vector<int> seen(n+5);
    rep(i, n) {
        int j = uf.root(i);
        if(seen[j]) continue;
        seen[j] = 1;
        ans += edge_no[j];
    }
    cout << ans << endl;
}

