bool marked[100000+10];
void mark(int u, int c) {
  if(marked[u]) {
    return;
  }
  // cerr << "mark! " << u+1 << endl;
  marked[u] = true;
  for(const E& e : g[u]) {
    if(e.c <= c) {
      mark(e.b, c);
    }
  }
}

