tpl es[100010];
UnionFindTree uft;
bool is_cand[100010];
bool used_e[100010];
bool used_n[100010];
vector<pii> G[100010];

void rec(int pos, int y){
    used_n[pos] = true;
    for(pii p : G[pos]){
        int npos = p.first;
        int eid = p.second;
        if(get<0>(es[eid]) > y){
            continue;
        }
        used_e[eid] = true;
        if(!used_n[npos]){
            rec(npos, y);
        }
    }
}

