        cin >> A[i] >> B[i] >> Y[i]; A[i]--; B[i]--;
        es[i] = tpl(Y[i], A[i], B[i]);
        sorted.push_back(pii(Y[i], i));
        rsorted.push_back(pii(Y[i], i));
        G[A[i]].push_back(pii(B[i], i));
        G[B[i]].push_back(pii(A[i], i));
    }

    uft.init(N, X);

    sort(sorted.begin(), sorted.end());
    sort(rsorted.begin(), rsorted.end(), greater<pii>());

    for(int i = 0; i < M; i++){
        auto t = sorted[i];
        int y = get<0>(t);
        int eid = get<1>(t);
        int a = get<1>(es[eid]);
        int b = get<2>(es[eid]);
        uft.unite(a, b);
        if(y <= uft.getCnt(a)){
            is_cand[eid] = true;
        }
    }

    for(int i = 0; i < M; i++){
        auto t = rsorted[i];
        int y = get<0>(t);
        int eid = get<1>(t);
        if(is_cand[eid]){
            int a = get<1>(es[eid]);
            int b = get<2>(es[eid]);
            // 小さい順番にdfsしていく
            if(used_e[eid]) continue;
            if(!used_n[a]) rec(a, y);
            if(!used_n[b]) rec(b, y);
        }
    }


    int ans = 0;
    for(int i = 0; i < M; i++){
        if(!used_e[i]) ans++;
    }

    cout << ans << endl;


    return 0;
}

