template<typename T>
struct UFkai{
    vector<int> par,siz;
    vector<T> a;
    using F=function<T(T,T)>;
    const F f;
    UFkai(int n,F f):f(f){
        par.resize(n);siz.assign(n,1);
        iota(ALL(par),0);
        a.resize(n,0);
    }
    void set(int i,T x){a[i]=x;}
    int root(int x){return (par[x]==x?x:(par[x]=root(par[x])));}
    bool unite(int x,int y){
        x=root(x),y=root(y);
        if(x==y) return false;
        if(siz[x]<siz[y]) swap(x,y);
        siz[x]+=siz[y];par[y]=x;
        a[x]=f(a[x],a[y]);
        return true;
    }
    T get(int x){return a[root(x)];}
    int size(int x){return siz[root(x)];}
    bool sameRoot(int x,int y){return root(x)==root(y);}
};

