void make_llist(V<t3> linklist[], const V<t4> &cost_edges)
{
    for (auto cost_edge : cost_edges) {
        ll ecost = get<0>(cost_edge);
        ll v1 = get<1>(cost_edge);
        ll v2 = get<2>(cost_edge);
        ll eidx = get<3>(cost_edge);

        linklist[v1].pb(t3(v2, eidx, ecost));
        linklist[v2].pb(t3(v1, eidx, ecost));
    }
}

void find_cand(UnionFind &uf, ll vsums[100005], bool e_iscand[100005],
               ll ecost, ll v1, ll v2, ll eidx)
{
    ll root1 = uf.root(v1);
    ll root2 = uf.root(v2);
    ll root = root1;

    if (root1 != root2) {
        ll newsum = vsums[root1] + vsums[root2];
        uf.unite(root1, root2);
        root = uf.root(root1);
        vsums[root] = newsum;
    }

    if (ecost < vsums[root]) e_iscand[eidx] = true;
}

void update_e_pass(bool e_pass[100005], const V<t3> linklist[100005],
                   ll ecost, ll v1, ll v2, ll eidx)
{
    queue<ll> q;
    static bool checked[100005];
    memset(checked, 0, sizeof(checked));

    q.push(v1); q.push(v2);
    checked[v1] = checked[v2] = true;
    e_pass[eidx] = true;

    while (!q.empty()) {
        ll v = q.front(); q.pop();
        // linklist[] ... (t3(v, eidx, ecost), ... );
        for (auto link : linklist[v]) {
            ll nv = get<0>(link);
            ll neidx = get<1>(link);
            ll necost = get<2>(link);

            if (ecost < necost) continue;

            e_pass[neidx] = true;

            if (checked[nv]) continue;

            checked[nv] = true;
            q.push(nv);
        }
    }
}

int _main()
{
    ll n; llin(n);
    ll m; llin(m);
    V<ll> xlist; xlist.pb(1e18); llina(xlist, n);
    V<t3> abylist; llinl3(abylist, m);

    V<t4> cost_edges;
    rep (i, m) {
        ll a = get<0>(abylist[i]);
        ll b = get<1>(abylist[i]);
        ll y = get<2>(abylist[i]);
        cost_edges.pb(t4(y, a, b, i));
    }

    sort(cost_edges);

    UnionFind uf(n);
    static ll vsums[100005];
    rep (i, n+1) vsums[i] = xlist[i];
    static bool e_iscand[100005];
    memset(e_iscand, 0, sizeof(e_iscand));

    static V<t3> linklist[100005];
    make_llist(linklist, cost_edges);

    for (auto cost_edge : cost_edges) {
        ll ecost = get<0>(cost_edge);
        ll v1 = get<1>(cost_edge);
        ll v2 = get<2>(cost_edge);
        ll eidx = get<3>(cost_edge);
        find_cand(uf, vsums, e_iscand, ecost, v1, v2, eidx);
    }

    debug_printf("---- e_iscand\n"); debug_print(e_iscand, m+1);

    sort_reverse(cost_edges);

    static bool e_pass[100005];
    memset(e_pass, 0, sizeof(e_pass));

    for (auto cost_edge : cost_edges) {
        ll ecost = get<0>(cost_edge);
        ll v1 = get<1>(cost_edge);
        ll v2 = get<2>(cost_edge);
        ll eidx = get<3>(cost_edge);

        if (e_pass[eidx] || !e_iscand[eidx]) continue;

        update_e_pass(e_pass, linklist, ecost, v1, v2, eidx);
    }

    ll passcount = 0LL;
    rep (i, m) {
        if (e_pass[i]) passcount++;
    }

    debug_printf("--- ans\n");
    cout << m - passcount << endl;

    return 0;
}

