    for(int i = 0;i < M;i++) {
        DS.merge(e[i].from,e[i].to);
        int r = DS.root(e[i].from);
        if(DS.node_weight[r] >= e[i].cost) {
            ans -= DS.edge_num[r];
            DS.edge_num[r] = 0;
        }
    }

    cout<<ans<<endl;

    return 0;
}

