struct UnionFind {
    //各要素が属する集合の代表(根)を管理する
    //もし、要素xが根であればdata[x]は負の値を取り、-data[x]はxが属する集合の大きさに等しい
    vector<int> data;

    UnionFind(int sz) : data(sz, -1) {}

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        bool is_union = (x != y);
        if (is_union) {
            if (data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return is_union;
    }

    int find(int x) {
        if (data[x] < 0) { //要素xが根である
            return x;
        } else {
            data[x] = find(data[x]); //data[x]がxの属する集合の根でない場合、根になるよう更新される
            return data[x];
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return -data[find(x)];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    vector<ll> x(n);
    for (int i = 0; i < n; i++) cin >> x[i];

    map<ll, vector<P> > memo;
    vector<T> es;
    for (int i = 0; i < m; i++) {
        int a, b;
        ll y;
        cin >> a >> b >> y;
        a--; b--;
        //es.emplace_back(y, a, b);
        memo[y].emplace_back(a, b);
    }
    //sort(es.begin(), es.end());

    vector<ll> cs;
    for (auto& pp : memo) {
        cs.push_back(pp.first);
    }

    int ok = 0, ng = cs.size() + 1;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;

        vector<ll> node_sum(n, 0);
        for (int i = 0; i < n; i++) node_sum[i] = x[i];

        vector<ll> edge_max(n, 0);
        UnionFind uf(n);

        for (int i = 0; i < mid; i++) {
            ll cost = cs[i];
            for (P& p : memo[cs[i]]) {
                int a = p.first, b = p.second;
                if (uf.same(a, b)) {
                    int r = uf.find(a);
                    edge_max[r] = max(edge_max[r], cost);               
                } else {
                    int ra = uf.find(a), rb = uf.find(b);
                    uf.unite(a, b);
                    int r = uf.find(a);
                    if (r == ra) {
                        node_sum[r] += node_sum[rb];
                        node_sum[rb] = 0;
                        edge_max[r] = max({cost, edge_max[r], edge_max[rb]});
                        edge_max[rb] = 0;
                    } else {
                        node_sum[r] += node_sum[ra];
                        node_sum[ra] = 0; 
                        edge_max[r] = max({cost, edge_max[r], edge_max[ra]});
                        edge_max[ra] = 0;                 
                    }
                }
            }
        }

        bool flag = true;
        for (int i = 0; i < n; i++) {
            if (uf.find(i) != i) continue;
            if (node_sum[i] < edge_max[i]) {
                flag = false;
                break;
            }
        }

        //cout << mid << " " << flag << endl;

        (flag ? ok : ng) = mid;
    }
    int ans = m;
    for (int i = 0; i < ok; i++) {
        ans -= (int)memo[cs[i]].size();
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<long long int> x;

struct UnionFind{
    vector<int> parent;
    vector<int> size;
    vector<int> rank;
    vector<long long int> sum;

    /* constructor (initialize) */
    UnionFind(int n){
        parent.resize(n);
        size.resize(n);
        rank.resize(n);
        sum.resize(n);
        for(int i=0; i<n; i++){
            parent[i] = i;// completely-disjoint
            size[i] = 1;
            rank[i] = 0;// union by rank
            sum[i] = x[i];
        }
    }

    int root(int x){
        // terminal case
        if(parent[x] == x){
            return x;// by definition
        }

        // recursion
        parent[x] = root(parent[x]);// path compression : keep tree as shallow as possible
        return parent[x];
    }

    void merge(int x, int y){
        int rx = root(x);
        int ry = root(y);

        // if (root(x) == root(y)) do nothing;
        if (rx != ry){
            if(rank[rx] < rank[ry]){
                parent[rx] = ry;// root of merged tree = ry
                size[ry] += size[rx];
                sum[ry] += sum[rx];
            }
            else if(rank[rx] == rank[ry]){
                parent[rx] = ry;
                size[ry] += size[rx];
                sum[ry] += sum[rx];
                rank[ry] += 1;
            }
            else if(rank[rx] > rank[ry]){
                parent[ry] = rx;// root of merged tree = rx
                size[rx] += size[ry];
                sum[rx] += sum[ry];
            }
        }
        return;
    }

    bool same(int x, int y){ return root(x) == root(y); }

    int nodes(int x){ return size[root(x)]; }

    long long int total(int x){ return sum[root(x)]; }
};

vector<vector<pair<pair<int, long long int>,int>>> graph;
vector<bool> flag;
vector<bool> visited;

void DFS(int a, long long int y){
    for(auto adjacent : graph[a]){
        int b = adjacent.first.first;
        int id = adjacent.second;
        //cout << "DFS : " << a+1 << " " << b+1 << " " << y << endl;
        if(visited[b] == true || adjacent.first.second > y) continue;

        flag[id] = true;
        visited[b] = true;
        DFS(b,y);
    }
}

int main(){
    int n, m;
    cin >> n >> m;

    x.resize(n);
    for(int i=0; i<n; i++){
        cin >> x[i];
    }

    graph.resize(n);
    vector<pair<pair<long long int, pair<int,int>>,int>> edge(m);
    for(int i=0; i<m; i++){
        int a, b;
        long long int y;
        cin >> a >> b >> y;
        a -= 1;
        b -= 1;
        graph[a].push_back({{b,y},i});
        graph[b].push_back({{a,y},i});
        edge[i] = {{y, {a,b}}, i};
    }
    sort(edge.begin(),edge.end());

    flag.assign(m, false);
    UnionFind uf(n);
    for(int i=0; i<m; i++){
        long long int y = edge[i].first.first;
        int a = edge[i].first.second.first;
        int b = edge[i].first.second.second;
        int id = edge[i].second;

        if(uf.same(a,b) == true){
            //cout << uf.total(a) << " + " << 0 << " = " << uf.total(a) << endl;
            if(uf.total(a) >= y) flag[id] = true;
        }
        if(uf.same(a,b) == false){
            //cout << uf.total(a) << " + " << uf.total(b) << " = " << uf.total(a) + uf.total(b) << endl;
            if(uf.total(a) + uf.total(b) >= y) flag[id] = true; 
            uf.merge(a,b);
        }
    }
    reverse(edge.begin(),edge.end());

    int ans = 0;
    visited.assign(n, false);
    for(int i=0; i<m; i++){
        //cout << "ans = " << ans << ", " << edge[i].first.second.first+1 << " " << edge[i].first.second.second+1 << endl;
        int id = edge[i].second;
        if(flag[id] == false) ans += 1;
        if(flag[id] == true){
            int a = edge[i].first.second.first;
            long long int y = edge[i].first.first;
            if(visited[a] == false){
                visited[a] = true;
                DFS(a,y);
            }
            visited[a] = true;
        }
    }
    cout << ans << endl;
    return 0;
}

#include <cstdio>
