using namespace std;

struct Edge
{
    long a, b, y;
};

struct Merge
{
    Edge e;
    long za, zb, l;
};

bool operator<(const Edge& e1, const Edge& e2)
{
    if (e1.y != e2.y) return e1.y < e2.y;
    if (e1.a != e2.a) return e1.a < e2.a;
    if (e1.b != e2.b) return e1.b < e2.b;
    return false;
}

class UnionFind
{
public:
    explicit UnionFind(long n) : data_(n, -1) {}

    long root(long i) {
        return (data_[i] >= 0) ? (data_[i] = root(data_[i])) : i;
    }

    bool unify(long i, long j) {
        i = root(i);
        j = root(j);
        if (i == j)
            return false;
        if (-data_[i] >= -data_[j]) {
            data_[i] += data_[j];
            data_[j] = i;
        } else {
            data_[j] += data_[i];
            data_[i] = j;
        }
        return true;
    }

private:
    vector<long> data_;
};

int main()
{
    long n, m;
    scanf("%ld%ld", &n, &m);
    vector<long> x(n);
    for (long i = 0; i < n; i++)
        scanf("%ld", &x[i]);
    vector<Edge> e(m);
    for (long i = 0; i < m; i++) {
        scanf("%ld%ld%ld", &e[i].a, &e[i].b, &e[i].y);
        --e[i].a;
        --e[i].b;
    }

    sort(e.begin(), e.end());

    vector<long> z = x;

    UnionFind uf(n);
    vector<Merge> merges;
    vector<long> last(n, -1);

    for (long i = 0; i < m; i++) {
        long a = uf.root(e[i].a);
        long b = uf.root(e[i].b);
        if (uf.unify(a, b)) {
            if (last[a] >= 0)
                merges[last[a]].l = merges.size();
            if (last[b] >= 0)
                merges[last[b]].l = merges.size();
            last[uf.root(a)] = merges.size();
            merges.push_back({e[i], z[a], z[b], -1});
            z[uf.root(a)] = z[a] + z[b];
        }
    }

    for (long i = merges.size() - 1; i >= 0; i--) {
        auto& mg = merges[i];
        if (mg.l >= 0 && merges[mg.l].za > 0)
            continue;
        if (mg.e.y <= mg.za + mg.zb)
            continue;
        mg.za = mg.zb = 0;
    }

    UnionFind uf2(n);
    for (auto& mg : merges) {
        if (mg.za > 0) {
            uf2.unify(mg.e.a, mg.e.b);
        }
    }
    vector<long> w(n, 0);
    for (long i = 0; i < n; i++)
        w[uf2.root(i)] += x[i];
    long ans = 0;
    for (long i = 0; i < m; i++)
        if (e[i].y > w[uf2.root(e[i].a)]) ++ans;
    printf("%ld\n", ans);
    return 0;
}

