//---------------------------------------------------------------------------------------------------
int ok[101010];
void dfs(int cu, int lim, int bat) {
    ok[cu] = 1;
    fore(p, E[cu]) if (p.second < lim) {
        int to = p.first;
        if (to == bat) continue;
        if (!ok[to]) dfs(to, lim, bat);
    }
}
