void _main() {
    cin >> N >> M;
    rep(i, 0, N) cin >> X[i];
    rep(i, 0, M) {
        cin >> A[i] >> B[i] >> Y[i];
        A[i]--; B[i]--;
        E[A[i]].push_back({ B[i], Y[i] });
        E[B[i]].push_back({ A[i], Y[i] });
    }

    vector<pair<int, int>> edges;
    rep(i, 0, M) edges.push_back({ Y[i], -i });
    sort(all(edges));

    UnionFind uf(N);
    rep(i, 0, N) {
        ng[i] = 0;
        sm[i] = X[i];
        ma[i] = -1;
    }

    int cnt = 0;
    fore(p, edges) {
        int id = -p.second;
        int a = A[id];
        int b = B[id];
        int c = p.first;
        cnt++;

        memo_ng_a[id] = ng[uf[a]];
        memo_ng_b[id] = ng[uf[b]];

        if (uf[a] == uf[b]) {
            int u = uf[a];

            chmax(ma[u], p.first);
            if (sm[u] < ma[u]) ng[u] = 1;

            memo_ng[id] = ng[u];
        } else {
            int ua = uf[a];
            int ub = uf[b];

            ll sm2 = sm[ua] + sm[ub];
            int ma2 = c;
            chmax(ma2, ma[ua]);
            chmax(ma2, ma[ub]);

            int ng2 = 0;
            if (sm2 < ma2) ng2 = 1;

            uf(a, b);
            int u = uf[a];
            int u2 = ua + ub - u;

            sm[u] = sm2;
            ma[u] = ma2;
            ng[u] = ng2;

            memo_ng[id] = ng[u];
        }
    }

    int ans = 0;
    rrep(j, edges.size() - 1, 0) {
        int i = -edges[j].second;

        int a = A[i];
        int b = B[i];

        //assert((ok[a] ^ ok[b]) == 0);

        if (ok[a]) continue;

        if (memo_ng[i] == 1) {
            ans++;
            if (memo_ng_a[i] == 0) dfs(a, edges[j].first, b);
            if (memo_ng_b[i] == 0) dfs(b, edges[j].first, a);
        }
    }
    cout << ans << endl;
}

