class UnionFind {
    vi par;
    vi rank;
public:
    vll sum;

    UnionFind(int n, vi w) {
        par.resize(n);
        rank.resize(n);
        sum.resize(n);
        REP(i, n) {
            par[i] = i;
            rank[i] = 0;
            sum[i] = w[i];
        }
    }

    int find(int x) {
        if (par[x] == x)
            return x;
        else
            return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;

        ll tx = sum[par[x]];
        ll ty = sum[par[y]];

        if (rank[x] < rank[y])
            par[x] = y;
        else {
            par[y] = x;
            if (rank[x] == rank[y])
                rank[x]++;
        }

        sum[find(par[x])] = tx + ty;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};


