        cin >> a >> b >> y;
        --a, --b;
        edges[i] = make_pair(y, make_pair(a, b));
    }
    sort(all(edges));

    UnionFind uf = UnionFind(N, X);
    int c = 0;
    int mc = 0;
    for (auto &&e:edges) {
        c++;

        int v = e.first;
        int p1 = e.second.first;
        int p2 = e.second.second;

        uf.unite(p1, p2);
        if (uf.sum[uf.find(p1)] >= v)
            mc = c;
    }

    return M - mc;
}


