    }
};

Graph g(0);

template <typename G>   //Abel group
struct UnionFind
{
    using F2 = function<G(G, G)>;
    using F1 = function<G(G)>;

    const F2 f;
    const F1 inverse;

    vector<int> par, rank;
    vector<G> dat;
    vector<int> last;

    UnionFind(int n, const F2 f = [](G a, G b){return a + b;}, F1 inv = [](G a){return -a;}) : f(f), inverse(inv){
        par.resize(n);
        rank.resize(n);
        dat.assign(n, 1);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        i = find(i), j = find(j);
        if(i == j) return;
        if(rank[i] < rank[j]){
            par[i] = j;
            dat[j] = f(dat[i], dat[j]);
            last.push_back(i);
            g.add_edge(j, i);
        }
        else{
            par[j] = i;
            dat[i] = f(dat[i], dat[j]);
            if(rank[i] == rank[j]) rank[i]++;
            last.push_back(j);
            g.add_edge(i, j);
        }
    }

    G query(int i){
        return dat[find(i)];
    }

    void undo(){
        if((int)last.size() == 0) return;
        int i = *(--last.end());
        int j = find(i);
        par[i] = i;
        dat[j] = f(dat[j], inverse(dat[i]));
        last.pop_back();
    }
};

