        cin >> a >> b >> y;
        a--; b--;
        p[i] = PP(y, P(a, b));
    }
    sort(p, p + m);
    vector<int> v;
    for(int i = 0; i < m; i++){
        int a = p[i].second.first, b = p[i].second.second;
        if(uf.find(a) != uf.find(b)){
            uf.unite(a, b);
            v.push_back(i);
        }
    }
    bool used[100002]{0};
    bool del[100002]{0};
    int ans = 0;
    for(int i = m - 1; i >= 0; i--){
        int a = p[i].second.first;
        if(!used[a]){
            if(uf.query(a) < p[i].first) ans++;
            else{
                queue<int> que;
                que.push(uf.find(a));
                while(que.size()){
                    int u = que.front();
                    que.pop();
                    used[u] = true;
                    for(int v : g.g[u]){
                        if(del[v]) continue;
                        que.push(v);
                    }
                }
            }
        }
        if(*(--v.end()) == i){
            del[*(--uf.last.end())] = true;
            uf.undo();
            v.pop_back();
        }
    }
    cout << ans << endl;
}

