    return w < rhs.w;
  }

  bool operator>(const Ed &rhs) const {
    return rhs < *this;
  }

  bool operator<=(const Ed &rhs) const {
    return !(rhs < *this);
  }

  bool operator>=(const Ed &rhs) const {
    return !(*this < rhs);
  }
};

