bool used[100010];

void dfs(int now,ll lim){
  for(int i=0;i<g[now].size();i++){
    int u=g[now][i].first;
    if(used[u]) continue;
    if(now<u){
      if(mp[make_pair(now,u)]==2) continue;
      else if(g[now][i].second<=lim){
        mp[make_pair(now,u)]=2;
        used[u]=true;
        dfs(u,lim);
      }
    }else{
      if(mp[make_pair(u,now)]==2) continue;
      else if(g[now][i].second<=lim){
        mp[make_pair(u,now)]=2;
        used[u]=true;
        dfs(u,lim);
      }
    }
  }
  return;
}

