int cnt;

struct edge {
	int from, to, id;
	edge(int from = 0, int to = 0,int id = 0) : from(from), to(to), id(id) {}
	bool operator < (const edge &e) const {
		return w[id] < w[e.id];
	}
};

vector<edge> eds;

int anc(int u) {
	if (par[u] == u) {
		return u;
	} else {
		return par[u] = anc(par[u]);
	}
}

void join(int u,int v) {
	u = anc(u), v = anc(v);
	if (u ^ v) {
		par[v] = u;
		a[u] += a[v];
	}
}

void dfs(int u,long long lim) {
	for (auto e : g[u]) {
		int v = e.first;
		int id = e.second;
		if (visit[id]) {
			continue;
		} else if (w[id] <= lim) {
			++cnt;
			visit[id] = true;
			dfs(v, lim);
		}
	}
}

