	while (l < m) {
		int r = l;
		while (r + 1 < m && w[eds[r + 1].id] == w[eds[r].id]) {
			++r;
		}
		for (int i = l; i <= r; ++i) {
			join(eds[i].from, eds[i].to);
		}
		for (int i = l; i <= r; ++i) {
			good[i] = w[eds[i].id] <= a[anc(eds[i].from)];
		}
		l = r + 1;
	}
	for (int i = eds.size() - 1; ~i; --i) {
		if (visit[eds[i].id]) {
			continue;
		} else if (good[i]) {
			dfs(eds[i].from, w[eds[i].id]);
		}
	}
	printf("%d\n", m - cnt);
}

