struct SizeAwareUnionFind
{
    vector<lint> par;
    vector<plint> cou;
    SizeAwareUnionFind(int N) : par(N), cou(N) { REP(i, N) par[i] = i, cou[i] = plint(1, 0); }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        par[y] = x, cou[x].first += cou[y].first;
    }
    lint weight(int x) { return cou[find(x)].first; }
    bool same(int x, int y) { return find(x) == find(y); }
};

