UnionFind* newUnionFind(int n,int *x){
  UnionFind *u=(UnionFind *)calloc(1,sizeof(UnionFind));
  u->parent=(int *)calloc(n,sizeof(int));
  u->weight=(int64 *)calloc(n,sizeof(int64));
  int i;
  for(i=0;i<n;i++){
    u->parent[i]=i;
