void makemkj(rs g[],mkj x[],long long n){
    long long i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

long long bd;

void rep(long long nv,bool fl[],rs g[],mkj x[]){
  long long i;
  for(i=x[nv].st;i<x[nv].st+x[nv].kz;i++){
    if(fl[g[i].id]==1 || g[i].kr>bd){continue;}
    fl[g[i].id]=1;
    rep(g[i].fi,fl,g,x);
  }
}

