import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            long[] x = in.nextLongArray(n);
            WeightUnionFind wuf = new WeightUnionFind(x);

            List<Edge> edges = new ArrayList<>();
            List<Set<Edge>> graph = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                graph.add(new HashSet<>());
            }
            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                long y = in.nextLong();

                edges.add(new Edge(a, b, y, i));
                graph.get(a).add(new Edge(a, b, y, i));
                graph.get(b).add(new Edge(b, a, y, i));
            }

            edges.sort(Comparator.comparingLong(e -> e.weight));
            Set<Integer> candidate = new HashSet<>();
            for (int i = 0; i < m; i++) {
                Edge e = edges.get(i);
                wuf.union(e.from, e.to);
                if (e.weight <= wuf.getWeightSum(e.from)) {
                    candidate.add(e.index);
                }
            }

            int ans = 0;
            boolean[] used = new boolean[m];
            for (int i = 0; i < m; i++) {
                Edge e = edges.get(m - 1 - i);
                if (used[e.index]) continue;
                if (candidate.contains(e.index)) {
                    dfs(e.from, e.weight, graph, used);
                } else {
                    ans++;
                }
            }

            out.println(ans);
        }

        void dfs(int x, long weight, List<Set<Edge>> graph, boolean[] used) {
            for (Edge e : graph.get(x)) {
                if (!used[e.index] && e.weight <= weight) {
                    used[e.index] = true;
                    dfs(e.to, weight, graph, used);
                }
            }
        }

        class Edge {
            int from;
            int to;
            long weight;
            int index;

            public Edge(int from, int to, long weight, int index) {
                this.from = from;
                this.to = to;
                this.weight = weight;
                this.index = index;
            }

            public boolean equals(Object obj) {
                Edge edge = (Edge) obj;
                return this.from == edge.from
                        && this.to == edge.to
                        && this.weight == edge.weight
                        && this.index == edge.index;
            }

            public int hashCode() {
                return this.index;
            }

            public String toString() {
                return from + "," + to + "," + weight + "," + index;
            }

        }

        class WeightUnionFind extends UnionFind {
            long[] weightSum;

            WeightUnionFind(long[] weightSum) {
                super(weightSum.length);
                this.weightSum = weightSum;
            }

            public boolean union(int x, int y) {
                boolean isConnected = super.isConnected(x, y);
                long sum = weightSum[super.root(x)] + weightSum[super.root(y)];
                boolean result = super.union(x, y);
                if (!isConnected) weightSum[super.root(x)] = sum;
                return result;
            }

            long getWeightSum(int x) {
                return weightSum[x];
            }

        }

    }

    static class InputReader {
        private BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
            st = new StringTokenizer("");
        }

        public String nextString() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public long nextLong() {
            return Long.parseLong(nextString());
        }

        public long[] nextLongArray(int n) {
            long[] res = new long[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextLong();
            }
            return res;
        }

    }

    static class UnionFind {
        int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            Arrays.fill(parent, -1);
        }

        public boolean union(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (parent[y] < parent[x]) {
                    int tmp = y;
                    y = x;
                    x = tmp;
                }
                parent[x] += parent[y];
                parent[y] = x;
                return true;
            }
            return false;
        }

        public boolean isConnected(int x, int y) {
            return root(x) == root(y);
        }

        public int root(int x) {
            return parent[x] < 0 ? x : (parent[x] = root(parent[x]));
        }

        public ArrayList<ArrayList<Integer>> getGroups() {
            int n = parent.length;
            ArrayList<ArrayList<Integer>> groups = new ArrayList<>();
            HashMap<Integer, Integer> map = new HashMap<>();
            for (int i = 0; i < n; i++) {
                int r = root(i);
                if (!map.containsKey(r)) {
                    map.put(r, groups.size());
                    groups.add(new ArrayList<>());
                }
                groups.get(map.get(r)).add(i);
            }
            return groups;
        }

        public String toString() {
            return getGroups().toString();
        }

    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

class E {
    static class Edge implements Comparable<Edge> {
        final int A, B;
        final long cost;

        public Edge(int a, int b, long cost) {
            A = a;
            B = b;
            this.cost = cost;
        }

        @Override
        public int compareTo(Edge o) {
            return Long.compare(cost, o.cost);
        }
    }

    private static class UnionFind {
        final int[] tree;

        private UnionFind(int size) {
            this.tree = new int[size];
            Arrays.fill(tree, -1);
        }

        public boolean union(int x, int y) {
            x = root(x);
            y = root(y);
            if (x == y)
                return false;
            if (tree[y] < tree[x]) {
                final int t = y;
                y = x;
                x = t;
            }
            tree[x] += tree[y];
            tree[y] = x;
            return true;
        }

        private int root(final int x) {
            return tree[x] < 0 ? x : (tree[x] = root(tree[x]));
        }
    }

    static class Group {
        final long value;
        final Group[] children;
        final int id;
        final boolean satisfied;

        public Group(long value, Group[] children, int id, boolean satisfied) {
            this.value = value;
            this.children = children;
            this.id = id;
            this.satisfied = satisfied;
        }

        ArrayList<Integer> members() {
            final ArrayList<Integer> ret = new ArrayList<>();
            final ArrayDeque<Group> que = new ArrayDeque<>();
            que.offerLast(this);
            while (!que.isEmpty()) {
                final Group g = que.pollFirst();
                if (g.id >= 0)
                    ret.add(g.id);
                else {
                    for (final Group child : g.children)
                        que.offerLast(child);
                }
            }
            return ret;
        }
    }

    public static void main(String... args) {
        final Scanner sc = new Scanner(System.in);
        final int N = sc.nextInt();
        final int M = sc.nextInt();
        final long[] X = new long[N];
        long sum = 0;
        for (int i = 0; i < N; i++) {
            X[i] = sc.nextLong();
            sum += X[i];
        }
        final Edge[] es = new Edge[M];
        for (int i = 0; i < M; i++)
            es[i] = new Edge(sc.nextInt() - 1, sc.nextInt() - 1, sc.nextLong());
        Arrays.sort(es);
        final UnionFind uf = new UnionFind(N);
        final Group[] gs = new Group[N];
        for (int i = 0; i < N; i++)
            gs[i] = new Group(X[i], null, i, true);
        for (final Edge e : es)
            if (e.cost <= sum) {
                final int a = uf.root(e.A);
                final int b = uf.root(e.B);
                if (uf.union(e.A, e.B)) {
                    final long value = gs[a].value + gs[b].value;
                    gs[uf.root(e.A)] = new Group(value, new Group[]{gs[a], gs[a]}, -1, value >= e.cost);
                }
            }
        final ArrayDeque<Group> que = new ArrayDeque<>();
        for (int i = 0; i < N; i++)
            if (uf.root(i) == i)
                que.offerLast(gs[i]);
        final ArrayList<Group> survivers = new ArrayList<>();
        while (!que.isEmpty()) {
            final Group g = que.pollFirst();
            if (g.satisfied)
                survivers.add(g);
            else {
                for (final Group child : g.children)
                    que.offerLast(child);
            }
        }
        final int[] map = new int[N];
        for (int i = 0; i < survivers.size(); i++)
            for (final int j : survivers.get(i).members())
                map[j] = i;
        long ans = 0;
        for (final Edge e : es) {
            if (map[e.A] != map[e.B] || survivers.get(map[e.A]).value < e.cost)
                ans++;
        }
        System.out.println(ans);
    }
}
public class Main {
    public static void main(String... args) {
        E.main();
    }
}

