		public Node(int id, long pw, long nw)
		{
			this.id = id;
			this.pw = pw;
			this.nw = nw;
			priority = gen.nextLong();
			update(this);
		}

		@Override
		public String toString() {
			StringBuilder builder = new StringBuilder();
			builder.append("Node [v=");
