import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    static long __startTime = System.currentTimeMillis();

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        long[] x = new long[n];
        for (int i = 0; i < n ; i++) {
            x[i] = in.nextLong();
        }
        int[][] edges = new int[m][3];
        for (int i = 0; i < m ; i++) {
            for (int j = 0; j < 2 ; j++) {
                edges[i][j] = in.nextInt()-1;
            }
            edges[i][2] = in.nextInt();
        }

        Arrays.sort(edges, Comparator.comparingInt(u -> u[2]));


        int lastGood = -1;
        {
            UnionFind uf = new UnionFind(n, x);
            Set<Integer> ngidSet = new HashSet<>();
            for (int i = 0; i < m; i++) {
                int u = edges[i][0];
                int v = edges[i][1];

                int id1 = uf.find(u);
                int id2 = uf.find(v);
                uf.unite(u, v);
                int nid = uf.find(u);
                if (ngidSet.contains(id1)) {
                    ngidSet.remove(id1);
                }
                if (ngidSet.contains(id2)) {
                    ngidSet.remove(id2);
                }
                if (uf.groupCount(nid) < edges[i][2]) {
                    ngidSet.add(nid);
                }
                if (ngidSet.size() == 0) {
                    lastGood = i;
                }
            }
        }
        UnionFind uf = new UnionFind(n, x);
        int ecount = 0;
        for (int i = 0; i <= lastGood; i++) {
            uf.unite(edges[i][0], edges[i][1]);
            ecount++;
        }

        boolean[] used = new boolean[m];
        while (true) {
            boolean changed = false;
            for (int i = lastGood + 1; i < m; i++) {
                if (used[i]) {
                    continue;
                }
                int id1 = uf.find(edges[i][0]);
                int id2 = uf.find(edges[i][1]);
                if (uf.issame(id1, id2)) {
                    if (uf.groupCount(id1) >= edges[i][2]) {
                        used[i] = true;
                        changed = true;
                        ecount++;
                    }
                } else {
                    if (uf.groupCount(id1) + uf.groupCount(id2) >= edges[i][2]) {
                        used[i] = true;
                        changed = true;
                        uf.unite(id1, id2);
                        ecount++;
                    }
                }
            }
            if (!changed) {
                break;
            }
        }

        out.println(m-ecount);
        out.flush();
    }


    static class UnionFind {
        int[] rank;
        int[] parent;
        long[] cnt;

        public UnionFind(int n, long[] x) {
            rank = new int[n];
            parent = new int[n];
            cnt = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                cnt[i] = x[i];
            }
        }

        public int find(int a) {
            if (parent[a] == a) {
                return a;
            }
            parent[a] = find(parent[a]);
            return parent[a];
        }

        public void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) {
                return;
            }
            if (rank[a] < rank[b]) {
                parent[a] = b;
                cnt[b] += cnt[a];
                cnt[a] = cnt[b];
            } else {
                parent[b] = a;
                cnt[a] += cnt[b];
                cnt[b] = cnt[a];
                if (rank[a] == rank[b]) {
                    rank[a]++;
                }
            }
        }

        public long groupCount(int a) {
            return cnt[find(a)];
        }

        private boolean issame(int a, int b) {
            return find(a) == find(b);
        }
    }


