        for (int i = 0; i < n ; i++) {
            x[i] = in.nextLong();
        }
        int[][] edges = new int[m][3];
        for (int i = 0; i < m ; i++) {
            for (int j = 0; j < 2 ; j++) {
                edges[i][j] = in.nextInt()-1;
            }
            edges[i][2] = in.nextInt();
        }

        Arrays.sort(edges, Comparator.comparingInt(u -> u[2]));


        UnionFind uf = new UnionFind(n, x);

        int lastGood = -1;
        {
            Set<Integer> ngidSet = new HashSet<>();
            for (int i = 0; i < m; i++) {
                int u = edges[i][0];
                int v = edges[i][1];

                int id1 = uf.find(u);
                int id2 = uf.find(v);
                ngidSet.remove(id1);
                ngidSet.remove(id2);

                uf.unite(u, v);
                int nid = uf.find(u);

                if (uf.groupCount(nid) < edges[i][2]) {
                    ngidSet.add(nid);
                }
                if (ngidSet.size() == 0) {
                    lastGood = i;
                }
            }
        }

        int ecount = 0;
        for (int i = 0; i <= lastGood; i++) {
            ecount++;
        }

        out.println(m-ecount);
        out.flush();
    }


    static class UnionFind {
        int[] rank;
        int[] parent;
        long[] cnt;

        public UnionFind(int n, long[] x) {
            rank = new int[n];
            parent = new int[n];
            cnt = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                cnt[i] = x[i];
            }
        }

        public int find(int a) {
            if (parent[a] == a) {
                return a;
            }
            parent[a] = find(parent[a]);
            return parent[a];
        }

        public void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) {
                return;
            }
            if (rank[a] < rank[b]) {
                parent[a] = b;
                cnt[b] += cnt[a];
                cnt[a] = cnt[b];
            } else {
                parent[b] = a;
                cnt[a] += cnt[b];
                cnt[b] = cnt[a];
                if (rank[a] == rank[b]) {
                    rank[a]++;
                }
            }
        }

        public long groupCount(int a) {
            return cnt[find(a)];
        }

        private boolean issame(int a, int b) {
            return find(a) == find(b);
        }
    }


