                }

                for (int i = 0; i < mid; i++) {
                    edge ce = edges.get(i);
                    dsu.mergeSets(ce.u, ce.v);
                }

                boolean poss = true;
                for (int i = 0; i < mid; i++) {
                    edge ce = edges.get(i);

                    long vw = dsu.size[dsu.findSet(ce.u)];
                    vw = Math.max(vw, dsu.size[dsu.findSet(ce.v)]);

                    if (vw < ce.w) {
                        poss = false;
                        break;
                    }
                }


                if (poss) {
                    int ca = mid;
                    for (int i = mid; i < m; i++) {
                        edge ce = edges.get(i);

                        if (dsu.findSet(ce.u) == dsu.findSet(ce.v)) {
                            long vw = dsu.size[dsu.findSet(ce.u)];
                            vw = Math.max(vw, dsu.size[dsu.findSet(ce.v)]);
                            if (vw >= ce.w) {
                                ca++;
                            }
                        } else {
                            long vw = dsu.size[dsu.findSet(ce.u)];
                            long vw2 = dsu.size[dsu.findSet(ce.v)];
                            if (ce.w <= vw + vw2) {
                                ca++;
                                dsu.mergeSets(ce.u, ce.v);
                            }
                        }


                    }

                    ans = Math.max(ans, ca);
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }

            out.println(m - ans);
        }

        class DsuInteger {
            int[] parent;
            int[] rank;
            long[] size;
            int n;
            long[] w;

            public DsuInteger(int n) {
                this.n = n;
                this.parent = new int[n];
                this.rank = new int[n];
                this.size = new long[n];
            }

            int createSet(int x) {
                parent[x] = x;
                rank[x] = 0;
                size[x] = w[x];
                return x;
            }

            int findSet(int x) {
                int par = parent[x];
                if (x != par) {
                    parent[x] = findSet(par);
                    return parent[x];
                }
                return par;
            }

            int mergeSets(int x, int y) {
                int rx = findSet(x);
                int ry = findSet(y);

                if (rx == ry) {
                    return rx;
                }

                int fp = -1;

                if (rank[rx] > rank[ry]) {
                    parent[ry] = rx;
                    fp = rx;
                } else {
                    parent[rx] = ry;
                    fp = ry;
                }

                size[fp] = size[rx] + size[ry];

                if (rank[rx] == rank[ry]) {
                    rank[ry] = rank[ry] + 1;
                }

                return fp;
            }

        }

        class edge {
            int u;
            int v;
            long w;
            int i;

            public edge(int u, int v, long w, int i) {
                this.u = u;
                this.v = v;
                this.w = w;
                this.i = i;
            }

        }

    }

