                    {
                        if ((nodeFlags[node] & 2) != 0)
                        {
                            Splay(node);
                            if (f(nodeL[node], idx)) return true;
                            break;
                        }
                        if ((nodeFlags[nodeChild[node << 1]] & 1) != 0) node = nodeChild[node << 1];
                        else node = nodeChild[(node << 1) | 1];
                    }
                    Splay(t);
                }
                return false;
            }
