                ptr.Remove((l, r));
                return true;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T Query(int p, int v)
            {
                Cut(p, v);
                var t = startNodeIndex + v;
                Splay(t);
                var res = nodeSum[t];
                Link(p, v);
                return res;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T Query(int s)
            {
                var t = startNodeIndex + s;
                Splay(t);
