            .Select(i => new Edge {
                Id = i,
                A = ni() - 1,
                B = ni() - 1,
                Weight = ni(),
            })
            .ToArray();

        var adj = E.Range(0, n).Select(_ => new List<Edge>()).ToArray();

        foreach (var e in edges) {
            adj[e.A].Add(e);
            adj[e.B].Add(e);
        }

        Array.Sort(edges, (e1, e2) => e1.Weight.CompareTo(e2.Weight));

        var disjointSet = new DisjointSet(n, x);
        var candidates = new List<Edge>();

        foreach (var e in edges) {
            disjointSet.Unite(e.A, e.B);
            if (disjointSet.Size(e.A) >= e.Weight) { // candidate
                candidates.Add(e);
            }
        }

        var isChoose = new bool[m];
        var visited = new BooleanArray(n);

        foreach (var e in candidates.AsEnumerable().Reverse()) {
            if (!isChoose[e.Id]) {
                var queue = new Queue<int>();
                queue.Enqueue(e.A);
                queue.Enqueue(e.B);
                isChoose[e.Id] = true;
                visited.Clear();
                while (queue.Count > 0) {
                    var current = queue.Dequeue();
                    if (visited[current]) continue;
                    visited[current] = true;
                    foreach (var edge in adj[current]) {
                        if (edge.Weight <= e.Weight) {
                            isChoose[edge.Id] = true;
                            var next = edge.A == current ? edge.B : edge.A;
                            queue.Enqueue(next);
                        }
                    }
                }
            }
        }

        var ans = m - isChoose.Count(t => t);
        cout.WriteLine(ans);
    }

