                this.f = f;
                this.ei = ei;
                this.startNodeIndex = nodeCount;
                for (var i = 0; i < n; i++)
                {
                    ptr[i] = new Dictionary<int, int>();
                    var nodePoint = NewNode(i, i);
                    nodeVal[nodePoint] = nodeSum[nodePoint] = ei;
                }
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            int GetNode(int l, int r)
            {
                if (l == r) return startNodeIndex + l;
                if (!ptr[l].ContainsKey(r)) ptr[l][r] = NewNode(l, r);
                return ptr[l][r];
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            int Root(int t)
            {
                while (nodeParent[t] != 0) t = nodeParent[t];
                return t;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            bool IsSameNode(int s, int t)
            {
                Splay(s);
                Splay(t);
                return Root(s) == Root(t);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            int ReRoot(int t)
            {
                if (t == 0) return 0;
                var s = Split(t);
                return Merge(s.Item2, s.Item1);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            (int, int) Split(int s)
            {
                if (s == 0) return (0, 0);
                Splay(s);
                var t = nodeChild[s << 1];
                nodeChild[s << 1] = nodeParent[t] = 0;
                return (t, UpdateNode(s));
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            (int, int) Split2(int s)
            {
                if (s == 0) return (0, 0);
                Splay(s);
                var t = nodeChild[s << 1];
                var u = nodeChild[(s << 1) | 1];
                nodeChild[s << 1] = nodeParent[t] = nodeChild[(s << 1) | 1] = nodeParent[u] = 0;
                return (t, u);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            (int, int, int) Split(int s, int t)
            {
                var u = Split2(s);
                if (IsSameNode(u.Item1, t))
                {
                    var r = Split2(t);
                    return (r.Item1, r.Item2, u.Item2);
                }
                else
                {
                    var r = Split2(t);
                    return (u.Item1, r.Item1, r.Item2);
                }
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            int Merge(int s, int t)
            {
                if (s == 0) return t;
                if (t == 0) return s;
                while (nodeChild[(s << 1) | 1] != 0) s = nodeChild[(s << 1) | 1];
                Splay(s);
                nodeChild[(s << 1) | 1] = t;
                if (t != 0) nodeParent[t] = s;
                return UpdateNode(s);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            int UpdateNode(int t)
            {
                if (t == 0) return 0;
                var sum = ei;
                var leftChild = nodeChild[t << 1];
                var rightChild = nodeChild[(t << 1) | 1];
                if (leftChild != 0) sum = f(sum, nodeSum[leftChild]);
                if (nodeL[t] == nodeR[t]) sum = f(sum, nodeVal[t]);
                if (rightChild != 0) sum = f(sum, nodeSum[rightChild]);
                nodeSum[t] = sum;
                nodeSz[t] = nodeSz[leftChild] + (nodeL[t] == nodeR[t] ? 1 : 0) + nodeSz[rightChild];
                var flag = nodeFlags[leftChild] | (nodeFlags[t] >> 1) | nodeFlags[rightChild];
                if ((flag & 1) != 0) nodeFlags[t] |= 1;
                else nodeFlags[t] &= 14;
                if ((flag & 4) != 0) nodeFlags[t] |= 4;
                else nodeFlags[t] &= 11;
                return t;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            void Push(int t)
            {
                // todo
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            void Rot(int t, int b)
            {
                if (t == 0) return;
                var x = nodeParent[t];
                var y = nodeParent[x];
                if ((nodeChild[(x << 1) | (1 - b)] = nodeChild[(t << 1) | b]) != 0) nodeParent[nodeChild[(t << 1) | b]] = x;
                nodeChild[(t << 1) | b] = x;
                nodeParent[x] = t;
                UpdateNode(x);
                UpdateNode(t);
                if ((nodeParent[t] = y) != 0)
                {
                    if (nodeChild[y << 1] == x) nodeChild[y << 1] = t;
                    if (nodeChild[(y << 1) | 1] == x) nodeChild[(y << 1) | 1] = t;
                    UpdateNode(y);
                }
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            void Splay(int t)
            {
                if (t == 0) return;
                Push(t);
                while (nodeParent[t] != 0)
                {
                    var q = nodeParent[t];
                    if (nodeParent[q] == 0)
                    {
                        Push(q);
                        Push(t);
                        Rot(t, nodeChild[q << 1] == t ? 1 : 0);
                    }
                    else
                    {
                        var r = nodeParent[q];
                        Push(r);
                        Push(q);
                        Push(t);
                        var b = nodeChild[r << 1] == q ? 1 : 0;
                        if (nodeChild[(q << 1) | (1 - b)] == t)
                        {
                            Rot(q, b);
                            Rot(t, b);
                        }
                        else
                        {
                            Rot(t, 1 - b);
                            Rot(t, b);
                        }
                    }
                }
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public int Size(int s)
            {
                var t = GetNode(s, s);
                Splay(t);
                return nodeSz[t];
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool IsSame(int s, int t) => IsSameNode(GetNode(s, s), GetNode(t, t));
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T Get(int s)
            {
                var t = GetNode(s, s);
                Splay(t);
                return nodeVal[t];
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void Update(int s, T x)
            {
                var t = GetNode(s, s);
                Splay(t);
                nodeVal[t] = x;
                UpdateNode(t);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void EdgeUpdate(int s, Action<int, int, int> g, int idx)
            {
                var t = GetNode(s, s);
                Splay(t);
                Action<int> dfs = null;
                dfs = node =>
                {
                    if (nodeL[node] < nodeR[node] && (nodeFlags[node] & 8) != 0)
                    {
                        Splay(node);
                        nodeFlags[node] &= 7;
                        g(nodeL[node], nodeR[node], idx);
                        return;
                    }
                    if ((nodeFlags[nodeChild[node << 1]] & 4) != 0) dfs(nodeChild[node << 1]);
                    else dfs(nodeChild[(node << 1) | 1]);
                };
                while ((nodeFlags[t] & 4) != 0)
                {
                    dfs(t);
                    Splay(t);
                }
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool TryReconnect(int s, Func<int, int, bool> f, int idx)
            {
                var t = GetNode(s, s);
                Splay(t);
                Func<int, bool> dfs = null;
                dfs = node =>
                {
                    if ((nodeFlags[node] & 2) != 0)
                    {
                        Splay(node);
                        return f(nodeL[node], idx);
                    }
                    if ((nodeFlags[nodeChild[node << 1]] & 1) != 0) return dfs(nodeChild[node << 1]);
                    else return dfs(nodeChild[(node << 1) | 1]);
                };
                while ((nodeFlags[t] & 1) != 0)
                {
                    if (dfs(t)) return true;
                    Splay(t);
                }
                return false;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void EdgeConnectedUpdate(int s, bool b)
            {
                var t = GetNode(s, s);
                Splay(t);
                if (b) nodeFlags[t] |= 2;
                else nodeFlags[t] &= 13;
                UpdateNode(t);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool Link(int l, int r)
            {
                if (IsSame(l, r)) return false;
                var lv = ReRoot(GetNode(l, l));
                var rv = ReRoot(GetNode(r, r));
                var lrnode = GetNode(l, r);
                nodeParent[lv] = nodeParent[rv] = lrnode;
                nodeChild[lrnode << 1] = lv;
                nodeChild[(lrnode << 1) | 1] = rv;
                UpdateNode(lrnode);
                Merge(lrnode, GetNode(r, l));
                return true;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool Cut(int l, int r)
            {
                if (!ptr[l].ContainsKey(r)) return false;
                var s = Split(GetNode(l, r), GetNode(r, l));
                Merge(s.Item1, s.Item3);
                var p = ptr[l][r];
                var q = ptr[r][l];
                ptr[l].Remove(r);
                ptr[r].Remove(l);
                return true;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T GetSum(int p, int v)
            {
                Cut(p, v);
                var t = GetNode(v, v);
                Splay(t);
                var res = nodeSum[t];
                Link(p, v);
                return res;
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public T GetSum(int s)
            {
                var t = GetNode(s, s);
                Splay(t);
                return nodeSum[t];
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;

namespace Competitive
{
    internal class Solution
    {
        public int N, M;
        public Graph G;
        public long[] X;

        public void Run()
        {
            // Input
            {
                var line = Input.ReadIntArray();
                N = line[0];
                M = line[1];
            }

            X = Input.ReadLongArray();

            var Edges = new List<Edge>();
            for (int i = 0; i < M; i++)
            {
                var line = Input.ReadIntArray();
                int u = line[0] - 1;
                int v = line[1] - 1;
                long y = line[2];

                var e1 = new Edge(u, v, y);
                Edges.Add(e1);
            }

            // 小さい方からソート
            Edges.Sort((e1, e2) => e1.Cost.CompareTo(e2.Cost));

            // UnionFindを作りながら、情報を整理
            var isNG = new bool[M];
            var prev1 = new int[M];
            var prev2 = new int[M];

            var uf = new UnionFind(N, X);

            for (int i = 0; i < M; i++)
            {
                var e = Edges[i];
                var tpl = uf.Unite(e.From, e.To, i);

                // uniteした重みと、以前Uniteした場所を保持する
                long weight = tpl.Item1;
                if (weight < e.Cost) isNG[i] = true;
                prev1[i] = tpl.Item2;
                prev2[i] = tpl.Item3;
            }

            // 上から順に見ていく
            int ret = 0;
            bool[] flags = new bool[M];

            if(M > 0) flags[M - 1] = true;

            for (int i = M - 1; i >= 0; i--)
            {
                if (flags[i] && isNG[i])
                {
                    ret++;
                    if (prev1[i] != -1) flags[prev1[i]] = true;
                    if (prev2[i] != -1) flags[prev2[i]] = true;
                }
            }

            Console.WriteLine(ret);
        }

    }

    internal class Graph
    {
        public List<Node> Nodes;

        public Node this[int i]
        {
            set { Nodes[i] = value; }
            get { return Nodes[i]; }
        }

        public Graph(int N)
        {
            Nodes = new List<Node>();
            for (int i = 0; i < N; i++)
            {
                Nodes.Add(new Node(i));
            }
        }

    }

