    {
        public List<Edge> Edges;
        public int Dist;
        public int No;

        public Node(int no)
        {
            this.No = no;
            Dist = int.MaxValue;
            Edges = new List<Edge>();
        }
    }

    internal class Edge
    {
        public int From;
        public int To;
        public long Cost;
        public Edge Rev;

        public Edge(int fr, int to, long cost = 0)
        {
            From = fr;
            To = to;
            Cost = cost;
        }

        public bool IsRev(Edge e)
        {
            return Rev != null && (e == Rev);
        }
    }

    // libs ----------
    class UnionFind
    {
        public List<int> Par;
        public List<int> Sizes;
        public List<int> PrevMerged;
        public List<long> Weight;

        public UnionFind(int n, long[] X)
        {
            Par = new List<int>();
            Sizes = new List<int>();
            PrevMerged = new List<int>();
            Weight = new List<long>();

            for (int i = 0; i < n; i++)
            {
                Par.Add(i);
                Sizes.Add(1);
                PrevMerged.Add(-1);
                Weight.Add(X[i]);
            }
        }

        public int Find(int x)
        {
            if (x == Par[x]) return x;
            Par[x] = Find(Par[x]);
            return Par[x];
        }

        public Tuple<long, int, int> Unite(int x, int y, int i)
        {
            x = Find(x);
            y = Find(y);

            if (x == y)
            {
                var tpl0 = Tuple.Create(Weight[x], PrevMerged[x], -1);
                PrevMerged[x] = i;
                return tpl0;
            }

            if (Sizes[x] < Sizes[y])
            {
                // swap
                int temp = x;
                x = y;
                y = temp;
            }

            var tpl = Tuple.Create(Weight[x] + Weight[y], PrevMerged[x], PrevMerged[y]);

            Par[y] = x;
            Sizes[x] += Sizes[y];
            Sizes[y] = 0;

            Weight[x] += Weight[y];
            Weight[y] = 0;
            PrevMerged[x] = i;
            PrevMerged[y] = -1;

            return tpl;
        }

        public bool Same(int x, int y)
        {
            return Find(x) == Find(y);
        }

        public int Size(int x)
        {
            return Sizes[Find(x)];
        }
    }


    // common ----------

    internal static class Input
    {
        public static string ReadString()
        {
            string line = Console.ReadLine();
            return line;
        }

        public static int ReadInt()
        {
            string line = Console.ReadLine();
            return int.Parse(line);
        }

        public static int[] ReadIntArray()
        {
            string line = Console.ReadLine();
            return line.Split(' ').Select(int.Parse).ToArray();            
        }

        public static long ReadLong()
        {
            string line = Console.ReadLine();
            return long.Parse(line);
        }

        public static long[] ReadLongArray()
        {
            string line = Console.ReadLine();
            return line.Split(' ').Select(long.Parse).ToArray();
        }

        public static double[] ReadDoubleArray()
        {
            string line = Console.ReadLine();
            return line.Split(' ').Select(double.Parse).ToArray();
        }
    }

    internal class Program
    {
        public static void Main(string[] args)
        {
            var s = new Solution();
            s.Run();
        }
    }
