using E = System.Linq.Enumerable;

internal partial class Solver {
    struct Edge {
        public int Id, A, B, Weight;
    }

    public void Run() {
        var n = ni();
        var m = ni();
        var x = ni(n);
        var edges = E.Range(0, m)
            .Select(i => new Edge {
                Id = i,
                A = ni() - 1,
                B = ni() - 1,
                Weight = ni(),
            })
            .ToArray();

        var adj = E.Range(0, n).Select(_ => new List<Edge>()).ToArray();

        foreach (var e in edges) {
            adj[e.A].Add(e);
            adj[e.B].Add(e);
        }

        Array.Sort(edges, (e1, e2) => e1.Weight.CompareTo(e2.Weight));

        var disjointSet = new DisjointSet(n, x);
        var candidates = new List<Edge>();

        foreach (var e in edges) {
            disjointSet.Unite(e.A, e.B);
            if (disjointSet.Size(e.A) >= e.Weight) { // candidate
                candidates.Add(e);
            }
        }

        var isChoose = new bool[m];
        var visited = new BooleanArray(n);

        foreach (var e in candidates.AsEnumerable().Reverse()) {
            if (!isChoose[e.Id]) {
                var queue = new Queue<int>();
                queue.Enqueue(e.A);
                queue.Enqueue(e.B);
                isChoose[e.Id] = true;
                visited.Clear();
                while (queue.Count > 0) {
                    var current = queue.Dequeue();
                    if (visited[current]) continue;
                    visited[current] = true;
                    foreach (var edge in adj[current]) {
                        if (edge.Weight <= e.Weight) {
                            isChoose[edge.Id] = true;
                            var next = edge.A == current ? edge.B : edge.A;
                            queue.Enqueue(next);
                        }
                    }
                }
            }
        }

        var ans = m - isChoose.Count(t => t);
        cout.WriteLine(ans);
    }

}

public class BooleanArray {
    private readonly int[] array;
    private int trueValue = 1;

    public BooleanArray(int size) {
        array = new int[size];
    }

    public void Clear() {
        trueValue++;
    }

    public bool this[int index] {
        get {
            return array[index] == trueValue;
        }
        set {
            array[index] = value ? trueValue : trueValue - 1;
        }
    }

    public int Length {
        get {
            return array.Length;
        }
    }
}
public class DisjointSet {
    private readonly int[] group;
    public int GroupCount { get; private set; }
    public DisjointSet(int n, int[] w = null) {
        group = new int[n];
        Clear(w);
        GroupCount = n;
    }
    public bool Unite(int x, int y) {
        x = Root(x); y = Root(y);
        if (x == y) {
            return false;
        }

        if (group[y] < group[x]) {
            return Unite(y, x);
        }

        group[x] += group[y];
        group[y] = x;
        GroupCount--;
        return true;
    }
    public bool IsSameSet(int x, int y) { return Root(x) == Root(y); }
    public int Root(int x) { return group[x] < 0 ? x : group[x] = Root(group[x]); }
    public int Size(int x) { return -group[Root(x)]; }
    public void Clear(int[] w) {
        for (int i = 0; i < group.Length; i++) {
            group[i] = -(w == null ? 1 : w[i]);
        }
    }
};

