        static public void Solve()
        {
            var N = NN;
            var M = NN;
            var XList = NNList(N);
            var ABY = Repeat(0, M).Select(_ => new { A = NN - 1, B = NN - 1, Y = NN }).ToArray();
            var sorted = ABY.OrderByDescending(e => e.Y).ToArray();
            var graph = new LIB_DynamicConnectivity<long>(N, 0, (x, y) => x + y);
            for (var i = 0; i < XList.Length; i++)
            {
                graph[i] = XList[i];
            }
            foreach (var item in ABY)
            {
                graph.Link(item.A, item.B);
            }
            var cnt = 0;
            foreach (var item in sorted)
            {
                var omomi = graph.Query(item.A);
                if (omomi < item.Y)
                {
                    ++cnt;
                    graph.Cut(item.A, item.B);
                }
            }
            Console.WriteLine(cnt);
        }
