            static int[] nodeL = new int[16384];
            static int[] nodeR = new int[16384];
            static int[] nodeSz = new int[16384];
            static T[] nodeVal = new T[16384];
            static T[] nodeSum = new T[16384];
            static byte[] nodeFlags = new byte[16384];
