                    }
                    {
                        var tmp = new int[nodeCount << 1];
                        for (var i = 0; i < nodeCount; i++) tmp[i] = nodeParent[i];
                        nodeParent = tmp;
                    }
                    {
                        var tmp = new int[nodeCount << 1];
                        for (var i = 0; i < nodeCount; i++) tmp[i] = nodeL[i];
                        nodeL = tmp;
                    }
                    {
                        var tmp = new int[nodeCount << 1];
                        for (var i = 0; i < nodeCount; i++) tmp[i] = nodeR[i];
                        nodeR = tmp;
                    }
                    {
                        var tmp = new int[nodeCount << 1];
                        for (var i = 0; i < nodeCount; i++) tmp[i] = nodeSz[i];
                        nodeSz = tmp;
                    }
