                        if (nodeL[t] < nodeR[t] && (nodeFlags[t] & 8) != 0)
                        {
                            g(nodeL[t], nodeR[t], idx);
                            Splay(t);
                            nodeFlags[t] &= 7;
                            UpdateNode(t);
                            break;
                        }
                        if ((nodeFlags[nodeChild[t << 1]] & 4) != 0) t = nodeChild[t << 1];
                        else t = nodeChild[(t << 1) | 1];
                    }
                }
            }
