                var t = startNodeIndex + s;
                Splay(t);
                while ((nodeFlags[t] & 1) != 0)
                {
                    while (true)
                    {
                        if ((nodeFlags[t] & 2) != 0)
                        {
                            if (f(nodeL[t], idx)) return true;
                            Splay(t);
                            break;
                        }
                        if ((nodeFlags[nodeChild[t << 1]] & 1) != 0) t = nodeChild[t << 1];
                        else t = nodeChild[(t << 1) | 1];
                    }
                }
