                if (l > r) { var t = l; l = r; r = t; }
                if (!ptr[l].ContainsKey(r)) return;
                var p = ptr[l][r];
                var q = p + 1;
                var s = Split(p, q);
                Merge(s.Item1, s.Item3);
                ptr[l].Remove(r);
            }
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
