#region DisjointSet
public class DisjointSet {
    long[] par;
    byte[] rank;
    Stack<KeyValuePair<int, long>> his = new Stack<KeyValuePair<int, long>>();
    public DisjointSet(int n, long[] a) {
        par = new long[n];
        for (int i = 0; i < n; i++)
            par[i] = -a[i];
        rank = new byte[n];
    }
    public int this[int id] {
        get {
            if ((par[id] < 0)) return id;
            return (int)this[(int)par[id]];
        }
    }
    public bool Unite(int x, int y) {
        x = this[x]; y = this[y];
        if (x == y) return false;
        if (rank[x] < rank[y]) { var z = x; x = y; y = z; }
        his.Push(new KeyValuePair<int, long>(x, par[x]));
        his.Push(new KeyValuePair<int, long>(y, par[y]));
        par[x] += par[y];
        par[y] = x;

        if (rank[x] == rank[y])
            rank[x]++;
        return true;
    }
    public void back() {
        var kv = his.Pop();
        par[kv.Key] = kv.Value;
        kv = his.Pop();
        par[kv.Key] = kv.Value;
    }
    public int Size(int x) { return (int)-par[(int)this[x]]; }
    public bool IsUnited(int x, int y) { return this[x] == this[y]; }

}
