using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;

namespace Competitive
{
    internal class Solution
    {
        public int N, M;
        public Graph G;
        public long[] X;

        public void Run()
        {
            // Input
            {
                var line = Input.ReadIntArray();
                N = line[0];
                M = line[1];
            }

            X = Input.ReadLongArray();

            var Edges = new List<Edge>();

            // Graph
            G = new Graph(N);
            for (int i = 0; i < M; i++)
            {
                var line = Input.ReadIntArray();
                int u = line[0] - 1;
                int v = line[1] - 1;
                long y = line[2];
                // 無向グラフ
                var e1 = new Edge(u, v, y);
                var e2 = new Edge(v, u, y);
                e1.Rev = e2;
                e2.Rev = e1;
                G[u].Edges.Add(e1);
                G[v].Edges.Add(e2);

                Edges.Add(e1);
            }

            // 小さい方からソート
            Edges.Sort((e1, e2) => e1.Cost.CompareTo(e2.Cost));

            // UnionFindを作りながら、情報を整理
            var isNG = new bool[M];
            var prev1 = new int[M];
            var prev2 = new int[M];

            var uf = new UnionFind(N, X);

            for (int i = 0; i < M; i++)
            {
                var e = Edges[i];
                var tpl = uf.Unite(e.From, e.To, i);

                // uniteした重みと、以前Uniteした場所
                long weight = tpl.Item1;
                if (weight < e.Cost) isNG[i] = true;
                prev1[i] = tpl.Item2;
                prev2[i] = tpl.Item3;
            }

            // 上から順に見ていく
            int ret = 0;
            bool[] flags = new bool[M];
            flags[M - 1] = true;

            for (int i = M - 1; i >= 0; i--)
            {
                if (flags[i] && isNG[i])
                {
                    ret++;
                    if (prev1[i] != -1) flags[prev1[i]] = true;
                    if (prev2[i] != -1) flags[prev2[i]] = true;
                }
            }

            Console.WriteLine(ret);
        }

    }

    internal class Graph
    {
        public List<Node> Nodes;

        public Node this[int i]
        {
            set { Nodes[i] = value; }
