using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;

using E = System.Linq.Enumerable;

internal partial class Solver {
    struct Edge {
        public int Id, A, B, Weight;
    }

    public void Run() {
        var n = ni();
        var m = ni();
        var x = ni(n);
        var edges = E.Range(0, m)
            .Select(i => new Edge {
                Id = i,
                A = ni() - 1,
                B = ni() - 1,
                Weight = ni(),
            })
            .ToArray();

        var adj = E.Range(0, n).Select(_ => new List<Edge>()).ToArray();

        foreach (var e in edges) {
            adj[e.A].Add(e);
            adj[e.B].Add(e);
        }

        Array.Sort(edges, (e1, e2) => e1.Weight.CompareTo(e2.Weight));

        var sumWeight = new long[n];
        for (int i = 0; i < n; i++) {
            sumWeight[i] = x[i];
        }

        var disjointSet = new DisjointSet(n);
        var candidates = new List<Edge>();

        foreach (var es in edges
            .GroupBy(ed => ed.Weight)
            .OrderBy(g => g.Key)) {
            foreach (var e in es) {
                var g1 = disjointSet.Root(e.A);
                var g2 = disjointSet.Root(e.B);
                if (disjointSet.Unite(e.A, e.B)) {
                    sumWeight[g1] = sumWeight[g2] = sumWeight[g1] + sumWeight[g2];
                }
            }
            foreach (var e in es) {
                var g = disjointSet.Root(e.A);
                var sumW = sumWeight[g];
                if (sumW >= e.Weight) { // candidate
                    candidates.Add(e);
                }
            }
        }

        var isChoose = new bool[m];
        var visited = new BooleanArray(n);

        foreach (var e in candidates.AsEnumerable().Reverse()) {
            if (!isChoose[e.Id]) {
                var queue = new Queue<int>();
                queue.Enqueue(e.A);
                queue.Enqueue(e.B);
                isChoose[e.Id] = true;
                visited.Clear();
                while (queue.Count > 0) {
                    var current = queue.Dequeue();
                    if (visited[current]) continue;
                    visited[current] = true;
                    foreach (var edge in adj[current]) {
                        if (edge.Weight <= e.Weight) {
                            isChoose[edge.Id] = true;
                            var next = edge.A == current ? edge.B : edge.A;
                            queue.Enqueue(next);
                        }
                    }
                }
            }
        }

        var ans = m - isChoose.Count(t => t);
        cout.WriteLine(ans);
    }

}

public class BooleanArray {
    private readonly int[] array;
    private int trueValue = 1;

    public BooleanArray(int size) {
        array = new int[size];
    }

    public void Clear() {
        trueValue++;
    }

    public bool this[int index] {
        get {
            return array[index] == trueValue;
        }
        set {
            array[index] = value ? trueValue : trueValue - 1;
        }
    }

    public int Length {
        get {
            return array.Length;
        }
    }
}
public class DisjointSet {
    private readonly int[] group;
    public int GroupCount { get; private set; }
    public DisjointSet(int n) {
        group = new int[n];
        Clear();
        GroupCount = n;
    }
    public bool Unite(int x, int y) {
        x = Root(x); y = Root(y);
        if (x == y) {
