/*

軽い橋から潤に採用していき、Union-findしていく

各連結成分についてこれらをおぼえておく
・島のコストの和
・保留中の橋の個数

つなぐ時、今つないだ橋のコストが島のコストの和以下だったら
その連携成分は生きになる
その連結成分で保留中の橋は一気に確定になる

*/

class Edge{
	Node node1;
	Node node2;
	long value;
	this(Node node1, Node node2, long value){
		this.node1 = node1, this.node2 = node2;
		this.value = value;
	}
}

class Node{
	long id;
	long value;
	Group group;
	this(long id, long value){
		this.id = id;
		this.value = value;
	}
}

class Group{
	long value;
	long pendingEdgeCount;
	long id;
	Node[] nodes;
	this(Node node){
		this.id = node.id;
		this.nodes = [node];
		this.value = node.value;
	}
	void eat(Group gp){
		if(gp.nodes.length > this.nodes.length) gp.eat(this);
		else{
			foreach(nd; gp.nodes){
				this.nodes ~= nd;
				nd.group = this;
				this.value += nd.value;
			}
			this.pendingEdgeCount += gp.pendingEdgeCount;
		}
	}
}

void main(){
	long n = read.to!long;
	long m = read.to!long;

	Node[] nodes;
	foreach(i; 0 .. n){
		long x = read.to!long;
		nodes ~= new Node(i, x);
	}

	foreach(nd; nodes){
		nd.group = new Group(nd);
	}

	Edge[] edges;
	foreach(i; 0 .. m){
		long a = read.to!long - 1;
		long b = read.to!long - 1;
		long y = read.to!long;

		edges ~= new Edge(nodes[a], nodes[b], y);
	}

	edges.sort!"a.value<b.value"();

	long edgecount;
	foreach(ed; edges){
		if(ed.node1.group.id != ed.node2.group.id){
			ed.node1.group.eat(ed.node2.group);
		}
		ed.node1.group.pendingEdgeCount += 1;
		if(ed.value <= ed.node1.group.value){
			edgecount += ed.node1.group.pendingEdgeCount;
			ed.node1.group.pendingEdgeCount = 0;
		}
	}

	(m - edgecount).writeln;

}

