    scan(n, m);
    auto x = readln.split.to!(long[]);
    auto e = new Edge[](m);
    foreach (i ; 0 .. m) {
        int u, v, w;
        scan(u, v, w);
        u--, v--;
        e[i] = Edge(u, v, w);
    }
    e.sort!"a.w < b.w"();

    auto uf = UnionFind(n, x);

    int ans;

    foreach (i ; 0 .. m) {
        int u, v; long w;
        u = e[i].u;
        v = e[i].v;
        w = e[i].w;

        if (uf.same(u, v)) {
            auto r = uf.findRoot(u);
            if (w > uf.wa[r] && !uf.bad[r]) {
                uf.bad[r] = true;
                uf.bcnt++;
            }
        }
        else {
            auto ru = uf.findRoot(u);
            auto rv = uf.findRoot(v);

            uf.merge(u, v);
            auto r = uf.findRoot(u);

            if (w > uf.wa[r]) {
                if (!uf.bad[ru] && !uf.bad[rv]) {
                    uf.bcnt++;
                }
                uf.bad[r] = true;
            }
            else {
                if (uf.bad[ru] || uf.bad[rv]) {
                    uf.bcnt--;
                }
                uf.bad[r] = false;
            }
        }

        debug {
            writeln(uf.wa);
            writeln(uf.bad);
