        }
    }

    ans = m - ans;

    writeln(ans);
}


struct UnionFind {
    private {
        int _size;
        int[] _parent;
        long[] wa;
        int bcnt;
        bool[] bad;
    }

    this(int N, long[] x) 
    in {
        assert(N > 0);
    }
    body {
        _size = N;
        _parent = new int[](_size);
        foreach (i ; 0 .. _size) {
            _parent[i] = i;
        }
        wa = new long[](N);
        wa[] = x.dup;
        bad = new bool[](N);
    }

    int findRoot(int x)
    in {
        assert(0 <= x && x < _size);
    }
    body {
        if (_parent[x] != x) {
            _parent[x] = findRoot(_parent[x]);
        }

        return _parent[x];
    }

    bool same(int x, int y)
    in {
        assert(0 <= x && x < _size);
        assert(0 <= y && y < _size);
    }
    body {
        return findRoot(x) == findRoot(y);
    }

    void merge(int x, int y)
    in {
        assert(0 <= x && x < _size);
        assert(0 <= y && y < _size);
    }
    body {
        int u = findRoot(x);
        int v = findRoot(y);

        if (u == v) return;

        _parent[v] = u;
        wa[u] += wa[v];
        wa[v] = 0;
    }
}






