    if e.y > k:
      continue
    if used[e.a] or used[e.b]:
      continue

    let v = e.a
    let r = rootTab[uft.find(v)]
    maxY[r] = max(maxY[r], e.y)

  var id = -1
  for i in 0..<rootCount:
    if sumX[i] >= maxY[i]:
      id = i
      break

