    return id

  var ans = 0
  for e in es:
    if e.y > k:
      continue
    if used[e.a] or used[e.b]:
      continue
    if rootTab[uft.find(e.a)] == id:
      ans += 1

  for v in 0..<n:
    if used[v]:
      continue
    if rootTab[uft.find(v)] == id:
      used[v] = true

  return ans

