    while ub - lb > 1:
      let mid = (ub + lb) div 2
      if eval(n, es, x, mid, used, false) >= 0:
        lb = mid
      else:
        ub = mid
    if lb <= 0:
      break
    ans += eval(n, es, x, lb, used, true)
  echo m - ans

main()

