        if p[x]!=x:
            p[x]=find(p[x])
        return p[x]

    def union(x,y,w):
        x,y=find(x),find(y)
        if r[x]<r[y]:x,y = y,x
        p[y]=x
        r[x] += r[x] == r[y]

        wt[x]+=wt[y]

        ba[x]+=ba[y]

        if wt[x]<w:
            ba[x]+=1
        else:
            ba[x]=0

    def add(x,w):
        x = find(x)
        if wt[x]<w:
            ba[x]+=1


