struct UnionFind {
      n: usize,
      parent: Vec<usize>,
      count: Vec<usize>,
      weight: Vec<i64>
}

impl UnionFind {
     fn new(n: usize) -> Self {
           let mut p = vec![0; n];
           for i in 0..n {
                 p[i] = i;
           }
           UnionFind { n: n, parent: p, count: vec![1; n], weight: vec![0; n] }
     }

     fn find(&mut self, a: usize) -> usize {
           if self.parent[a] == a {
                 return a;
           }
           let par = self.parent[a];
           self.parent[a] = self.find(par);
           self.parent[a]
     }

     fn unite(&mut self, a: usize, b: usize) {
           let a = self.find(a);
           let b = self.find(b);
           if a == b {
                 return;
           }
           let ca = self.count[a];
           let cb = self.count[b];
           let total = ca + cb;
           let total_weight = self.weight[a] + self.weight[b];
           self.count[b] = total;
           self.count[a] = total;
           self.weight[b] = total_weight;
           self.weight[a] = total_weight;
           if ca < cb {
                 self.parent[a] = b;
           } else {
                 self.parent[b] = a;
           }
     }

     fn same(&mut self, a: usize, b: usize) -> bool {
           self.find(a) == self.find(b)
     }

     fn count(&mut self, a: usize) -> usize {
           let a = self.find(a);
           self.count[a]
     }
}

type Edge = (usize, usize, i64);

fn merge(u: usize, v: usize, uf: &mut UnionFind, pointer: &mut Vec<usize>, pending_edges: &mut Vec<Vec<Edge>>) {
    if uf.same(u, v) {
        return;
    }

    let gid0 = pointer[uf.find(u)];
    let gid1 = pointer[uf.find(v)];
    let newgid = ifv!(pending_edges[gid0].len() < pending_edges[gid1].len(), gid1, gid0);
    let oldgid = gid0+gid1-newgid;
    uf.unite(u, v);
    let idx = uf.find(u);
    pointer[idx] = newgid;

    let mut a = vec![];
    for &e in &pending_edges[oldgid] {
        a.push(e);
    }
    pending_edges[newgid].append(&mut a);
    pending_edges[oldgid].clear();
}

fn main() {
    input! {
        n: usize, m: usize,
        x: [i64; n],
        edges: [(usize1, usize1, i64); m]
    };
    let mut edges = edges;
    edges.sort_by_key(|&(u, v, y)| y);


    let mut pending_edges = vec![vec![]; n];
    let mut pointer = vec![0; n];
    let mut uf = UnionFind::new(n);
    for i in 0..n {
        pointer[i] = i;
        uf.weight[i] = x[i];
    }

    for (u, v, y) in edges {
        if uf.same(u, v) {
            let rid = uf.find(u);
            if uf.weight[rid] < y {
                let gid = pointer[uf.find(u)];
                pending_edges[gid].push((u, v, y));
            }
        } else {
            let idx0 = uf.find(u);
            let idx1 = uf.find(v);
            if uf.weight[idx0] + uf.weight[idx1] < y {
                if !uf.same(u, v) {
                    merge(u, v, &mut uf, &mut pointer, &mut pending_edges);
                }
                let newgid = pointer[uf.find(u)];
                pending_edges[newgid].push((u, v, y));
            } else {
                merge(u, v, &mut uf, &mut pointer, &mut pending_edges);
                let gid = pointer[uf.find(u)];
                pending_edges[gid].clear();
            }
        }
    }

    let idx = uf.find(0);
    let gid = pointer[idx];

    println!("{}", pending_edges[gid].len());
}

