use std::cell::Cell;

#[derive(Clone, Debug)]
pub struct UnionFind {
	/// size / parent
	ps: Vec<Cell<usize>>,
	pub is_root: Vec<bool>
}

impl UnionFind {
	pub fn new(n: usize) -> UnionFind {
		UnionFind { ps: vec![Cell::new(1); n], is_root: vec![true; n] }
	}
	pub fn find(&self, x: usize) -> usize {
		if self.is_root[x] { x }
		else {
			let p = self.find(self.ps[x].get());
			self.ps[x].set(p);
			p
		}
	}
	pub fn unite(&mut self, x: usize, y: usize) {
		let mut x = self.find(x);
		let mut y = self.find(y);
		if x == y { return }
		if self.ps[x].get() < self.ps[y].get() {
			::std::mem::swap(&mut x, &mut y);
		}
		*self.ps[x].get_mut() += self.ps[y].get();
		self.ps[y].set(x);
		self.is_root[y] = false;
	}
	pub fn same(&self, x: usize, y: usize) -> bool {
		self.find(x) == self.find(y)
	}
	pub fn size(&self, x: usize) -> usize {
		self.ps[self.find(x)].get()
	}
}

fn run() {
	let (N, M) = read!(usize, usize);
	let mut X = read!([i64]);
	let X0 = X.clone();
	let mut es = vec![];
	for (a, b, y) in read!(usize, usize, i64; M) {
		es.push((y, a - 1, b - 1));
	}
	es.sort();
	let mut uf = UnionFind::new(N);
	let mut ok = vec![false; M];
	let mut hold = vec![vec![]; N];
	for i in 0..M {
		let (y, a, b) = es[i];
		if uf.find(a) != uf.find(b) {
			let A = uf.find(a);
			let B = uf.find(b);
			let tmp = X[uf.find(a)] + X[uf.find(b)];
			uf.unite(a, b);
			if uf.find(a) == A {
				let c = hold[B].clone();
				hold[A].extend(c);
			} else {
				let c = hold[A].clone();
				hold[B].extend(c);
			}
			X[uf.find(a)] = tmp;
			if tmp >= y {
				ok[i] = true;
				for &j in &hold[uf.find(a)] {
					ok[j] = true;
				}
				hold[uf.find(a)].clear();
			} else {
				hold[uf.find(a)].push(i);
			}
		}
	}
	uf = UnionFind::new(N);
	X = X0.clone();
	for i in 0..M {
		if ok[i] {
			let (_, a, b) = es[i];
			let tmp = X[uf.find(a)] + X[uf.find(b)];
			uf.unite(a, b);
			X[uf.find(a)] = tmp;
		}
	}
	let mut ans = 0;
	for i in 0..M {
		let (y, a, b) = es[i];
		if uf.find(a) != uf.find(b) || X[uf.find(a)] < y {
			ans += 1;
		}
	}
	println!("{}", ans);
}

