fn dfs(cur: usize, max_cost: i64, edges: &Vec<Vec<(usize, i64, usize)>>, checked: &mut Vec<bool>) {
    for &(to, cost, i) in edges[cur].iter() {
        if checked[i] || cost > max_cost {
            continue;
        }
        checked[i] = true;
        dfs(to, max_cost, edges, checked);
    }
}

fn main() {
    let v = read_vec::<usize>();
    let (n, m) = (v[0], v[1]);
    let x = read_vec::<i64>();
    let mut edges = vec![];
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let v = read_vec::<i64>();
        let (a, b, c) = (v[0] as usize - 1, v[1] as usize - 1, v[2]);
        edges.push((c, a, b, i));
        graph[a].push((b, c, i));
        graph[b].push((a, c, i));
    }
    edges.sort();
    let mut sum = x.clone();

    let mut ok = vec![false; m];

    let mut uft = UnionFindTree::new(n);
    for &(y, a, b, i) in edges.iter() {
        let mut a = uft.find(a);
        let mut b = uft.find(b);
        if uft.same(a, b) {
            continue;
        }
        uft.unite(a, b);
        if a != uft.find(a) {
            std::mem::swap(&mut a, &mut b);
        }
        sum[a] += sum[b];
        if y <= sum[a] {
            ok[i] = true;
        }
    }

    edges.reverse();
    let mut checked = vec![false; m];
    for &(y, a, b, i) in edges.iter() {
        if ok[i] {
            dfs(a, y, &graph, &mut checked);
        }
    }
    debug!(checked);

    let ans = m - checked.iter().filter(|&&x| x).count();

    println!("{}", ans);
}

