#[derive(Eq, PartialEq, Clone, Debug)]
enum Tree {
    Leaf(i64, usize),
    Node(i64, i64, Box<Tree>, Box<Tree>),
}

impl Tree {
    fn cost(&self) -> i64 {
        match self {
            &Tree::Leaf(x, ..) => x,
            &Tree::Node(x, ..) => x,
        }
    }

    fn unite_ids(&self, uf: &mut UnionFind) -> usize {
        match self {
            &Tree::Leaf(nc, nid) => {
                nid
            },
            &Tree::Node(nc, ec, ref l, ref r) => {
                let li = l.unite_ids(uf);
                let ri = r.unite_ids(uf);
                uf.unite(li, ri);
                uf.find(li)
            },
        }
    }

    fn solve<'a, 'b>(&'a self, st: &mut Vec<&'b Tree>)
    where
        'a: 'b,
    {
        match self {
            &Tree::Leaf(nc, nid) => {
                st.push(self);
            },
            &Tree::Node(nc, ec, ref l, ref r) => {
                if ec <= nc {
                    st.push(self);
                } else {
                    l.solve(st);
                    r.solve(st);
                }
            },
        }
    }
}



