pub struct UnionFindForest {
    nodes: Vec<UffNode>,
}

enum UffNode {
    Root(usize),
    Child(usize),
}

impl UnionFindForest {
    pub fn new(size: usize) -> Self {
        UnionFindForest {
            nodes: (0..size).map(|_| UffNode::Root(1)).collect::<Vec<_>>(),
        }
    }

    pub fn root_node(&mut self, v: usize) -> (usize, usize) {
        match self.nodes[v] {
            UffNode::Root(rank) => (v, rank),
            UffNode::Child(u) => {
                let (u, rank) = self.root_node(u);
                self.nodes[v] = UffNode::Child(u);
                (u, rank)
            }
        }
    }

    pub fn root(&mut self, v: usize) -> usize {
        self.root_node(v).0
    }

    pub fn connects(&mut self, u: usize, v: usize) -> bool {
        self.root(u) == self.root(v)
    }

    pub fn merge(&mut self, u: usize, v: usize) {
        let (u, u_rank) = self.root_node(u);
        let (v, v_rank) = self.root_node(v);

        if u == v {
            return;
        }

        if u_rank < v_rank {
            self.merge(v, u);
            return;
        }

        self.nodes[v] = UffNode::Child(u);
        self.nodes[u] = UffNode::Root(u_rank + 1);
    }
}

fn main() {
    let (N, M) = read!(usize, usize);
    let X = read![[i64]];
    let T = read![usize, usize, i64; M];

    let mut E = T
        .into_iter()
        .enumerate()
        .map(|(e, (u, v, w))| (w, u - 1, v - 1, e))
        .collect::<Vec<_>>();
    E.sort();

    let mut G = vec![vec![]; N];
    for &(w, u, v, e) in &E {
        G[u].push((w, u, v, e));
        G[v].push((w, v, u, e));
    }

    let mut uff = UnionFindForest::new(N);
    let mut weights = X.clone();
    let mut maybe_max = vec![false; M];

    // N 頂点グラフに、コスト昇順に辺を追加していく
    for &(w, u, v, e) in &E {
        // この辺を含む、コスト w 以下の辺からなる連結成分の重み
        let mut sum = weights[uff.root(u)];

        // 辺を追加して、追加後の連結成分の重みを計算する
        if uff.root(u) != uff.root(v) {
            sum += weights[uff.root(v)];
            uff.merge(u, v);
            weights[uff.root(u)] = sum;

            debug!((e, u, v, w, sum));
        }

        // コスト w 以下の辺からなる連結成分がこの辺を支えられるなら、この辺は最終的な連結成分の重み最大辺である可能性がある
        if w <= sum {
            maybe_max[e] = true;
        }
    }

    debug!(maybe_max);

    E.reverse();

    // done[e] = n : 辺 e を残すかどうか
    // n=0: 未定
    // n=1: 残すことに決定
    // n=2: 捨てることに決定
    let mut done = vec![0; M];

    // コスト降順に辺をみていく
    for &(w, u, v, e) in &E {
        if done[e] != 0 {
            continue;
        }

        if !maybe_max[e] {
            done[e] = 2;
            continue;
        }

        // 残すことに決定
        done[e] = 1;
        // コスト w 以下で到達できるすべての辺も残す
        let mut stack = vec![u, v];
        while let Some(u) = stack.pop() {
            debug!((w, u));

            for i in 0..G[u].len() {
                let (w2, _, v, e) = G[u][i];
                if done[e] != 0 || w2 > w {
                    continue;
                }
                done[e] = 1;
                stack.push(v);
            }
        }
    }

    let score = done.iter().filter(|&&x| x != 1).count();
    println!("{}", score)
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };

    let n = sc.read();
    let m = sc.read();
    let x: Vec<usize> = sc.read_vec(n);

    let mut edges = vec![];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        let y: usize = sc.read();
        edges.push((y, a, b));
    }
    edges.sort();

    let mut can_use = vec![false; m];
    let mut uf = UnionFind::new(x);

    let mut cur = 0;
    while cur < m {
        let (cur_weight, _, _) = edges[cur];
        let mut pos = cur;
        while pos < m {
            let (w, a, b) = edges[pos];
            if w != cur_weight {
                break;
            }
            uf.unite(a, b);
            pos += 1;
        }

        let mut pos = cur;
        while pos < m {
            let (w, a, _) = edges[pos];
            if w != cur_weight {
                break;
            }
            let root = uf.find(a);
            if uf.weights[root] >= w {
                can_use[pos] = true;
            }
            pos += 1;
        }

        cur = pos;
    }

    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let (w, a, b) = edges[i];
        graph[a].push((i, w, b));
        graph[b].push((i, w, a));
    }

    let mut is_used = vec![false; m];
    for i in (0..m).rev() {
        if is_used[i] || !can_use[i] {
            continue;
        }
        let (w, a, b) = edges[i];
        dfs(a, &mut is_used, &graph, w);
        dfs(b, &mut is_used, &graph, w);
    }

    println!("{}", is_used.iter().filter(|&&u| !u).count());
}

fn dfs(
    v: usize,
    is_used: &mut Vec<bool>,
    graph: &Vec<Vec<(usize, usize, usize)>>,
    max_weight: usize,
) {
    for &(edge_id, weight, next) in graph[v].iter() {
        if is_used[edge_id] {
            continue;
        }
        if weight > max_weight {
            continue;
        }
        is_used[edge_id] = true;
        dfs(next, is_used, graph, max_weight);
    }
}

pub struct UnionFind {
    parent: Vec<usize>,
    sizes: Vec<usize>,
    weights: Vec<usize>,
    size: usize,
}

impl UnionFind {
    pub fn new(weights: Vec<usize>) -> UnionFind {
        let n = weights.len();
        UnionFind {
            parent: (0..n).map(|i| i).collect::<Vec<usize>>(),
            sizes: vec![1; n],
            weights: weights,
            size: n,
        }
    }

    pub fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let px = self.parent[x];
            self.parent[x] = self.find(px);
            self.parent[x]
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) -> bool {
        let parent_x = self.find(x);
        let parent_y = self.find(y);
        if parent_x == parent_y {
            return false;
        }

        let (large, small) = if self.sizes[parent_x] < self.sizes[parent_y] {
            (parent_y, parent_x)
        } else {
            (parent_x, parent_y)
        };

        self.parent[small] = large;

        self.sizes[large] += self.sizes[small];
        self.sizes[small] = 0;

        self.weights[large] += self.weights[small];
        self.weights[small] = 0;

        self.size -= 1;
        return true;
    }
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let x: Vec<i64> = sc.vec(n);
    let mut edges = vec![];
    let mut costs = vec![];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        let cost: i64 = sc.read();
        costs.push((cost, i));
        edges.push((a, b, cost));
    }

    let mut uf = UnionFind::new(n, &x);
    let mut ok = vec![false; m];
    costs.sort();
    costs.reverse();
    while let Some(&(cost, _)) = costs.last() {
        let mut e = vec![];
        while let Some((c, edge)) = costs.pop() {
            if c == cost {
                e.push(edge);
            } else {
                costs.push((c, edge));
                break;
            }
        }

        for &i in e.iter() {
            let (a, b, _) = edges[i];
            uf.unite(a, b);
        }

        for &i in e.iter() {
            let (a, _, _) = edges[i];
            let root = uf.find(a);
            let sum = uf.sum[root];
            if sum >= cost {
                ok[i] = true;
            }
        }
    }

    let mut costs = edges
        .iter()
        .enumerate()
        .map(|(i, &(_, _, cost))| (cost, i))
        .collect::<Vec<_>>();
    costs.sort();
    costs.reverse();

    let mut graph = vec![vec![]; n];
    for (i, &(a, b, cost)) in edges.iter().enumerate() {
        graph[a].push((b, cost, i));
        graph[b].push((a, cost, i));
    }

    let mut vis = vec![false; m];
    for (_, i) in costs.into_iter() {
        if !ok[i] {
            continue;
        }
        let (a, b, cost) = edges[i];
        vis[i] = true;
        dfs(a, &graph, &mut vis, cost);
        dfs(b, &graph, &mut vis, cost);
    }

    let remove = vis.into_iter().filter(|&v| !v).count();
    println!("{}", remove);
}

fn dfs(v: usize, graph: &Vec<Vec<(usize, i64, usize)>>, vis: &mut Vec<bool>, cost: i64) {
    for &(next, edge_cost, edge_id) in graph[v].iter() {
        if vis[edge_id] {
            continue;
        }
        if edge_cost > cost {
            continue;
        }
        vis[edge_id] = true;
        dfs(next, graph, vis, cost);
    }
}

