fn main() {
    let v = read_vec::<usize>();
    let (n, m) = (v[0], v[1]);
    let x = read_vec::<i64>();
    let mut edges = vec![];
    for i in 0..m {
        let v = read_vec::<i64>();
        let (a, b, c) = (v[0] as usize - 1, v[1] as usize - 1, v[2]);
        edges.push((c, a, b));
    }
    edges.sort();
    let mut sum = x.clone();

    let mut ok = vec![0; n];

    let mut uft = UnionFindTree::new(n);
    for &(y, a, b) in edges.iter() {
        let a = uft.find(a);
        let b = uft.find(b);
        if uft.same(a, b) {
            continue;
        }
        uft.unite(a, b);
        let root = uft.find(a);
        if root == a {
            sum[a] += sum[b];
        } else {
            sum[b] += sum[a];
        }
        if y <= sum[root] {
            ok[a] = y;
            ok[b] = y;
        }
    }

    let mut uft = UnionFindTree::new(n);
    for _ in 0..1 {
        for &(y, a, b) in edges.iter() {
            if ok[uft.find(a)] >= y || ok[uft.find(b)] >= y {
                uft.unite(a, b);
            }
        }
