#[derive(Eq, PartialEq, Clone, Debug)]
enum Tree {
    Leaf(i64, usize),
    Node(i64, i64, Box<Tree>, Box<Tree>),
}

impl Tree {
    fn cost(&self) -> i64 {
        match self {
            &Tree::Leaf(x, ..) => x,
            &Tree::Node(x, ..) => x,
        }
    }

    fn unite_ids(&self, uf: &mut UnionFind) -> usize {
        match self {
            &Tree::Leaf(nc, nid) => {
                nid
            },
            &Tree::Node(nc, ec, ref l, ref r) => {
                let li = l.unite_ids(uf);
                let ri = r.unite_ids(uf);
                uf.unite(li, ri);
                uf.find(li)
            },
        }
    }

    fn solve<'a, 'b>(&'a self, st: &mut Vec<&'b Tree>)
    where
        'a: 'b,
    {
        match self {
            &Tree::Leaf(nc, nid) => {
                st.push(self);
            },
            &Tree::Node(nc, ec, ref l, ref r) => {
                if ec <= nc {
                    st.push(self);
                } else {
                    l.solve(st);
                    r.solve(st);
                }
            },
        }
    }
}



fn main() {
    use std::mem::replace;
    use std::io::Write;
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    #[allow(unused_macros)]
    macro_rules! printf { ($($arg:tt)*) => (write!(out, $($arg)*).unwrap()); }
    #[allow(unused_macros)]
    macro_rules! printfln { () => (writeln!(out).unwrap()); ($($arg:tt)*) => (writeln!(out, $($arg)*).unwrap()); }

    input! {
        n: usize,
        m: usize,
        x: [i64; n],
        edges: [(usize, usize, i64); m],
    }

    let mut g = AdjList::new(n);
    for (f, t, c) in edges {
        g.add_uedge(f-1, t-1, c);
    }

    // let (_, mst) = g.construct_mst();
    let mut edges: Vec<_> = g.adj
        .iter()
        .enumerate()
        .flat_map(|(i, es)| es.iter().cloned().map(move |e| (e, i)))
        .collect();
    edges.sort();
    edges.reverse();
    let mut sts: Vec<_> = (0..n).map(|i| Some(Tree::Leaf(x[i], i))).collect();
    let mut uft = UnionFind::new(n);
    for (e, f) in edges.iter().cloned() {
        debug!((&e, &f));
        debug!(sts);
        let f = uft.find(f);
        let t = uft.find(e.to);
        if !uft.same(f, t) {
            uft.unite(f, t);
            let r = uft.find(f);
            let ft = replace(&mut sts[f], None).unwrap();
            let tt = replace(&mut sts[t], None).unwrap();
            sts[r] = Some(Tree::Node(ft.cost() + tt.cost(), e.cost, Box::new(ft), Box::new(tt)));
        }
    }

    let mut ss = Vec::new();
    let tr = sts.into_iter().filter(|x| x.is_some()).next().unwrap().unwrap();
    debug!(tr);
    tr.solve(&mut ss);
    debug!(ss);
    let mut uft = UnionFind::new(n);
    let mut cv = vec![0; n];
    for tr in &ss {
        let i = tr.unite_ids(&mut uft);
        cv[i] = tr.cost();

    }

    let mut ans = 0;
    for f in 0..n {
        for e in g[f].iter() {
            let t = e.to;
            debug!((f, t));
            if uft.same(f, t) {
                let r = uft.find(f);
                if cv[r] < e.cost {
                    ans += 1;
                }
            } else {
                ans += 1;
            }
        }
    }
    printfln!("{}", ans / 2);
}

