struct UnionFindNode {
    parent: usize,
    num: usize,
    x: i64,
}

impl UnionFindNode {
    fn new(parent: usize, x: i64) -> UnionFindNode {
        UnionFindNode {
            parent: parent,
            num: 1,
            x: x,
        }
    }
}

pub struct UnionFind(Vec<UnionFindNode>, Vec<Option<(usize,usize,usize,usize,i64)>>);

impl UnionFind {
    pub fn new(n: usize, ys: &Vec<i64>) -> UnionFind {
        let mut xs = vec![];
        for i in 0..n {
            xs.push(UnionFindNode::new(i, ys[i]));
        }
        UnionFind(xs, vec![])
    }
    pub fn root(&mut self, i: usize) -> usize {
        let parent = self.0[i].parent;
        if parent == i {
            i
        }
        else {
            let res = self.root(parent);
            // self.0[i].parent = res;
            res
        }
    }
    pub fn unite(&mut self, i: usize, k: usize) {
        let i = self.root(i);
        let k = self.root(k);
        if i == k {
            self.1.push(None);
            return;
        }
        let (i,k) = if self.0[i].num < self.0[k].num {
            (i,k)
        }
        else {
            (k,i)
        };
        self.1.push(Some((i,k,self.0[i].parent,self.0[k].num,self.0[k].x)));
        self.0[i].parent = k;
        self.0[k].num += self.0[i].num;
        self.0[k].x += self.0[i].x;
    }
    pub fn back(&mut self) -> bool {
        if let Some(t) = self.1.pop() {
            if let Some((i,k,i_parent,k_num,k_x)) = t {
                self.0[i].parent = i_parent;
                self.0[k].num = k_num;
                self.0[k].x = k_x;
            }
            true
        }
        else {
            false
        }
    }
    pub fn get_x(&mut self, i: usize) -> i64 {
        let r = self.root(i);
        self.0[r].x
    }
    pub fn is_same_set(&mut self, i: usize, k: usize) -> bool {
        self.root(i) == self.root(k)
    }
    pub fn num(&mut self, i: usize) -> usize {
        let i = self.root(i);
        self.0[i].num
    }
}

