pub struct GraphRec<'a> {
    pub n: usize,
    pub used: Vec<bool>,
    pub visited: Vec<bool>,
    y: &'a Vec<u64>,
}
impl<'a> GraphRec<'a> {
    pub fn new(n: usize, m: usize, y: &'a Vec<u64>) -> Self {
        Self {
            n,
            visited: vec![false; n],
            used: vec![false; m],
            y,
        }
    }
    pub fn dfs(&mut self, u: usize, w: u64, graph: &Graph) {
        self.visited[u] = true;
        for a in graph.adjacency(u) {
            if self.y[a.id] <= w {
                self.used[a.id] = true;
                if !self.visited[a.to] {
                    self.dfs(a.to, w, graph);
                }
            }
        }
    }
}
